:root {
  /* Base mode tokens — dark */
  --bg-primary: #11151A;
  --bg-secondary: #14181C;
  --bg-card: rgba(20, 24, 28, .62);
  --bg-card-solid: #14181C;
  --bg-hover: rgba(30, 35, 41, .94);
  /* 深色主题文字：三档对比度整体提升（和 #11151A 背景分别约 17.2 / 13.2 / 11.8 : 1，均 AAA 级） */
  --text-primary: #F5F7FA;
  --text-secondary: #D9DEE4;
  --text-muted: #C5CCD4;
  --text-strong: #FFFFFF;
  /* 通用容器/输入框背景变量（drawer / modal / form 等组件共用） */
  --bg-base: #14181C;
  --bg-elevated: rgba(255, 255, 255, .035);
  --bg-input: rgba(255, 255, 255, .06);
  --surface-workbench: rgba(20, 24, 28, .88);
  --surface-workbench-inset: rgba(255, 255, 255, .035);
  --surface-workbench-control: var(--bg-primary);
  --surface-workbench-action: rgba(245, 247, 250, .04);
  --sidebar-w: 176px;
  --sidebar-collapsed-w: 52px;
  --panel-w: 220px;
  --panel-collapsed-w: 40px;
  /* Default palette tokens (champagne) — overridden by [data-palette] */
  --accent-cyan: #C9A961;
  --accent-blue: #B89752;
  --accent-violet: #8C8C8C;
  --accent-emerald: #A88643;
  --accent-amber: #D4B576;
  --accent-rose: #7A7A7A;
  --gradient-primary: linear-gradient(135deg, #D4B576, #C9A961);
  --accent-cyan-soft: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  --accent-cyan-softer: color-mix(in srgb, var(--accent-cyan) 7.5%, transparent);
  --accent-cyan-border: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  --accent-amber-soft: color-mix(in srgb, var(--accent-amber) 14%, transparent);
  --border-color: color-mix(in srgb, var(--accent-cyan) 32%, transparent);
  --border-active: color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  --border-glow: color-mix(in srgb, var(--accent-cyan) 18%, transparent);
  /* 布局原语变量（P1：收敛重复 border 规则） */
  --panel-border: 2px solid var(--border-color);
  /* 圆角 token（卡片/面板级） */
  --radius-card: 12px;
  /* 阴影 token（容器面板去 shadow，内容卡片用轻 shadow） */
  --shadow-subtle: 0 2px 8px rgba(0, 0, 0, .18);
  /* 模态框阴影：将卡片从页面背景中清晰分离（深色下增强层次，浅色下用冷灰） */
  --shadow-modal: 0 24px 64px rgba(0, 0, 0, .5), 0 2px 12px rgba(0, 0, 0, .3), 0 0 0 1px rgba(255, 255, 255, .04) inset;
  /* 动画 token（统一 4 种时长 + 2 种缓动） */
  --ease-fast: .15s ease;
  --ease-base: .2s ease;
  --transition-base: all .2s ease;
  /* 间距 token（4px 阶梯） */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 16px;
  --space-xl: 24px;
  --space-2xl: 32px;
  --bg-glow-1: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  --bg-glow-2: rgba(140,140,140,.07);
  --particle-c1: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  --particle-c2: color-mix(in srgb, var(--accent-amber) 42%, transparent);
  /* 水墨氛围光晕：BackgroundLayer 多层 radial-gradient 使用 */
  --ink-glow-1: color-mix(in srgb, var(--accent-cyan) 35%, transparent);   /* 左上金色光晕 */
  --ink-glow-2: color-mix(in srgb, var(--accent-cyan) 25%, transparent);   /* 右下金色光晕 */
  --ink-glow-3: rgba(120,108,140,.22);  /* 中下灰紫光晕 */
  --particle-count: 55;
  --particle-size-min: 1px;
  --particle-size-max: 3px;
  --shadow-card: 0 16px 40px rgba(0,0,0,.5);
  --surface-workbench-ai: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 10.5%, transparent), color-mix(in srgb, var(--accent-blue) 5.5%, transparent)), rgba(20,24,28,.88);
  --workbench-page-wash: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 5.5%, transparent), transparent 250px);
  /* 信号色 — 红涨绿跌（A股惯例：.up 用 signal-critical 红，.down 用 signal-positive 绿）
     水墨调和：降低饱和度，避免高对比鲜色破坏墨色基调 */
  --signal-positive: #5fa86d;      /* 墨青绿：原 #22c55e 降饱和，用于下跌 */
  --signal-critical: #c25858;      /* 墨赭红：原 #ef4444 降饱和，用于上涨 */
  --signal-critical-soft: rgba(194, 88, 88, .12);
  --accent-red: #c25858;
  --accent-green: #5fa86d;
  /* 滚动条主题 token（随 12 配色 & dark/light 双模式实时切色）
     — 默认 fallback = champagne 香槟金 thumb；
     — 侧边栏 / 主区 / 右面板 / 模态框 统一走这 3 个变量。*/
  --scrollbar-track: transparent;
  --scrollbar-thumb: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  --scrollbar-thumb-hover: color-mix(in srgb, var(--accent-cyan) 58%, transparent);
  --scrollbar-size: 8px;
}

:root[data-mode="light"] {
  /* Base mode tokens — light 暖米白（暖色调、温和不刺眼） */
  --bg-primary: #F6F1E8;
  --bg-secondary: #FCF9F3;
  --bg-card: rgba(252, 249, 243, .94);
  --bg-card-solid: #FCF9F3;
  --bg-hover: #EDE5D6;
  /* 浅色主题文字：暖棕黑三档，对比度进一步提升（和 #F6F1E8 背景分别约 15.5 / 9.8 / 5.9 : 1，AA~AAA 级） */
  --text-primary: #1C1710;
  --text-secondary: #42392B;
  --text-muted: #6E6250;
  --text-strong: #100B05;
  /* 通用容器/输入框背景变量（drawer / modal / form 等组件共用） */
  --bg-base: #FCF9F3;
  --bg-elevated: rgba(120, 90, 40, .045);
  --bg-input: rgba(120, 90, 40, .06);
  --surface-workbench: rgba(252, 249, 243, .98);
  --surface-workbench-inset: rgba(237, 229, 214, .6);
  --surface-workbench-control: #F8F3EA;
  --surface-workbench-action: rgba(90, 65, 30, .05);
  /* 暖金棕 palette tokens */
  --accent-cyan: #85652F;
  --accent-blue: #9A7436;
  --accent-violet: #7C6A50;
  --accent-emerald: #6E7A45;
  --accent-amber: #B08A3E;
  --accent-rose: #A05C3E;
  --gradient-primary: linear-gradient(135deg, #A87E34, #7E5F28);
  --accent-cyan-soft: rgba(138,106,53,.10);
  --accent-cyan-softer: rgba(138,106,53,.055);
  --accent-cyan-border: rgba(138,106,53,.22);
  --accent-amber-soft: rgba(176,138,62,.12);
  --border-color: rgba(var(--hairline-tint), .16);
  /* shadow-tint 默认已在上文声明 */
  /* v16 表面/阴影 tint：暖米白默认；冷 palette 在 themes.css light 块覆盖 */
  --surface-sidebar: #FBF7EF;
  --surface-topbar: rgba(252,249,243,.88);
  --surface-panel: #FBF7EF;
  --surface-soft: rgba(252,249,243,.95);
  --shadow-tint: 90, 60, 20;
  --hairline-tint: 120, 90, 40;
  --border-active: rgba(138,106,53,.38);
  --border-glow: rgba(138,106,53,.08);
  --bg-glow-1: rgba(176,138,62,.07);
  --bg-glow-2: rgba(122,106,82,.05);
  --particle-c1: rgba(176,138,62,.35);
  --particle-c2: rgba(138,106,53,.28);
  /* 暖金光晕 */
  /* v16：墨晕跟随调色板（可读 accent 低透明派生），冷 palette 不再被暖晕染黄 */
  --ink-glow-1: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  --ink-glow-2: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  --ink-glow-3: color-mix(in srgb, var(--accent-violet) 6%, transparent);
  --particle-count: 42;
  --particle-size-min: 1px;
  --particle-size-max: 2.5px;
  --shadow-card: 0 4px 20px rgba(var(--shadow-tint), .06), 0 1px 3px rgba(var(--shadow-tint), .04);
  --shadow-modal: 0 24px 64px rgba(70,45,15,.18), 0 2px 12px rgba(70,45,15,.08), 0 0 0 1px rgba(138,106,53,.08) inset;
  --surface-workbench-ai: linear-gradient(135deg, rgba(176,138,62,.06), rgba(138,106,53,.035)), rgba(252,249,243,.98);
  --workbench-page-wash: linear-gradient(180deg, rgba(176,138,62,.045), rgba(246,241,232,.25) 210px, transparent 310px);
  /* 信号色（暖调：墨青绿 / 砖红） */
  --signal-positive: #5E7A4E;
  --signal-critical: #A5503A;
  --signal-critical-soft: rgba(165, 80, 58, .10);
  --accent-red: #A5503A;
  --accent-green: #5E7A4E;
  /* 滚动条（light 下整体浅 1 档，暖金 thumb） */
  --scrollbar-thumb: rgba(138,106,53,.35);
  --scrollbar-thumb-hover: rgba(138,106,53,.55);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

:root[data-mode="light"] body {
  background:
    radial-gradient(circle at 12% -8%, var(--bg-glow-1), transparent 34%),
    radial-gradient(circle at 82% 0%, var(--bg-glow-2), transparent 30%),
    var(--bg-primary);
}

#root { min-height: 100vh; }

.app { position: relative; min-height: 100vh; overflow: hidden; }

/* 创作中心全屏模式 */
.app.editor-fullscreen .sidebar { display: none; }
.app.editor-fullscreen .panel { display: none; }
.app.editor-fullscreen .main { margin-left: 0; margin-right: 0; height: 100vh; }
.app.editor-fullscreen .topbar { display: none; }
.app.editor-fullscreen .stats-bar { display: none; }
.app.editor-fullscreen .feed { padding: 0; height: 100vh; overflow-y: auto; }
.app.editor-fullscreen .trends-dashboard { min-height: 100vh; display: flex; flex-direction: column; }
.app.editor-fullscreen .article-editor { flex: 1; display: flex; flex-direction: column; min-height: 0; }
.app.editor-fullscreen .editor-split-view { flex: 1; min-height: 0; }
.app.editor-fullscreen .editor-pane,
.app.editor-fullscreen .preview-pane { min-height: 300px; }
.app.editor-fullscreen .article-content-editor { min-height: 300px; }

/* 移除左上/右下大光晕圆（默认金色光被用户要求去掉，连带灰紫副光晕一起移除，保持干净背景）
 * .app::before / ::after 已不渲染背景，但保留空壳 content（避免子元素 absolute 定位坐标变化）。
 * 原 glowPulse 动画保留（不影响，无元素再引用到）。
 */
.app::before, .app::after { content: ''; position: fixed; pointer-events: none; z-index: 0; background: none !important; animation: none !important; }
:root[data-mode="light"] .app::before,
:root[data-mode="light"] .app::after { background: none !important; }
@keyframes glowPulse { 0%, 100% { opacity: .6; transform: scale(1); } 50% { opacity: .9; transform: scale(1.1); } }

