   现在统一走文件底部 L22214「滚动条美化」token 化规则，并随 12 配色主题实时切色。*/

/* Sidebar */
.sidebar { position: fixed; left: 0; top: 0; bottom: 0; width: var(--sidebar-w); background: var(--bg-secondary); border-right: 1px solid var(--border-color); display: flex; flex-direction: column; z-index: 100; transition: width .3s cubic-bezier(.4, 0, .2, 1); overflow: hidden; }
:root[data-mode="light"] .sidebar { background: var(--surface-sidebar); border-right-color: rgba(var(--hairline-tint), .10); box-shadow: 2px 0 12px rgba(var(--shadow-tint), .03); }
.sidebar.collapsed { width: var(--sidebar-collapsed-w); }
.sidebar-header { padding: 10px 12px; border-bottom: 1px solid var(--border-color); display: flex; align-items: center; justify-content: space-between; gap: var(--space-sm); }
.sidebar.collapsed .sidebar-header { flex-direction: column; padding: 8px 4px; gap: var(--space-xs); }
.logo { display: flex; align-items: center; gap: var(--space-sm); flex: 1; min-width: 0; }
.logo-icon { width: 36px; height: 36px; flex-shrink: 0; display: grid; place-items: center; background: transparent; border-radius: 10px; position: relative; }
.logo-icon svg { width: 32px; height: 32px; }
.sidebar.collapsed .logo-icon { width: 28px; height: 28px; }
.sidebar.collapsed .logo-icon svg { width: 24px; height: 24px; }
.logo-text { font-size: 17px; font-weight: 700; background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-blue) 60%, var(--accent-violet) 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; white-space: nowrap; transition: opacity .2s; letter-spacing: .3px; text-shadow: 0 0 14px var(--border-glow); }
.sidebar.collapsed .logo-text { opacity: 0; pointer-events: none; }
.logo-copy { display: flex; min-width: 0; flex-direction: column; gap: 1px; }
.logo-copy small { max-width: 142px; overflow: hidden; color: var(--text-muted); font-size: 10px; font-weight: 800; letter-spacing: 0; text-overflow: ellipsis; white-space: nowrap; }
.collapse-btn { width: 28px; height: 28px; flex-shrink: 0; display: grid; place-items: center; background: transparent; border: var(--panel-border); border-radius: 6px; color: var(--text-muted); cursor: pointer; transition: all .2s; }
.collapse-btn:hover { border-color: var(--border-active); color: var(--accent-cyan); }
.collapse-btn svg { width: 16px; height: 16px; }

.nav-menu { flex: 1; min-height: 0; padding: 8px 6px; overflow-y: auto; overflow-x: hidden; mask-image: linear-gradient(to bottom, transparent, black 8px, black calc(100% - 8px), transparent); -webkit-mask-image: linear-gradient(to bottom, transparent, black 8px, black calc(100% - 8px), transparent); }
.nav-group { margin-bottom: 6px; }
.nav-group-toggle { display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 4px 10px; background: transparent; border: none; color: var(--text-muted); font-size: 11px; font-weight: 700; letter-spacing: .4px; text-transform: uppercase; cursor: pointer; border-radius: 8px; }
.nav-primary-group, .nav-context-group { margin-bottom: 12px; }
.nav-group-title-static { padding: 5px 10px; color: var(--text-muted); font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.nav-item { display: flex; align-items: center; gap: var(--space-sm); width: 100%; padding: 7px 10px; margin-bottom: 1px; background: transparent; border: none; border-radius: 8px; color: var(--text-muted); font-size: 13px; font-weight: 500; cursor: pointer; transition: all .15s; text-align: left; white-space: nowrap; }
.nav-item:hover { background: var(--bg-hover); color: var(--text-secondary); }
.nav-item.active { background: rgba(56, 189, 248, .1); color: var(--accent-cyan); }
.nav-primary-item { min-height: 42px; align-items: center; margin-bottom: 3px; border: 1px solid transparent; }
.nav-primary-item.active { border-color: var(--accent-cyan-border); background: var(--surface-workbench-ai); }
.nav-label-wrap { display: flex; min-width: 0; flex: 1; flex-direction: column; gap: 2px; }
.nav-label-wrap small { overflow: hidden; color: var(--text-muted); font-size: 10px; font-weight: 600; text-overflow: ellipsis; }
.nav-primary-item.active .nav-label-wrap small { color: var(--accent-cyan); }
.nav-sub-item { min-height: 34px; padding-left: 14px; font-size: 12px; }
.agent-nav-summary .nav-label { overflow: hidden; text-overflow: ellipsis; }
.nav-icon { width: 18px; height: 18px; flex-shrink: 0; opacity: .7; transition: opacity .15s; }
.nav-item.active .nav-icon { opacity: 1; }
.nav-label { flex: 1; overflow: hidden; text-overflow: ellipsis; transition: opacity .2s; }
.sidebar.collapsed .nav-label { opacity: 0; }
.nav-count { font-size: 10px; padding: 2px 6px; background: rgba(56, 189, 248, .15); border-radius: 4px; color: var(--accent-cyan); transition: opacity .2s; }
.sidebar.collapsed .nav-count { opacity: 0; }
.sidebar.collapsed .nav-group-toggle { display: none; }

/* Sidebar Follow - Nav Group Style */
.nav-follow-group { margin-bottom: 0; }
.nav-group-follow-count { min-width: 16px; height: 16px; display: inline-grid; place-items: center; background: rgba(251, 191, 36, .15); color: var(--accent-amber); border-radius: 4px; font-size: 10px; font-weight: 700; padding: 0 4px; margin-left: 4px; }
.nav-follow-list { margin: 0 0 4px; padding: 4px 6px; }
.nav-follow-empty { font-size: 11px; color: var(--text-muted); text-align: center; padding: 8px 0; }
.nav-follow-item { display: flex; align-items: center; gap: 6px; padding: 5px 8px; margin-bottom: 2px; border-radius: 6px; transition: all .15s; }
.nav-follow-item:last-of-type { margin-bottom: 0; }
.nav-follow-item:hover { background: var(--bg-hover); }
.nav-follow-item-pinned { background: rgba(251, 191, 36, .08); }
.nav-follow-item-pinned:hover { background: rgba(251, 191, 36, .14); }
.nav-follow-name { font-size: 13px; font-weight: 500; color: var(--text-secondary); background: transparent; border: none; cursor: pointer; padding: 0; text-align: left; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: color .15s; display: flex; align-items: center; gap: var(--space-xs); }
.nav-follow-name:hover { color: var(--accent-cyan); }
.nav-follow-item-pinned .nav-follow-name { color: var(--accent-amber); }
.nav-follow-pin-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--accent-amber); box-shadow: 0 0 4px var(--accent-amber); }
.nav-follow-btns { display: flex; gap: 2px; opacity: 0; transition: opacity .15s; flex-shrink: 0; }
.nav-follow-item:hover .nav-follow-btns { opacity: 1; }
.nav-follow-pin-btn { width: 20px; height: 20px; display: grid; place-items: center; background: transparent; border: none; border-radius: 4px; color: var(--text-muted); cursor: pointer; transition: all .15s; padding: 0; }
.nav-follow-pin-btn:hover { color: var(--accent-amber); }
.nav-follow-pin-btn.pinned { color: var(--accent-amber); }
.nav-follow-del-btn { width: 20px; height: 20px; display: grid; place-items: center; background: transparent; border: none; border-radius: 4px; color: var(--text-muted); cursor: pointer; transition: all .15s; padding: 0; }
.nav-follow-del-btn:hover { color: var(--accent-rose); }
.nav-follow-add { display: flex; gap: var(--space-xs); align-items: center; margin-top: 6px; }
.nav-follow-add input { flex: 1; height: 28px; padding: 0 8px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; color: var(--text-primary); font-size: 12px; outline: none; transition: border-color .2s; min-width: 0; }
.nav-follow-add input:focus { border-color: var(--accent-cyan); }
.nav-follow-add input::placeholder { color: var(--text-muted); }
.nav-follow-add-btn { width: 28px; height: 28px; display: grid; place-items: center; background: var(--gradient-primary); border: none; border-radius: 6px; color: var(--bg-primary); cursor: pointer; transition: opacity .2s; }
.nav-follow-add-btn:hover { opacity: .85; }
.nav-follow-add-btn svg { width: 14px; height: 14px; }

.sidebar-footer { position: sticky; bottom: 0; padding: 8px 8px; border-top: 1px solid var(--border-color); background: var(--bg-secondary); z-index: 2; }
.sidebar-action { display: flex; align-items: center; gap: var(--space-sm); width: 100%; padding: 7px 10px; background: transparent; border: none; border-radius: 8px; color: var(--text-muted); font-size: 13px; cursor: pointer; transition: all .15s; white-space: nowrap; }
.sidebar-action:hover { background: var(--bg-hover); color: var(--text-secondary); }
.sidebar-action svg { width: 18px; height: 18px; flex-shrink: 0; }
.sidebar-action span { transition: opacity .2s; }
.sidebar.collapsed .sidebar-action span { opacity: 0; }

/* Main */
.main { margin-left: var(--sidebar-w); margin-right: var(--panel-w); height: 100vh; display: flex; flex-direction: column; background: transparent; transition: margin-left .3s ease, margin-right .3s ease; position: relative; z-index: 1; overflow-y: auto; }
.app.sidebar-collapsed .main { margin-left: var(--sidebar-collapsed-w); }
.app.panel-collapsed .main { margin-right: var(--panel-collapsed-w); }
.app.sidebar-collapsed.panel-collapsed .main { margin-left: var(--sidebar-collapsed-w); margin-right: var(--panel-collapsed-w); }
.app.no-right-panel .main,
.app.no-right-panel.panel-collapsed .main {
  margin-right: 0;
}

/* Topbar */
.topbar { position: sticky; top: 0; z-index: 50; padding: 12px 20px; background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); display: flex; flex-direction: column; gap: 10px; transition: background .3s, backdrop-filter .3s, border-color .3s; }
:root[data-mode="light"] .topbar { background: var(--surface-topbar); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border-bottom-color: rgba(var(--hairline-tint), .07); box-shadow: 0 1px 6px rgba(var(--shadow-tint), .02); }
/* 滚动时毛玻璃化 + 底部金色渐变线 */
.topbar.topbar-scrolled {
  background: color-mix(in srgb, var(--bg-secondary) 75%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom-color: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  box-shadow: 0 1px 0 0 color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
:root[data-mode="light"] .topbar.topbar-scrolled {
  background: rgba(252,249,243,.95);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom-color: rgba(var(--hairline-tint), .07);
  box-shadow: 0 1px 10px rgba(var(--shadow-tint), .04);
}
@supports not ((backdrop-filter: blur(12px)) or (-webkit-backdrop-filter: blur(12px))) {
  .topbar.topbar-scrolled { background: var(--bg-secondary); }
}
.topbar-all { padding: 6px 20px 5px; gap: 2px; }
.topbar-brand { display: flex; align-items: center; min-height: 34px; }
.topbar-main-row-all .topbar-brand { position: static; top: auto; margin-bottom: 0; align-self: flex-end; padding-bottom: 2px; }
.brand-title { font-size: 28px; font-weight: 900; letter-spacing: .9px; text-transform: uppercase; background: linear-gradient(120deg, var(--accent-cyan), var(--accent-blue), var(--accent-violet), var(--accent-cyan)); background-size: 260% 100%; -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; text-shadow: 0 0 10px var(--border-glow); filter: drop-shadow(0 0 7px var(--border-glow)); animation: brandFlow 6s linear infinite, brandPulse 3.8s ease-in-out infinite; }
.brand-theme-icon { width: 24px; height: 24px; margin-left: 10px; display: inline-flex; align-items: center; justify-content: center; color: var(--accent-cyan); filter: drop-shadow(0 0 6px var(--border-glow)); }
.brand-theme-icon svg { width: 24px; height: 24px; }
@keyframes brandFlow { 0% { background-position: 0% 50%; } 100% { background-position: 220% 50%; } }
@keyframes brandPulse { 0%, 100% { transform: translateY(0); opacity: .95; } 50% { transform: translateY(-1px); opacity: 1; } }

/* 滚动资讯热点区域 */
.scrolling-news-container {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 8px 12px;
  background: var(--accent-cyan-softer);
  border: 1px solid var(--accent-cyan-border);
  border-radius: var(--radius-card);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 0 18px var(--border-glow);
  position: relative;
  overflow: hidden;
}

.scrolling-news-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
  opacity: .38;
}

.scrolling-news-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-right: 12px;
  border-right: 1px solid var(--accent-cyan-border);
  flex-shrink: 0;
}

.scrolling-news-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-cyan);
  text-transform: uppercase;
  letter-spacing: .5px;
  text-shadow: 0 0 6px var(--border-glow);
}

.scrolling-news-icon {
  color: #ff6b35;
  filter: drop-shadow(0 0 6px rgba(255, 107, 53, .5));
  animation: firePulse 1.5s ease-in-out infinite;
}

.scrolling-news-icon svg {
  width: 14px;
  height: 14px;
}

@keyframes firePulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.1); opacity: .8; }
}

.scrolling-news-content {
  flex: 1;
  min-width: 0;
  position: relative;
  height: 32px;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-behavior: auto;
  cursor: grab;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.scrolling-news-content::-webkit-scrollbar { display: none; }
.scrolling-news-content:active { cursor: grabbing; }

.scrolling-news-track {
  display: flex;
  align-items: center;
  gap: 0;
  height: 100%;
  width: max-content;
}

.scrolling-news-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 20px;
  background: transparent;
  border: none;
  border-radius: 0;
  flex-shrink: 0;
  white-space: nowrap;
  cursor: pointer;
  border-right: 1px solid var(--border-color);
}
.scrolling-news-item:last-child { border-right: none; }

.scrolling-news-item:hover {
  background: transparent;
}
.scrolling-news-item:hover .scrolling-news-title {
  color: var(--accent-cyan);
}

.scrolling-news-hot {
  display: inline-flex;
  align-items: center;
  padding: 2px 6px;
  background: linear-gradient(135deg, #ff6b35, #ff8c42);
  border-radius: 4px;
  color: white;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .3px;
  box-shadow: 0 0 8px rgba(255, 107, 53, .4);
  animation: hotPulse 2s ease-in-out infinite;
}

@keyframes hotPulse {
  0%, 100% { box-shadow: 0 0 8px rgba(255, 107, 53, .4); }
  50% { box-shadow: 0 0 12px rgba(255, 107, 53, .6); }
}

.scrolling-news-title {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scrolling-news-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  flex-shrink: 0;
}

.scrolling-news-source {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.scrolling-news-time {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 400;
}

/* 浅色主题适配 */
:root[data-mode="light"] .scrolling-news-container {
  background: var(--accent-cyan-soft);
  border-color: var(--accent-cyan-border);
  box-shadow: 0 0 18px var(--border-glow);
}

:root[data-mode="light"] .scrolling-news-container::before {
  background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
}

:root[data-mode="light"] .scrolling-news-label {
  color: var(--accent-cyan);
  text-shadow: 0 0 6px var(--border-glow);
}

:root[data-mode="light"] .scrolling-news-header {
  border-right-color: var(--accent-cyan-border);
}

:root[data-mode="light"] .scrolling-news-item {
  background: var(--accent-cyan-soft);
  border-color: var(--accent-cyan-border);
}

:root[data-mode="light"] .scrolling-news-item:hover {
  background: var(--accent-cyan-softer);
  border-color: var(--border-active);
  box-shadow: 0 0 12px var(--border-glow);
}

.topbar-main { display: flex; align-items: center; gap: 18px; width: 100%; min-width: 0; }
.topbar-main-row { display: flex; align-items: center; gap: var(--space-md); }
.topbar-main-row .search-wrap { flex: 1; }
.topbar-main-all { flex-direction: column; align-items: stretch; gap: var(--space-sm); }
.topbar-main-row-all { width: 100%; justify-content: flex-end; }
.topbar-main-row-all .search-wrap { margin-left: auto; max-width: 374px; }
.search-wrap { flex: 1; max-width: 460px; min-width: 260px; position: relative; display: flex; align-items: center; }
.topbar-main-all .search-wrap { margin-top: 0; }
.search-wrap svg { position: absolute; left: 12px; width: 16px; height: 16px; color: var(--text-muted); pointer-events: none; }
.search-wrap input { width: 100%; height: 36px; padding: 0 12px 0 38px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; color: var(--text-primary); font-size: 13px; outline: none; transition: border-color .2s, box-shadow .2s; }
.search-wrap input:focus { border-color: var(--accent-cyan); box-shadow: 0 0 0 3px rgba(56, 189, 248, .1); }
.search-wrap input::placeholder { color: var(--text-muted); }

/* Search Dropdown */
.search-dropdown { position: absolute; top: calc(100% + 4px); left: 0; right: 0; background: var(--bg-secondary); border: var(--panel-border); border-radius: 10px; padding: 6px; z-index: 70; box-shadow: 0 10px 40px rgba(0, 0, 0, .3); animation: dropIn .15s ease; }
.search-suggestion, .search-history-item { display: flex; align-items: center; gap: var(--space-sm); width: 100%; padding: 8px 10px; background: transparent; border: none; border-radius: 6px; color: var(--text-secondary); font-size: 13px; cursor: pointer; transition: background .15s; text-align: left; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.search-suggestion:hover, .search-history-item:hover { background: var(--bg-hover); }
.search-history-item svg { width: 14px; height: 14px; color: var(--text-muted); flex-shrink: 0; }
.search-suggestion span, .search-history-item span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.search-sort-row { display: flex; gap: var(--space-xs); padding: 4px 6px; border-top: 1px solid var(--border-color); margin-top: 4px; }
.search-sort-btn { padding: 4px 10px; background: transparent; border: var(--panel-border); border-radius: 4px; color: var(--text-muted); font-size: 11px; cursor: pointer; transition: all .15s; }
.search-sort-btn.active { background: var(--accent-cyan); color: var(--bg-primary); border-color: var(--accent-cyan); }
/* Search submit button in dropdown */
.search-submit-btn{display:block;width:100%;padding:8px;margin-top:6px;border:none;border-radius:6px;background:linear-gradient(135deg,var(--accent-cyan-soft),var(--accent-cyan-softer));color:var(--accent-cyan);font-size:12px;font-weight:700;cursor:pointer;text-align:center;transition:var(--transition-base);}
.search-submit-btn:hover{background:var(--accent-cyan);color:#fff;}

@keyframes dropIn { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: translateY(0); } }

.topbar-actions { display: flex; align-items: center; gap: var(--space-md); flex: 1; min-width: 0; flex-wrap: nowrap; }
.topbar-actions-all { width: 100%; flex: 0 0 auto; }
.topbar-actions.singleline { flex-wrap: nowrap; gap: var(--space-sm); overflow: hidden; }
.topbar-trending .search-wrap { max-width: 280px; }
.topbar-trending .topbar-actions { gap: 6px; }

.lang-switcher { position: relative; display: inline-flex; flex-shrink: 0; }
.lang-switcher-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--surface-bg);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all .15s ease;
  user-select: none;
}
.lang-switcher-trigger:hover {
  border-color: var(--accent-color, #3b82f6);
  color: var(--text-primary);
  background: var(--surface-hover, rgba(59,130,246,.05));
}
.lang-switcher-icon { flex-shrink: 0; opacity: .85; }
.lang-switcher-label { line-height: 1; min-width: 18px; text-align: center; }
.lang-switcher-chevron { opacity: .6; transition: transform .2s ease; }
.lang-switcher-chevron.is-open { transform: rotate(180deg); }

.lang-switcher-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  min-width: 180px;
  list-style: none;
  margin: 0;
  padding: 6px;
  background: var(--surface-bg);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0,0,0,.18);
