}
@keyframes langSwitcherDropIn {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}
.lang-switcher-option {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  cursor: pointer;
  transition: background .12s ease;
  outline: none;
}
.lang-switcher-option:hover,
.lang-switcher-option:focus-visible {
  background: var(--surface-hover, rgba(59,130,246,.08));
}
.lang-switcher-option.is-active {
  background: linear-gradient(135deg, rgba(59,130,246,.12), rgba(168,85,247,.08));
  color: var(--accent-color, #3b82f6);
}
.lang-switcher-option-label { flex: 1; font-size: 13px; font-weight: 500; }
.lang-switcher-option-short {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--surface-bg);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  min-width: 24px;
  text-align: center;
}
.lang-switcher-option.is-active .lang-switcher-option-short {
  border-color: var(--accent-color, #3b82f6);
