}
.lang-switcher-check { flex-shrink: 0; color: var(--accent-color, #3b82f6); }

/* 窄屏适配：让切换器始终可见 */
@media (max-width: 720px) {
  .lang-switcher-trigger { padding: 6px 8px; }
  .lang-switcher-menu { min-width: 160px; }
}

/* Category Dropdown */
.category-dropdown-wrap { position: relative; }
.category-dropdown-btn { display: flex; align-items: center; gap: 6px; padding: 6px 12px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; color: var(--text-primary); font-size: 13px; font-weight: 500; cursor: pointer; transition: border-color .2s; }
.category-dropdown-btn:hover { border-color: var(--border-active); }
.category-dropdown-btn .chevron { width: 16px; height: 16px; display: flex; align-items: center; transition: transform .2s; }
.category-dropdown-btn .chevron svg { width: 16px; height: 16px; }
.category-dropdown-btn .chevron.open { transform: rotate(180deg); }
.dropdown-backdrop { position: fixed; inset: 0; z-index: 60; }
.category-dropdown { position: absolute; top: calc(100% + 6px); left: 0; min-width: 200px; background: var(--bg-secondary); border: var(--panel-border); border-radius: 10px; padding: 6px; z-index: 70; box-shadow: 0 10px 40px rgba(0, 0, 0, .3); animation: dropIn .15s ease; }
.category-option { display: flex; align-items: center; gap: var(--space-sm); width: 100%; padding: 8px 10px; background: transparent; border: none; border-radius: 6px; color: var(--text-secondary); font-size: 13px; cursor: pointer; transition: all .15s; text-align: left; }
.category-option:hover { background: var(--bg-hover); color: var(--text-primary); }
.category-option.active { background: var(--accent-cyan-soft); color: var(--accent-cyan); }
.cat-icon { width: 16px; height: 16px; flex-shrink: 0; display: flex; align-items: center; }
.cat-icon svg { width: 16px; height: 16px; }
.category-dropdown-grouped { min-width: 280px; max-height: 400px; overflow-y: auto; }
.category-group { margin-top: 8px; }
.category-group:first-child { margin-top: 0; }
.category-group-header { display: flex; align-items: center; gap: 6px; padding: 6px 10px 4px; font-size: 11px; font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: .3px; }
.cat-group-icon { width: 14px; height: 14px; display: flex; align-items: center; color: var(--accent-cyan); }
.cat-group-icon svg { width: 14px; height: 14px; }
.category-group-items { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2px; }
.category-group-items .category-option { padding: 6px 8px; font-size: 12px; }
.category-group-items .cat-icon { width: 14px; height: 14px; }
.category-group-items .cat-icon svg { width: 14px; height: 14px; }

/* View Toggle */
.view-toggle { display: flex; background: var(--bg-primary); border-radius: 8px; padding: 3px; gap: 2px; }
.view-btn { width: 30px; height: 26px; display: grid; place-items: center; background: transparent; border: none; border-radius: 6px; color: var(--text-muted); cursor: pointer; transition: all .15s; }
.view-btn:hover { color: var(--text-secondary); }
.view-btn.active { background: var(--accent-cyan); color: #071d18; }
.view-btn svg { width: 14px; height: 14px; }

.lang-tabs, .mode-tabs { display: flex; background: var(--bg-primary); border-radius: 8px; padding: 4px; }
.lang-tab, .mode-tab { padding: 6px 12px; background: transparent; border: none; border-radius: 6px; color: var(--text-muted); font-size: 12px; font-weight: 500; cursor: pointer; transition: all .15s; }
.lang-tab:hover, .mode-tab:hover { color: var(--text-secondary); }
.lang-tab.active, .mode-tab.active { background: var(--accent-cyan); color: #071d18; }

:root[data-mode="light"] .view-btn.active,
:root[data-mode="light"] .lang-tab.active,
:root[data-mode="light"] .mode-tab.active {
  color: #fffdf7;
}
.source-filter-wrap { display: flex; align-items: center; gap: 6px; padding: 4px 8px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; min-width: 170px; max-width: 240px; }
.source-filter-select { height: 26px; width: 100%; min-width: 0; background: transparent; border: none; color: var(--text-primary); font-size: 12px; outline: none; text-overflow: ellipsis; cursor: pointer; }

.btn-refresh { display: flex; align-items: center; gap: 6px; padding: 7px 14px; background: var(--gradient-primary); border: none; border-radius: 8px; color: var(--bg-primary); font-size: 12px; font-weight: 600; cursor: pointer; transition: opacity .2s; flex-shrink: 0; position: relative; }

/* 新资讯计数徽标：自上次访问以来新增 N 条 */
.new-news-badge { position: absolute; top: -6px; right: -8px; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: linear-gradient(135deg, #ef4444, #f97316); color: #fff; font-size: 10px; font-weight: 700; display: flex; align-items: center; justify-content: center; box-shadow: 0 2px 6px rgba(239, 68, 68, .4); animation: newPulse 1.6s ease-in-out 3; z-index: 3; }
.btn-refresh:hover { opacity: .9; }
.btn-refresh svg { width: 14px; height: 14px; }
.topbar-actions-all .btn-refresh-all { margin-left: auto; }

.globe-entry-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border: 1px solid var(--accent-cyan-border, color-mix(in srgb, var(--accent-cyan) 40%, transparent));
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent-cyan-softer), transparent);
  color: var(--accent-cyan);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  overflow: hidden;
  transition: border-color .2s, box-shadow .2s, transform .15s;
  flex-shrink: 0;
  margin-left: auto;
}
.globe-entry-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 30%, color-mix(in srgb, var(--accent-cyan) 15%, transparent) 50%, transparent 70%);
  transform: translateX(-100%);
  transition: transform .6s;
}
.globe-entry-btn:hover {
  border-color: var(--accent-cyan);
  box-shadow: 0 0 14px var(--border-glow);
  transform: translateY(-1px);
}
.globe-entry-btn:hover::before { transform: translateX(100%); }
.globe-entry-btn svg {
  width: 15px;
  height: 15px;
  filter: drop-shadow(0 0 4px var(--border-glow));
  animation: globeSpin 8s linear infinite;
}
@keyframes globeSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.region-filter-wrap { display: flex; align-items: center; gap: 6px; padding: 4px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; }
.region-filter-btn { padding: 6px 12px; background: transparent; border: none; border-radius: 6px; color: var(--text-secondary); font-size: 12px; font-weight: 600; cursor: pointer; transition: var(--transition-base); white-space: nowrap; }
.region-filter-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.region-filter-btn.active { color: var(--accent-cyan); background: var(--accent-cyan-soft); }

/* 活动筛选 chip 条 —— 「全部动态」当前筛选可视化 */
.active-filters-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  background: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  flex-wrap: wrap;
  animation: fadeUp .25s ease;
}
.active-filters-label {
  font-size: 11px;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
}
.active-filters-chips {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  background: var(--accent-cyan-soft);
  border: 1px solid rgba(34, 211, 238, .35);
  border-radius: 999px;
  color: var(--accent-cyan);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all .15s ease;
  animation: fadeUp .2s ease backwards;
}
.filter-chip:hover {
  background: rgba(34, 211, 238, .22);
  border-color: var(--accent-cyan);
}
.filter-chip-x {
  /* —— button 原生样式重置：解决"打叉按钮不渲染"问题 —— */
  background: transparent;
  border: none;
  padding: 0;
  margin: 0;
  outline: none;
  -webkit-appearance: none;
  appearance: none;
  /* —— 布局/外观 —— */
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  /* —— 字符样式 —— */
  font-size: 14px;
  line-height: 1;
  color: inherit;          /* 继承父级 filter-chip 的主题色 */
  opacity: .75;
  font-weight: 900;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;  /* 避免 × 字符被等宽字体替代成方块 */
  cursor: pointer;
  transition: opacity .15s ease, background-color .15s ease;
}
.filter-chip-x:hover {
  opacity: 1;
  background-color: currentColor;
  background-color: color-mix(in srgb, currentColor 15%, transparent);
}
.filter-chip-x:active {
  transform: scale(0.92);
}
.filter-chip:hover .filter-chip-x { opacity: 1; }
.filter-chip-clear-all {
  padding: 4px 10px;
  background: transparent;
  border: 1px dashed var(--border-color);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all .15s ease;
}
.filter-chip-clear-all:hover {
  color: var(--text-primary);
  border-color: var(--text-secondary);
  border-style: solid;
}

.topbar-trending .mode-tabs .mode-tab { padding: 6px 11px; font-size: 12px; }
.topbar-trending .view-btn { width: 30px; height: 26px; }
.topbar-trending .btn-refresh { padding: 7px 12px; font-size: 12px; }

/* Stats Bar */
.stats-bar { display: flex; align-items: center; gap: 24px; padding: 10px 20px; border-bottom: 1px solid var(--border-color); background: var(--bg-secondary); }
.stat-item { display: flex; align-items: baseline; gap: 6px; }
.stat-value { font-size: 17px; font-weight: 700; color: var(--text-primary); }
.stat-value.highlight { color: var(--accent-cyan); }
.stat-value.live { color: var(--accent-emerald); position: relative; }
.stat-value.live::before { content: ''; position: absolute; left: -10px; top: 50%; transform: translateY(-50%); width: 5px; height: 5px; background: var(--accent-emerald); border-radius: 50%; box-shadow: 0 0 6px var(--accent-emerald); animation: pulse 2s infinite; }
.stat-label { font-size: 11px; color: var(--text-muted); }
.stat-item.time { margin-left: auto; display: flex; align-items: center; gap: 6px; color: var(--text-muted); font-size: 12px; }
.stat-item.time svg { width: 14px; height: 14px; }
.panel-toggle { width: 28px; height: 28px; display: grid; place-items: center; background: transparent; border: var(--panel-border); border-radius: 6px; color: var(--text-muted); cursor: pointer; transition: all .2s; }
.panel-toggle:hover { border-color: var(--border-active); color: var(--accent-cyan); }
.panel-toggle svg { width: 16px; height: 16px; }

/* Feed */
.feed { flex: 1; min-height: 0; padding: 16px 24px; overflow-y: auto; }
.loading-state, .error-state, .empty-state { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-md); padding: 60px; color: var(--text-muted); }
.spinner { width: 32px; height: 32px; border: 3px solid var(--border-color); border-top-color: var(--accent-cyan); border-radius: 50%; animation: spin .8s linear infinite; }

/* Skeleton */
.skeleton { pointer-events: none; }
.skeleton-tags { display: flex; gap: 6px; margin-bottom: 8px; }
.skeleton-tag { width: 40px; height: 16px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
.skeleton-time { width: 50px; height: 12px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; margin-top: 8px; }
.skeleton-title { width: 85%; height: 18px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; margin-bottom: 10px; }
.skeleton-summary { display: flex; flex-direction: column; gap: 6px; margin-bottom: 12px; }
.skeleton-summary span { height: 12px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
.skeleton-meta { display: flex; justify-content: space-between; margin-top: 8px; }
.skeleton-source { width: 80px; height: 10px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
.skeleton-link { width: 60px; height: 10px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
.skeleton-gh-header { width: 60%; height: 16px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; margin-bottom: 10px; }
.skeleton-gh-desc { width: 90%; height: 12px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; margin-bottom: 16px; }
.skeleton-gh-stats { display: flex; gap: var(--space-md); }
.skeleton-gh-stats::before, .skeleton-gh-stats::after { content: ''; width: 60px; height: 12px; background: linear-gradient(90deg, var(--bg-hover) 25%, var(--bg-card) 50%, var(--bg-hover) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

.error-state button, .empty-state button { padding: 8px 20px; background: var(--accent-cyan); border: none; border-radius: 6px; color: var(--bg-primary); font-weight: 600; cursor: pointer; }
.feed-list { display: flex; flex-direction: column; gap: 10px; }
.recommendation-snapshot-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 10px;
  padding: 8px 10px;
