  border-radius: 8px;
  background: var(--surface-workbench-control, var(--surface-card));
  color: var(--text-muted);
  font-size: 12px;
}
.recommendation-snapshot-meta strong { color: var(--text-primary); }

/* 精准推荐 / 全部动态 的排序说明条 */
.precision-meta-bar,
.discover-meta-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 8px 12px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control, var(--surface-card));
  font-size: 12px;
  color: var(--text-muted);
}
.precision-meta-title,
.discover-meta-title {
  font-weight: 700;
  font-size: 13px;
  color: var(--text-primary);
}
.precision-meta-chip,
.discover-meta-chip {
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  background: color-mix(in srgb, var(--accent-cyan, #22d3ee) 12%, transparent);
  color: var(--accent-cyan, #22d3ee);
