}
.precision-meta-desc,
.discover-meta-desc {
  flex: 1;
  min-width: 200px;
  font-size: 11px;
  line-height: 1.5;
}

/* Load More Sentinel */
.load-more-area { display: flex; align-items: center; justify-content: center; gap: var(--space-sm); padding: 20px 0; color: var(--text-muted); font-size: 13px; }
.form-group-flex { flex: 1; }
.load-more-spinner { display: flex; align-items: center; gap: 10px; }
.load-more-spinner .spinner { width: 20px; height: 20px; border-width: 2px; }
.load-more-hint { opacity: .6; }
.load-more-done { opacity: .4; }

/* Section Header */
.section-header { margin-bottom: 20px; }
.section-title { display: flex; align-items: center; gap: 10px; font-size: 18px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }
.section-title svg { width: 22px; height: 22px; color: var(--accent-cyan); }
.section-desc { font-size: 13px; color: var(--text-muted); }

.agent-home { display: flex; flex-direction: column; gap: 18px; width: min(1440px, 100%); margin: 0 auto; padding: 8px 0 32px; }
.agent-home-hero { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 22px; border: var(--panel-border); border-radius: var(--radius-card); background: var(--bg-card); }
.agent-home-hero h1 { margin: 6px 0 8px; color: var(--text-primary); font-size: 30px; line-height: 1.1; }
.agent-home-hero p { max-width: 660px; color: var(--text-secondary); font-size: 14px; line-height: 1.7; }
.agent-workflow-layout { display: grid; grid-template-columns: minmax(260px, .75fr) minmax(460px, 1.2fr) minmax(360px, .95fr); gap: 14px; align-items: start; }
.agent-workflow-panel { min-height: 420px; padding: 18px; border: var(--panel-border); border-radius: var(--radius-card); background: var(--bg-card); }
.agent-scope-selector { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-sm); margin-bottom: 12px; }
.agent-scope-selector button { min-width: 0; padding: 10px; border: var(--panel-border); border-radius: 8px; background: var(--surface-workbench-control); color: var(--text-secondary); cursor: pointer; text-align: left; }
.agent-scope-selector button:hover, .agent-scope-selector button.active { border-color: var(--border-active); background: var(--surface-workbench-ai); color: var(--text-primary); }
.agent-scope-selector span, .agent-scope-selector small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.agent-scope-selector span { color: var(--text-primary); font-size: 12px; font-weight: 800; }
.agent-scope-selector small { margin-top: 4px; color: var(--text-muted); font-size: 10px; font-weight: 700; }
.agent-workflow-missions { display: flex; flex-direction: column; gap: var(--space-sm); }
.agent-workflow-mission { padding: 12px; border: var(--panel-border); border-radius: 9px; background: var(--surface-workbench-control); color: var(--text-secondary); text-align: left; cursor: pointer; transition: border-color .18s ease, background .18s ease, transform .18s ease; }
.agent-workflow-mission:hover, .agent-workflow-mission.active { border-color: var(--border-active); background: var(--surface-workbench-ai); transform: translateY(-1px); }
.agent-workflow-mission span { display: block; color: var(--text-primary); font-size: 13px; font-weight: 800; }
.agent-workflow-mission small { display: block; margin-top: 4px; color: var(--accent-cyan); font-size: 11px; font-weight: 700; }
.agent-custom-run { display: flex; flex-direction: column; gap: var(--space-sm); margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--border-color); }
.agent-custom-run label { color: var(--text-primary); font-size: 12px; font-weight: 800; }
.agent-custom-run textarea { width: 100%; resize: vertical; min-height: 92px; padding: 10px; border: var(--panel-border); border-radius: 8px; background: var(--bg-primary); color: var(--text-primary); font-size: 12px; line-height: 1.6; outline: none; }
.agent-custom-run textarea:focus { border-color: var(--border-active); }
.agent-custom-run button, .agent-result-actions button, .agent-source-strategy button, .agent-result-error button { min-height: 34px; padding: 0 12px; border: var(--panel-border); border-radius: 8px; background: var(--surface-workbench-control); color: var(--text-primary); font-weight: 800; cursor: pointer; }
.agent-custom-run button:hover, .agent-result-actions button:hover, .agent-source-strategy button:hover, .agent-result-error button:hover { border-color: var(--border-active); background: var(--accent-cyan-soft); color: var(--accent-cyan); }
.agent-context-grid { display: grid; grid-template-columns: 1fr; gap: var(--space-sm); }
.agent-context-grid div { padding: 11px; border: var(--panel-border); border-radius: 8px; background: var(--surface-workbench-control); }
.agent-context-grid span { display: block; margin-bottom: 5px; color: var(--text-muted); font-size: 11px; font-weight: 700; }
.agent-context-grid strong { display: block; color: var(--text-primary); font-size: 13px; line-height: 1.5; }
.agent-source-strategy { margin-top: 12px; padding: 12px; border: 1px solid var(--accent-cyan-border); border-radius: 9px; background: var(--surface-workbench-ai); }
.agent-source-strategy strong { color: var(--text-primary); font-size: 13px; }
.agent-source-strategy p { margin: 6px 0 10px; color: var(--text-secondary); font-size: 12px; line-height: 1.7; }
.agent-result-loading, .agent-result-empty, .agent-result-error { min-height: 260px; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: var(--space-md); color: var(--text-muted); text-align: center; }
.agent-result-content { min-height: 310px; max-height: 58vh; overflow: auto; padding: 14px; border: var(--panel-border); border-radius: 9px; background: var(--bg-primary); color: var(--text-primary); white-space: pre-wrap; font: 13px/1.75 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
.agent-result-actions { display: flex; gap: var(--space-sm); justify-content: flex-end; margin-top: 12px; }
.workflow-run-panel {
  margin-bottom: 12px;
  padding: 12px;
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--surface-workbench-control);
}

.workflow-run-head {
