.workflow-validation-head strong {
  display: block;
  margin-top: 3px;
  color: var(--text-primary);
  font-size: 13px;
}

.workflow-import-actions button,
.workflow-template-card {
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--bg-primary);
  color: var(--text-primary);
  cursor: pointer;
}

.workflow-import-actions button {
  min-height: 32px;
  padding: 0 10px;
  font-size: 12px;
  font-weight: 850;
}

.workflow-import-actions button:hover,
.workflow-template-card:hover {
  border-color: var(--border-active);
  background: var(--surface-workbench-ai);
}

.workflow-template-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-sm);
}

.workflow-template-card {
  min-height: 122px;
  padding: 10px;
  text-align: left;
}

.workflow-template-card strong {
  display: block;
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.35;
}

.workflow-template-card p {
  margin: 6px 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.5;
}

.workflow-template-card small {
  display: block;
  margin-bottom: 6px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 800;
  line-height: 1.35;
}

.workflow-template-card span {
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 850;
}

.workflow-validation-panel.ready {
  border-color: var(--accent-cyan-border);
  background: var(--accent-cyan-softer);
}

.workflow-validation-panel.blocked {
  border-color: rgba(239, 68, 68, .28);
}

.workflow-validation-head em {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--bg-primary);
  color: var(--accent-cyan);
  font-size: 13px;
  font-style: normal;
  font-weight: 900;
}

.workflow-validation-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.workflow-validation-item {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: var(--space-sm);
  align-items: center;
  padding: 8px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--bg-primary);
}

.workflow-validation-item > span {
  display: grid;
  place-items: center;
  min-height: 24px;
  border-radius: 7px;
  background: var(--surface-workbench-control);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 900;
}

.workflow-validation-item.ok > span {
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}

.workflow-validation-item.bad > span {
  background: rgba(239, 68, 68, .12);
  color: #ef4444;
}

.workflow-validation-item.warn > span {
  background: rgba(245, 158, 11, .14);
  color: #d97706;
}

.workflow-validation-item p {
  margin: 0;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.35;
}

.workflow-validation-item small {
  display: block;
  margin-top: 3px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
}

.workflow-draft-form label,
.workflow-node-editor label {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.workflow-draft-form span,
.workflow-node-editor span,
.workflow-node-editor-head span,
.workflow-blueprint-preview span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
}

.workflow-draft-form input,
.workflow-draft-form textarea,
.workflow-node-editor input,
.workflow-node-editor textarea,
.workflow-node-editor select,
.workflow-add-row select {
  width: 100%;
  padding: 9px 10px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
}

.workflow-draft-form textarea,
.workflow-node-editor textarea {
  resize: vertical;
}

.workflow-canvas {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.workflow-node-frame {
  position: relative;
  min-width: 0;
}

.workflow-node-frame.dragging {
  opacity: .55;
}

.workflow-builder-node {
  width: 100%;
  min-height: 128px;
  padding: 12px;
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--surface-workbench-control);
  color: var(--text-secondary);
  text-align: left;
  cursor: pointer;
}

.workflow-connector {
  position: absolute;
  right: -15px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border: 1px solid var(--accent-cyan-border);
  border-radius: 999px;
  background: var(--bg-card);
  color: var(--accent-cyan);
  font-size: 13px;
  font-weight: 900;
  pointer-events: none;
}

.workflow-node-frame:nth-child(2n) .workflow-connector {
  display: none;
}

.workflow-builder-node.active {
  border-color: var(--border-active);
  box-shadow: 0 0 0 1px var(--border-active);
}

.workflow-builder-node.disabled {
  opacity: .55;
}

.workflow-node-index {
  display: block;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 900;
}

.workflow-node-type {
  display: inline-flex;
  margin: 6px 0 8px;
  padding: 3px 7px;
  border-radius: 999px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  font-size: 10px;
  font-weight: 900;
}

.workflow-builder-node strong {
  display: block;
  margin-bottom: 5px;
  color: var(--text-primary);
  font-size: 14px;
}

.workflow-builder-node p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.workflow-builder-node small {
  display: inline-flex;
  max-width: 100%;
  margin-top: 8px;
  padding: 4px 7px;
  border: var(--panel-border);
  border-radius: 7px;
  background: var(--bg-primary);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 850;
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
}

.workflow-add-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.workflow-add-row button,
.workflow-delete-node {
  min-height: 34px;
  padding: 0 12px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
  color: var(--text-primary);
  font-weight: 800;
  cursor: pointer;
}

.workflow-add-row button:hover,
.workflow-delete-node:hover {
  border-color: var(--border-active);
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}

.workflow-node-editor-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.workflow-node-editor-head strong {
  display: block;
  color: var(--text-primary);
  font-size: 14px;
}

.workflow-node-tools {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.workflow-node-tools button {
  min-height: 28px;
  padding: 0 9px;
  border: var(--panel-border);
  border-radius: 7px;
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.workflow-node-tools button:hover {
  border-color: var(--border-active);
  color: var(--accent-cyan);
}

.workflow-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 800;
}

.workflow-node-editor-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.workflow-node-editor-grid.condition-grid {
  grid-template-columns: minmax(0, 1.2fr) minmax(74px, .5fr) minmax(86px, .55fr);
}

.workflow-node-relations {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-sm);
}

.workflow-node-relations div {
  padding: 10px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--bg-primary);
}

.workflow-node-relations span {
  display: block;
  margin-bottom: 5px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
}

.workflow-node-relations strong {
  color: var(--text-primary);
  font-size: 13px;
}

.workflow-blueprint-preview {
  padding: 12px;
  border: 1px solid var(--accent-cyan-border);
  border-radius: 10px;
  background: var(--accent-cyan-softer);
}

.workflow-blueprint-preview p {
  margin: 6px 0 0;
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.6;
}

.workflow-hint {
  margin: 6px 0 0;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--bg-secondary);
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
  border: 1px dashed var(--panel-border);
}

.workflow-checkbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  font-size: 12px;
  color: var(--text-secondary);
}
.workflow-checkbox-row input[type="checkbox"] {
  margin: 0;
  flex-shrink: 0;
}

/* 子工作流节点 */
.workflow-node-subworkflow {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--accent-pink-border, rgba(236, 72, 153, .35));
  border-radius: 8px;
  background: rgba(236, 72, 153, .06);
}

/* 并行节点 */
.workflow-node-parallel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
  border: 1px solid rgba(249, 115, 22, .35);
  border-radius: 8px;
  background: rgba(249, 115, 22, .06);
}

.workflow-branches-list,
.workflow-routes-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.workflow-branches-head,
.workflow-routes-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 600;
}

.workflow-branch-add,
.workflow-route-add {
  padding: 4px 10px;
  font-size: 12px;
  color: var(--accent-cyan);
  background: transparent;
  border: 1px solid var(--accent-cyan-border);
  border-radius: 6px;
  cursor: pointer;
  transition: all .15s;
}
.workflow-branch-add:hover,
.workflow-route-add:hover {
  background: var(--accent-cyan-softer);
}

.workflow-branch-item {
  padding: 8px;
  border: 1px solid var(--panel-border);
  border-radius: 6px;
  background: var(--bg-primary);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.workflow-branch-row {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
}

.workflow-branch-name,
.workflow-route-value {
  min-width: 0;
  padding: 4px 8px;
  font-size: 12px;
  border: 1px solid var(--panel-border);
  border-radius: 4px;
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.workflow-branch-agent {
  padding: 4px 8px;
  font-size: 12px;
  border: 1px solid var(--panel-border);
  border-radius: 4px;
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.workflow-branch-remove,
.workflow-route-remove {
  padding: 4px 10px;
  font-size: 12px;
  color: var(--accent-rose, #f43f5e);
  background: transparent;
  border: 1px solid rgba(244, 63, 94, .4);
  border-radius: 4px;
  cursor: pointer;
  transition: all .15s;
}
.workflow-branch-remove:hover,
.workflow-route-remove:hover {
  background: rgba(244, 63, 94, .1);
}

/* 路由节点 */
.workflow-node-router {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
  border: 1px solid rgba(168, 85, 247, .35);
  border-radius: 8px;
  background: rgba(168, 85, 247, .06);
}

.workflow-route-item {
  padding: 8px;
  border: 1px solid var(--panel-border);
  border-radius: 6px;
  background: var(--bg-primary);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.workflow-route-match {
  display: grid;
  grid-template-columns: minmax(80px, .6fr) minmax(0, 1.4fr);
  gap: 6px;
  align-items: center;
}

.workflow-route-target {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 6px;
  align-items: center;
}

.workflow-route-default {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px dashed rgba(168, 85, 247, .4);
  border-radius: 6px;
  background: rgba(168, 85, 247, .04);
  font-size: 12px;
  color: var(--text-secondary);
}
.workflow-route-default select {
  flex: 1;
  min-width: 0;
  padding: 4px 8px;
  font-size: 12px;
  border: 1px solid var(--panel-border);
  border-radius: 4px;
  background: var(--bg-secondary);
  color: var(--text-primary);
}
@media (max-width: 1280px) { .agent-workflow-layout { grid-template-columns: 1fr; } .agent-workflow-panel { min-height: auto; } }

.agent-workflow-layout .context-panel {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-md);
  min-height: 0;
  padding: 12px 14px;
  order: -1;
}
.agent-workflow-layout .context-panel .section-header {
  margin: 0;
}
.agent-workflow-layout .context-panel .section-desc,
.agent-workflow-layout .context-panel .agent-source-strategy {
  display: none;
}
.agent-workflow-layout .context-panel .agent-context-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.agent-workflow-layout .context-panel .agent-context-grid div {
  padding: 8px;
}

@media (max-width: 1280px) {
  .workflow-canvas,
  .workflow-node-editor-grid,
  .workflow-template-bar,
  .workflow-node-relations {
    grid-template-columns: 1fr;
  }

  .workflow-connector {
    display: none;
  }
}

.source-strategy-panel { display: flex; justify-content: space-between; gap: 16px; align-items: center; margin-bottom: 16px; padding: 14px; border: 1px solid var(--accent-cyan-border); border-radius: 10px; background: var(--surface-workbench-ai); }
.source-strategy-panel span { color: var(--accent-cyan); font-size: 10px; font-weight: 900; letter-spacing: .12em; text-transform: uppercase; }
.source-strategy-panel strong { display: block; margin-top: 4px; color: var(--text-primary); font-size: 14px; }
.source-strategy-panel p { margin-top: 6px; color: var(--text-secondary); font-size: 12px; line-height: 1.6; }
.source-strategy-panel button { flex-shrink: 0; min-height: 34px; padding: 0 12px; border: 1px solid var(--border-active); border-radius: 8px; background: var(--accent-cyan-soft); color: var(--accent-cyan); font-weight: 800; cursor: pointer; }
.source-strategy-panel button:disabled { cursor: not-allowed; opacity: .6; }

.source-ops-dashboard {
  display: flex;
