}
.source-focus-strip button small {
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
}

.source-action-queue {
  display: grid;
  grid-template-columns: minmax(180px, .42fr) minmax(0, 1fr);
  gap: 10px;
  padding: 10px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
}
.source-action-queue-title span {
  color: var(--accent-amber);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
