  font-size: 11px;
  line-height: 1.5;
}
.source-action-item button {
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid var(--border-active);
  border-radius: 8px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.source-action-item button:hover {
  background: var(--surface-workbench-ai);
}

.source-simplify-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
