  margin-bottom: 12px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
}
.source-simplify-toggle button {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid var(--border-active);
  border-radius: 8px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
.source-simplify-toggle p {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}
.sources-simple-mode .source-type-tabs,
.sources-simple-mode .grade-stats-panel,
.sources-simple-mode .builtin-stats-panel,
.sources-simple-mode .builtin-operations-bar,
.sources-simple-mode .source-filter-bar,
.sources-simple-mode .builtin-sources-grid,
.sources-simple-mode .custom-sources-grid,
.sources-simple-mode .monitor-control-panel,
.sources-simple-mode .source-batch-actions,
.sources-simple-mode .source-form-modal-overlay,
.sources-simple-mode .all-sources-verify-results {
  display: none;
}

.source-discovery-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 12px;
  padding: 12px;
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--bg-card);
}
.source-discovery-copy span {
  color: var(--accent-emerald);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
}
.source-discovery-copy strong {
  display: block;
  margin-top: 4px;
  color: var(--text-primary);
  font-size: 14px;
}
.source-discovery-copy p {
  margin-top: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.6;
}
.source-discovery-form {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) auto;
  gap: var(--space-sm);
}
.source-discovery-form button,
.source-discovery-actions button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--border-active);
  border-radius: 8px;
  background: var(--surface-workbench-control);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
.source-discovery-form button:hover:not(:disabled),
.source-discovery-actions button:hover {
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}
.source-discovery-form button:disabled {
  cursor: not-allowed;
  opacity: .6;
}
.source-discovery-error {
  padding: 9px 10px;
  border: 1px solid rgba(248, 113, 113, .25);
  border-radius: 8px;
  background: rgba(248, 113, 113, .08);
  color: var(--accent-rose);
  font-size: 12px;
}
.source-discovery-results {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}
.source-discovery-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
}
.source-discovery-main {
  min-width: 0;
}
.source-discovery-main strong {
  display: block;
  color: var(--text-primary);
  font-size: 13px;
}
.source-discovery-main span {
  display: block;
  overflow: hidden;
  margin-top: 3px;
  color: var(--accent-cyan);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.source-discovery-main p {
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}
.source-discovery-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  max-width: 210px;
}
.source-discovery-meta span {
  padding: 3px 7px;
  border: var(--panel-border);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 700;
}
@media (max-width: 720px) {
  .source-ops-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .source-ops-actions {
    justify-content: flex-start;
  }
  .source-ops-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .source-focus-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .source-action-queue,
  .source-action-item {
    grid-template-columns: 1fr;
  }
  .source-action-item button {
    width: 100%;
  }
  .source-discovery-form,
  .source-discovery-card {
    grid-template-columns: 1fr;
  }
  .source-discovery-meta {
    justify-content: flex-start;
    max-width: none;
  }
}

/* Event Clusters */
.event-clusters { display: flex; flex-direction: column; gap: 10px; margin-bottom: 16px; }
.event-cluster-card { background: var(--bg-card); border: 1px solid var(--border-active); border-radius: 10px; overflow: hidden; }
.cluster-header { display: flex; align-items: center; gap: var(--space-sm); padding: 12px 14px; cursor: pointer; transition: background .15s; }
.cluster-header:hover { background: var(--bg-hover); }
.cluster-icon { width: 16px; height: 16px; color: var(--accent-violet); display: flex; }
.cluster-icon svg { width: 16px; height: 16px; }
.cluster-keyword { font-size: 13px; font-weight: 600; color: var(--text-primary); flex: 1; }
.cluster-count { font-size: 11px; padding: 2px 8px; background: rgba(167, 139, 250, .15); border-radius: 4px; color: var(--accent-violet); }
.cluster-chevron { width: 16px; height: 16px; color: var(--text-muted); transition: transform .2s; display: flex; }
.cluster-chevron svg { width: 16px; height: 16px; }
.cluster-chevron.open { transform: rotate(180deg); }
.cluster-items { border-top: 1px solid var(--border-color); padding: 8px; display: flex; flex-direction: column; gap: 6px; }

/* News Item - 轻量化边框：平时淡边框，hover 才浮起 */
.news-item { display: flex; gap: 16px; padding: 14px 16px; background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 10px; transition: border-color .2s, transform .2s, box-shadow .2s; position: relative; }
:root[data-mode="light"] .news-item { box-shadow: 0 2px 10px rgba(var(--shadow-tint), .04); }
:root[data-mode="light"] .news-item:hover { box-shadow: 0 6px 20px rgba(var(--shadow-tint), .07), 0 1px 3px rgba(var(--shadow-tint), .03); }
/* 视口淡入：默认隐藏，进入视口后加 news-item-visible 触发动画 */
.news-item.news-item-hidden { opacity: 0; transform: translateY(12px); }
.news-item.news-item-visible { animation: fadeUp .4s ease forwards; }
@media (prefers-reduced-motion: reduce) {
  .news-item.news-item-hidden { opacity: 1; transform: none; }
  .news-item.news-item-visible { animation: none; }
}
.news-item:hover { border-color: var(--border-active); transform: translateY(-2px); box-shadow: 0 4px 14px var(--border-glow); }
.news-item.focused { border-color: var(--accent-cyan); box-shadow: 0 0 0 1px var(--accent-cyan), 0 0 18px var(--border-glow); }
.news-item.followed { border-left: 3px solid var(--accent-amber); }

/* Follow Badge */
.follow-badge { position: absolute; top: 8px; right: 10px; font-size: 9px; font-weight: 800; padding: 2px 7px; border: 1px solid var(--accent-amber-soft); background: var(--accent-amber-soft); border-radius: 999px; color: var(--accent-amber); }

/* NEW 角标：5分钟内新资讯的视觉提示 */
.new-badge { position: absolute; top: 8px; left: 10px; font-size: 10px; font-weight: 800; padding: 2px 8px; border: none; border-radius: 999px; color: #fff; background: linear-gradient(135deg, #ef4444, #f97316); box-shadow: 0 2px 8px rgba(239, 68, 68, .35); animation: newPulse 1.6s ease-in-out 3; z-index: 2; letter-spacing: .5px; }
@keyframes newPulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.08); opacity: .85; } }
@media (prefers-reduced-motion: reduce) { .new-badge { animation: none; } }

/* Compact View */
.compact-media-indicator { flex: 0 0 24px; width: 24px; height: 24px; display: grid; place-items: center; border: var(--panel-border); border-radius: 6px; background: var(--bg-hover); color: var(--text-muted); }
.compact-media-indicator svg { width: 13px; height: 13px; }
.compact-media-indicator.has-video { color: var(--accent-violet); border-color: rgba(167, 139, 250, .3); background: rgba(167, 139, 250, .1); }
.compact-media-indicator.has-image { color: var(--accent-cyan); border-color: var(--accent-cyan-border); background: var(--accent-cyan-soft); }

/* Card View */
.news-item.view-card { flex-direction: column; gap: var(--space-md); }
.news-item.view-card .item-left { flex-direction: row; width: 100%; justify-content: space-between; }
.news-item.view-card .item-title { font-size: 15px; -webkit-line-clamp: 2; }
.news-item.view-card .item-summary { -webkit-line-clamp: 2; }

/* Card View Grid Layout */
.feed-list.card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: var(--space-md); }
.feed-list.card-grid .news-item { flex-direction: column; gap: 6px; min-height: 180px; }
.feed-list.card-grid .item-left { flex-direction: row; width: 100%; justify-content: space-between; align-items: flex-start; }
.feed-list.card-grid .item-tags { display: flex; flex-wrap: wrap; gap: var(--space-xs); }
.feed-list.card-grid .item-title { font-size: 15px; font-weight: 600; -webkit-line-clamp: 2; margin-bottom: 2px; }
.feed-list.card-grid .item-summary { font-size: 13px; -webkit-line-clamp: 3; flex: 1; margin: 0; }
.feed-list.card-grid .item-meta { margin-top: auto; flex-direction: column; gap: 4px; }
.feed-list.card-grid .item-tags-row:empty { display: none; }
.feed-list.card-grid .item-footer { flex-wrap: wrap; gap: 6px; }
.feed-list.card-grid .item-source-container { flex-wrap: wrap; gap: 4px; }
.feed-list.card-grid .item-content-row { flex-direction: column; }
.feed-list.card-grid .item-media,
.feed-list.card-grid .item-media-thumb,
.feed-list.card-grid .item-media-video-link,
.feed-list.card-grid .item-media-video-only { width: 100%; }
.feed-list.card-grid .item-media-thumb,
.feed-list.card-grid .item-media-video-link,
.feed-list.card-grid .item-media-video-only { height: 132px; }

.item-left { display: flex; flex-direction: column; align-items: center; gap: 7px; min-width: 44px; padding-top: 2px; }
.item-tags { display: flex; flex-direction: column; gap: var(--space-xs); }
.item-mode, .item-region { min-width: 42px; padding: 3px 7px; border-radius: 6px; font-size: 10px; font-weight: 800; text-align: center; }
.mode-flash { background: rgba(251, 191, 36, .15); color: var(--accent-amber); }
.mode-deep { background: rgba(167, 139, 250, .15); color: var(--accent-violet); }
.mode-technical { background: rgba(52, 211, 153, .15); color: var(--accent-emerald); }
.item-time { font-size: 11px; color: var(--text-muted); white-space: nowrap; }

/* 统一幽灵图标按钮：默认透明无边框，hover 才显底色，active 语义色填充 */
.item-actions { display: flex; align-items: center; gap: 2px; opacity: 0; transition: opacity .15s; flex-shrink: 0; margin-left: auto; }
.news-item:hover .item-actions,
.news-item.focused .item-actions { opacity: 1; }
.item-action-btn {
  width: 26px; height: 26px;
  display: grid; place-items: center;
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: 6px;
  transition: background .15s, color .15s;
}
.item-action-btn svg { width: 14px; height: 14px; }
.item-action-btn:hover { background: var(--bg-hover, rgba(125,125,125,.12)); color: var(--text-secondary); }
.item-action-btn:disabled { opacity: .5; cursor: wait; }
.item-action-btn.loading svg { animation: spin .9s linear infinite; }
.item-action-btn.bookmark-btn.active { color: var(--accent-amber); }
.item-action-btn.bookmark-btn:hover { color: var(--accent-amber); background: rgba(245,158,11,.12); }
.item-action-btn.add-material-btn.active { color: var(--accent-violet); }
.item-action-btn.add-material-btn:hover { color: var(--accent-violet); background: rgba(167,139,250,.12); }
.item-action-btn.summary-btn:hover { color: var(--accent-cyan); background: var(--accent-cyan-softer); }
.item-action-btn.translate-btn.active { color: var(--accent-blue, #60a5fa); }
.item-action-btn.translate-btn:hover { color: var(--accent-blue, #60a5fa); background: rgba(96,165,250,.12); }
/* 紧凑视图：按钮常显（行高小，hover 不便） */

.item-main { flex: 1; min-width: 0; }
.item-content-row { display: flex; gap: 14px; align-items: flex-start; }
.item-text { flex: 1; min-width: 0; }
.item-media { flex-shrink: 0; width: 140px; }
.item-media-thumb { position: relative; width: 140px; height: 90px; border-radius: 8px; overflow: hidden; cursor: pointer; background: var(--bg-card); border: var(--panel-border); }
.item-media-thumb::after { content: ''; position: absolute; inset: auto 0 0; z-index: 1; height: 36%; background: linear-gradient(180deg, transparent, rgba(0, 0, 0, .18)); pointer-events: none; }
.item-media-thumb img { width: 100%; height: 100%; object-fit: cover; transition: transform .2s; }
.item-media-thumb img[style*="display: none"] + .item-media-play { display: none; }
.item-media-thumb:hover img { transform: scale(1.05); }
.item-media-play { position: absolute; inset: 0; z-index: 2; display: grid; place-items: center; background: rgba(0, 0, 0, .4); border-radius: 8px; color: white; }
.item-media-play svg { width: 24px; height: 24px; }

/* 多图网格（2-4 张） */
.item-media-play.video-play { background: rgba(0, 0, 0, .5); }
.item-media-play.video-play svg { width: 32px; height: 32px; filter: drop-shadow(0 2px 4px rgba(0, 0, 0, .3)); }
.item-media-video-link { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-xs); width: 140px; height: 90px; border-radius: 8px; background: var(--bg-card); border: var(--panel-border); color: var(--text-secondary); font-size: 12px; transition: all .15s; }
.item-media-video-link:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.item-media-video-link svg { width: 20px; height: 20px; }
.item-media-video-only { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; width: 140px; height: 90px; border-radius: 8px; background: var(--bg-card); border: var(--panel-border); color: var(--text-secondary); font-size: 12px; transition: all .15s; }
.item-media-video-only:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); background: var(--accent-cyan-soft); }
.item-title { font-size: 15px; font-weight: 800; color: var(--text-primary); margin-bottom: 6px; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; transition: color .15s; }
.news-item.followed .item-title { padding-right: 54px; }
.item-rank { color: var(--accent-cyan); font-weight: 900; margin-right: 5px; }
.news-item:hover .item-title { color: var(--accent-cyan); }
.item-summary { font-size: 12px; color: var(--text-secondary); line-height: 1.6; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 10px; }
.item-meta { display: flex; flex-direction: column; gap: 6px; }
.item-tags-row { display: flex; gap: 5px; flex-wrap: wrap; }
/* 网格视图顶部标签条：mode/region/赛道横排，明显直观 */
.item-top-tags { display: none; gap: 5px; flex-wrap: wrap; align-items: center; margin-bottom: 8px; }
.feed-list.card-grid .item-top-tags { display: flex; }
.feed-list.card-grid .item-left .item-tags { display: none; }
.feed-list.card-grid .card-grid-hide { display: none; }
/* 网格视图标签样式增强：更明显的色块 */
.feed-list.card-grid .item-mode,
.feed-list.card-grid .item-region { min-width: auto; padding: 2px 8px; font-size: 10px; font-weight: 800; border-radius: 4px; letter-spacing: .02em; }
.feed-list.card-grid .item-tag { max-width: none; padding: 2px 8px; font-size: 10px; font-weight: 600; border-radius: 4px; }
.item-tag { max-width: 108px; padding: 3px 7px; background: var(--surface-workbench-action); border: var(--panel-border); border-radius: 999px; font-size: 10px; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* AI 评分标签：必读/关注（来自 /api/ai-insights 的 itemScores 回写） */
.ai-label-badge { display: inline-flex; align-items: center; gap: 4px; padding: 3px 8px; border-radius: 999px; font-size: 10px; font-weight: 700; letter-spacing: .3px; cursor: help; }
.ai-label-badge::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ai-label-must { background: linear-gradient(135deg, rgba(239, 68, 68, .15), rgba(249, 115, 22, .15)); color: #ef4444; border: 1px solid rgba(239, 68, 68, .35); }
.ai-label-watch { background: linear-gradient(135deg, rgba(59, 130, 246, .12), rgba(99, 102, 241, .12)); color: #3b82f6; border: 1px solid rgba(59, 130, 246, .3); }
.item-footer { display: flex; align-items: center; justify-content: space-between; gap: var(--space-sm); padding-top: 2px; }
.compact-footer { display: flex; align-items: center; gap: var(--space-sm); }
.item-source-container { display: flex; align-items: center; gap: 4px; min-width: 0; flex: 1; overflow: hidden; }
.item-source { font-size: 11px; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.item-link { display: flex; align-items: center; gap: var(--space-xs); font-size: 12px; font-weight: 800; color: var(--accent-cyan); text-decoration: none; transition: opacity .15s; }
.item-link:hover { opacity: .78; }
.item-link svg { width: 12px; height: 12px; }

/* AI Summary */
.ai-summary { margin-top: 10px; padding: 10px 12px; background: rgba(167, 139, 250, .055); border: 1px solid rgba(167, 139, 250, .16); border-radius: 8px; animation: fadeUp .2s ease; }
.ai-summary-header { display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 700; color: var(--accent-violet); margin-bottom: 5px; }
.ai-summary-header svg { width: 14px; height: 14px; }
.ai-summary-content p { margin: 0; font-size: 12px; color: var(--text-secondary); line-height: 1.55; }

.recommendation-reason { margin: 10px 0 8px; padding: 10px 12px; background: rgba(20, 184, 166, .1); border: 1px solid rgba(20, 184, 166, .18); border-radius: 10px; animation: fadeUp .2s ease; }

/* Bookmark Item */
.bookmark-item .item-left { align-items: center; gap: var(--space-sm); }

/* Product Pages */
.product-page {
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: 8px 0 36px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.product-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 20px;
  padding: 22px;
  border: var(--panel-border);
  border-radius: var(--radius-card);
  background: var(--surface-workbench-ai);
  box-shadow: var(--shadow-card);
}

.product-hero h1 {
  margin: 6px 0 8px;
  color: var(--text-primary);
  font-size: 30px;
  line-height: 1.12;
  letter-spacing: 0;
}

.product-hero p {
  max-width: 680px;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.75;
}

.product-hero-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.secondary-action,
.profile-memory-panel .empty-state button {
  min-height: 40px;
  padding: 0 14px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
  color: var(--text-primary);
  font-weight: 800;
  cursor: pointer;
}

.secondary-action:hover,
.profile-memory-panel .empty-state button:hover {
  border-color: var(--border-active);
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}

.studio-module-grid,
.profile-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-md);
}

.studio-module-card,
.profile-summary-grid div,
.workflow-builder-preview,
.profile-control-panel,
.profile-memory-panel,
.studio-module-card {
  min-height: 186px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  text-align: left;
  color: inherit;
  cursor: pointer;
  transition: transform .18s ease, border-color .18s ease, background .18s ease;
}

.studio-module-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-active);
  background: var(--surface-workbench-ai);
}

.studio-module-meta { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: var(--space-md); color: var(--text-muted); font-size: 12px; }
.studio-module-meta strong { color: var(--accent-cyan); font-size: 13px; }
.studio-module-meta em { font-style: normal; font-weight: 800; }

.workflow-builder-preview,
.profile-memory-panel {
  padding: 16px;
}

.workflow-node-strip {
  display: grid;
  grid-template-columns: repeat(7, minmax(112px, 1fr));
  gap: var(--space-sm);
  overflow-x: auto;
}

.workflow-node-card {
  min-height: 126px;
  padding: 12px;
  border: 1px solid var(--accent-cyan-border);
  border-radius: 10px;
  background: linear-gradient(180deg, var(--accent-cyan-softer), transparent 120%), var(--surface-workbench-control);
}

.workflow-node-card span {
  display: block;
  margin-bottom: 8px;
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 900;
}

.workflow-node-card strong {
  display: block;
  margin-bottom: 6px;
  color: var(--text-primary);
  font-size: 13px;
}

.workflow-node-card p {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.studio-asset-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-md);
}

/* 快速创建按钮条 */
.studio-quick-create {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-md);
}
.quick-create-btn {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: 14px 16px;
  border: 1px dashed var(--border-active);
  border-radius: var(--radius-card);
  background: var(--surface-workbench-ai);
  cursor: pointer;
  transition: all .18s ease;
  text-align: left;
  color: inherit;
}
.quick-create-btn:hover {
  border-style: solid;
  border-color: var(--accent-cyan);
  background: var(--accent-cyan-soft);
  transform: translateY(-1px);
}
.quick-create-icon {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  flex-shrink: 0;
}
.quick-create-icon svg { width: 18px; height: 18px; }
.quick-create-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.quick-create-text strong { font-size: 14px; font-weight: 800; color: var(--text-primary); }
.quick-create-text em { font-style: normal; font-size: 11px; color: var(--text-muted); }

/* 主推模块卡高亮 */
.studio-module-card.primary {
  background: linear-gradient(135deg, var(--accent-cyan-soft), var(--surface-workbench-ai));
  border-color: var(--accent-cyan-border);
}

/* 工作流节点改为按钮后的交互态 */
.workflow-node-card {
  cursor: pointer;
  text-align: left;
  color: inherit;
  transition: transform .15s ease, border-color .15s ease;
  display: flex;
  flex-direction: column;
}
.workflow-node-card:hover {
  transform: translateY(-2px);
  border-color: var(--accent-cyan);
}
.workflow-node-cta {
  margin-top: auto;
  padding-top: 8px;
  font-size: 11px;
  font-weight: 800;
  color: var(--accent-cyan);
  font-style: normal;
}

/* 素材/文章列表 */
.studio-asset-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}
.studio-asset-list li {
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--surface-workbench-action);
  border: var(--panel-border);
}
.studio-asset-list-clickable li {
  cursor: pointer;
  position: relative;
  padding-right: 32px;
  transition: background var(--ease-fast), border-color var(--ease-fast);
}
.studio-asset-list-clickable li:hover {
  background: var(--bg-hover);
  border-color: var(--border-active);
}
.studio-asset-list-clickable li .studio-asset-open {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  opacity: .5;
  transition: opacity var(--ease-fast);
  display: inline-flex;
  align-items: center;
}
.studio-asset-list-clickable li:hover .studio-asset-open { opacity: 1; }
.studio-asset-list li strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.studio-asset-list li p {
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 工作空间文件预览：侧边滑出 panel（双击文件触发） */
.workspace-side-panel-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, .35);
  backdrop-filter: blur(2px);
  z-index: 195;
  animation: workspaceSideFadeIn var(--ease-base);
}
@keyframes workspaceSideFadeIn { from { opacity: 0; } to { opacity: 1; } }
.workspace-side-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  /* 从整个页面右侧抽出窗口（回滚到原 560px 抽屉式） */
  width: min(560px, 92vw);
  background: var(--bg-card-solid);
  border-left: 1px solid var(--border-color);
  box-shadow: -24px 0 60px rgba(0, 0, 0, .35);
  z-index: 200;
  display: flex;
  flex-direction: column;
  animation: workspaceSideSlideIn var(--ease-base);
}
@keyframes workspaceSideSlideIn { from { transform: translateX(100%); } to { transform: translateX(0); } }
@media (prefers-reduced-motion: reduce) {
  .workspace-side-panel { animation: none; }
  .workspace-side-panel-backdrop { animation: none; }
}
.workspace-side-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-md);
  padding: var(--space-lg) var(--space-xl);
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.workspace-side-panel-meta { flex: 1; min-width: 0; }
.workspace-side-panel-meta h3 {
  margin: 6px 0 0;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  word-break: break-word;
}
.workspace-side-panel-type {
  display: inline-block;
  padding: 2px 8px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .5px;
  text-transform: uppercase;
  color: var(--accent-cyan);
  background: var(--accent-cyan-soft);
  border-radius: 4px;
}
.workspace-side-panel-path {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono, ui-monospace, monospace);
  word-break: break-all;
}
.workspace-side-panel-close {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background var(--ease-fast), color var(--ease-fast);
  flex-shrink: 0;
}
.workspace-side-panel-close:hover { background: var(--bg-hover); color: var(--text-primary); }
.workspace-side-panel-body {
  padding: var(--space-lg) var(--space-xl);
  overflow-y: auto;
  flex: 1;
  font-size: 13px;
  line-height: 1.75;
  color: var(--text-secondary);
}
.workspace-side-panel-body h1, .workspace-side-panel-body h2, .workspace-side-panel-body h3 {
  color: var(--text-primary);
  margin: var(--space-md) 0 var(--space-sm);
  font-size: 15px;
}
.workspace-side-panel-body h1 { font-size: 17px; }
.workspace-side-panel-body p { margin: var(--space-sm) 0; }
.workspace-side-panel-body code {
  background: var(--surface-workbench-action);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 12px;
  font-family: var(--font-mono, ui-monospace, monospace);
}
.workspace-side-panel-body pre {
  background: var(--surface-workbench-action);
  padding: var(--space-md);
  border-radius: 8px;
  overflow-x: auto;
  margin: var(--space-md) 0;
  font-size: 12px;
}
.workspace-side-panel-body pre code { background: transparent; padding: 0; }
.workspace-side-panel-body a { color: var(--accent-cyan); }
.workspace-side-panel-body ul, .workspace-side-panel-body ol { padding-left: 1.4em; }
.workspace-side-panel-body blockquote {
  border-left: 3px solid var(--accent-cyan);
  padding-left: var(--space-md);
  margin: var(--space-sm) 0;
  color: var(--text-muted);
}
.workspace-side-panel-empty {
  color: var(--text-muted);
  text-align: center;
  padding: var(--space-2xl);
}
.workspace-side-panel-foot {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-sm);
  padding: var(--space-md) var(--space-xl);
  border-top: 1px solid var(--border-color);
  flex-shrink: 0;
}
.workspace-side-panel-link {
  padding: 6px 12px;
  font-size: 12px;
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  text-decoration: none;
  transition: all var(--ease-fast);
}
.workspace-side-panel-link:hover { border-color: var(--border-active); color: var(--text-primary); }
.workspace-side-panel-action {
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 600;
  background: var(--accent-cyan);
  color: var(--bg-primary);
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: opacity var(--ease-fast);
}
.workspace-side-panel-action:hover { opacity: .9; }
/* 预览 ⇄ 编辑 切换 + 编辑态样式（v3.1） */
.workspace-side-panel-head-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  flex-shrink: 0;
}
.workspace-side-panel-toggle {
  padding: 5px 12px;
  font-size: 12px;
  font-weight: 600;
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  cursor: pointer;
  transition: all var(--ease-fast);
}
.workspace-side-panel-toggle:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.workspace-side-panel-toggle.active {
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}
.workspace-side-panel-action.primary {
  background: var(--accent-cyan);
}
.workspace-side-panel-action:disabled {
  opacity: .45;
  cursor: not-allowed;
}
/* v12 预览格式扩展：图片 / HTML iframe / 通用代码文本 */
.wp-image-preview {
  max-width: 100%; max-height: 100%;
  object-fit: contain; border-radius: 8px; margin: auto; display: block;
}
.wp-html-preview {
  width: 100%; height: 100%; min-height: 260px; flex: 1;
  border: none; border-radius: 8px; background: #fff;
}
.wp-code-preview {
  margin: 0; flex: 1; min-height: 0; overflow: auto;
}

.workspace-preview-editor {
  width: 100%;
  min-height: 100%;
  flex: 1;
  resize: none;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12.5px;
  line-height: 1.7;
  white-space: pre-wrap;
  word-break: break-word;
}
.workspace-preview-editor::placeholder { color: var(--text-muted); }
.workspace-side-panel-loading {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: var(--text-muted);
  padding: var(--space-2xl);
  justify-content: center;
}

/* 双击提示：文件项右下角小标 */
.workspace-tree-file.has-dblclick::after {
  content: '双击';
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .5px;
  color: var(--text-muted);
  opacity: .4;
  pointer-events: none;
  transition: opacity var(--ease-fast);
}
.workspace-tree-file.has-dblclick:hover::after { opacity: .9; }
.workspace-tree-file { position: relative; }

/* CreativeWorkspace 内联预览（保留原样） */
.creative-toggle-preview {
  margin-top: var(--space-sm);
  background: transparent;
  border: 1px dashed var(--border-color);
  color: var(--text-muted);
  font-size: 11px;
  padding: 4px 10px;
  border-radius: 6px;
  cursor: pointer;
  transition: all var(--ease-fast);
}
.creative-toggle-preview:hover {
  color: var(--text-primary);
  border-color: var(--border-active);
}
.creative-asset-preview {
  margin-top: var(--space-sm);
  padding: var(--space-md);
  background: var(--surface-workbench-inset);
  border-radius: 8px;
  border: 1px solid var(--border-color);
  font-size: 12px;
  line-height: 1.7;
  color: var(--text-secondary);
  max-height: 320px;
  overflow-y: auto;
}
.creative-asset-preview h1, .creative-asset-preview h2, .creative-asset-preview h3 {
  color: var(--text-primary);
  margin: var(--space-sm) 0 var(--space-xs);
  font-size: 13px;
}
.creative-asset-preview p { margin: var(--space-xs) 0; }
.creative-asset-preview a { color: var(--accent-cyan); }
.creative-asset-preview code {
  background: var(--surface-workbench-action);
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 11px;
}
.studio-asset-empty strong { display: block; font-size: 14px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }
.studio-asset-empty p { margin: 0; font-size: 12px; color: var(--text-secondary); line-height: 1.6; }

.profile-summary-grid span {
  display: block;
  margin-bottom: 6px;
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .08em;
}

.profile-summary-grid div {
  min-height: 110px;
  padding: 14px;
}

.profile-summary-grid strong {
  display: block;
  color: var(--text-primary);
  font-size: 28px;
  line-height: 1;
}

.profile-summary-grid p {
  margin-top: 8px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.profile-learning-panel {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(280px, .9fr);
  gap: var(--space-md);
  padding: 16px;
  border: 1px solid var(--accent-cyan-border);
  border-radius: var(--radius-card);
  background: var(--surface-workbench-ai);
  box-shadow: var(--shadow-card);
}

.profile-learning-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.profile-learning-score {
  display: grid;
  gap: 6px;
}

.profile-learning-score strong {
  color: var(--text-primary);
  font-size: 38px;
  line-height: 1;
}

.profile-learning-score span {
  color: var(--accent-cyan);
  font-size: 12px;
  font-weight: 900;
}

.profile-learning-score p {
  max-width: 760px;
  margin: 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.7;
}

.profile-learning-actions {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.profile-learning-actions button {
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid var(--accent-cyan-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.profile-learning-actions button:hover {
  border-color: var(--border-active);
  color: var(--accent-cyan);
}

.profile-learning-side {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-sm);
}

.profile-learning-side div {
  min-width: 0;
  padding: 10px;
  border: var(--panel-border);
  border-radius: 9px;
  background: var(--surface-workbench-control);
}

.profile-learning-side span {
  display: block;
  margin-bottom: 6px;
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 900;
}

.profile-learning-side p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.profile-control-layout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-md);
}

.profile-control-panel {
  padding: 16px;
}

.profile-calibration-panel {
  padding: 16px;
  border: var(--panel-border);
  border-radius: var(--radius-card);
  background: var(--bg-card);
  box-shadow: var(--shadow-card);
}

.profile-calibration-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.profile-calibration-card {
  min-height: 118px;
  padding: 14px;
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--surface-workbench-control);
}

.profile-calibration-card span {
  display: block;
  margin-bottom: 8px;
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .06em;
}

.profile-calibration-card strong {
  display: block;
  color: var(--text-primary);
  font-size: 26px;
  line-height: 1;
}

.profile-calibration-card p {
  margin: 8px 0 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.priority-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.priority-row {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) minmax(130px, .8fr) 28px;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: var(--panel-border);
  border-radius: 9px;
  background: var(--surface-workbench-control);
}

.priority-row span {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 800;
}

.priority-row svg { width: 15px; height: 15px; color: var(--accent-cyan); }
.priority-row strong { color: var(--accent-cyan); font-size: 14px; text-align: right; }

.profile-tier-control {
  display: grid;
  grid-template-columns: repeat(3, minmax(82px, 1fr));
  gap: 4px;
  min-width: 0;
}

.profile-tier-control button {
  min-height: 32px;
  padding: 5px 7px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border-radius: 4px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: 'Courier New', monospace;
}

.profile-tier-control button:hover,
.profile-tier-control button:focus-visible {
  border-color: color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  color: color-mix(in srgb, var(--accent-cyan) 70%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 5%, transparent);
  outline: none;
}

.profile-tier-control button.active {
  border-color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  color: var(--accent-cyan);
  font-weight: 700;
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}

.profile-snapshot-list {
  display: grid;
  gap: var(--space-sm);
}

.profile-snapshot {
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  position: relative;
}

.profile-snapshot::before {
  content: "";
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  width: 2px;
  background: linear-gradient(180deg, var(--accent-cyan), transparent);
  border-radius: 1px;
}

.profile-snapshot span {
  color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  font-size: 11px;
  font-weight: 700;
  font-family: 'Courier New', monospace;
}

.profile-snapshot strong {
  display: block;
  margin: 4px 0;
  color: var(--text-primary);
}

.profile-snapshot p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.6;
}

@media (max-width: 980px) {
  .product-hero,
  .studio-asset-row,
  .profile-learning-panel,
  .profile-control-layout {
    grid-template-columns: 1fr;
  }

  .product-hero-actions {
    justify-content: flex-start;
  }

  .studio-module-grid,
  .profile-summary-grid,
  .profile-learning-side,
  .profile-calibration-grid {
    grid-template-columns: 1fr;
  }

  .workflow-node-strip {
    grid-template-columns: repeat(7, minmax(150px, 1fr));
  }

  .priority-row {
    grid-template-columns: 1fr;
  }

  .priority-row strong {
    text-align: left;
  }
}

/* GitHub Grid */
.github-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: var(--space-md); }
.github-card {
  padding: 14px 16px 14px;
  /* 与 news-card 一致：玻璃质感 + 渐变描金边 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, rgba(255,255,255,.022) 60%, var(--bg-card-solid)) 0%,
      var(--bg-card-solid) 50%) padding-box,
    linear-gradient(180deg,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 20%, transparent) 50%, transparent) 0%,
      transparent 100%) border-box;
  border: 1px solid transparent;
  border-radius: 10px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: border-color .2s, transform .2s, box-shadow .2s;
  animation: fadeUp .4s ease backwards;
  display: flex;
  flex-direction: column;
  gap: 10px;
  position: relative;
  min-height: 100%;
  box-shadow: 0 2px 10px -4px rgba(0,0,0,.18);
}
.github-card::before {
  /* 顶部描金细线，呼应资讯卡 */
  content: "";
  position: absolute;
  top: 0; left: 10px; right: 10px;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 25%, transparent) 50%, transparent) 40%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 38%, transparent) 60%, transparent) 50%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 22%, transparent) 50%, transparent) 60%,
    transparent 100%);
  opacity: .7;
  pointer-events: none;
}
