/* Particle Layer — Theme-driven shape engine
 * 每个主题通过 :root[data-palette] 设置 6 个驱动变量来切换粒子形态：
 *   --particle-shape     : dot | bubble | stardust | leaf | halo | hex | aurora | petal
 *   --particle-size-base : 基础尺寸倍数（1 ≈ 4px）
 *   --particle-size-delta: 每 3N/4N/5N 颗的尺寸差
 *   --particle-fill      : 填充方式：solid / glassy（泡泡带描边+高光）
 *   --particle-drift     : 横向漂移强度，px 值
 *   --particle-wobble    : wobble 动画启用 0/1
 *   --particle-tint-2     : 第 3n 颗粒子颜色（通常 = c2，可选覆盖）
 *   --particle-animation  : 动画 keyframes 名（particleRise / bubbleRise / stardustDrift / leafSway / haloFloat / hexFloat / auroraWave / petalFall）
 */
.particle-layer { position: fixed; inset: 0; pointer-events: none; z-index: 0; overflow: hidden; }
.particle {
  --base-w: calc(4px * var(--particle-size-base, 1));
  --base-h: calc(4px * var(--particle-size-base, 1));
  position: absolute;
  width: var(--base-w);
  height: var(--base-h);
  left: calc((var(--i) * 4.16%));
  top: 100%;
  opacity: .8;
  /* 统一背景 + 辉光 */
  background:
    /* 泡泡（glassy 模式）：半透明底 + 左上高光 + 右下内发光描边 */
    var(
      --particle-fill-bg,
      var(--particle-c1)
    );
  box-shadow:
    0 0 calc(12px * var(--particle-size-base, 1)) var(--particle-c1),
    0 0 calc(24px * var(--particle-size-base, 1)) var(--particle-c1);
  /* 形状驱动（圆点/六边形/椭圆/斜菱形/光环/椭圆叶） */
  border-radius: var(--particle-radius, 999px);
  clip-path: var(--particle-clip, none);
  transform: rotate(var(--particle-rot, 0deg));
  /* 动画 */
  animation-name: var(--particle-animation, particleRise);
  animation-duration: calc(14s + (var(--i) * .3s));
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-delay: calc(var(--i) * -.5s);
}

/* —— 尺寸分层：保留原 nth-child 分布思路 —— */
.particle:nth-child(3n) {
  background: var(--particle-fill-bg-2, var(--particle-c2));
  box-shadow:
    0 0 calc(14px * var(--particle-size-base, 1)) var(--particle-c2),
    0 0 calc(28px * var(--particle-size-base, 1)) var(--particle-c2);
}
.particle:nth-child(4n) {
  width: calc(var(--base-w) - calc(1px * var(--particle-size-delta, 1)));
  height: calc(var(--base-h) - calc(1px * var(--particle-size-delta, 1)));
}
.particle:nth-child(5n) {
  width: calc(var(--base-w) + calc(1px * var(--particle-size-delta, 1)));
  height: calc(var(--base-h) + calc(1px * var(--particle-size-delta, 1)));
}
.particle:nth-child(7n) { opacity: 1; }

/* —— 默认形态：dot（champagne 等未明确指定 shape 时 fallback） —— */

/* —— 动画 keyframes（8 种形态各自的动作特征） —— */
@keyframes particleRise {
  0%   { transform: translate(0, 0) scale(.5); opacity: 0; }
  5%   { opacity: .8; transform: translate(calc(var(--particle-drift, 5px) * .2), -5vh) scale(1); }
  50%  { transform: translate(var(--particle-drift, 15px), -50vh) scale(.8); }
  95%  { opacity: .6; }
  100% { transform: translate(calc(var(--particle-drift, -10px)), -105vh) scale(.3); opacity: 0; }
}

@keyframes bubbleRise {
  0%   { transform: translate(0, 0) scale(.4); opacity: 0; }
  6%   { opacity: .85; transform: translate(2px, -6vh) scale(.7); }
  30%  { transform: translate(var(--particle-drift, 12px), -35vh) scale(.9) rotate(-2deg); }
  60%  { transform: translate(calc(var(--particle-drift, -6px) * -1), -65vh) scale(1) rotate(3deg); }
  94%  { opacity: .7; }
  100% { transform: translate(var(--particle-drift, 20px), -108vh) scale(1.05) rotate(-4deg); opacity: 0; }
}

@keyframes stardustDrift {
  0%   { transform: translate(0, 0) rotate(0deg) scale(.6); opacity: 0; filter: blur(0); }
  10%  { opacity: .9; }
  50%  { transform: translate(var(--particle-drift, 30px), -55vh) rotate(180deg) scale(1.1); }
  90%  { opacity: .75; }
  100% { transform: translate(calc(var(--particle-drift, -40px) * -1), -110vh) rotate(360deg) scale(.5); opacity: 0; }
}

@keyframes leafSway {
  0%   { transform: translate(0, 0) rotate(var(--particle-rot, 0deg)); opacity: 0; }
  8%   { opacity: .85; }
  25%  { transform: translate(var(--particle-drift, 22px), -28vh) rotate(calc(var(--particle-rot, 0deg) + 25deg)); }
  50%  { transform: translate(calc(var(--particle-drift, -18px) * -1), -52vh) rotate(calc(var(--particle-rot, 0deg) - 20deg)); }
  75%  { transform: translate(var(--particle-drift, 28px), -80vh) rotate(calc(var(--particle-rot, 0deg) + 35deg)); opacity: .7; }
  100% { transform: translate(calc(var(--particle-drift, -12px) * -1), -112vh) rotate(calc(var(--particle-rot, 0deg) - 15deg)); opacity: 0; }
}

@keyframes haloFloat {
  0%   { transform: translate(0, 0) scale(.6); opacity: 0; }
  10%  { opacity: .6; }
  50%  { transform: translate(var(--particle-drift, 10px), -50vh) scale(1.1); filter: blur(.5px); }
  90%  { opacity: .5; }
  100% { transform: translate(calc(var(--particle-drift, -14px) * -1), -108vh) scale(.9); opacity: 0; }
}

@keyframes hexFloat {
  0%   { transform: translate(0, 0) rotate(0deg) scale(.7); opacity: 0; }
  10%  { opacity: .85; }
  50%  { transform: translate(var(--particle-drift, 16px), -50vh) rotate(30deg) scale(1); }
  90%  { opacity: .75; }
  100% { transform: translate(calc(var(--particle-drift, -20px) * -1), -110vh) rotate(60deg) scale(.6); opacity: 0; }
}

@keyframes auroraWave {
  0%   { transform: translate(0, 0) skewX(0deg); opacity: 0; filter: blur(1px); }
  12%  { opacity: .8; }
  50%  { transform: translate(var(--particle-drift, 40px), -50vh) skewX(12deg) scale(1.15); filter: blur(2px); }
  88%  { opacity: .7; }
  100% { transform: translate(calc(var(--particle-drift, -50px) * -1), -110vh) skewX(-14deg) scale(.9); opacity: 0; }
}

@keyframes petalFall {
  0%   { transform: translate(0, 0) rotate(0deg); opacity: 0; }
  10%  { opacity: .9; }
  35%  { transform: translate(var(--particle-drift, 30px), -38vh) rotate(80deg) scale(1.05); }
  65%  { transform: translate(calc(var(--particle-drift, -36px) * -1), -72vh) rotate(-60deg) scale(.95); }
  92%  { opacity: .7; }
  100% { transform: translate(var(--particle-drift, 22px), -112vh) rotate(160deg) scale(.75); opacity: 0; }
}

/* ==========================================================================
   Palette → particle shape 映射（和 themes.css 的 12 palette 一一对应）
   每个 palette 分别在 dark / light 两种 data-mode 下设置驱动变量。
   蓝色系（cosmos/neon/arctic/twilight 等）→ bubble 泡泡（用户指定"蓝色可以为泡泡"）
   森林/墨竹青 → leaf 叶脉/竹叶漂落
   樱花粉 → petal 花瓣
   极光紫 → aurora 光波
   香槟金/琥珀 → dot 星点 / halo 光斑
   珊瑚橙/赤陶 → hex 六边形蜡印
   ========================================================================== */

/* --- 1. 香槟金 champagne (默认) → 温润星点 dot --- */
:root[data-palette="champagne"] .particle {
  --particle-size-base: 1;
  --particle-size-delta: 1;
  --particle-drift: 15px;
  --particle-animation: particleRise;
}

/* --- 2. 樱花粉 sakura → 柔粉花瓣下落 petal --- */
:root[data-palette="sakura"] .particle {
  --particle-size-base: 1.5;
  --particle-size-delta: 1.5;
  --particle-drift: 30px;
  --particle-radius: 60% 40% 55% 45% / 45% 55% 50% 50%;
  --particle-clip: none;
  --particle-rot: -12deg;
  --particle-animation: petalFall;
}

/* --- 3. 翠翠绿 forest → 绿叶漂落 leaf --- */
:root[data-palette="forest"] .particle {
  --particle-size-base: 1.6;
  --particle-size-delta: 1.4;
  --particle-drift: 22px;
  --particle-radius: 2px 80% 4px 70%;
  --particle-clip: ellipse(45% 60% at 50% 50%);
  --particle-rot: 12deg;
  --particle-animation: leafSway;
}

/* --- 4. 赛博蓝 neon → 漂浮泡泡 bubble（用户指定"蓝色泡泡"） --- */
:root[data-palette="neon"] .particle {
  --particle-size-base: 2.2;
  --particle-size-delta: 2;
  --particle-drift: 14px;
  --particle-radius: 999px;
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.55) 0, rgba(255,255,255,0) 36%),
    radial-gradient(circle at 70% 80%, color-mix(in srgb, var(--particle-c1) 35%, transparent) 0, transparent 60%),
    color-mix(in srgb, var(--particle-c1) 22%, transparent);
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.5) 0, rgba(255,255,255,0) 36%),
    radial-gradient(circle at 70% 80%, color-mix(in srgb, var(--particle-c2) 35%, transparent) 0, transparent 60%),
    color-mix(in srgb, var(--particle-c2) 22%, transparent);
  --particle-animation: bubbleRise;
}
:root[data-mode="light"][data-palette="neon"] .particle {
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.7) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c1) 40%, rgba(255,255,255,.18));
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.7) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c2) 40%, rgba(255,255,255,.18));
}

/* --- 5. 深空蓝 cosmos → 泡泡 bubble（用户指定"蓝色泡泡"） --- */
:root[data-palette="cosmos"] .particle {
  --particle-size-base: 2.0;
  --particle-size-delta: 1.8;
  --particle-drift: 14px;
  --particle-radius: 999px;
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.5) 0, rgba(255,255,255,0) 36%),
    color-mix(in srgb, var(--particle-c1) 30%, transparent);
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.45) 0, rgba(255,255,255,0) 36%),
    color-mix(in srgb, var(--particle-c2) 30%, transparent);
  --particle-animation: bubbleRise;
}
:root[data-mode="light"][data-palette="cosmos"] .particle {
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.72) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c1) 38%, rgba(255,255,255,.18));
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.72) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c2) 38%, rgba(255,255,255,.18));
}

/* --- 6. 赤陶橘 terracotta → 六边形蜡印 hex --- */
:root[data-palette="terracotta"] .particle {
  --particle-size-base: 1.4;
  --particle-size-delta: 1.2;
  --particle-drift: 16px;
  --particle-radius: 0;
  --particle-clip: polygon(50% 0%, 95% 25%, 95% 75%, 50% 100%, 5% 75%, 5% 25%);
  --particle-animation: hexFloat;
}

/* --- 7. 北极银 arctic → 泡泡 bubble（用户指定"蓝色泡泡"，冰蓝白） --- */
:root[data-palette="arctic"] .particle {
  --particle-size-base: 2.0;
  --particle-size-delta: 1.6;
  --particle-drift: 10px;
  --particle-radius: 999px;
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.65) 0, rgba(255,255,255,0) 34%),
    color-mix(in srgb, var(--particle-c1) 25%, transparent);
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.6) 0, rgba(255,255,255,0) 34%),
    color-mix(in srgb, var(--particle-c2) 25%, transparent);
  --particle-animation: bubbleRise;
}
:root[data-mode="light"][data-palette="arctic"] .particle {
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.78) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c1) 32%, rgba(255,255,255,.22));
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.78) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c2) 32%, rgba(255,255,255,.22));
}

/* --- 8. 极光紫 aurora → 扭动极光带 auroraWave --- */
:root[data-palette="aurora"] .particle {
  --particle-size-base: 2.6;
  --particle-size-delta: 2.4;
  --particle-drift: 40px;
  --particle-radius: 40% 60% 60% 40% / 60% 50% 50% 40%;
  --particle-clip: none;
  --particle-animation: auroraWave;
}

/* --- 9. 墨竹青 bamboo → 竹叶漂落 leaf --- */
:root[data-palette="bamboo"] .particle {
  --particle-size-base: 1.5;
  --particle-size-delta: 1.3;
  --particle-drift: 20px;
  --particle-radius: 3px 90% 4px 80%;
  --particle-clip: ellipse(30% 65% at 50% 50%);
  --particle-rot: 14deg;
  --particle-animation: leafSway;
}

/* --- 10. 琥珀棕 amber → 柔化光晕 halo（和金色/琥珀色匹配） --- */
:root[data-palette="amber"] .particle {
  --particle-size-base: 1.8;
  --particle-size-delta: 1.6;
  --particle-drift: 10px;
  --particle-radius: 999px;
  --particle-animation: haloFloat;
}

/* --- 11. 暮光蓝 twilight → 泡泡 bubble（用户指定"蓝色泡泡"） --- */
:root[data-palette="twilight"] .particle {
  --particle-size-base: 1.9;
  --particle-size-delta: 1.6;
  --particle-drift: 12px;
  --particle-radius: 999px;
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.55) 0, rgba(255,255,255,0) 36%),
    color-mix(in srgb, var(--particle-c1) 28%, transparent);
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.5) 0, rgba(255,255,255,0) 36%),
    color-mix(in srgb, var(--particle-c2) 28%, transparent);
  --particle-animation: bubbleRise;
}
:root[data-mode="light"][data-palette="twilight"] .particle {
  --particle-fill-bg:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.76) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c1) 38%, rgba(255,255,255,.22));
  --particle-fill-bg-2:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.76) 0, rgba(255,255,255,0) 32%),
    color-mix(in srgb, var(--particle-c2) 38%, rgba(255,255,255,.22));
}

/* --- 12. 珊瑚橙 coral → 六边形 hex（蜡封/贝壳质感） --- */
:root[data-palette="coral"] .particle {
  --particle-size-base: 1.3;
  --particle-size-delta: 1.1;
  --particle-drift: 16px;
  --particle-radius: 0;
  --particle-clip: polygon(50% 0%, 95% 25%, 95% 75%, 50% 100%, 5% 75%, 5% 25%);
  --particle-animation: hexFloat;
}

