.ai-brief-action-btn.primary { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent); color: #C9A961; font-weight: 600; }
.ai-brief-action-btn.primary:hover { background: color-mix(in srgb, var(--accent-cyan) 18%, transparent); }
:root[data-mode="light"] .ai-brief-action-btn.primary { background: color-mix(in srgb, var(--accent-amber) 10%, transparent); border-color: color-mix(in srgb, var(--accent-amber) 25%, transparent); color: #D4B576; }
:root[data-mode="light"] .ai-brief-action-btn.primary:hover { background: color-mix(in srgb, var(--accent-amber) 15%, transparent); }
.ai-brief-generate { padding: 5px 14px; background: var(--gradient-primary); color: white; border: none; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; transition: opacity .15s; }
