.ai-brief-content .brief-h2 { font-size: 14px; font-weight: 700; color: var(--accent-cyan); margin: 16px 0 8px; }
:root[data-mode="light"] .ai-brief-content .brief-h2 { color: #D4B576; }
.ai-brief-content .brief-p { font-size: 13px; line-height: 1.7; color: var(--text-secondary); margin: 4px 0; }
.ai-brief-content .brief-list { list-style: none; padding: 0; margin: 6px 0; }
.ai-brief-content .brief-list li { font-size: 13px; line-height: 1.6; color: var(--text-secondary); padding: 3px 0 3px 16px; position: relative; }
.ai-brief-content .brief-list li::before { content: ''; position: absolute; left: 4px; top: 10px; width: 5px; height: 5px; background: var(--accent-cyan); border-radius: 50%; }
:root[data-mode="light"] .ai-brief-content .brief-list li::before { background: #D4B576; }
.ai-brief-content .brief-list li strong { color: var(--text-primary); font-weight: 600; }
.ai-brief-content strong { color: var(--text-primary); font-weight: 600; }
.ai-brief-time { font-size: 10px; color: var(--text-muted); margin-top: 12px; text-align: right; }
.ai-brief-error { background: rgba(239, 68, 68, .08); border: 1px solid rgba(239, 68, 68, .2); border-radius: 8px; padding: 10px; font-size: 12px; color: #ef4444; }
.ai-brief-placeholder { text-align: center; padding: 20px; color: var(--text-muted); font-size: 13px; }
.ai-brief-placeholder p { margin: 4px 0; }
.ai-brief-hint { font-size: 11px; color: var(--text-muted); opacity: .7; }
.ai-brief-loading { display: flex; align-items: center; gap: 10px; padding: 20px; color: var(--text-secondary); font-size: 13px; }
.ai-brief-spinner { width: 18px; height: 18px; border: 2px solid var(--border-color); border-top-color: var(--accent-cyan); border-radius: 50%; animation: spin .8s linear infinite; }

/* 洞察通用区块 */
.insight-section { background: var(--bg-card); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border: var(--panel-border); border-radius: var(--radius-card); padding: 20px; position: relative; overflow: hidden; transition: all .3s ease; }
.insight-section::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px; background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 30%, transparent), transparent); opacity: .6; }
:root[data-mode="light"] .insight-section::before { background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-amber) 40%, transparent), transparent); }
.insight-section:hover { border-color: var(--border-active); box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 6%, transparent); }
:root[data-mode="light"] .insight-section:hover { box-shadow: 0 0 20px color-mix(in srgb, var(--accent-amber) 10%, transparent); }
.insight-section-title { font-size: 15px; font-weight: 700; color: var(--text-primary); margin-bottom: 16px; display: flex; align-items: center; gap: var(--space-sm); position: relative; }
.insight-section-title::before { content: ''; width: 4px; height: 16px; background: var(--gradient-primary); border-radius: 2px; }
:root[data-mode="light"] .insight-section-title::before { background: linear-gradient(135deg, #D4B576, #9BA3AD); }

/* 概览页顶部双栏 */
.overview-top-row { display: block; margin-bottom: 12px; }

/* 头条要闻 - 紧凑模块 */

/* 赛道态势统一图表 */

/* 信号中心 */

/* 赛道态势统一图表 */

.legend-dot { width: 6px; height: 6px; border-radius: 50%; flex-shrink: 0; }

/* 技术关键词 TF-IDF */
.insight-tech-keywords { display: flex; flex-wrap: wrap; gap: var(--space-sm); }
.insight-tech-kw { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 6px 12px; background: var(--bg-hover); border: var(--panel-border); border-radius: 8px; cursor: pointer; transition: all .15s; text-align: center; }
.insight-tech-kw:hover { border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.tech-kw-word { font-size: 12px; font-weight: 600; color: var(--text-primary); }
.tech-kw-meta { font-size: 9px; color: var(--text-muted); }

/* 技术雷达四象限 */
.tech-radar-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-md); }
.tech-radar-quadrant { padding: 14px; border-radius: 10px; border: var(--panel-border); }
.tech-radar-quadrant.adopt { background: color-mix(in srgb, var(--accent-cyan) 4%, transparent); border-color: color-mix(in srgb, var(--accent-cyan) 20%, transparent); }
.tech-radar-quadrant.trial { background: rgba(168, 85, 247, .04); border-color: rgba(168, 85, 247, .2); }
.tech-radar-quadrant.assess { background: rgba(245, 158, 11, .04); border-color: rgba(245, 158, 11, .2); }
.tech-radar-quadrant.hold { background: rgba(107, 114, 128, .04); border-color: rgba(107, 114, 128, .15); }
:root[data-mode="light"] .tech-radar-quadrant.adopt { background: color-mix(in srgb, var(--accent-amber) 6%, transparent); border-color: color-mix(in srgb, var(--accent-amber) 25%, transparent); }
:root[data-mode="light"] .tech-radar-quadrant.trial { background: rgba(168, 85, 247, .06); border-color: rgba(168, 85, 247, .25); }
:root[data-mode="light"] .tech-radar-quadrant.assess { background: color-mix(in srgb, var(--accent-amber) 6%, transparent); border-color: color-mix(in srgb, var(--accent-amber) 25%, transparent); }
:root[data-mode="light"] .tech-radar-quadrant.hold { background: rgba(156, 163, 175, .06); border-color: rgba(156, 163, 175, .2); }
.radar-quadrant-title { font-size: 14px; font-weight: 700; margin: 0 0 2px; }
.adopt .radar-quadrant-title { color: #C9A961; }
.trial .radar-quadrant-title { color: #a855f7; }
.assess .radar-quadrant-title { color: #f59e0b; }
.hold .radar-quadrant-title { color: #6b7280; }
:root[data-mode="light"] .adopt .radar-quadrant-title { color: #D4B576; }
:root[data-mode="light"] .trial .radar-quadrant-title { color: #9BA3AD; }
:root[data-mode="light"] .assess .radar-quadrant-title { color: #D4B576; }
:root[data-mode="light"] .hold .radar-quadrant-title { color: #6b7280; }
.radar-quadrant-desc { display: block; font-size: 10px; color: var(--text-muted); margin-bottom: 10px; }
.radar-items { display: flex; flex-wrap: wrap; gap: 6px; }
.radar-item { padding: 4px 10px; border-radius: 6px; font-size: 11px; font-weight: 500; cursor: pointer; transition: all .15s; }
.adopt .radar-item { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); color: #C9A961; }
.adopt .radar-item:hover { background: color-mix(in srgb, var(--accent-cyan) 20%, transparent); }
.trial .radar-item { background: rgba(168, 85, 247, .1); color: #a855f7; }
.trial .radar-item:hover { background: rgba(168, 85, 247, .2); }
.assess .radar-item { background: rgba(245, 158, 11, .1); color: #f59e0b; }
.assess .radar-item:hover { background: rgba(245, 158, 11, .2); }
.hold .radar-item { background: rgba(107, 114, 128, .08); color: #6b7280; }
.hold .radar-item:hover { background: rgba(107, 114, 128, .15); }
.radar-item-empty { opacity: .4; cursor: default; }

/* 源质量排行 */
.source-quality-list { display: flex; flex-direction: column; gap: var(--space-sm); }
.source-quality-row { display: grid; grid-template-columns: 24px 1fr 80px 60px 36px; gap: var(--space-sm); align-items: center; padding: 8px 10px; background: var(--bg-hover); border-radius: 8px; }
.source-quality-rank { font-size: 12px; font-weight: 700; color: var(--text-muted); text-align: center; }
.source-quality-name { font-size: 12px; font-weight: 600; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.source-quality-meta { font-size: 10px; color: var(--text-muted); }
.source-quality-bar-wrap { height: 4px; background: var(--bg-card); border-radius: 2px; overflow: hidden; }
.source-quality-bar { height: 100%; border-radius: 2px; transition: width .3s; }
.source-quality-score { font-size: 13px; font-weight: 700; color: var(--text-primary); text-align: right; }

/* 头条要闻 */

/* 热力图 */
.insight-heatmap { display: flex; flex-direction: column; gap: 3px; overflow-x: auto; padding-bottom: 4px; }
.heatmap-header { display: flex; gap: 3px; margin-bottom: 4px; }
.heatmap-label { width: 80px; min-width: 80px; font-size: 10px; color: var(--text-muted); flex-shrink: 0; }
.heatmap-day { flex: 1; text-align: center; font-size: 9px; color: var(--text-muted); min-width: 32px; }
.heatmap-row { display: flex; gap: 3px; align-items: center; }
.heatmap-cell { flex: 1; min-width: 32px; height: 26px; display: flex; align-items: center; justify-content: center; border-radius: 4px; font-size: 10px; font-weight: 600; color: var(--text-primary); transition: opacity .15s; }
.heatmap-cell:hover { opacity: .8; }
:root[data-mode="light"] .heatmap-cell { background: color-mix(in srgb, var(--accent-amber) 8%, transparent); border: 1px solid color-mix(in srgb, var(--accent-amber) 15%, transparent); }
:root[data-mode="light"] .heatmap-cell:hover { background: color-mix(in srgb, var(--accent-amber) 15%, transparent); }

/* 区域分布 */
.insight-region-bars { display: flex; flex-direction: column; gap: 10px; }
.insight-region-row { display: grid; grid-template-columns: 50px 1fr 45px; gap: 10px; align-items: center; }
.insight-region-label { font-size: 12px; font-weight: 600; }
.insight-region-bar-wrap { height: 8px; background: var(--bg-hover); border-radius: 4px; overflow: hidden; }
:root[data-mode="light"] .insight-region-bar-wrap { background: rgba(0, 0, 0, .05); }
.insight-region-bar { height: 100%; border-radius: 4px; transition: width .4s ease; }
.insight-region-pct { font-size: 13px; font-weight: 700; color: var(--text-primary); text-align: right; }

/* 关键词 */

/* 追踪表单 */
.tracker-form { display: flex; gap: var(--space-sm); margin-bottom: 12px; }
.tracker-form input { flex: 1; height: 36px; padding: 0 12px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; color: var(--text-primary); font-size: 13px; outline: none; }
.tracker-form input:focus { border-color: var(--accent-cyan); }
.tracker-form-btn { padding: 0 14px; height: 36px; background: var(--accent-cyan); border: none; border-radius: 8px; color: var(--bg-primary); font-size: 13px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: var(--space-xs); }
.tracker-form-btn svg { width: 14px; height: 14px; }
.tracker-presets { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 16px; }
.tracker-preset { padding: 4px 10px; background: var(--bg-hover); border: var(--panel-border); border-radius: 6px; font-size: 12px; color: var(--text-secondary); cursor: pointer; transition: all .15s; }
.tracker-preset:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }

/* 追踪列表 */
.insight-watchlist { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-md); }
.insight-watch-card { background: var(--bg-card); border: var(--panel-border); border-radius: 10px; padding: 14px; position: relative; }
.insight-watch-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.insight-watch-name { font-size: 15px; font-weight: 700; color: var(--text-primary); }
.insight-watch-remove { width: 22px; height: 22px; display: grid; place-items: center; background: transparent; border: none; color: var(--text-muted); cursor: pointer; border-radius: 4px; font-size: 14px; }
.insight-watch-remove:hover { color: var(--accent-rose); background: rgba(248, 113, 113, .1); }
.insight-watch-stats { display: flex; gap: var(--space-md); align-items: center; margin-bottom: 10px; }
.insight-watch-val { font-size: 18px; font-weight: 700; color: var(--text-primary); }
.insight-watch-val sub { font-size: 10px; color: var(--text-muted); }
.insight-watch-change { font-size: 14px; font-weight: 700; }
.insight-watch-change.up { color: var(--accent-emerald); }
.insight-watch-change.down { color: var(--accent-rose); }
.insight-watch-status { font-size: 11px; font-weight: 600; margin-left: auto; }
.insight-watch-sparkline { display: flex; align-items: flex-end; gap: 3px; height: 36px; margin-bottom: 4px; }
.spark-bar { flex: 1; background: var(--accent-cyan); border-radius: 2px 2px 0 0; min-height: 3px; transition: height .3s ease; }
.insight-watch-spark-labels { display: flex; gap: 3px; }
.insight-watch-spark-labels span { flex: 1; text-align: center; font-size: 9px; color: var(--text-muted); }

/* 阅读指标 */
.reading-metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.reading-metric { background: var(--bg-card); border: var(--panel-border); border-radius: 10px; padding: 16px 14px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: var(--space-xs); }
.reading-metric-value { font-size: 22px; font-weight: 700; color: var(--text-primary); }
.reading-metric-label { font-size: 11px; color: var(--text-muted); }

/* 阅读热力 */

/* 兴趣分布 */
.reading-interests { display: flex; flex-direction: column; gap: var(--space-sm); }
.reading-interest-row { display: grid; grid-template-columns: 24px 70px 1fr 40px; gap: 10px; align-items: center; padding: 4px 0; }
.reading-interest-rank { width: 22px; height: 22px; display: grid; place-items: center; background: var(--bg-hover); border-radius: 5px; font-size: 11px; font-weight: 700; color: var(--text-muted); }
.reading-interest-row:first-child .reading-interest-rank { background: linear-gradient(135deg, #a78bfa, #8C8C8C); color: white; }
.reading-interest-name { font-size: 12px; font-weight: 600; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.reading-interest-bar-wrap { height: 6px; background: var(--bg-hover); border-radius: 3px; overflow: hidden; }
.reading-interest-bar { height: 100%; background: linear-gradient(90deg, #a78bfa, #818cf8); border-radius: 3px; transition: width .4s ease; }
.reading-interest-pct { font-size: 12px; font-weight: 700; color: var(--accent-violet); text-align: right; }

/* 文字工具类 */
.text-up { color: var(--accent-emerald); font-weight: 600; }
.text-down { color: var(--accent-rose); font-weight: 600; }
/* text-muted 变深 — 不再灰蒙蒙 */
.text-muted { color: var(--text-secondary); font-weight: 500; }

/* 响应式 */
@media (max-width: 768px) {
  .overview-top-row { margin-bottom: 12px; }
  .reading-metrics { grid-template-columns: repeat(2, 1fr); }
  .insight-watchlist { grid-template-columns: 1fr; }
  .insight-status-meta { flex-wrap: wrap; gap: var(--space-sm); }
  .insight-tabs { gap: var(--space-xs); }
  .insight-tab { height: 30px; padding: 0 10px; font-size: 12px; }
}

/* Translation */
.translate-btn { width: 26px; height: 26px; display: grid; place-items: center; background: transparent; border: none; color: var(--text-muted); cursor: pointer; border-radius: 6px; transition: all .15s; }
.translate-btn:hover { color: var(--accent-violet); background: rgba(167, 139, 250, .1); }
.translate-btn.active { color: var(--accent-violet); background: rgba(167, 139, 250, .15); }
.translate-btn svg { width: 14px; height: 14px; }

/* Shortcuts */
.shortcuts-list { display: flex; flex-direction: column; gap: var(--space-sm); }
.shortcut-row { display: flex; align-items: center; gap: var(--space-md); }
.shortcut-row kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 32px; height: 28px; padding: 0 8px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--text-primary); font-family: 'Inter', monospace; }
.shortcut-row span { font-size: 13px; color: var(--text-secondary); }

/* Responsive */
.mobile-menu-btn { display: none; width: 36px; height: 36px; align-items: center; justify-content: center; background: transparent; border: var(--panel-border); border-radius: 8px; color: var(--text-secondary); cursor: pointer; }
.mobile-menu-btn svg { width: 20px; height: 20px; }
.mobile-overlay { display: none; position: fixed; inset: 0; background: rgba(0, 0, 0, .6); z-index: 99; }

@media (max-width: 1200px) {
  .panel { display: none; }
  .sidebar { width: var(--sidebar-collapsed-w); }
  .main { margin-right: 0; margin-left: var(--sidebar-collapsed-w); }
  .sidebar .logo-text, .sidebar .nav-label, .sidebar .nav-count, .sidebar .sidebar-action span, .sidebar .nav-follow-group .nav-group-title { opacity: 0; display: none; }
}
@media (max-width: 900px) {
  .mobile-menu-btn { display: flex; }
  .mobile-overlay { display: block; }
  .sidebar { display: flex; transform: translateX(-100%); width: var(--sidebar-w); }
  .sidebar.mobile-open { transform: translateX(0); }
  .sidebar.collapsed { width: var(--sidebar-w); }
  .sidebar .logo-text, .sidebar .nav-label, .sidebar .nav-count, .sidebar .sidebar-action span { opacity: 1; display: initial; }
  .nav-follow-group { display: block; }
  .main { margin-left: 0; margin-right: 0; }
  .github-grid { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .topbar { flex-wrap: wrap; gap: 10px; }
  .search-wrap { order: 1; max-width: none; width: 100%; }
  .topbar-actions { order: 2; width: 100%; justify-content: flex-start; flex-wrap: wrap; }
  .source-filter-wrap { max-width: 100%; width: 100%; }
  .source-filter-select { max-width: 100%; }
  .stats-bar { flex-wrap: wrap; gap: var(--space-md); }
  .news-item { flex-direction: column; gap: var(--space-md); }
  .item-left { flex-direction: row; width: 100%; justify-content: space-between; }
  .modal { width: 100%; margin: 16px; max-height: calc(100vh - 32px); }
  .github-grid { grid-template-columns: 1fr; }
}

/* 素材库 */
.material-filter { height: 32px; padding: 0 10px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; color: var(--text-primary); }
.material-count { font-size: 12px; color: var(--text-muted); }
.empty-materials { text-align: center; padding: 40px 20px; color: var(--text-muted); }
.empty-materials .hint { font-size: 12px; margin-top: 8px; }
/* 素材库视图切换 */
.materials-view-switch {
  display: inline-flex;
  border: 1px solid var(--panel-border);
  border-radius: 6px;
  overflow: hidden;
  margin-right: 8px;
}
.materials-view-btn {
  background: transparent;
  border: none;
  padding: 6px 10px;
  color: var(--text-muted, #8b93a7);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  transition: background .2s;
}
.materials-view-btn svg { width: 16px; height: 16px; }
.materials-view-btn.active {
  background: rgba(106, 160, 255, .14);
  color: var(--accent, #6aa0ff);
}
/* 知识图谱 overlay（AI 工作站顶部按钮打开） */
.graph-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, .55);
  backdrop-filter: blur(3px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.graph-overlay-panel {
  width: min(960px, 92vw);
  height: min(640px, 88vh);
  background: var(--bg-card, #11151c);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  box-shadow: 0 24px 60px rgba(0,0,0,.4);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.graph-overlay-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--panel-border);
  position: relative;
  background: var(--bg-elevated, rgba(0,0,0,.02));
}
.graph-overlay-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-strong, #e8ecf4);
}
.graph-overlay-sub {
  font-size: 12px;
  color: var(--text-muted, #8b93a7);
}
.graph-overlay-close {
  margin-left: auto;
  background: transparent;
  border: none;
  color: var(--text-muted, #8b93a7);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  padding: 4px;
  border-radius: 4px;
  transition: background .2s;
}
.graph-overlay-close:hover { background: var(--bg-elevated, rgba(255,255,255,.08)); }
.graph-overlay-panel .material-graph { flex: 1; border: none; border-radius: 0; }
.graph-overlay-detail {
  padding: 12px 16px;
  border-top: 1px solid var(--panel-border);
