.material-graph-hubs button em { font-style: normal; font-family: var(--font-mono, monospace); font-size: 9.5px; color: var(--accent-cyan); }
.material-graph-hubs button span, .material-graph-hubs button { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.materials-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--space-md); }
.material-card { background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); padding: 12px; transition: all .2s; max-height: 240px; display: flex; flex-direction: column; overflow: hidden; }
