/* 创作中心 */
.editor-header { display: flex; justify-content: space-between; align-items: center; }
.editor-header-actions { display: flex; gap: var(--space-sm); align-items: center; }
.editor-fullscreen-btn { display: flex; align-items: center; gap: var(--space-xs); height: 36px; padding: 0 12px; background: var(--bg-tertiary); border: var(--panel-border); border-radius: 8px; color: var(--text-secondary); font-size: 13px; font-weight: 500; cursor: pointer; transition: all .2s; }
.editor-fullscreen-btn:hover { background: var(--accent-cyan); color: white; border-color: var(--accent-cyan); }
.editor-fullscreen-btn svg { width: 16px; height: 16px; }
.btn-new-article-pro { display: flex; align-items: center; gap: 6px; height: 36px; padding: 0 16px; background: linear-gradient(135deg, #C9A961 0%, #D4B576 100%); border: none; border-radius: 10px; color: white; font-size: 14px; font-weight: 600; cursor: pointer; transition: all .2s; }
.btn-new-article-pro:hover { transform: translateY(-1px); box-shadow: 0 4px 16px color-mix(in srgb, var(--accent-cyan) 40%, transparent); }
.btn-new-article-pro svg { width: 16px; height: 16px; }
.btn-key-hint { font-size: 11px; font-weight: 400; opacity: .7; margin-left: 4px; }

/* 模板弹出菜单 */
.template-popover { position: relative; }
.btn-template-popover { display: flex; align-items: center; gap: 6px; height: 36px; padding: 0 12px; background: var(--bg-card); border: var(--panel-border); border-radius: 10px; color: var(--text-primary); font-size: 13px; font-weight: 500; cursor: pointer; transition: all .2s; }
.btn-template-popover:hover { border-color: var(--accent-violet); color: var(--accent-violet); background: rgba(167, 139, 250, .05); }
.btn-template-popover svg { width: 16px; height: 16px; }
.template-popover-menu { position: absolute; top: calc(100% + 6px); right: 0; background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); box-shadow: 0 12px 32px rgba(0,0,0,.25); z-index: 200; min-width: 200px; overflow: hidden; animation: popoverIn .15s ease; }
@keyframes popoverIn { from { opacity: 0; transform: translateY(-6px) scale(.97); } to { opacity: 1; transform: translateY(0) scale(1); } }
.template-menu-title { padding: 10px 14px 6px; font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase; letter-spacing: .5px; }
.template-menu-item { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 14px; background: transparent; border: none; color: var(--text-primary); font-size: 13px; cursor: pointer; transition: background .15s; text-align: left; }
.template-menu-item:hover { background: var(--bg-hover); }
.template-menu-icon { width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; background: var(--bg-primary); border-radius: 6px; color: var(--accent-violet); }
.template-menu-icon svg { width: 16px; height: 16px; }
.template-menu-label { font-weight: 500; }

/* 旧样式兼容 */
.editor-template-dropdown { display: flex; align-items: center; position: relative; }
.article-editor { min-height: 600px; }
.article-toolbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }
.btn-back-list { height: 32px; padding: 0 12px; background: var(--bg-hover); border: var(--panel-border); border-radius: 6px; color: var(--text-secondary); cursor: pointer; transition: all .2s; }
.btn-back-list:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.article-actions { display: flex; align-items: center; gap: var(--space-sm); }
.autosave-indicator { font-size: 11px; color: var(--accent-emerald); font-weight: 500; }
.article-status-select { height: 28px; padding: 0 8px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; color: var(--text-primary); font-size: 12px; cursor: pointer; }
.article-status-select:focus { outline: none; border-color: var(--accent-cyan); }
.btn-copy-article { height: 28px; padding: 0 8px; background: var(--bg-hover); border: var(--panel-border); border-radius: 6px; color: var(--text-secondary); cursor: pointer; transition: all .2s; display: flex; align-items: center; }
.btn-copy-article:hover { border-color: var(--accent-violet); color: var(--accent-violet); }
.btn-copy-article svg { width: 14px; height: 14px; }
.article-title-input { width: 100%; font-size: 24px; font-weight: 700; background: transparent; border: none; border-bottom: 2px solid var(--border-color); color: var(--text-primary); padding: 8px 0; margin-bottom: 12px; }
.article-title-input:focus { outline: none; border-bottom-color: var(--accent-cyan); }
.article-meta-bar { display: flex; gap: var(--space-md); align-items: center; margin-bottom: 12px; font-size: 12px; color: var(--text-muted); flex-wrap: wrap; }
.article-template-select { height: 28px; padding: 0 8px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; color: var(--text-primary); cursor: pointer; }
.article-tags-inline { display: flex; align-items: center; gap: var(--space-xs); flex-wrap: wrap; flex: 1; }
.article-tag-pill { display: inline-flex; align-items: center; gap: 2px; padding: 2px 8px; background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border: 1px solid color-mix(in srgb, var(--accent-cyan) 30%, transparent); border-radius: var(--radius-card); color: var(--accent-cyan); font-size: 11px; font-weight: 500; }
.article-tag-remove { background: transparent; border: none; color: var(--accent-cyan); cursor: pointer; padding: 0; display: flex; align-items: center; margin-left: 2px; opacity: .6; transition: opacity .2s; }
.article-tag-remove:hover { opacity: 1; }
.article-tag-remove svg { width: 10px; height: 10px; }
.article-tag-input { height: 22px; padding: 0 6px; background: transparent; border: 1px dashed var(--border-color); border-radius: var(--radius-card); color: var(--text-primary); font-size: 11px; width: 60px; }
.article-tag-input:focus { outline: none; border-color: var(--accent-cyan); border-style: solid; }
.article-updated { font-size: 11px; color: var(--text-muted); margin-left: auto; white-space: nowrap; }

/* Markdown 工具栏 */
.editor-toolbar { display: flex; gap: var(--space-xs); align-items: center; margin-bottom: 8px; flex-wrap: wrap; padding: 6px; background: var(--bg-card); border: var(--panel-border); border-radius: 8px; }
.editor-toolbar-group { display: flex; gap: 2px; align-items: center; }
.editor-toolbar-group:not(:last-child) { border-right: 1px solid var(--border-color); padding-right: 6px; margin-right: 4px; }
.editor-tool-btn { width: 28px; height: 28px; padding: 0; background: transparent; border: 1px solid transparent; border-radius: 4px; color: var(--text-secondary); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all .15s; }
.editor-tool-btn:hover { background: var(--bg-hover); border-color: var(--border-color); color: var(--text-primary); }
.editor-tool-btn svg { width: 14px; height: 14px; }
.editor-tab-group { margin-left: auto; border-right: none !important; padding-right: 0 !important; }
.editor-tab-btn { height: 26px; padding: 0 10px; background: transparent; border: var(--panel-border); border-radius: 4px; color: var(--text-secondary); font-size: 11px; font-weight: 500; cursor: pointer; transition: all .15s; }
.editor-tab-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.editor-tab-btn.active { background: color-mix(in srgb, var(--accent-cyan) 15%, transparent); border-color: var(--accent-cyan); color: var(--accent-cyan); }

/* 编辑器分栏布局 */
.editor-split-view { display: grid; gap: var(--space-md); margin: 8px 0; min-height: 500px; }
.editor-mode-edit { grid-template-columns: 1fr; }
.editor-mode-split { grid-template-columns: 1fr 1fr; }
.editor-mode-preview { grid-template-columns: 1fr; }
.editor-pane { display: flex; flex-direction: column; min-height: 0; }
.article-content-editor {
  width: 100%;
  flex: 1;
  /* 墨色化底：净墨 + 顶部金色微光，让长文编辑有"宣纸"感 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 2.5%, transparent) 70%, var(--bg-primary)) 0%,
      var(--bg-primary) 120px);
  border: var(--panel-border);
  border-radius: 8px;
  color: var(--text-primary);
  padding: 16px;
  font-family: 'DM Mono', monospace;
  font-size: 14px;
  line-height: 1.6;
  resize: vertical;
  min-height: 0;
  position: relative;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 4%, transparent);
  transition: border-color .2s ease, box-shadow .2s ease;
}
.article-content-editor:focus {
  outline: none;
  border-color: var(--accent-cyan);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 6%, transparent),
    0 0 0 1px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.preview-pane {
  /* 预览面板：玻璃质感 + 顶部描金线，呼应编辑器的"宣纸"基调 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, rgba(255,255,255,.02) 60%, var(--bg-card)) 0%,
      var(--bg-card) 50%) padding-box,
    linear-gradient(180deg,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 18%, transparent) 50%, transparent) 0%,
      transparent 100%) border-box;
  border: 1px solid transparent;
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  box-shadow: 0 2px 10px -4px rgba(0,0,0,.18);
}
.preview-pane::before {
  content: "";
  position: absolute;
  top: 0; left: 10px; right: 10px;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 22%, transparent) 50%, transparent) 40%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 34%, transparent) 60%, transparent) 50%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 20%, transparent) 50%, transparent) 60%,
    transparent 100%);
  opacity: .7;
  pointer-events: none;
  z-index: 1;
}
.preview-header { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; background: var(--bg-hover); border-bottom: 1px solid var(--border-color); font-size: 12px; font-weight: 600; color: var(--text-muted); flex-shrink: 0; }
.preview-stats { font-weight: 400; color: var(--text-secondary); }
.editor-mode-edit .preview-pane { display: none; }
.editor-mode-preview .editor-pane { display: none; }

/* Markdown 预览增强 */
.markdown-preview { padding: 16px; flex: 1; overflow-y: auto; font-size: 14px; line-height: 1.6; color: var(--text-primary); }
.markdown-preview del { text-decoration: line-through; color: var(--text-muted); }
.markdown-preview pre { background: var(--bg-hover); padding: 12px; border-radius: 6px; overflow-x: auto; margin: 12px 0; }
.markdown-preview pre code { background: none; padding: 0; font-size: 13px; }
.markdown-preview ul, .markdown-preview ol { margin: 12px 0; padding-left: 24px; }
.markdown-preview table { border-collapse: collapse; width: 100%; margin: 12px 0; }
.markdown-preview th, .markdown-preview td { border: var(--panel-border); padding: 8px 12px; text-align: left; }
.markdown-preview th { background: var(--bg-hover); font-weight: 600; }
.markdown-preview img { max-width: 100%; border-radius: 6px; margin: 8px 0; }
.markdown-preview hr { border: none; border-top: 1px solid var(--border-color); margin: 20px 0; }

/* AI 助手面板 */
.ai-assistant-panel { margin-top: 12px; background: var(--bg-card); border: var(--panel-border); border-radius: 10px; overflow: hidden; transition: all .2s; }
.ai-panel-header { display: flex; justify-content: space-between; align-items: center; padding: 10px 14px; cursor: pointer; user-select: none; transition: background .15s; }
.ai-panel-header:hover { background: var(--bg-hover); }
.ai-panel-title { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; color: var(--text-primary); }
.ai-panel-title svg { width: 16px; height: 16px; color: var(--accent-violet); }
.ai-status-dot { width: 6px; height: 6px; background: var(--accent-emerald); border-radius: 50%; margin-left: 4px; }
.ai-panel-chevron { transition: transform .2s; color: var(--text-muted); }
.ai-panel-chevron svg { width: 16px; height: 16px; }
.ai-panel-chevron.open { transform: rotate(180deg); }
.ai-panel-body { padding: 12px 14px; border-top: 1px solid var(--border-color); }
.ai-config-hint { padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px; background: var(--bg-hover); border-radius: 6px; }

/* AI 快速操作 */
.ai-quick-actions { display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }
.ai-action-group { display: flex; flex-direction: column; gap: 6px; }
.ai-group-label { font-size: 11px; color: var(--text-muted); font-weight: 600; text-transform: uppercase; letter-spacing: .5px; }
.ai-action-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.ai-action-btn { display: flex; flex-direction: column; align-items: center; gap: var(--space-xs); padding: 10px 6px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; color: var(--text-secondary); font-size: 11px; cursor: pointer; transition: all .15s; text-align: center; }
.ai-action-btn:hover { border-color: var(--accent-violet); color: var(--accent-violet); background: rgba(167, 139, 250, .08); transform: translateY(-1px); }
.ai-action-btn svg { width: 18px; height: 18px; }
