.ai-loading-spinner { width: 16px; height: 16px; border: 2px solid var(--border-color); border-top-color: var(--accent-violet); border-radius: 50%; animation: spin .8s linear infinite; }

/* AI 结果块 */
.ai-result-block { margin-top: 10px; border: 1px solid var(--accent-violet); border-radius: 8px; overflow: hidden; }
.ai-result-header { display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; background: rgba(167, 139, 250, .08); border-bottom: 1px solid rgba(167, 139, 250, .2); }
