.material-space-filter select { width: 100%; height: 32px; padding: 0 10px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; color: var(--text-primary); font-size: 13px; outline: none; cursor: pointer; }
.article-materials-panel h4 { margin-bottom: 0; font-size: 14px; }
.linked-material-count { font-size: 11px; color: var(--accent-cyan); font-weight: 500; }
.linked-materials-list { display: flex; flex-wrap: wrap; gap: var(--space-xs); margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid var(--border-color); }
.linked-material-item { display: inline-flex; align-items: center; gap: var(--space-xs); padding: 4px 8px; background: color-mix(in srgb, var(--accent-cyan) 5%, transparent); border: 1px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent); border-radius: 6px; font-size: 11px; }
.linked-material-text { max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-secondary); }
.linked-material-remove { background: transparent; border: none; color: var(--text-muted); cursor: pointer; padding: 0; display: flex; opacity: .5; transition: opacity .2s; }
