.materials-picker-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: var(--space-sm); max-height: 300px; overflow-y: auto; padding: 8px 0; }
.material-picker-item { display: flex; flex-direction: column; gap: var(--space-xs); padding: 8px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; cursor: pointer; transition: all .2s; text-align: left; }
.material-picker-item.selected { border-color: var(--accent-emerald); background: rgba(52, 211, 153, .05); }
.material-picker-content { font-size: 12px; color: var(--text-secondary); line-height: 1.4; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* 创作空间 Tabs */
.article-space-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 1px solid var(--border-color); }
.article-space-tab { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 12px; background: var(--bg-primary); border: var(--panel-border); border-radius: 8px; color: var(--text-secondary); font-size: 12px; font-weight: 500; cursor: pointer; transition: all .15s; }
