.article-space-assign { height: 24px; padding: 0 6px; background: var(--bg-primary); border: var(--panel-border); border-radius: 4px; color: var(--text-secondary); font-size: 11px; cursor: pointer; max-width: 100px; overflow: hidden; text-overflow: ellipsis; }
.article-space-assign:focus { outline: none; border-color: var(--accent-violet); }

/* 文章列表工具栏 */
.article-list-toolbar { display: flex; gap: var(--space-sm); align-items: center; margin-bottom: 12px; flex-wrap: wrap; }
.article-search-box { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 200px; padding: 0 10px; background: var(--bg-card); border: var(--panel-border); border-radius: 8px; color: var(--text-secondary); }
