.article-filter-select { height: 28px; padding: 0 8px; background: var(--bg-card); border: var(--panel-border); border-radius: 6px; color: var(--text-primary); font-size: 12px; cursor: pointer; }
.article-filter-select:focus { outline: none; border-color: var(--accent-cyan); }
