/* 文章列表项 */
.article-item-meta { display: flex; gap: var(--space-sm); align-items: center; font-size: 12px; color: var(--text-muted); flex-wrap: wrap; }
.btn-duplicate { width: 28px; height: 28px; background: transparent; border: var(--panel-border); border-radius: 6px; color: var(--text-secondary); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all .2s; }
.btn-duplicate svg { width: 14px; height: 14px; }
.btn-delete-article { width: 28px; height: 28px; background: transparent; border: var(--panel-border); border-radius: 6px; color: var(--text-muted); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all .2s; }
.btn-delete-article svg { width: 14px; height: 14px; }

/* 导出发布 */
.article-export-list { display: flex; flex-direction: column; gap: var(--space-sm); }
.article-export-item { display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background: var(--bg-card); border: var(--panel-border); border-radius: 8px; }
.article-export-info { display: flex; gap: var(--space-sm); align-items: center; flex: 1; }
