.article-export-actions { display: flex; gap: 6px; flex-wrap: wrap; }
.btn-export-md, .btn-export-html, .btn-export-wechat, .btn-export-zhihu, .btn-export-pdf { height: 28px; padding: 0 12px; border: var(--panel-border); border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; transition: all .2s; background: transparent; }
.btn-export-md { color: var(--accent-cyan); border-color: var(--accent-cyan); }
.btn-export-md:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.btn-export-html { color: var(--accent-blue); border-color: var(--accent-blue); }
.btn-export-html:hover { background: color-mix(in srgb, var(--accent-amber) 10%, transparent); }
.btn-export-pdf { color: var(--accent-rose); border-color: var(--accent-rose); }
.btn-export-pdf:hover { background: rgba(248, 113, 113, .1); }
.btn-export-wechat { color: var(--accent-emerald); border-color: var(--accent-emerald); }
