.batch-space-select { height: 24px; padding: 0 8px; background: var(--bg-card); border: 1px solid var(--accent-violet); border-radius: 4px; color: var(--text-primary); font-size: 11px; cursor: pointer; }
.batch-space-select:focus { outline: none; border-color: var(--accent-cyan); }
.btn-batch-delete { height: 24px; padding: 0 8px; background: rgba(248, 113, 113, .1); border: 1px solid rgba(248, 113, 113, .3); border-radius: 4px; color: var(--accent-rose); font-size: 11px; cursor: pointer; }
.btn-batch-delete:hover { background: rgba(248, 113, 113, .2); }
.btn-clear-selection { height: 24px; padding: 0 8px; background: transparent; border: var(--panel-border); border-radius: 4px; color: var(--text-secondary); font-size: 11px; cursor: pointer; }
.btn-clear-selection:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.btn-select-all { height: 24px; padding: 0 8px; background: transparent; border: var(--panel-border); border-radius: 4px; color: var(--text-secondary); font-size: 11px; cursor: pointer; }
.btn-select-all:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }

/* 标签筛选 */
.material-tag-filters { display: flex; align-items: center; gap: var(--space-xs); flex-wrap: wrap; }
.tag-filter-label { font-size: 11px; color: var(--text-muted); font-weight: 600; }
.material-tag-btn { height: 22px; padding: 0 8px; background: var(--bg-card); border: var(--panel-border); border-radius: 4px; color: var(--text-secondary); font-size: 11px; cursor: pointer; transition: all .2s; }
.material-tag-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.material-tag-btn.active { background: color-mix(in srgb, var(--accent-cyan) 15%, transparent); border-color: var(--accent-cyan); color: var(--accent-cyan); }
.tag-clear-btn { height: 22px; padding: 0 6px; background: transparent; border: none; color: var(--text-muted); font-size: 11px; cursor: pointer; text-decoration: underline; }

/* 素材卡片选中状态 */
.material-card { position: relative; }
.material-card.selected { border-color: var(--accent-violet); box-shadow: 0 0 0 2px rgba(167, 139, 250, .2); }
