.material-checkbox-label { display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 12px; color: var(--text-secondary); }
.material-checkbox-label input { width: 14px; height: 14px; cursor: pointer; accent-color: var(--accent-violet); }
.checkbox-custom { display: inline-block; width: 14px; height: 14px; border: var(--panel-border); border-radius: 3px; transition: all .2s; }
