.btn-icon { background: transparent; border: var(--panel-border); border-radius: 6px; padding: 6px; cursor: pointer; transition: all .2s; color: var(--text-secondary); display: flex; align-items: center; }
.btn-icon:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
