.add-material-form { padding: 20px; }
.form-group { margin-bottom: 12px; }
.form-group label { display: block; font-size: 12px; font-weight: 600; color: var(--text-secondary); margin-bottom: 4px; }
.form-group input, .form-group select, .form-group textarea { width: 100%; padding: 8px 10px; background: var(--bg-primary); border: var(--panel-border); border-radius: 6px; color: var(--text-primary); font-size: 13px; font-family: inherit; }
