.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-md); }
.form-actions { display: flex; justify-content: flex-end; gap: var(--space-sm); margin-top: 16px; }
.btn-modal-cancel { height: 32px; padding: 0 16px; background: transparent; border: var(--panel-border); border-radius: 6px; color: var(--text-secondary); font-size: 13px; cursor: pointer; }
.btn-modal-cancel:hover { border-color: var(--text-primary); color: var(--text-primary); }
.btn-modal-submit { height: 32px; padding: 0 16px; background: linear-gradient(135deg, #C9A961 0%, #D4B576 100%); border: none; border-radius: 6px; color: white; font-size: 13px; font-weight: 600; cursor: pointer; }
.btn-modal-submit:hover { opacity: .9; }

.markdown-preview h1 { font-size: 24px; border-bottom: 1px solid var(--border-color); padding-bottom: 8px; margin-bottom: 16px; }
.markdown-preview h2 { font-size: 20px; margin: 20px 0 12px; }
.markdown-preview h3 { font-size: 16px; margin: 16px 0 8px; }
.markdown-preview p { margin-bottom: 12px; }
.markdown-preview strong { font-weight: 700; }
.markdown-preview em { font-style: italic; }
.markdown-preview code { background: var(--bg-hover); padding: 2px 4px; border-radius: 3px; font-family: 'DM Mono', monospace; font-size: 13px; }
.markdown-preview blockquote { border-left: 3px solid var(--accent-violet); padding-left: 12px; color: var(--text-secondary); margin: 12px 0; }
.markdown-preview li { margin-left: 20px; margin-bottom: 4px; }
.markdown-preview a { color: var(--accent-cyan); text-decoration: underline; }

/* AI 结果内联展示 */
.ai-result-actions { display: flex; gap: var(--space-xs); margin-bottom: 8px; }
.btn-ai-insert { height: 24px; padding: 0 8px; background: var(--accent-violet); border: none; border-radius: 4px; color: white; font-size: 11px; cursor: pointer; }
.btn-ai-insert:hover { opacity: .8; }
.btn-ai-copy { height: 24px; padding: 0 8px; background: transparent; border: var(--panel-border); border-radius: 4px; color: var(--text-secondary); font-size: 11px; cursor: pointer; }
.btn-ai-copy:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.btn-ai-clear { height: 24px; padding: 0 8px; background: transparent; border: var(--panel-border); border-radius: 4px; color: var(--text-muted); font-size: 11px; cursor: pointer; }
.btn-ai-clear:hover { border-color: var(--accent-rose); color: var(--accent-rose); }
.ai-result-content { white-space: pre-wrap; font-size: 13px; line-height: 1.5; color: var(--text-primary); max-height: 200px; overflow-y: auto; padding: 8px; background: var(--bg-card); border-radius: 4px; }
.ai-result-error { margin-top: 8px; padding: 6px 10px; background: rgba(248, 113, 113, .1); border: 1px solid rgba(248, 113, 113, .3); border-radius: 6px; display: flex; justify-content: space-between; align-items: center; color: var(--accent-rose); font-size: 12px; }
.ai-result-error button { background: transparent; border: none; color: var(--accent-rose); cursor: pointer; }

/* 素材提示 */
.material-hint { font-size: 11px; color: var(--text-muted); font-weight: 400; }
.material-picker-item { cursor: pointer; transition: all .15s; }
.material-picker-item:hover { border-color: var(--accent-violet); background: rgba(167, 139, 250, .05); }

/* Responsive Layout */
@media (max-width: 768px) {
  .insight-watchlist { grid-template-columns: 1fr; }
  .reading-metrics { grid-template-columns: repeat(2, 1fr); }
}

/* Globe View */
.globe-container { width: 100%; min-height: 420px; }
.globe-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.globe-title { font-size: 15px; font-weight: 700; color: var(--text-primary); margin: 0; display: flex; align-items: center; gap: var(--space-sm); }
.globe-title::before { content: ''; width: 4px; height: 16px; background: var(--gradient-primary); border-radius: 2px; }
.globe-legend { display: flex; gap: 16px; }
.globe-legend-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-secondary); }
.globe-legend-dot { width: 8px; height: 8px; border-radius: 50%; }
.globe-legend-dot.heat-low { background: #10b981; }
.globe-legend-dot.heat-mid { background: #f59e0b; }
.globe-legend-dot.heat-high { background: #ef4444; }
.globe-wrapper { display: flex; justify-content: center; width: 100%; min-height: 420px; }
.globe-wrapper canvas { border-radius: var(--radius-card); }
.globe-expand-btn { position: absolute; top: 8px; right: 8px; z-index: 20; width: 32px; height: 32px; border-radius: 8px; border: 1px solid rgba(255, 255, 255, .1); background: rgba(10, 12, 16, .8); color: var(--text-secondary); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: var(--transition-base); backdrop-filter: blur(8px); }
.globe-expand-btn:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent); color: #C9A961; }
.globe-detail-panel { position: absolute; top: 0; right: 0; width: 320px; height: 420px; background: rgba(10, 12, 16, .95); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border-left: 1px solid rgba(255, 255, 255, .08); border-radius: 0 12px 12px 0; display: flex; flex-direction: column; z-index: 10; animation: slideInRight .3s ease-out; }
:root[data-mode="light"] .globe-detail-panel { background: rgba(255, 255, 255, .95); border-left: 1px solid var(--border-color); }
.globe-detail-header { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; border-bottom: 1px solid rgba(255, 255, 255, .06); }
:root[data-mode="light"] .globe-detail-header { border-bottom: 1px solid var(--border-color); }
.globe-detail-title { font-size: 14px; font-weight: 700; color: var(--text-primary); margin: 0; display: flex; align-items: center; gap: var(--space-sm); }
.globe-detail-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; box-shadow: 0 0 6px currentColor; }
.globe-detail-close { width: 28px; height: 28px; border-radius: 6px; border: 1px solid rgba(255, 255, 255, .08); background: rgba(255, 255, 255, .04); color: var(--text-secondary); cursor: pointer; transition: var(--transition-base); display: flex; align-items: center; justify-content: center; }
.globe-detail-close:hover { background: rgba(255, 255, 255, .12); color: var(--text-primary); }
:root[data-mode="light"] .globe-detail-close { border-color: var(--border-color); background: var(--bg-hover); }
:root[data-mode="light"] .globe-detail-close:hover { background: var(--bg-hover); border-color: var(--border-active); }
.globe-detail-list { flex: 1; overflow-y: auto; padding: 8px 12px; }
.globe-detail-item { padding: 10px 12px; border-radius: 8px; margin-bottom: 6px; cursor: pointer; transition: var(--transition-base); border: 1px solid transparent; }
.globe-detail-item:hover { background: rgba(255, 255, 255, .06); border-color: color-mix(in srgb, var(--accent-cyan) 20%, transparent); }
:root[data-mode="light"] .globe-detail-item:hover { background: var(--bg-hover); border-color: color-mix(in srgb, var(--accent-amber) 20%, transparent); }
.globe-detail-item-title { font-size: 12px; font-weight: 600; color: var(--text-primary); margin-bottom: 4px; line-height: 1.4; }
.globe-detail-item-meta { display: flex; justify-content: space-between; font-size: 10px; color: var(--text-muted); }

/* 小屏全球热点组件样式 */
.globe-embed-wrapper { position: relative; min-height: 420px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 2%, transparent), color-mix(in srgb, var(--accent-amber) 2%, transparent)); border-radius: 16px; padding: 16px; border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
:root[data-mode="light"] .globe-embed-wrapper { background: linear-gradient(135deg, color-mix(in srgb, var(--accent-amber) 4%, transparent), rgba(155, 163, 173, .04)); border: 1px solid color-mix(in srgb, var(--accent-amber) 10%, transparent); }
.globe-timeline { display: flex; align-items: center; gap: var(--space-sm); margin-bottom: 12px; padding: 8px 12px; background: var(--bg-card); border-radius: 10px; border: var(--panel-border); box-shadow: 0 2px 8px rgba(0, 0, 0, .04); }
:root[data-mode="light"] .globe-timeline { box-shadow: 0 2px 8px rgba(0, 0, 0, .06); }
.globe-timeline-btn { width: 28px; height: 28px; border-radius: 6px; border: var(--panel-border); background: var(--bg-card); color: var(--text-muted); font-size: 12px; cursor: pointer; transition: var(--transition-base); display: flex; align-items: center; justify-content: center; }
.globe-timeline-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border-color: var(--border-active); color: var(--accent-cyan); transform: translateY(-1px); box-shadow: 0 2px 4px color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
:root[data-mode="light"] .globe-timeline-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-amber) 10%, transparent); border-color: var(--border-active); color: #D4B576; box-shadow: 0 2px 4px color-mix(in srgb, var(--accent-amber) 10%, transparent); }
.globe-timeline-play { width: 32px; height: 28px; border-radius: 6px; border: 1px solid var(--border-active); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); color: var(--accent-cyan); font-size: 14px; cursor: pointer; transition: var(--transition-base); display: flex; align-items: center; justify-content: center; }
.globe-timeline-play:hover { background: color-mix(in srgb, var(--accent-cyan) 15%, transparent); transform: translateY(-1px); box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-cyan) 20%, transparent); }
:root[data-mode="light"] .globe-timeline-play:hover { background: color-mix(in srgb, var(--accent-amber) 15%, transparent); box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-amber) 20%, transparent); }
.globe-timeline-dates { display: flex; gap: 6px; flex: 1; overflow-x: auto; }
.globe-timeline-date { padding: 4px 10px; border-radius: 6px; border: var(--panel-border); background: var(--bg-card); color: var(--text-muted); font-size: 11px; cursor: pointer; transition: var(--transition-base); white-space: nowrap; font-weight: 500; }
.globe-timeline-date:hover { background: var(--bg-hover); border-color: var(--border-active); color: var(--text-secondary); transform: translateY(-1px); }
.globe-timeline-date.active { background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 15%, transparent), color-mix(in srgb, var(--accent-amber) 15%, transparent)); border-color: var(--border-active); color: var(--accent-cyan); font-weight: 600; box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-cyan) 20%, transparent); }
:root[data-mode="light"] .globe-timeline-date.active { background: linear-gradient(135deg, color-mix(in srgb, var(--accent-amber) 15%, transparent), rgba(155, 163, 173, .15)); color: #D4B576; box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-amber) 20%, transparent); }
.globe-filter-bar { display: flex; gap: var(--space-md); margin-bottom: 12px; }
.globe-filter-group { display: flex; align-items: center; gap: var(--space-sm); flex: 1; }
.globe-filter-label { font-size: 12px; font-weight: 600; color: var(--text-secondary); white-space: nowrap; }
.globe-filter-select { flex: 1; padding: 8px 12px; border-radius: 8px; border: var(--panel-border); background: var(--bg-card); color: var(--text-primary); font-size: 12px; cursor: pointer; transition: var(--transition-base); font-weight: 500; min-width: 0; }
.globe-filter-select:hover { border-color: var(--border-active); box-shadow: 0 2px 8px rgba(0, 0, 0, .06); }
.globe-filter-select:focus { outline: none; border-color: var(--accent-cyan); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
:root[data-mode="light"] .globe-filter-select:focus { border-color: #D4B576; box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-amber) 10%, transparent); }
.globe-filter-select option { padding: 8px; }
.globe-stats-bar { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 12px; }
.globe-stat-card { padding: 12px 14px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 5%, transparent), color-mix(in srgb, var(--accent-amber) 5%, transparent)); border-radius: var(--radius-card); border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent); text-align: center; transition: all .3s ease; position: relative; overflow: hidden; }
.globe-stat-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px; background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 40%, transparent), transparent); opacity: .6; }
.globe-stat-card:hover { border-color: var(--border-active); transform: translateY(-2px); box-shadow: 0 8px 20px color-mix(in srgb, var(--accent-cyan) 12%, transparent); }
:root[data-mode="light"] .globe-stat-card { background: linear-gradient(135deg, color-mix(in srgb, var(--accent-amber) 6%, transparent), rgba(155, 163, 173, .06)); border: 1px solid color-mix(in srgb, var(--accent-amber) 10%, transparent); }
:root[data-mode="light"] .globe-stat-card::before { background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-amber) 40%, transparent), transparent); }
:root[data-mode="light"] .globe-stat-card:hover { box-shadow: 0 8px 20px color-mix(in srgb, var(--accent-amber) 15%, transparent); }
.globe-stat-label { font-size: 11px; color: var(--text-muted); margin-bottom: 6px; font-weight: 600; text-transform: uppercase; letter-spacing: .5px; }
.globe-stat-value { font-size: 20px; font-weight: 800; color: var(--text-primary); line-height: 1; }
.globe-stat-unit { font-size: 11px; color: var(--text-secondary); margin-left: 3px; font-weight: 500; }

/* 全屏大屏样式 */
.globe-dashboard-overlay { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: var(--bg-primary); z-index: 9999; display: flex; flex-direction: column; overflow: hidden; }
.globe-dashboard { display: flex; flex: 1; overflow: hidden; position: relative; }
.globe-topbar { display: flex; align-items: center; justify-content: space-between; padding: 12px 20px; background: rgba(10, 12, 16, .95); border-bottom: 1px solid rgba(255, 255, 255, .06); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); }
:root[data-mode="light"] .globe-topbar { background: rgba(255, 255, 255, .95); border-bottom: 1px solid var(--border-color); }
.globe-topbar-left, .globe-topbar-center, .globe-topbar-right { display: flex; align-items: center; gap: var(--space-md); }
.globe-brand-icon { width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #C9A961, #D4B576); border-radius: 8px; }
.globe-topbar-stat { text-align: center; }
.globe-topbar-date { display: flex; align-items: center; gap: var(--space-sm); padding: 6px 12px; background: rgba(255, 255, 255, .04); border-radius: 6px; border: 1px solid rgba(255, 255, 255, .06); }
:root[data-mode="light"] .globe-topbar-date { background: var(--bg-hover); border: var(--panel-border); }
.globe-date-value { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.globe-bottombar { display: flex; align-items: center; gap: var(--space-sm); padding: 8px 20px; background: rgba(10, 12, 16, .95); border-top: 1px solid rgba(255, 255, 255, .06); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); }
:root[data-mode="light"] .globe-bottombar { background: rgba(255, 255, 255, .95); border-top: 1px solid var(--border-color); }
.globe-live-item { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--text-secondary); }
.globe-live-dot { width: 8px; height: 8px; border-radius: 50%; background: #ef4444; animation: pulse 2s infinite; flex-shrink: 0; }
.globe-live-dot.green { background: #22c55e; animation-delay: .5s; }
.globe-live-dot.blue { background: #C9A961; animation-delay: 1s; }

/* 全屏侧边栏面板 */
.globe-side-panel { width: 280px; background: rgba(10, 12, 16, .95); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border: 1px solid rgba(255, 255, 255, .06); display: flex; flex-direction: column; overflow: hidden; }
:root[data-mode="light"] .globe-side-panel { background: rgba(255, 255, 255, .95); border: var(--panel-border); }
.globe-side-left { border-right: 1px solid rgba(255, 255, 255, .06); }
:root[data-mode="light"] .globe-side-left { border-right: 1px solid var(--border-color); }
.globe-side-right { border-left: 1px solid rgba(255, 255, 255, .06); }
:root[data-mode="light"] .globe-side-right { border-left: 1px solid var(--border-color); }
.globe-panel { padding: 16px; }
.globe-panel-section { margin-bottom: 16px; }
.globe-panel-title { font-size: 13px; font-weight: 600; color: var(--text-primary); margin: 0 0 10px; display: flex; align-items: center; gap: 6px; }
.globe-panel-content { max-height: 200px; overflow-y: auto; }
.globe-stat-row { display: flex; align-items: center; gap: var(--space-sm); padding: 6px 0; cursor: pointer; transition: var(--transition-base); }
.globe-stat-row:hover { background: rgba(255, 255, 255, .04); padding-left: 8px; padding-right: 8px; margin-left: -8px; margin-right: -8px; }
:root[data-mode="light"] .globe-stat-row:hover { background: var(--bg-hover); }
.globe-stat-row-label { font-size: 11px; color: var(--text-secondary); flex: 1; }
.globe-stat-row-bar-wrap { width: 60px; height: 6px; background: rgba(255, 255, 255, .06); border-radius: 3px; overflow: hidden; }
:root[data-mode="light"] .globe-stat-row-bar-wrap { background: var(--bg-hover); }
.globe-stat-row-bar { height: 100%; background: linear-gradient(90deg, #C9A961, #D4B576); border-radius: 3px; transition: width .3s ease; }
.globe-stat-row-value { font-size: 12px; font-weight: 600; color: var(--text-primary); min-width: 24px; text-align: right; }
.globe-trend-chart { display: flex; flex-direction: column; gap: var(--space-xs); }
.globe-trend-date { font-size: 10px; color: var(--text-muted); text-align: center; }
.globe-trend-bar { height: 4px; background: linear-gradient(90deg, #C9A961, #D4B576); border-radius: 2px; transition: height .3s ease; }
.globe-topic-tag { padding: 4px 10px; background: rgba(255, 255, 255, .04); border-radius: var(--radius-card); border: 1px solid rgba(255, 255, 255, .06); font-size: 11px; color: var(--text-secondary); cursor: pointer; transition: var(--transition-base); }
.globe-topic-tag:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border-color: color-mix(in srgb, var(--accent-cyan) 20%, transparent); color: #C9A961; }
:root[data-mode="light"] .globe-topic-tag { background: var(--bg-hover); border: var(--panel-border); }
:root[data-mode="light"] .globe-topic-tag:hover { background: color-mix(in srgb, var(--accent-amber) 10%, transparent); border-color: color-mix(in srgb, var(--accent-amber) 20%, transparent); color: #D4B576; }

/* 全屏模式新闻列表 */
.globe-news-item { padding: 10px; border-radius: 8px; margin-bottom: 8px; cursor: pointer; transition: var(--transition-base); border: 1px solid transparent; }
.globe-news-item:hover { background: rgba(255, 255, 255, .04); border-color: color-mix(in srgb, var(--accent-cyan) 20%, transparent); }
.globe-news-title { font-size: 12px; font-weight: 600; color: var(--text-primary); margin-bottom: 4px; line-height: 1.4; }

@keyframes slideInRight { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

/* Logo Animations */
.logo-core-glow { animation: coreGlowPulse 3s ease-in-out infinite; }
.logo-rings { animation: ringsRotate 12s linear infinite; transform-origin: 24px 24px; }
.logo-core { animation: coreFloat 4s ease-in-out infinite; }
.logo-data-flow { animation: dataFlow 2s ease-in-out infinite; }
.logo-nodes { animation: nodesPulse 3s ease-in-out infinite; }
.logo-particles { animation: particlesOrbit 8s linear infinite; transform-origin: 24px 24px; }

@keyframes coreGlowPulse {
  0%, 100% { opacity: .8; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.15); }
}

@keyframes ringsRotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes coreFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2px); }
}

@keyframes dataFlow {
  0%, 100% { opacity: .6; }
  50% { opacity: 1; }
}

@keyframes nodesPulse {
  0%, 100% { opacity: .7; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.1); }
}

@keyframes particlesOrbit {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

.globe-dashboard-overlay { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: var(--bg-primary); z-index: 9999; overflow: hidden; }

/* 地球铺满全屏背景 */

/* 扫描线遮罩 */

/* 四角边框装饰 */
.globe-dashboard-overlay::before, .globe-dashboard-overlay::after { content: ''; position: absolute; width: 120px; height: 120px; border: 2px solid var(--border-glow); pointer-events: none; z-index: 3; }
.globe-dashboard-overlay::before { top: 16px; left: 16px; border-right: none; border-bottom: none; }
.globe-dashboard-overlay::after { top: 16px; right: 16px; border-left: none; border-bottom: none; }
.globe-dashboard-overlay .corner-bl, .globe-dashboard-overlay .corner-br { position: absolute; width: 120px; height: 120px; border: 2px solid var(--border-glow); pointer-events: none; z-index: 3; }
.globe-dashboard-overlay .corner-bl { bottom: 16px; left: 16px; border-right: none; border-top: none; }
.globe-dashboard-overlay .corner-br { bottom: 16px; right: 16px; border-left: none; border-top: none; }

/* 顶部标题栏 - 浮层 */
.globe-topbar > * { pointer-events: auto; }
.globe-topbar-left { display: flex; align-items: center; }
.globe-topbar-date { display: flex; flex-direction: column; align-items: center; gap: var(--space-xs); padding: 8px 24px; background: color-mix(in srgb, var(--accent-cyan) 5%, transparent); border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent); border-radius: 8px; }
.globe-date-label { font-size: 9px; color: var(--accent-cyan); text-transform: uppercase; letter-spacing: 3px; opacity: .6; }

/* 关闭按钮 */
.globe-close-btn:hover { background: rgba(239, 68, 68, .15); border-color: rgba(239, 68, 68, .4); color: #ef4444; box-shadow: 0 0 12px rgba(239, 68, 68, .2); }

/* 侧边浮层面板 */
.globe-side-panel > * { pointer-events: auto; }

/* 底部时间轴 */
.globe-bottombar > * { pointer-events: auto; }
.globe-bottombar .globe-timeline-btn { width: 32px; height: 32px; border-radius: 6px; border: var(--panel-border); background: var(--bg-card); color: var(--text-muted); font-size: 12px; cursor: pointer; transition: var(--transition-base); display: flex; align-items: center; justify-content: center; }
.globe-bottombar .globe-timeline-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border-color: var(--border-active); color: var(--accent-cyan); }
.globe-bottombar .globe-timeline-btn:disabled { opacity: .3; cursor: not-allowed; }
.globe-bottombar .globe-timeline-play { width: 36px; height: 32px; border-radius: 6px; border: 1px solid var(--border-active); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); color: var(--accent-cyan); font-size: 14px; cursor: pointer; transition: var(--transition-base); display: flex; align-items: center; justify-content: center; }
.globe-bottombar .globe-timeline-play:hover { background: color-mix(in srgb, var(--accent-cyan) 15%, transparent); box-shadow: 0 0 12px var(--border-glow); }
.globe-bottombar .globe-timeline-dates { display: flex; gap: 6px; }
.globe-bottombar .globe-timeline-date { padding: 6px 12px; border-radius: 6px; border: var(--panel-border); background: var(--bg-card); color: var(--text-muted); font-size: 12px; cursor: pointer; transition: var(--transition-base); white-space: nowrap; }
.globe-bottombar .globe-timeline-date:hover { background: var(--bg-hover); border-color: var(--border-active); color: var(--text-secondary); }
.globe-bottombar .globe-timeline-date.active { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); border-color: var(--border-active); color: var(--accent-cyan); font-weight: 600; box-shadow: 0 0 12px var(--border-glow); }

/* 详情面板 - 全屏模式居中 */
.globe-detail-panel.fullscreen { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 480px; max-height: 70vh; background: var(--bg-card); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border: 1px solid var(--border-active); border-radius: 16px; display: flex; flex-direction: column; z-index: 20; animation: panelScaleIn .3s ease-out; box-shadow: 0 0 60px var(--border-glow); }
@keyframes panelScaleIn { from { opacity: 0; transform: translate(-50%, -50%) scale(.9); } to { opacity: 1; transform: translate(-50%, -50%) scale(1); } }

/* 大屏主容器 */

/* 顶部标题栏 - 青蓝色发光效果 */

.globe-topbar::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 50%, transparent), transparent);
  animation: topbarGlow 3s ease-in-out infinite;
}

@keyframes topbarGlow {
  0%, 100% { opacity: .3; }
  50% { opacity: .8; }
}

/* 品牌区域 */

/* 统计卡片区域 */

.globe-topbar-stat:hover {
  background: color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  transform: translateY(-2px);
}

/* 关闭按钮 */

.globe-close-btn:hover {
  background: rgba(239, 68, 68, .2);
  border-color: rgba(239, 68, 68, .5);
  box-shadow: 0 0 15px rgba(239, 68, 68, .4);
  transform: rotate(90deg);
}

/* 左右侧边面板 */

.globe-side-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 50%, transparent), transparent);
  border-radius: var(--radius-card) 12px 0 0;
}

.globe-side-panel::-webkit-scrollbar {
  width: 4px;
}

.globe-side-panel::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, .02);
  border-radius: 2px;
}

.globe-side-panel::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #C9A961, #D4B576);
  border-radius: 2px;
  box-shadow: 0 0 10px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}

/* 面板区块 */

.globe-panel-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 30%, transparent), transparent);
  opacity: .5;
}

.globe-panel-section:hover {
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  transform: translateY(-2px);
}

.globe-panel-section:last-child {
  margin-bottom: 0;
}

/* 面板标题 */

/* 统计行 */

.globe-stat-row:hover {
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  transform: translateX(4px);
}

.globe-stat-row-bar-wrap {
  height: 6px;
  background: rgba(255, 255, 255, .1);
  border-radius: 3px;
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .3);
}

.globe-stat-row-bar {
  height: 100%;
  background: linear-gradient(90deg, #C9A961, #D4B576, #C9A961);
  background-size: 200% 100%;
  border-radius: 3px;
  transition: width .5s ease, background-position .3s ease;
  box-shadow: 0 0 10px color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  animation: barGlow 2s linear infinite;
}

.globe-stat-row-bar.source {
  background: linear-gradient(90deg, #fbbf24, #D4B576, #fbbf24);
  box-shadow: 0 0 10px rgba(251, 191, 36, .4);
}

.globe-stat-row-value {
  font-size: 12px;
  font-weight: 700;
  color: #C9A961;
  text-align: right;
  text-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}

/* 趋势图表 */

.globe-trend-bar {
  width: 100%;
  max-width: 30px;
  background: linear-gradient(180deg, #C9A961 0%, #D4B576 50%, #5A5A5A 100%);
  border-radius: 4px 4px 0 0;
  transition: height .5s ease;
  min-height: 8px;
  box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 30%, transparent), 0 4px 8px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  position: relative;
  overflow: hidden;
}

.globe-trend-bar::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: rgba(255, 255, 255, .5);
  box-shadow: 0 0 10px rgba(255, 255, 255, .5);
}

.globe-trend-date {
  font-size: 10px;
  color: rgba(203, 213, 225, .7);
  font-weight: 500;
}

/* 资讯列表 */

.globe-news-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.globe-news-item:hover {
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  transform: translateX(4px);
}

/* 话题云 */

.globe-topic-tag:hover {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 20%, transparent), color-mix(in srgb, var(--accent-amber) 20%, transparent));
  border-color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  transform: translateY(-2px);
}

/* 实时动态 */

.globe-live-item:hover {
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}

.globe-live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #C9A961;
  box-shadow: 0 0 10px #C9A961;
  animation: livePulse 1.5s ease-in-out infinite;
}

.globe-live-dot.blue {
  background: #D4B576;
  box-shadow: 0 0 10px #D4B576;
}

/* 底部时间轴 */

.globe-timeline-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  border-radius: 6px;
  color: #C9A961;
  cursor: pointer;
  transition: var(--transition-base);
}

.globe-timeline-btn:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  transform: scale(1.05);
}

.globe-timeline-btn:disabled {
  opacity: .3;
  cursor: not-allowed;
}

.globe-timeline-play {
  width: 40px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #C9A961, #D4B576);
