  border-radius: 6px;
  color: #0a0e1a;
  cursor: pointer;
  transition: var(--transition-base);
  box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 40%, transparent);
}

.globe-timeline-play:hover {
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  transform: scale(1.05);
}

/* 四角装饰 */
.corner-bl, .corner-br {
  position: absolute;
  width: 150px;
  height: 150px;
  border: 2px solid color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  pointer-events: none;
  z-index: 40;
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
}

.corner-bl {
  bottom: 20px;
  left: 20px;
  border-right: none;
  border-top: none;
}

.corner-br {
  bottom: 20px;
  right: 20px;
  border-left: none;
  border-top: none;
}

