.globe-dashboard {
  --gtd-accent: #18dcf5;
  --gtd-line: rgba(24, 220, 245, .28);
  --gtd-line-strong: rgba(24, 220, 245, .52);
  --gtd-text: rgba(239, 247, 252, .92);
  --gtd-muted: rgba(126, 180, 194, .78);
  --gtd-gap: clamp(12px, 1vw, 20px);
  --gtd-top: clamp(88px, 12vh, 124px);
  --gtd-bottom: clamp(82px, 11vh, 112px);
  --gtd-side: clamp(280px, 22vw, 420px);
  position: relative;
  width: 100vw;
  height: 100vh;
  display: grid;
  grid-template-rows: var(--gtd-top) minmax(0, 1fr) var(--gtd-bottom);
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  padding: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 46%, rgba(24, 220, 245, .12), transparent 32%),
    linear-gradient(180deg, #050a0f 0%, #07111a 52%, #03070b 100%);
  color: var(--gtd-text);
  font-family: "Bahnschrift", "DIN Alternate", "Microsoft YaHei", sans-serif;
}

.globe-dashboard::before {
  content: "";
  position: absolute;
  inset: var(--gtd-top) clamp(10px, 1.2vw, 22px) var(--gtd-bottom);
  border: 1px solid var(--gtd-line);
  box-shadow: inset 0 0 42px rgba(24, 220, 245, .05);
  pointer-events: none;
  z-index: 1;
}

.globe-dashboard::after {
  content: "";
  position: absolute;
  inset: var(--gtd-top) 0 var(--gtd-bottom);
  background-image:
    linear-gradient(rgba(24, 220, 245, .035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(24, 220, 245, .026) 1px, transparent 1px);
  background-size: 100% 4px, 56px 56px;
  pointer-events: none;
  z-index: 0;
}

.globe-topbar {
  position: relative;
  inset: auto;
  height: auto;
  grid-row: 1;
  display: grid;
  grid-template-columns: minmax(320px, .92fr) minmax(360px, 1.45fr) auto;
  align-items: center;
  gap: var(--gtd-gap);
  padding: clamp(14px, 2vh, 22px) clamp(18px, 2vw, 44px);
  background: rgba(3, 8, 13, .96);
  border-bottom: 1px solid var(--gtd-line);
  box-shadow: 0 16px 34px rgba(0, 0, 0, .28);
  z-index: 10;
}

.globe-topbar-brand {
  display: flex;
  align-items: center;
  gap: clamp(12px, 1vw, 18px);
  min-width: 0;
}

.globe-brand-icon {
  width: clamp(42px, 4.5vw, 54px);
  height: clamp(42px, 4.5vw, 54px);
  flex: 0 0 auto;
  border-radius: 10px;
  color: var(--gtd-accent);
  background: linear-gradient(145deg, rgba(24, 220, 245, .18), rgba(24, 220, 245, .05));
  border: 1px solid var(--gtd-line-strong);
  box-shadow: 0 0 22px rgba(24, 220, 245, .2), inset 0 0 18px rgba(24, 220, 245, .08);
}

.globe-brand-title {
  margin: 0;
  max-width: 100%;
  color: var(--gtd-accent);
  font-size: clamp(22px, 1.8vw, 30px);
  line-height: 1.08;
  font-weight: 900;
  letter-spacing: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 0 18px rgba(24, 220, 245, .34);
  background: none;
  -webkit-text-fill-color: currentColor;
}

.globe-brand-subtitle {
  margin-top: clamp(5px, .8vh, 9px);
  color: rgba(24, 220, 245, .68);
  font-size: clamp(10px, .78vw, 13px);
  letter-spacing: clamp(3px, .35vw, 6px);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.globe-topbar-center {
  min-width: 0;
}

.globe-hot-ticker {
  height: clamp(50px, 6.2vh, 70px);
  display: grid;
  grid-template-columns: clamp(104px, 8vw, 142px) 34px minmax(0, 1fr) 34px;
  gap: clamp(8px, .8vw, 16px);
  align-items: center;
  padding: 0 clamp(10px, .9vw, 16px);
  border-radius: 9px;
  border: 1px solid var(--gtd-line);
  background: rgba(6, 20, 30, .86);
  overflow: hidden;
}

.globe-hot-label {
  height: 70%;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-sm);
  color: var(--gtd-accent);
