  border-right: 1px solid var(--gtd-line);
  white-space: nowrap;
}

.globe-hot-track {
  display: flex;
  gap: clamp(10px, 1vw, 18px);
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-behavior: smooth;
  scrollbar-width: none;
}

.globe-hot-track::-webkit-scrollbar {
  display: none;
}

.globe-hot-nav {
  width: 32px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(24, 220, 245, .2);
  border-radius: 7px;
  color: var(--gtd-accent);
  background: rgba(24, 220, 245, .07);
  cursor: pointer;
  transition: background .18s ease, border-color .18s ease, transform .18s ease;
}

.globe-hot-nav:hover {
  background: rgba(24, 220, 245, .16);
