  transform: translateY(-1px);
}

.globe-hot-chip {
  height: clamp(34px, 4.3vh, 46px);
  min-width: min(420px, 52vw);
  display: grid;
  grid-template-columns: auto minmax(90px, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 0 clamp(10px, .9vw, 16px);
  border-radius: 7px;
  border: 1px solid rgba(24, 220, 245, .16);
  background: rgba(22, 42, 56, .72);
  text-align: left;
  cursor: pointer;
  font: inherit;
  flex: 0 0 auto;
  transition: background .18s ease, border-color .18s ease, transform .18s ease;
}

.globe-hot-chip:hover {
  background: rgba(24, 220, 245, .12);
  border-color: rgba(24, 220, 245, .38);
  transform: translateY(-1px);
}

.globe-hot-chip strong,
.globe-hot-chip span,
.globe-hot-chip em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.globe-hot-chip strong {
  color: var(--gtd-accent);
  font-size: clamp(12px, .74vw, 14px);
}

.globe-hot-chip span {
  color: var(--gtd-text);
