}

.globe-topbar-stats {
  display: flex;
  align-items: center;
  gap: clamp(8px, 1vw, 18px);
}

.globe-topbar-stat {
  width: clamp(76px, 6.3vw, 112px);
  height: clamp(62px, 7.6vh, 86px);
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 7px;
  padding: 0 8px;
  border-radius: 8px;
  border: 1px solid var(--gtd-line);
  background: rgba(6, 20, 30, .9);
}

.globe-stat-num {
  max-width: 100%;
  color: var(--gtd-accent);
  font-size: clamp(18px, 1.25vw, 24px);
  line-height: 1;
  font-weight: 900;
  letter-spacing: 1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  background: none;
  -webkit-text-fill-color: currentColor;
}

.globe-stat-desc {
  color: rgba(24, 220, 245, .68);
  font-size: clamp(10px, .72vw, 13px);
  white-space: nowrap;
}

.globe-close-btn {
  width: clamp(42px, 4vw, 52px);
  height: clamp(42px, 4vw, 52px);
  flex: 0 0 auto;
  border-radius: 10px;
}

.globe-stage,
.globe-side-panel,
.globe-bottombar {
  position: relative;
  inset: auto;
  transform: none;
}

.globe-stage {
  grid-row: 2;
  grid-column: 1;
  align-self: stretch;
  justify-self: stretch;
  margin: 0 calc(var(--gtd-side) + var(--gtd-gap));
  min-width: 0;
  min-height: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  z-index: 1;
  border-left: 1px solid var(--gtd-line);
  border-right: 1px solid var(--gtd-line);
  background:
    radial-gradient(circle at center, rgba(24, 220, 245, .15), transparent 35%),
    linear-gradient(90deg, rgba(24, 220, 245, .05), transparent 20%, transparent 80%, rgba(24, 220, 245, .05));
}

.globe-stage canvas {
  max-width: 100%;
  max-height: 100%;
  transform: scale(1.03);
  filter: saturate(1.08) contrast(1.04) drop-shadow(0 0 32px rgba(24, 220, 245, .18));
}

.globe-side-panel {
  grid-row: 2 / 4;
  width: var(--gtd-side);
  min-width: 0;
  top: auto;
  bottom: auto;
  padding: var(--gtd-gap);
  overflow-y: auto;
  z-index: 4;
  border: 1px solid var(--gtd-line);
  background: linear-gradient(180deg, rgba(5, 16, 24, .9), rgba(5, 16, 24, .68));
  box-shadow: inset 0 0 34px rgba(24, 220, 245, .04);
}

.globe-side-left {
  position: absolute;
  left: clamp(12px, 1.2vw, 24px);
  top: calc(var(--gtd-top) + var(--gtd-gap));
  bottom: var(--gtd-gap);
}

.globe-side-right {
  position: absolute;
  right: clamp(12px, 1.2vw, 24px);
  top: calc(var(--gtd-top) + var(--gtd-gap));
  bottom: var(--gtd-gap);
}

.globe-panel {
  height: 100%;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: var(--gtd-gap);
  overflow: visible;
}

.globe-panel-section {
  min-height: 0;
  margin: 0;
  padding: clamp(13px, 1.25vw, 20px);
  border-radius: 10px;
  border: 1px solid rgba(24, 220, 245, .18);
  background: linear-gradient(180deg, rgba(5, 15, 23, .88), rgba(5, 15, 23, .58));
  overflow: hidden;
}

.globe-panel-left .globe-panel-section:nth-child(1),
.globe-panel-left .globe-panel-section:nth-child(2) {
  min-height: clamp(126px, 17vh, 172px);
}

.globe-panel-right .globe-panel-section:nth-child(1) {
  min-height: clamp(248px, 35vh, 378px);
}

.globe-panel-title {
  margin: 0 0 clamp(10px, 1.4vh, 18px);
  color: var(--gtd-accent);
  font-size: clamp(17px, 1.2vw, 22px);
  font-weight: 900;
  text-shadow: 0 0 12px rgba(24, 220, 245, .35);
}

.globe-panel-icon {
  width: clamp(18px, 1.2vw, 22px);
  height: clamp(18px, 1.2vw, 22px);
}

.globe-panel-content {
  gap: clamp(8px, 1vh, 14px);
}

.globe-stat-row {
  grid-template-columns: minmax(98px, .78fr) minmax(66px, 1fr) 32px;
  gap: clamp(8px, .9vw, 14px);
