/* 聊天窗口头部 */
.ai-elf-chat-header { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 10%, transparent), color-mix(in srgb, var(--accent-amber) 10%, transparent)); border-bottom: 1px solid var(--border-color); flex-shrink: 0; }
