.ai-elf-message.assistant .ai-elf-message-text { background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 4%, transparent), transparent 60%); color: var(--text-primary); border-left: 2px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent); border-bottom-left-radius: 4px; }
:root[data-mode="light"] .ai-elf-message.user .ai-elf-message-text { background: linear-gradient(135deg, rgba(154, 123, 63, .1), rgba(120, 110, 90, .06)); border-color: rgba(154, 123, 63, .2); }
:root[data-mode="light"] .ai-elf-message.assistant .ai-elf-message-text { background: linear-gradient(180deg, rgba(154, 123, 63, .03), transparent 60%); border-left-color: rgba(154, 123, 63, .2); }

/* AI精灵消息内的Markdown样式 */
.ai-elf-message-text table { border-collapse: collapse; width: 100%; margin: 8px 0; font-size: 12px; }
.ai-elf-message-text th, .ai-elf-message-text td { border: var(--panel-border); padding: 6px 10px; text-align: left; }
.ai-elf-message-text th { background: var(--bg-hover); font-weight: 600; }
