.ai-elf-message-text code { padding: 2px 4px; background: var(--bg-primary); border-radius: 3px; font-family: 'SF Mono', 'Fira Code', monospace; font-size: 11px; color: var(--accent-cyan); }
.ai-elf-message-text pre { background: var(--bg-primary); padding: 8px; border-radius: 6px; overflow-x: auto; margin: 8px 0; }
