.ai-elf-message-text hr { border: none; border-top: 1px solid var(--border-color); margin: 12px 0; }

.ai-elf-message-time { font-size: 11px; color: var(--text-muted); margin-top: 4px; padding: 0 4px; }

/* AI精灵消息操作按钮 */
.ai-elf-message-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; padding: 0 4px; }
.ai-elf-action-btn {
