  border: 1px solid var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 12.5px;
  transition: all .18s cubic-bezier(.4,0,.2,1);
}
.source-filter-chips-row .chip svg { width: 14px; height: 14px; }
.source-filter-chips-row .chip:hover {
  border-color: rgba(138,106,53,.45);
