  border-color: transparent;
  box-shadow: 0 3px 8px rgba(138,106,53,.25);
}
.source-filter-chips-row .chip .chip-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 16px;
  padding: 0 5px;
  border-radius: 8px;
  font-size: 10.5px;
  background: rgba(120,130,145,.18);
  color: var(--text-secondary);
  font-weight: 600;
}
.source-filter-chips-row .chip.active .chip-badge {
  background: rgba(255,255,255,.22);
  color: #fff;
}

/* 源卡片布局 */
.source-batch-actions,
.source-filter-bar {
