  align-items: center;
  gap: var(--space-sm);
  margin-bottom: 16px;
  padding: 12px 16px;
  background: var(--bg-secondary);
  border-radius: 8px;
  flex-wrap: nowrap;
  overflow-x: auto;
}

.source-filter-bar::-webkit-scrollbar {
  height: 4px;
}

.source-filter-bar::-webkit-scrollbar-track {
  background: transparent;
}

.source-filter-bar::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 2px;
}

