  transform: none !important;
  box-shadow: none !important;
}

.source-action-btn.primary {
  background: var(--accent-cyan);
  color: var(--bg-primary);
  border-color: var(--accent-cyan);
  font-weight: 600;
}

.source-action-btn.primary:hover:not(:disabled) {
  opacity: .9;
  transform: translateY(-1px);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-cyan) 40%, transparent);
}

.source-action-btn.danger {
  border-color: var(--accent-red);
  color: var(--accent-red);
}

.source-action-btn.danger:hover:not(:disabled) {
  background: var(--accent-red);
  color: var(--bg-primary);
  border-color: var(--accent-red);
}

.source-search-input,
.source-filter-select {
  padding: 6px 10px;
  background: var(--bg-primary);
  border: var(--panel-border);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 13px;
  transition: border-color .2s ease, box-shadow .2s ease;
  min-height: 32px;
  min-width: 90px;
  max-width: 110px;
  flex-shrink: 0;
}

.source-search-input:focus,
.source-filter-select:focus {
  outline: none;
  border-color: var(--accent-cyan);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}

.source-search-input {
  flex: 1;
  min-width: 150px;
  max-width: 250px;
}

.source-filter-select {
  cursor: pointer;
  background-color: var(--bg-primary);
}

.source-filter-select option {
  background: var(--bg-primary);
  color: var(--text-primary);
  padding: 8px 12px;
}

/* 统计面板 - 内置信息源 */
.builtin-stats-panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 20px;
  padding: 20px;
  background: var(--bg-secondary);
  border-radius: var(--radius-card);
  border: var(--panel-border);
}

.builtin-stat-item {
  display: flex;
  align-items: center;
  gap: 16px;
