  border-radius: 8px;
  border: var(--panel-border);
  transition: var(--transition-base);
}

.builtin-stat-item:hover {
  border-color: var(--accent-cyan);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  transform: translateY(-2px);
}

.builtin-stat-item.enabled {
  border-left: 4px solid var(--accent-green);
}

.builtin-stat-item.disabled {
