  flex-direction: column;
  gap: var(--space-xs);
}

.builtin-stat-value {
  font-size: 28px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.builtin-stat-label {
  font-size: 13px;
  color: var(--text-muted);
  font-weight: 500;
}

/* 操作栏 - 内置信息源 */
.builtin-operations-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  padding: 16px 20px;
