  background: var(--bg-primary);
  border: var(--panel-border);
  border-radius: 8px;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition-base);
}

.batch-action-btn:hover:not(:disabled) {
