/* 源卡片网格 */
.sources-grid,
.builtin-sources-grid,
.custom-sources-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px;
  margin-top: 16px;
  max-height: 600px;
  overflow-y: auto;
  padding-right: 8px;
}

.sources-grid::-webkit-scrollbar,
.builtin-sources-grid::-webkit-scrollbar,
