  flex: 1;
}

/* 源卡片 */
.source-card {
  display: flex;
  background: var(--bg-secondary);
  border: var(--panel-border);
  border-radius: var(--radius-card);
  padding: 16px;
  transition: var(--transition-base);
  position: relative;
  overflow: hidden;
}

.source-card:hover {
