  box-shadow: 0 4px 12px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  transform: translateY(-2px);
}

.source-card.disabled {
  opacity: .5;
  background: var(--bg-secondary);
  filter: grayscale(30%);
  border-color: var(--border-color);
}

.source-card.disabled:hover {
  opacity: .6;
  border-color: var(--border-color);
  transform: none;
}

.source-card.disabled .source-card-name {
  color: var(--text-muted);
  text-decoration: line-through;
}

.source-card.disabled .source-card-url {
  color: var(--text-muted);
}

.source-card.disabled .source-grade-badge {
  opacity: .4;
}

.source-toggle-btn {
  padding: 6px 12px;
  background: var(--bg-primary);
  border: var(--panel-border);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition-base);
  white-space: nowrap;
}

.source-toggle-btn:hover {
  background: var(--bg-secondary);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}

.source-toggle-btn:active {
  transform: scale(.98);
}

.source-card.disabled .source-toggle-btn {
  background: var(--accent-green);
  border-color: var(--accent-green);
  color: #fff;
}

.source-card.disabled .source-toggle-btn:hover {
