  border-color: #15803d;
  color: #fff;
}

.source-card.health-healthy {
  border-left: 3px solid var(--accent-green);
}

.source-card.health-warning {
  border-left: 3px solid var(--accent-orange);
}

.source-card.health-error {
  border-left: 3px solid var(--accent-red);
}

.source-card-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.source-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
