/* 源等级徽章 - 简约风格 */
.source-grade-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .5px;
  color: #fff;
  margin-left: 8px;
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(10px);
  box-shadow: 0 4px 12px rgba(0, 0, 0, .15),
              inset 0 1px 0 rgba(255, 255, 255, .2);
}

.source-grade-badge::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(255, 255, 255, .3) 0%, rgba(255, 255, 255, 0) 50%);
  pointer-events: none;
}

.source-grade-badge::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, .15) 0%, transparent 70%);
  opacity: 0;
  transition: opacity .3s ease;
  pointer-events: none;
}

.source-grade-badge:hover::after {
  opacity: 1;
}

/* 新闻卡片中的等级徽章 - 透明荧光动态脉动效果 */
.news-item-source-grade {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  position: relative;
  z-index: 0;
  color: var(--grade-primary);
  text-shadow: none;
}

.news-item-source-grade::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  border: 1px solid var(--grade-primary);
  border-radius: 7px;
  background: rgba(255, 255, 255, .04);
  box-shadow:
    0 5px 12px var(--grade-glow),
    inset 0 0 0 1px rgba(255, 255, 255, .04);
}

.news-item-source-grade::after {
  content: '';
  position: absolute;
  inset: 3px;
  background: var(--grade-primary);
  opacity: .1;
  border-radius: 4px;
  z-index: -1;
}

