.panel-globe-preview {
  padding: 12px 14px 16px;
}

.globe-preview-card {
  position: relative;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 5%, transparent), color-mix(in srgb, var(--accent-amber) 5%, transparent));
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  border-radius: var(--radius-card);
  padding: 14px;
  cursor: pointer;
  transition: all .3s ease;
  overflow: hidden;
}

.globe-preview-card:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  transform: translateY(-2px);
}

.globe-preview-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 50%, transparent), transparent);
  opacity: .6;
}

.globe-preview-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
}

.globe-preview-globe {
  position: relative;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, color-mix(in srgb, var(--accent-cyan) 20%, transparent), transparent 60%),
              radial-gradient(circle at 65% 65%, color-mix(in srgb, var(--accent-amber) 15%, transparent), transparent 60%);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 10%, transparent), inset 0 0 15px color-mix(in srgb, var(--accent-cyan) 5%, transparent);
  animation: globePulse 3s ease-in-out infinite;
}

@keyframes globePulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 15px color-mix(in srgb, var(--accent-cyan) 10%, transparent), inset 0 0 15px color-mix(in srgb, var(--accent-cyan) 5%, transparent); }
  50% { transform: scale(1.05); box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 20%, transparent), inset 0 0 20px color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
}

.globe-preview-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80%;
  height: 80%;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  animation: ringExpand 2s ease-out infinite;
}

@keyframes ringExpand {
  0% { transform: translate(-50%, -50%) scale(.8); opacity: 1; }
  100% { transform: translate(-50%, -50%) scale(1.2); opacity: 0; }
}

.glob-preview-dot {
  position: absolute;
  width: 4px;
  height: 4px;
  background: var(--accent-cyan);
  border-radius: 50%;
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  animation: dotPulse 2s ease-in-out infinite;
}

.glob-preview-dot:nth-child(2) { animation-delay: .3s; }
.glob-preview-dot:nth-child(3) { animation-delay: .6s; }
.glob-preview-dot:nth-child(4) { animation-delay: .9s; }
.glob-preview-dot:nth-child(5) { animation-delay: 1.2s; }

@keyframes dotPulse {
  0%, 100% { opacity: .4; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.3); }
}

.globe-preview-info {
  text-align: center;
  margin-bottom: 8px;
}

.globe-preview-label {
