/* Copilot 锁定在右侧列，左侧内容可伸缩 */

/* 左侧拖拽缩放手柄 — 手柄向右拖 = 面板变宽 */

/* AiChatPanel — fixed right copilot, width by JS (panelWidth) */
.ai-chat-panel {
  position: fixed;
  right: 0;
  top: 0;
  bottom: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  height: 100vh;
  border-left: 1px solid var(--border-active);
  background: var(--surface-workbench);
  overflow: hidden;
  box-shadow: -4px 0 20px var(--border-glow);
}

/* AiChatPanel 作为首页三栏布局容器：会话栏 | 对话区 | 智能管理栏 */
.ai-chat-panel-main {
  position: relative;
  right: auto;
  top: auto;
  bottom: auto;
  z-index: auto;
  width: 100%;
  height: 100%;
  min-height: 0;
  border: none;
  border-radius: 0;
  box-shadow: none;
  background: var(--surface-workbench);
  display: grid;
  /* 三栏列宽可拖拽（v7）：变量由 AiChatPanel 根节点注入，拖动手柄改写 */
  grid-template-columns: var(--ws-left-w, 200px) 1fr var(--ws-right-w, 260px);
}
.ai-chat-panel-main.session-collapsed {
  grid-template-columns: 1fr var(--ws-right-w, 260px);
}
/* 三栏拖拽手柄：绝对定位贴列边界，不占 grid 单元 */
.ws-resize-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 8px;
  cursor: col-resize;
  z-index: 60;
  touch-action: none;
}
.ws-resize-handle::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  transform: translateX(-50%) scaleX(0);
  background: var(--accent-cyan);
  transition: transform .15s ease;
}
.ws-resize-handle:hover::after,
.ws-resize-handle:active::after {
  transform: translateX(-50%) scaleX(1);
}
.ws-resize-left { left: calc(var(--ws-left-w, 200px) - 4px); }
.ws-resize-right { right: calc(var(--ws-right-w, 260px) - 4px); }
.ai-chat-panel-main .chat-main-col {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  /* 净墨底：中栏保持最干净，仅顶部一点微光提亮焦点 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, rgba(255,255,255,.025) 70%, var(--bg-base, var(--bg-primary))) 0%,
      var(--bg-base, var(--bg-primary)) 18%);
  border-right: 1px solid color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 18%, transparent) 30%, var(--border-color));
  border-left: 1px solid color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 18%, transparent) 30%, var(--border-color));
  overflow: hidden;
  position: relative;
}
.ai-chat-panel-main .chat-main-col::before,
.ai-chat-panel-main .chat-main-col::after {
  /* 左右两侧描金渐隐分隔线（顶尾淡，中段微亮） */
  content: "";
  position: absolute;
  top: 0; bottom: 0;
  width: 1px;
  pointer-events: none;
  z-index: 1;
}
.ai-chat-panel-main .chat-main-col::before {
  left: 0;
  background: linear-gradient(180deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 14%, transparent) 50%, transparent) 30%,
    transparent 100%);
}
.ai-chat-panel-main .chat-main-col::after {
  right: 0;
  background: linear-gradient(180deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 14%, transparent) 50%, transparent) 30%,
    transparent 100%);
}
.ai-chat-panel-main .chat-messages { flex: 1 1 0; min-height: 0; min-width: 0; }

