/* --- Colorful Artistic Bubbles (scattered, draggable, poppable) --- */
/* --- Interest Bubbles (compact pill layout) --- */
.interest-bubble-container {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  width: 100%;
  padding: 0;
  min-height: 28px;
}

.interest-bubble {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 26px;
  padding: 0 12px;
  border-radius: 13px;
  border: none;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  transition: filter .2s ease, box-shadow .25s ease, transform .15s ease;
  animation: bubbleEnter .35s cubic-bezier(.34, 1.56, .64, 1) both;
}

.interest-bubble:hover {
  filter: brightness(1.15) saturate(1.2);
  transform: translateY(-1px);
}

.interest-bubble:active {
  transform: scale(.95);
}

.interest-bubble.bubble-entering {
  animation: bubbleEnter .35s cubic-bezier(.34, 1.56, .64, 1) both;
}

.interest-bubble.popping {
  animation: bubblePop .3s ease-out forwards !important;
  pointer-events: none;
}

.interest-bubble.popping::before {
  content: '';
  position: absolute;
  inset: -3px;
  border-radius: 16px;
  border: 1.5px solid currentColor;
  opacity: 0;
  animation: popRing .3s ease-out forwards;
}

@keyframes bubbleEnter {
  0%   { transform: scale(0); opacity: 0; }
  60%  { transform: scale(1.12); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

@keyframes bubblePop {
  0%   { transform: scale(1); opacity: 1; }
  40%  { transform: scale(1.3); opacity: .7; }
  100% { transform: scale(0); opacity: 0; }
}

@keyframes popRing {
  0%   { transform: scale(.8); opacity: .5; }
  100% { transform: scale(2); opacity: 0; }
}

.interest-bubble-empty {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 26px;
  padding: 0 10px;
  border-radius: 13px;
  border: 1.5px dashed var(--accent-cyan);
  background: var(--accent-cyan-softer);
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition-base);
}

.interest-bubble-empty:hover {
  background: var(--accent-cyan-soft);
  border-style: solid;
  box-shadow: 0 0 12px var(--border-glow);
}

.filter-pill {
  height: 32px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 700;
}

/* 评分徽章 */

.feedback-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
