/* 每日汇报「为你推荐」卡片边框增强 — 只作用于该区域，不影响全站 news-item */

.chat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
  background: linear-gradient(180deg, var(--accent-cyan-softer) 0%, transparent 100%);
}

.chat-header-left {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  flex: 1;
  min-width: 0;
}

.chat-header-left:hover { opacity: .85; }

.chat-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--accent-cyan) 25%, transparent));
  animation: chatAvatarPulse 3.5s ease-in-out infinite;
}

.chat-header-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: .3px;
}

.chat-header-actions {
  display: flex;
  gap: 6px;
}

.chat-header-btn {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: var(--surface-workbench-action);
  color: var(--text-muted);
  cursor: pointer;
  transition: all .15s ease;
}

.chat-header-btn:hover {
