.stock3-search .stock-search-dropdown { position: absolute; top: 100%; left: 0; right: 0; margin-top: 4px; background: var(--bg-card-solid); border: var(--panel-border); border-radius: 10px; overflow: hidden; z-index: 70; max-height: 320px; overflow-y: auto; }
