.stock-intelligence-head strong { color: var(--text-primary); font-size: 13px; }
.stock-intelligence-head span, .stock-intelligence-market span { color: var(--text-muted); font-size: 10px; }
.stock-intelligence-market { display: flex; align-items: center; gap: 8px; white-space: nowrap; }
.stock-intelligence-market b { color: var(--accent-amber); font: 700 11px var(--font-mono); }
.stock-intelligence-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 7px; }
.stock-intelligence-card { min-width: 0; padding: 9px 10px 7px; border: 1px solid var(--border-color); border-radius: 7px; background: var(--bg-primary); color: var(--text-secondary); text-align: left; transition: border-color .15s, background .15s; }
.stock-intelligence-card:hover, .stock-intelligence-card.active { border-color: var(--accent-cyan); background: var(--accent-cyan-soft); }
.stock-intelligence-pick { display: block; width: 100%; padding: 0; border: 0; background: transparent; color: inherit; text-align: left; cursor: pointer; }
.stock-intelligence-card-top { display: flex; align-items: baseline; gap: 5px; min-width: 0; }
.stock-intelligence-card-top strong { overflow: hidden; color: var(--text-primary); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.stock-intelligence-card-top em { overflow: hidden; color: var(--text-muted); font: 9px var(--font-mono); text-overflow: ellipsis; white-space: nowrap; }
.stock-intelligence-card-top b { margin-left: auto; color: var(--accent-amber); font: 700 15px var(--font-mono); }
.stock-intelligence-state, .stock-intelligence-reason, .stock-intelligence-risk { display: block; overflow: hidden; margin-top: 5px; font-size: 9px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.stock-intelligence-factors { display: block; overflow: hidden; margin-top: 4px; color: var(--text-muted); font: 8px var(--font-mono); line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.stock-intelligence-state { font-weight: 700; }
.stock-intelligence-state.positive, .stock-intelligence-reason { color: var(--signal-positive); }
.stock-intelligence-state.negative, .stock-intelligence-risk { color: var(--signal-critical); }
.stock-intelligence-state.caution { color: var(--accent-amber); }
.stock-intelligence-risk { color: var(--text-muted); }
.stock-intelligence-inspect { width: 100%; margin-top: 7px; padding: 5px 0 0; border: 0; border-top: 1px solid var(--border-color); background: transparent; color: var(--accent-cyan); font-size: 9px; font-weight: 700; text-align: left; cursor: pointer; }
.stock-intelligence-foot { display: flex; justify-content: space-between; gap: 12px; margin-top: 8px; color: var(--text-muted); font-size: 9px; }
.stock-intelligence-foot span:last-child { text-align: right; }
.stock-intelligence-empty { color: var(--text-muted); font-size: 11px; }
.stock-decision-tool { display: flex; flex-direction: column; gap: 12px; }
.stock-decision-summary { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 12px; border-left: 3px solid var(--accent-cyan); background: var(--bg-primary); }
.stock-decision-summary > div { display: flex; align-items: baseline; gap: 10px; }
.stock-decision-summary span { color: var(--text-muted); font-size: 10px; }
.stock-decision-summary strong { color: var(--text-primary); font-size: 14px; }
.stock-decision-summary button, .stock-decision-next button { padding: 6px 10px; border: 1px solid var(--accent-cyan-border); border-radius: 5px; background: var(--accent-cyan-soft); color: var(--accent-cyan); font-size: 10px; font-weight: 700; cursor: pointer; }
.stock-decision-summary button:disabled { opacity: .45; cursor: not-allowed; }
.stock-decision-coverage { display: grid; grid-template-columns: auto minmax(120px, 1fr) auto; align-items: center; gap: 10px; padding: 9px 11px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-primary); }
.stock-decision-coverage > div:first-child { display: flex; align-items: baseline; gap: 7px; white-space: nowrap; }
.stock-decision-coverage strong { color: var(--text-primary); font-size: 10px; }
.stock-decision-coverage span, .stock-decision-coverage small { color: var(--text-muted); font-size: 9px; }
.stock-decision-coverage-bar { height: 5px; overflow: hidden; border-radius: 999px; background: var(--bg-tertiary); }
.stock-decision-coverage-bar i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--signal-critical), var(--accent-cyan)); transition: width .2s ease; }
.stock-decision-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.stock-decision-grid section { min-width: 0; padding: 10px 11px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-primary); }
.stock-decision-grid section.support { border-top-color: rgba(34, 197, 94, .55); }
.stock-decision-grid section.counter { border-top-color: rgba(239, 68, 68, .55); }
.stock-decision-grid section.invalid { border-top-color: rgba(245, 196, 81, .55); }
.stock-decision-grid strong { display: block; margin-bottom: 6px; color: var(--text-primary); font-size: 10px; }
.stock-decision-grid p { margin: 4px 0; color: var(--text-secondary); font-size: 10px; line-height: 1.5; }
.stock-decision-missing { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
.stock-decision-missing strong { color: var(--signal-critical); font-size: 10px; }
.stock-decision-missing span { padding: 4px 7px; border: 1px solid rgba(239, 68, 68, .2); border-radius: 4px; color: var(--text-muted); font-size: 9px; }
.stock-decision-next { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 9px; border-top: 1px solid var(--border-color); }
.stock-decision-next > span { color: var(--text-secondary); font-size: 10px; line-height: 1.5; }
.stock-decision-next > div { display: flex; gap: 6px; flex-shrink: 0; }
.stock-policy-tool { display: flex; flex-direction: column; gap: 12px; }
.stock-policy-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; }
.stock-policy-grid label { display: flex; min-width: 0; flex-direction: column; gap: 5px; color: var(--text-muted); font-size: 9px; font-weight: 700; }
.stock-policy-grid input[type="number"], .stock-policy-grid select { width: 100%; height: 34px; padding: 0 9px; border: 1px solid var(--border-color); border-radius: 5px; background: var(--bg-primary); color: var(--text-primary); font: 11px var(--font-mono); outline: none; }
.stock-policy-grid input:focus, .stock-policy-grid select:focus { border-color: var(--accent-cyan); }
.stock-policy-grid .stock-policy-toggle { align-items: center; justify-content: center; flex-direction: row; padding: 0 10px; border: 1px solid var(--border-color); border-radius: 5px; background: var(--bg-primary); cursor: pointer; }
.stock-policy-toggle input { accent-color: var(--accent-cyan); }
.stock-policy-toggle span { color: var(--text-secondary); font-size: 10px; }
.stock-policy-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; }
.stock-policy-summary > div { padding: 9px 10px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-primary); }
.stock-policy-summary span, .stock-policy-summary strong { display: block; }
.stock-policy-summary span { margin-bottom: 4px; color: var(--text-muted); font-size: 9px; }
.stock-policy-summary strong { overflow: hidden; color: var(--text-primary); font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.stock-data-scope {
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 32px;
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 7px;
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 10px;
}
.stock-data-scope strong { color: var(--text-secondary); font-size: 10px; }
.stock-data-scope .limited { margin-left: auto; color: var(--accent-amber); }
.stock-benchmark-select { display: inline-flex; align-items: center; gap: 6px; color: var(--text-muted); font-size: 10px; white-space: nowrap; }
.stock-benchmark-select select { height: 24px; padding: 0 22px 0 7px; border: var(--panel-border); border-radius: 5px; background: var(--bg-primary); color: var(--text-primary); font-size: 10px; }
.stock-help-dot {
  display: inline-grid;
  place-items: center;
  width: 15px;
  height: 15px;
  margin-left: 4px;
  border: 1px solid var(--border-color);
  border-radius: 50%;
  color: var(--text-muted);
  font: 700 9px/1 var(--font-sans);
}

/* 三栏主体 */
.stock3-body {
  display: grid;
  grid-template-columns: clamp(210px, 17vw, 250px) minmax(480px, 1fr) clamp(270px, 21vw, 320px);
  gap: 10px;
  height: clamp(540px, 64vh, 650px);
  min-height: 0;
}
.stock3-body.no-left {
  grid-template-columns: minmax(520px, 1fr) clamp(270px, 21vw, 320px);
}
.stock3-body.no-right {
  grid-template-columns: clamp(210px, 17vw, 250px) minmax(520px, 1fr);
}
.stock3-body.no-left.no-right {
  grid-template-columns: minmax(0, 1fr);
}
.stock3-body.no-left.no-right .stock3-main {
  min-height: 650px;
}

/* 左栏 */
.stock3-left { display: flex; flex-direction: column; height: 100%; min-height: 0; border: var(--panel-border); border-radius: 10px; background: var(--bg-card); overflow: hidden; }
.stock3-left-tabs { display: flex; border-bottom: 1px solid var(--border-color); }
.stock3-left-tab { flex: 1; padding: 10px; border: none; background: transparent; color: var(--text-muted); font-size: 13px; font-weight: 600; cursor: pointer; transition: all .15s; border-bottom: 2px solid transparent; }
.stock3-left-tab.active { color: var(--accent-cyan); border-bottom-color: var(--accent-cyan); }
.stock3-left-list { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-gutter: stable; padding: 4px; }
.stock3-list-empty { padding: 24px 12px; text-align: center; font-size: 12px; color: var(--text-muted); line-height: 1.6; }
.stock3-list-item { display: flex; align-items: center; justify-content: space-between; gap: var(--space-sm); width: 100%; padding: 6px 10px; border: none; border-radius: 6px; background: transparent; cursor: pointer; transition: background .12s; text-align: left; margin-bottom: 2px; }
.stock3-list-item:hover { background: var(--bg-hover); }
.stock3-list-item.active { background: var(--accent-cyan-soft); }
.stock3-list-item .li-left { display: flex; flex-direction: column; gap: 1px; min-width: 0; flex: 1; }
.stock3-list-item .li-right { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; flex-shrink: 0; }
.stock3-list-item .li-name { font-size: 13px; font-weight: 600; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 130px; }
.stock3-list-item .li-price { font-family: var(--font-mono); font-size: 13px; font-weight: 700; }
.stock3-list-item .li-code { font-family: var(--font-mono); font-size: 10px; color: var(--text-muted); }
.stock3-list-item .li-chg { font-family: var(--font-mono); font-size: 11px; font-weight: 700; }
.stock3-list-item.up .li-price, .stock3-list-item.up .li-chg { color: var(--signal-critical); }
.stock3-list-item.down .li-price, .stock3-list-item.down .li-chg { color: var(--signal-positive); }

/* 中栏 */
.stock3-main {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  border: var(--panel-border);
  border-radius: 10px;
  /* 墨色玻璃质感：底色 + 内嵌金线 + 顶部微光 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, rgba(255,255,255,.018) 70%, var(--bg-card)) 0%,
      var(--bg-card) 60%) padding-box,
    linear-gradient(180deg,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 22%, transparent) 50%, transparent) 0%,
      transparent 100%) border-box;
  padding: 14px 16px;
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 5%, transparent),
    0 2px 10px -4px rgba(0,0,0,.18);
  transition: box-shadow .25s ease;
  position: relative;
}
.stock3-main::before {
  /* 顶部 1px 描金渐隐线，呼应水墨卡片风格 */
  content: "";
  position: absolute;
  top: 0; left: 10px; right: 10px;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 28%, transparent) 50%, transparent) 40%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 40%, transparent) 60%, transparent) 50%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 24%, transparent) 50%, transparent) 60%,
    transparent 100%);
  opacity: .75;
  pointer-events: none;
}
.stock3-chart-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; gap: var(--space-md); flex-wrap: wrap; }
.stock3-title { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.stock3-title h2 { margin: 0; font-size: 18px; font-weight: 700; color: var(--text-primary); }
.stock3-code { font-family: var(--font-mono); font-size: 12px; color: var(--text-muted); }
.stock3-price { display: inline-flex; align-items: baseline; gap: var(--space-sm); }
.stock3-price strong { font-family: var(--font-mono); font-size: 20px; font-weight: 700; }
.stock3-price em { font-family: var(--font-mono); font-size: 13px; font-style: normal; }
.stock3-price.up strong, .stock3-price.up em { color: var(--signal-critical); }
.stock3-price.down strong, .stock3-price.down em { color: var(--signal-positive); }
.stock3-chart-toolbar { display: flex; align-items: center; justify-content: flex-end; gap: 8px; min-width: 0; flex-wrap: wrap; }
.stock3-period { display: flex; gap: var(--space-xs); max-width: 100%; overflow-x: auto; background: var(--bg-primary); border-radius: 8px; padding: 3px; }
.stock3-period-btn { padding: 5px 12px; border: none; border-radius: 6px; background: transparent; color: var(--text-muted); font-size: 12px; font-weight: 600; cursor: pointer; transition: all .15s; }
.stock3-period-btn.active { background: var(--accent-cyan); color: #071d18; }
.stock3-adjust { display: inline-flex; align-items: center; gap: 5px; color: var(--text-muted); font-size: 10px; white-space: nowrap; }
.stock3-adjust select { height: 28px; padding: 0 22px 0 7px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); color: var(--text-secondary); font-size: 11px; outline: none; cursor: pointer; }
.stock-kline-status { padding: 4px 7px; border: 1px solid var(--border-color); border-radius: 5px; color: var(--text-muted); font: 700 9px/1 var(--font-mono); white-space: nowrap; }
.stock-kline-status.error { border-color: rgba(239, 68, 68, .35); color: var(--signal-critical); }
.stock3-layout-tools { display: inline-flex; align-items: center; gap: 3px; padding: 3px; border: var(--panel-border); border-radius: 7px; background: var(--bg-primary); }
.stock3-layout-tools button { width: 28px; height: 28px; display: grid; place-items: center; padding: 0; border: 0; border-radius: 5px; background: transparent; color: var(--text-muted); cursor: pointer; }
.stock3-layout-tools button:hover, .stock3-layout-tools button.active { background: var(--accent-cyan-soft); color: var(--accent-cyan); }
.stock3-layout-tools svg { width: 14px; height: 14px; }
.stock3-chart-wrap { flex: 1 1 auto; height: auto; min-height: 0; display: flex; overflow: hidden; }
.stock-kline-shell { position: relative; flex: 1 1 auto; min-width: 0; height: 100%; min-height: 0; overflow: hidden; }
.stock-kline-svg { display: block; width: 100%; height: 100%; overflow: visible; }
.stock-kline-svg { cursor: crosshair; user-select: none; touch-action: none; }
.stock-kline-svg.is-dragging { cursor: grabbing; }
.stock-kline-controls { position: absolute; z-index: 2; top: 7px; right: 8px; display: inline-flex; align-items: center; gap: 3px; padding: 3px; border: 1px solid var(--border-color); border-radius: 6px; background: color-mix(in srgb, var(--bg-card) 90%, transparent); color: var(--text-muted); font: 10px var(--font-mono); }
.stock-kline-controls span { padding: 0 4px; }
.stock-kline-controls button { width: 24px; height: 22px; padding: 0; border: 0; border-radius: 4px; background: transparent; color: var(--text-secondary); font: 700 16px/1 var(--font-mono); cursor: pointer; }
.stock-kline-controls button:hover:not(:disabled) { background: var(--accent-cyan-soft); color: var(--accent-cyan); }
.stock-kline-controls button:disabled { opacity: .35; cursor: not-allowed; }
.stock-kline-grid { stroke: var(--border-color); stroke-width: 1; stroke-dasharray: 3 5; }
.stock-kline-divider { stroke: var(--border-strong); stroke-width: 1; }
.stock-kline-axis { fill: var(--text-muted); font: 10px var(--font-mono); }
.stock-kline-wick { stroke: currentColor; stroke-width: 1; vector-effect: non-scaling-stroke; }
.stock-kline-body { fill: currentColor; }
.stock-kline-volume { fill: currentColor; opacity: .28; }
.stock-kline-svg g.up { color: var(--signal-critical); }
.stock-kline-svg g.down { color: var(--signal-positive); }
.stock-kline-ma { fill: none; stroke-width: 1.3; vector-effect: non-scaling-stroke; }
.stock-kline-ma.ma5 { stroke: #f5c451; }
.stock-kline-ma.ma10 { stroke: #46b8e8; }
.stock-kline-ma.ma20 { stroke: #c084fc; }
.stock-kline-legend text { font: 700 10px var(--font-mono); fill: var(--text-muted); }
.stock-kline-legend text.ma5 { fill: #f5c451; }
.stock-kline-legend text.ma10 { fill: #46b8e8; }
.stock-kline-legend text.ma20 { fill: #c084fc; }
.stock-kline-crosshair line { stroke: var(--accent-cyan); stroke-width: 1; stroke-dasharray: 3 3; vector-effect: non-scaling-stroke; opacity: .8; }
.stock-kline-crosshair circle { fill: var(--bg-card); stroke: var(--accent-cyan); stroke-width: 2; vector-effect: non-scaling-stroke; }
.stock-kline-price-tag { fill: var(--accent-cyan); }
.stock-kline-price-text { fill: #071116; font: 700 10px var(--font-mono); }
.stock-kline-tooltip rect { fill: color-mix(in srgb, var(--bg-card) 96%, #071116); stroke: var(--border-strong); stroke-width: 1; vector-effect: non-scaling-stroke; }
.stock-kline-tooltip text { fill: var(--text-secondary); font: 10px var(--font-mono); }
.stock-kline-tooltip text.date { fill: var(--text-primary); font-weight: 700; }
.stock-kline-tooltip text.change-up { fill: var(--signal-critical); }
.stock-kline-tooltip text.change-down { fill: var(--signal-positive); }
.stock-kline-svg g.is-active .stock-kline-body { stroke: var(--accent-cyan); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.stock3-chart-wrap .stock-timeline-svg { width: 100%; height: 100%; min-height: 0; }
.stock-chart-empty { display: flex; align-items: center; justify-content: center; width: 100%; min-height: 380px; color: var(--text-muted); font-size: 13px; }
.stock-kline-empty { position: absolute; inset: 0; min-height: 0; background: var(--bg-card); }
.stock-kline-empty { flex-direction: column; gap: 9px; text-align: center; }
.stock-kline-empty .spinner { width: 18px; height: 18px; border: 2px solid var(--border-color); border-top-color: var(--accent-cyan); border-radius: 50%; animation: spin .8s linear infinite; }
.stock-chart-error strong { color: var(--text-primary); font-size: 13px; }
.stock-chart-error span { max-width: 420px; color: var(--text-muted); font-size: 11px; line-height: 1.5; }
.stock-chart-error button { height: 30px; padding: 0 12px; border: 1px solid var(--accent-cyan-border); border-radius: 6px; background: var(--accent-cyan-soft); color: var(--accent-cyan); font-size: 11px; font-weight: 800; cursor: pointer; }

/* 右栏 */
.stock3-right { display: flex; flex-direction: column; gap: var(--space-md); min-height: 0; max-height: 100%; overflow-y: auto; overscroll-behavior: contain; scrollbar-gutter: stable; }
.stock3-right .stock3-panel { flex-shrink: 0; }
.stock3-panel { border: var(--panel-border); border-radius: 10px; background: var(--bg-card); padding: 12px 14px; }
.stock3-panel-label { font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 10px; }

/* 五档盘口 */
.stock-orderbook { display: flex; flex-direction: column; gap: 6px; }
.stock-orderbook-rows { display: flex; flex-direction: column; gap: 2px; }
.stock-orderbook-row { position: relative; display: grid; grid-template-columns: 32px 1fr 50px; align-items: center; gap: var(--space-sm); padding: 4px 6px; border-radius: 4px; overflow: hidden; }
.stock-orderbook-row .ob-label { font-size: 10px; color: var(--text-muted); font-weight: 600; z-index: 1; }
.stock-orderbook-row .ob-price { font-family: var(--font-mono); font-size: 12px; font-weight: 700; z-index: 1; }
.stock-orderbook-row .ob-vol { font-family: var(--font-mono); font-size: 11px; color: var(--text-muted); text-align: right; z-index: 1; }
.stock-orderbook-row .ob-bar { position: absolute; top: 0; right: 0; bottom: 0; opacity: .15; }
.stock-orderbook-row.ask .ob-price { color: var(--signal-critical); }
.stock-orderbook-row.ask .ob-bar { background: var(--signal-critical); }
.stock-orderbook-row.bid .ob-price { color: var(--signal-positive); }
.stock-orderbook-row.bid .ob-bar { background: var(--signal-positive); }
.stock-orderbook-mid { display: flex; align-items: baseline; justify-content: center; gap: var(--space-sm); padding: 6px 0; border-top: 1px dashed var(--border-color); border-bottom: 1px dashed var(--border-color); margin: 4px 0; }
.stock-orderbook-mid span { font-family: var(--font-mono); font-size: 18px; font-weight: 800; }
.stock-orderbook-mid span.up { color: var(--signal-critical); }
.stock-orderbook-mid span.down { color: var(--signal-positive); }
.stock-orderbook-mid em { font-family: var(--font-mono); font-size: 12px; color: var(--text-muted); font-style: normal; }
.stock-orderbook-empty { padding: 20px; text-align: center; font-size: 12px; color: var(--text-muted); }

/* 关键指标 */
.stock3-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-sm); }
.stock3-metric { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); }
.stock3-metric span { font-size: 10px; color: var(--text-muted); letter-spacing: .04em; }
.stock3-metric strong { font-family: var(--font-mono); font-size: 13px; font-weight: 700; color: var(--text-primary); }

.stock-ai-action {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 8px 14px;
