  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}
.block-panel-desc {
  font-size: 12px;
  color: var(--text-muted);
  margin: 2px 0 0;
  line-height: 1.5;
}
.block-panel-action { flex-shrink: 0; }
.block-panel-body { min-width: 0; }

.block-panel-clickable { cursor: pointer; text-align: left; color: inherit; }
.block-panel-interactive { transition: transform var(--ease-base), border-color var(--ease-base), background var(--ease-base); }
.block-panel-interactive:hover {
  transform: translateY(-2px);
  border-color: var(--border-active);
  background: var(--surface-workbench-ai);
}

.block-list { display: flex; flex-direction: column; }
.block-list-divided .block-row + .block-row { border-top: 1px solid var(--border-color); }

/* BlockList.Row */
.block-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 8px;
  color: inherit;
  text-align: left;
  transition: background .15s ease, border-color .18s ease, transform .18s ease;
}
.block-row-grid {
  display: grid;
  grid-template-columns: 24px 1fr auto;
  align-items: center;
}
.block-row-clickable { cursor: pointer; }
.block-row-clickable:hover { background: var(--bg-hover); }
.block-row-active,
.block-row-clickable.block-row-active:hover {
  border: 1px solid var(--border-active);
  background: var(--surface-workbench-ai);
}
.block-row-rank {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-muted);
  line-height: 1;
  text-align: center;
  font-family: var(--font-mono);
}
/* 前三名排名高亮（对齐 hotspot-row 配色） */
.block-row-grid:nth-child(1) .block-row-rank { color: #fbbf24; }
.block-row-grid:nth-child(2) .block-row-rank { color: #f97316; }
.block-row-grid:nth-child(3) .block-row-rank { color: #ef4444; }
.block-row-title {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.block-row-meta {
  color: var(--text-muted);
  font-size: 11px;
  white-space: nowrap;
}

.block-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}
.block-toolbar-wrap { flex-wrap: wrap; }
.block-toolbar-slot { margin-left: auto; display: flex; align-items: center; gap: var(--space-sm); }

.block-pills {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.block-pill {
  border: var(--panel-border);
  background: var(--surface-workbench-control);
  color: var(--text-secondary);
  border-radius: 7px;
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color .18s ease, color .18s ease, background .18s ease;
}
.block-pill:hover { color: var(--text-primary); border-color: var(--border-active); }
.block-pill.active {
  color: var(--accent-cyan);
  border-color: var(--border-active);
  background: var(--accent-cyan-soft);
}

.block-search {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 6px 12px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control);
  min-width: 180px;
}
.block-search:focus-within { border-color: var(--accent-cyan); }
.block-search-icon {
  display: grid;
  place-items: center;
  color: var(--text-muted);
  flex-shrink: 0;
}
.block-search-icon svg { width: 15px; height: 15px; }
.block-search input {
  border: none;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 13px;
  width: 100%;
  min-width: 0;
}
.block-search input::placeholder { color: var(--text-muted); }

.block-grid {
  display: grid;
  gap: var(--space-md);
}

/* 窄屏降级 */

/* BlockGrid.Card */
.block-grid-card {
  min-height: 186px;
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: 10px;
  text-align: left;
  color: inherit;
  cursor: pointer;
  border: var(--panel-border);
  border-radius: var(--radius-card);
  background: var(--bg-card);
  box-shadow: var(--shadow-subtle);
  transition: transform var(--ease-base), border-color var(--ease-base), background var(--ease-base);
}
.block-grid-card-clickable:hover {
  transform: translateY(-2px);
  border-color: var(--border-active);
  background: var(--surface-workbench-ai);
}
.block-grid-card-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}
.block-grid-card-icon svg { width: 18px; height: 18px; }
.block-grid-card-title {
  color: var(--text-primary);
  font-size: 17px;
  font-weight: 900;
}
.block-grid-card-desc {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.65;
}
.block-grid-card-meta {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
  color: var(--text-muted);
  font-size: 12px;
}
.block-grid-card-meta strong { color: var(--accent-cyan); font-size: 13px; }
.block-grid-card-meta em { font-style: normal; font-weight: 800; }

.block-stat-card {
  border: var(--panel-border);
  border-radius: var(--radius-card);
  background: var(--bg-card);
  box-shadow: var(--shadow-card);
  min-height: 110px;
  padding: 14px;
  display: flex;
  flex-direction: column;
}
.block-stat-card-label {
  display: block;
  margin-bottom: 6px;
  color: var(--accent-cyan);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .08em;
}
.block-stat-card-value {
  display: block;
  color: var(--text-primary);
  font-size: 28px;
  line-height: 1;
  font-weight: 800;
}
.block-stat-card-desc {
  margin-top: 8px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.cmd-palette-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, .4);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  animation: cmd-palette-fade .15s ease;
}
@keyframes cmd-palette-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
.cmd-palette {
  width: min(560px, 92vw);
  max-height: 60vh;
  background: var(--bg-card-solid, var(--bg-card));
  border: 1px solid var(--border-active);
  border-radius: 14px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, .4), 0 0 0 1px var(--accent-cyan-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: cmd-palette-slide .18s ease;
}
@keyframes cmd-palette-slide {
  from { transform: translateY(-12px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
.cmd-palette-input-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--border-color);
}
.cmd-palette-icon {
  display: grid;
  place-items: center;
  color: var(--text-muted);
  flex-shrink: 0;
}
.cmd-palette-icon svg { width: 18px; height: 18px; }
.cmd-palette-input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 15px;
}
.cmd-palette-input::placeholder { color: var(--text-muted); }
.cmd-palette-esc {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  background: var(--surface-workbench-control);
  border: var(--panel-border);
  border-radius: 5px;
  padding: 2px 6px;
  flex-shrink: 0;
}
.cmd-palette-list {
  overflow-y: auto;
  padding: 6px;
  flex: 1;
}
.cmd-palette-empty {
  padding: 24px;
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
}
.cmd-palette-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 12px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  border-radius: 8px;
  cursor: pointer;
  text-align: left;
  transition: background .1s ease, color .1s ease;
}
.cmd-palette-item.active {
  background: var(--accent-cyan-soft);
  color: var(--text-primary);
}
.cmd-palette-item-icon {
  display: grid;
  place-items: center;
  color: var(--accent-cyan);
  flex-shrink: 0;
}
.cmd-palette-item-icon svg { width: 15px; height: 15px; }
.cmd-palette-item-label {
  flex: 1;
  font-size: 13px;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cmd-palette-item-hint {
  font-size: 11px;
  color: var(--text-muted);
  flex-shrink: 0;
}
.cmd-palette-item.active .cmd-palette-item-hint {
  color: var(--accent-cyan);
}

.page-loading-skeleton {
  min-height: 320px;
  display: grid;
  place-items: center;
  color: var(--text-muted);
  font-size: 13px;
  background:
    linear-gradient(90deg, transparent, var(--surface-workbench-ai), transparent) center / 200% 100% no-repeat,
    var(--bg-secondary);
  animation: skeleton-shimmer 1.4s ease infinite;
}
@keyframes skeleton-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.sidebar.collapsed .nav-primary-item {
  flex-direction: column;
  gap: 2px;
  padding: 4px 2px;
  min-height: 48px;
}
.nav-short-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  line-height: 1;
  letter-spacing: .02em;
  transition: opacity .15s;
}
.nav-primary-item.active .nav-short-label {
  color: var(--accent-cyan);
}
.sidebar:not(.collapsed) .nav-short-label { display: none; }

.stock3-breadth {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 10px;
  border-left: 1px solid var(--border-color);
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
}
.stock3-breadth .breadth-up { color: var(--signal-critical); }
.stock3-breadth .breadth-flat { color: var(--text-muted); }
.stock3-breadth .breadth-down { color: var(--signal-positive); }
.stock3-breadth .breadth-label {
  color: var(--text-muted);
  font-family: var(--font-sans);
  font-size: 10px;
  font-weight: 600;
}

.stock3-sectors {
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--bg-card);
  padding: 8px 12px;
  margin-bottom: 10px;
}
.stock3-sectors-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}
.stock3-sectors-label {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-secondary);
  letter-spacing: .04em;
}
.stock3-sectors-tabs { display: flex; gap: var(--space-xs); }
.stock3-sector-tab {
  padding: 3px 10px;
  border: 1px solid var(--border-color);
  border-radius: 5px;
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all .15s;
}
.stock3-sector-tab.active {
  color: var(--accent-cyan);
  border-color: var(--accent-cyan-border);
  background: var(--accent-cyan-soft);
}
.stock3-sectors-strip {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 2px;
}
.stock3-sector {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 5px 10px;
  border-radius: 6px;
  background: var(--surface-workbench-control);
  min-width: 72px;
  cursor: default;
  transition: transform .12s;
}
.stock3-sector:hover { transform: translateY(-1px); }
.stock3-sector .sector-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
  max-width: 80px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.stock3-sector .sector-chg {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
}
.stock3-sector.up .sector-chg { color: var(--signal-critical); }
.stock3-sector.down .sector-chg { color: var(--signal-positive); }
.stock3-sector-empty {
  color: var(--text-muted);
  font-size: 12px;
  padding: 8px;
}

.stock3-index-skeleton-card {
  width: 120px;
  height: 52px;
  border-radius: 8px;
  background: linear-gradient(90deg, var(--surface-workbench-control) 0%, var(--surface-workbench-ai) 50%, var(--surface-workbench-control) 100%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.4s ease infinite;
}
.stock3-sector-skeleton {
  flex-shrink: 0;
  width: 72px;
  height: 42px;
  border-radius: 6px;
  background: linear-gradient(90deg, var(--surface-workbench-control) 0%, var(--surface-workbench-ai) 50%, var(--surface-workbench-control) 100%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.4s ease infinite;
}

.price-flash { animation: price-flash-anim .6s ease-out; }
.price-flash.flash-up { animation-name: price-flash-up; }
.price-flash.flash-down { animation-name: price-flash-down; }
@keyframes price-flash-up {
  0% { background: rgba(239, 68, 68, .35); }
  100% { background: transparent; }
}
@keyframes price-flash-down {
  0% { background: rgba(34, 197, 94, .35); }
  100% { background: transparent; }
}

/* empty-state 内的辅助提示文字 */
.empty-state-hint {
  font-size: 12px;
  opacity: .6;
  margin: 0;
  color: var(--text-muted);
}

/* AI briefing hub */
.ai-briefing-home,
.recommendation-timeline-page { width: min(1440px, 100%); margin: 0 auto; padding: 28px 32px 56px; }
.ai-home-header,
.recommendation-page-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 28px; padding-bottom: 22px; border-bottom: var(--panel-border); }
.ai-home-header h1,
.recommendation-page-header h1 { margin: 5px 0 8px; color: var(--text-primary); font-size: 32px; line-height: 1.15; letter-spacing: 0; }
.ai-home-header p,
.recommendation-page-header p { max-width: 820px; margin: 0; color: var(--text-secondary); font-size: 14px; line-height: 1.7; }
.ai-home-mode { display: flex; align-items: center; gap: 10px; margin-top: 14px; color: var(--text-muted); font-size: 12px; }
.ai-home-mode span { padding: 3px 7px; border: var(--panel-border); border-radius: 5px; color: var(--accent-cyan); }
.ai-home-actions { display: flex; flex: 0 0 auto; gap: 8px; }
.ai-home-lanes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; margin-top: 24px; }
.ai-home-lane { min-width: 0; border: var(--panel-border); border-radius: 8px; background: var(--bg-card); overflow: hidden; }
.ai-home-lane > header { display: flex; align-items: center; justify-content: space-between; padding: 15px 16px; border-bottom: var(--panel-border); }
.ai-home-lane > header span { color: var(--text-primary); font-size: 14px; font-weight: 750; }
.ai-home-lane > header p { margin: 3px 0 0; color: var(--text-muted); font-size: 11px; }
.ai-home-lane > header strong { color: var(--accent-cyan); font: 700 20px/1 var(--font-mono); }
.ai-home-lane ol { margin: 0; padding: 0; list-style: none; }
.ai-home-lane li + li { border-top: var(--panel-border); }
.ai-home-lane li button { display: grid; width: 100%; min-height: 92px; padding: 13px 16px; border: 0; background: transparent; color: inherit; text-align: left; cursor: pointer; }
.ai-home-lane li button:hover,
.ai-home-lane li button:focus-visible { background: var(--bg-hover); outline: none; }
.ai-home-item-title { overflow-wrap: anywhere; color: var(--text-primary); font-size: 13px; font-weight: 700; line-height: 1.45; }
.ai-home-item-meta { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 7px; color: var(--text-muted); font-size: 11px; }
.ai-home-item-meta small { color: var(--accent-cyan); font-family: var(--font-mono); }
.ai-home-reasons { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; }
.ai-home-reasons em,
.recommendation-reason-list span { padding: 3px 6px; border: var(--panel-border); border-radius: 5px; color: var(--text-secondary); font-size: 10px; font-style: normal; }
.ai-home-empty { padding: 28px 16px; color: var(--text-muted); font-size: 13px; text-align: center; }
.ai-home-signals { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; padding: 24px 0; border-bottom: var(--panel-border); }
.ai-home-signals h2 { margin: 0 0 10px; color: var(--text-primary); font-size: 14px; letter-spacing: 0; }
.ai-home-signals p { margin: 5px 0; color: var(--text-secondary); font-size: 12px; line-height: 1.55; }
.ai-home-shortcuts { display: flex; flex-wrap: wrap; gap: 8px; padding-top: 18px; }
.ai-home-shortcuts button { padding: 8px 12px; border: var(--panel-border); border-radius: 6px; background: var(--bg-card); color: var(--text-secondary); cursor: pointer; }
.ai-home-shortcuts button:hover,
.ai-home-shortcuts button:focus-visible { border-color: var(--border-active); color: var(--text-primary); outline: none; }

/* Immutable recommendation calendar and timeline */
.recommendation-layout { display: grid; grid-template-columns: minmax(260px, 320px) minmax(0, 1fr); gap: 24px; margin-top: 24px; }
.recommendation-calendar { align-self: start; padding: 14px; border: var(--panel-border); border-radius: 8px; background: var(--bg-card); }
.recommendation-calendar > header { display: grid; grid-template-columns: 32px 1fr 32px; align-items: center; gap: 8px; }
.recommendation-calendar > header strong { color: var(--text-primary); font-size: 13px; text-align: center; }
.recommendation-calendar > header button { width: 32px; height: 32px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); color: var(--text-secondary); font-size: 20px; cursor: pointer; }
.recommendation-weekdays,
.recommendation-days { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; }
.recommendation-weekdays { margin-top: 12px; color: var(--text-muted); font-size: 10px; text-align: center; }
.recommendation-days { margin-top: 7px; }
.recommendation-days > span,
.recommendation-days button { aspect-ratio: 1; min-width: 0; border: 1px solid transparent; border-radius: 5px; background: transparent; color: var(--text-secondary); font-size: 11px; }
.recommendation-days button { position: relative; cursor: pointer; }
.recommendation-days button:hover,
.recommendation-days button:focus-visible { border-color: var(--border-active); outline: none; }
.recommendation-days button.has-snapshot::after { position: absolute; right: 4px; bottom: 3px; width: 4px; height: 4px; border-radius: 50%; background: var(--signal-positive); content: ''; }
.recommendation-days button.active { border-color: var(--accent-cyan); background: var(--accent-cyan-soft); color: var(--accent-cyan); font-weight: 700; }
.recommendation-calendar-legend { display: flex; align-items: center; gap: 6px; margin-top: 12px; color: var(--text-muted); font-size: 10px; }
.recommendation-calendar-legend i { width: 6px; height: 6px; border-radius: 50%; background: var(--signal-positive); }
.recommendation-day-timeline { min-width: 0; }
.recommendation-snapshot-header { display: flex; justify-content: space-between; gap: 20px; padding-bottom: 16px; border-bottom: var(--panel-border); }
.recommendation-snapshot-header h2 { max-width: 760px; margin: 5px 0 0; color: var(--text-primary); font-size: 18px; line-height: 1.45; letter-spacing: 0; }
.recommendation-snapshot-header span { color: var(--text-muted); font-size: 11px; }
.recommendation-snapshot-header > div:last-child { display: flex; flex-direction: column; gap: 6px; text-align: right; }
.recommendation-origin-event { display: flex; align-items: center; gap: 10px; padding: 16px 0 8px; }
.recommendation-origin-event i,
.recommendation-event-dot { width: 9px; height: 9px; flex: 0 0 auto; border: 2px solid var(--accent-cyan); border-radius: 50%; background: var(--bg-primary); }
.recommendation-origin-event div { display: flex; align-items: baseline; gap: 10px; }
.recommendation-origin-event strong { color: var(--text-primary); font-size: 12px; }
.recommendation-origin-event span { color: var(--text-muted); font-size: 11px; }
.recommendation-timeline-lane { margin-top: 14px; }
.recommendation-timeline-lane > header { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: var(--panel-border); }
.recommendation-timeline-lane > header h2 { margin: 0; color: var(--text-primary); font-size: 14px; letter-spacing: 0; }
.recommendation-timeline-lane > header span { color: var(--text-muted); font-size: 11px; }
.recommendation-timeline-lane article { display: grid; grid-template-columns: 12px minmax(0, 1fr); gap: 10px; padding: 13px 0; border-bottom: var(--panel-border); }
.recommendation-event-dot { margin-top: 5px; width: 8px; height: 8px; border-color: var(--text-muted); }
.recommendation-event-content { min-width: 0; }
.recommendation-event-meta { display: flex; justify-content: space-between; gap: 10px; color: var(--text-muted); font-size: 10px; }
.recommendation-event-meta strong { color: var(--accent-cyan); font-family: var(--font-mono); }
.recommendation-event-content h3 { margin: 5px 0 8px; overflow-wrap: anywhere; color: var(--text-primary); font-size: 13px; line-height: 1.45; letter-spacing: 0; }
.recommendation-reason-list,
.recommendation-feedback-actions { display: flex; flex-wrap: wrap; gap: 5px; }
.recommendation-score-details > button,
.recommendation-feedback-actions button { margin-top: 8px; padding: 4px 7px; border: var(--panel-border); border-radius: 5px; background: transparent; color: var(--text-muted); font-size: 10px; cursor: pointer; }
.recommendation-feedback-actions button:hover { border-color: var(--border-active); color: var(--text-primary); }
.recommendation-score-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 5px; margin-top: 7px; }
.recommendation-score-grid div { display: flex; justify-content: space-between; gap: 8px; padding: 5px 7px; background: var(--surface-workbench-inset); color: var(--text-muted); font-size: 10px; }
.recommendation-score-grid strong { color: var(--text-primary); font-family: var(--font-mono); }
.recommendation-empty { padding: 56px 20px; border: var(--panel-border); border-radius: 8px; color: var(--text-muted); text-align: center; }
.recommendation-empty h2 { margin: 0 0 8px; color: var(--text-primary); font-size: 18px; letter-spacing: 0; }

@media (max-width: 960px) {
