  .ai-home-actions { width: 100%; }
  .ai-home-actions button { flex: 1; }
  .recommendation-snapshot-header > div:last-child { text-align: left; }
}

/* Newspaper view backed by the same immutable recommendation snapshot */
.today-newspaper { width: min(1380px, 100%); margin: 0 auto; padding: 22px 32px 60px; }
.newspaper-masthead { display: grid; grid-template-columns: 1fr auto 1fr; align-items: end; gap: 20px; padding: 8px 0 15px; border-top: 4px solid var(--text-primary); border-bottom: 1px solid var(--text-primary); }
.newspaper-masthead > div:first-child span,
.newspaper-columns > section > header span,
.newspaper-domain-band > header span { color: var(--text-muted); font: 600 10px/1 var(--font-mono); }
.newspaper-masthead h1 { margin: 4px 0 0; color: var(--text-primary); font-family: Georgia, 'Noto Serif SC', serif; font-size: 30px; line-height: 1; letter-spacing: 0; }
.newspaper-edition { display: flex; flex-direction: column; align-items: center; gap: 3px; color: var(--text-secondary); font-size: 11px; }
.newspaper-actions { display: flex; justify-content: flex-end; gap: 6px; }
.newspaper-actions button { padding: 6px 9px; border: var(--panel-border); border-radius: 5px; background: transparent; color: var(--text-secondary); font-size: 11px; cursor: pointer; }
.newspaper-actions button:hover { border-color: var(--border-active); color: var(--text-primary); }
.newspaper-lead { padding: 28px max(0px, 5vw); text-align: center; border-bottom: 1px solid var(--text-primary); }
.newspaper-lead h2 { max-width: 980px; margin: 10px auto 14px; color: var(--text-primary); font-family: Georgia, 'Noto Serif SC', serif; font-size: 24px; line-height: 1.4; letter-spacing: 0; }
.newspaper-lead > button { display: block; max-width: 880px; margin: 0 auto; border: 0; background: transparent; color: var(--accent-cyan); font-size: 15px; font-weight: 700; line-height: 1.45; cursor: pointer; }
.newspaper-lead p { max-width: 820px; margin: 12px auto 0; color: var(--text-secondary); font-size: 13px; line-height: 1.75; }
.newspaper-lead footer { margin-top: 12px; color: var(--text-muted); font-size: 10px; }
.newspaper-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border-bottom: 1px solid var(--text-primary); }
.newspaper-columns > section { min-width: 0; padding: 20px 22px; }
.newspaper-columns > section > header { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding-bottom: 9px; border-bottom: 2px solid var(--text-primary); }
.newspaper-columns h2,
.newspaper-domain-band h2,
.newspaper-sources h2 { margin: 0; color: var(--text-primary); font-family: Georgia, 'Noto Serif SC', serif; font-size: 18px; letter-spacing: 0; }
.newspaper-story { display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: 8px; padding: 14px 0; border-bottom: var(--panel-border); }
.newspaper-story-title { padding: 0; border: 0; background: transparent; color: var(--text-primary); font-family: Georgia, 'Noto Serif SC', serif; font-size: 14px; font-weight: 700; line-height: 1.45; text-align: left; cursor: pointer; overflow-wrap: anywhere; }
.newspaper-story-title:hover { color: var(--accent-cyan); }
.newspaper-story p { display: -webkit-box; margin: 7px 0; overflow: hidden; color: var(--text-secondary); font-size: 11px; line-height: 1.55; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
.newspaper-story footer { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: var(--text-muted); font-size: 9px; }
.newspaper-verify-badge { color: var(--accent-emerald, #10b981); border: 1px solid var(--accent-emerald, #10b981); border-radius: 999px; padding: 1px 7px; font-size: 9px; line-height: 1.4; white-space: nowrap; }
.newspaper-story footer button { margin-left: auto; padding: 3px 6px; border: var(--panel-border); border-radius: 4px; background: transparent; color: var(--text-muted); font-size: 9px; cursor: pointer; }
.newspaper-domain-band { padding: 20px 0; border-bottom: 1px solid var(--text-primary); }
.newspaper-domain-band > header { display: flex; align-items: baseline; justify-content: space-between; }
.newspaper-domain-band > div { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 0; margin-top: 12px; border-top: var(--panel-border); border-left: var(--panel-border); }
.newspaper-domain-band section { min-width: 0; padding: 12px; border-right: var(--panel-border); border-bottom: var(--panel-border); }
.newspaper-domain-band h3 { margin: 0 0 7px; color: var(--accent-cyan); font-size: 11px; }
.newspaper-domain-band button { display: block; width: 100%; padding: 5px 0; overflow: hidden; border: 0; background: transparent; color: var(--text-secondary); font-size: 10px; line-height: 1.4; text-align: left; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }
.newspaper-domain-band button:hover { color: var(--text-primary); }
.newspaper-judgement-band { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border-bottom: 1px solid var(--text-primary); }
.newspaper-judgement-band section { padding: 17px 22px; }
.newspaper-judgement-band h2 { margin: 0 0 8px; color: var(--text-primary); font-size: 13px; letter-spacing: 0; }
.newspaper-judgement-band p { margin: 5px 0; color: var(--text-secondary); font-size: 11px; line-height: 1.55; }
.newspaper-sources ol { columns: 2; column-gap: 34px; margin: 12px 0 0; padding-left: 24px; }
.newspaper-sources li { padding: 4px 0; color: var(--text-muted); font-size: 10px; break-inside: avoid; }
.newspaper-sources li span { margin-right: 7px; color: var(--text-primary); font-weight: 700; }
.newspaper-sources a { color: var(--text-secondary); text-decoration: none; }
.newspaper-sources a:hover { color: var(--accent-cyan); }
.newspaper-empty { padding: 70px 20px; color: var(--text-muted); text-align: center; }

.stock-analysis-result { gap: 12px; }
.stock-analysis-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border: var(--panel-border); border-radius: 8px; overflow: hidden; }
.stock-analysis-summary > div { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 12px; }
.stock-analysis-summary > div + div { border-left: var(--panel-border); }
.stock-analysis-summary span,
.stock-analysis-metrics span { color: var(--text-muted); font-size: 10px; }
.stock-analysis-summary strong { color: var(--accent-amber); font-size: 13px; }
/* ============ 紧凑指标矩阵：4 分组 × 紧凑行，替代大块方框 ============ */
.stock-analysis-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.stock-metrics-group {
  min-width: 0;
  padding: 9px 10px 7px;
  border: 1px solid color-mix(in srgb, var(--border-color) 70%, transparent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--bg-primary) 60%, transparent);
}
.stock-metrics-group-title {
  margin: 0 0 6px;
  color: var(--accent-cyan);
  font: 600 9px/1 var(--font-mono);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.stock-metrics-rows { display: grid; gap: 1px; }
.stock-metrics-rows > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  padding: 4px 0;
  border-bottom: 1px dashed color-mix(in srgb, var(--border-color) 55%, transparent);
}
.stock-metrics-rows > div:last-child { border-bottom: 0; }
.stock-metrics-rows span { flex: 0 0 auto; font: 500 10px/1.3 var(--font-mono); letter-spacing: 0.03em; }
.stock-metrics-rows strong {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-align: right;
  color: var(--text-primary);
  font: 700 11px/1.3 var(--font-mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* 涨跌语义着色（中文约定：涨红跌绿） */
.stock-metrics-rows strong.is-up { color: var(--accent-red, #ef4444); }
.stock-metrics-rows strong.is-down { color: var(--accent-green, #22c55e); }
.stock-analysis-fallback { padding: 8px 10px; border-left: 2px solid var(--accent-amber); color: var(--accent-amber); font-size: 11px; }
.stock-analysis-evidence { display: flex; flex-wrap: wrap; gap: 5px; }
.stock-analysis-evidence span { padding: 4px 7px; border: var(--panel-border); border-radius: 5px; color: var(--text-muted); font-size: 10px; }
/* ============ 证据卡：数量徽章 + 单条折叠 + 展开按钮 ============ */
.stock-thesis-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 10px; }
.stock-thesis-block {
  min-width: 0;
  padding: 9px 11px 10px;
  border: 1px solid var(--border-color);
  border-left: 3px solid var(--border-color);
  border-radius: 6px;
  background: color-mix(in srgb, var(--bg-primary) 55%, transparent);
}
.stock-thesis-block.bullish { border-left-color: var(--signal-positive); }
.stock-thesis-block.bearish { border-left-color: var(--signal-critical); }
.stock-thesis-block.invalidation { border-left-color: var(--accent-amber); }
.stock-thesis-block.risk { border-left-color: var(--accent-violet); }
.stock-thesis-head { display: flex; align-items: center; gap: 7px; margin-bottom: 4px; }
.stock-thesis-head strong { color: var(--text-primary); font-size: 12px; font-weight: 600; }
.stock-thesis-count {
  flex: 0 0 auto;
  min-width: 18px;
  height: 17px;
  padding: 0 5px;
  border-radius: 9px;
  color: var(--accent-cyan);
  font: 700 9.5px/17px var(--font-mono);
  text-align: center;
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}
.stock-thesis-sub { flex: 1 1 auto; min-width: 0; overflow: hidden; color: var(--text-muted); font-size: 10px; letter-spacing: 0.03em; text-overflow: ellipsis; white-space: nowrap; }
.stock-thesis-toggle {
  flex: 0 0 auto;
  padding: 2px 8px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  background: transparent;
  color: var(--accent-cyan);
  font: 600 9.5px/1.5 var(--font-mono);
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.stock-thesis-toggle:hover { color: var(--text-primary); border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.stock-thesis-block p { position: relative; margin: 6px 0 0; padding-left: 11px; color: var(--text-secondary); font-size: 11.5px; line-height: 1.6; }
.stock-thesis-block p::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.65;
}
.stock-thesis-block p.muted { color: var(--text-muted); font-style: italic; }
.stock-thesis-block p.muted::before { display: none; }
.stock-thesis-block small {
  display: block;
  margin-top: 8px;
  padding-top: 6px;
  border-top: 1px dashed color-mix(in srgb, var(--border-color) 50%, transparent);
  color: var(--text-muted);
  font-size: 9.5px;
  line-height: 1.5;
}
/* ============ 存素材库按钮（与 stock-ai-rerun 同族，青色高亮） ============ */
.stock-ai-save {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  align-self: flex-start;
  padding: 5px 12px;
  border: var(--panel-border);
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.stock-ai-save svg { width: 12px; height: 12px; }
.stock-ai-save:hover:not(:disabled) {
  color: var(--accent-cyan);
  border-color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 7%, transparent);
}
.stock-ai-save:disabled { opacity: 0.5; cursor: not-allowed; }
.stock-research-journal { display: flex; flex-direction: column; gap: 12px; }
.stock-research-workflow { display: flex; align-items: center; gap: 6px; padding: 8px 10px; border: var(--panel-border); border-radius: 7px; background: var(--surface-workbench-inset); overflow-x: auto; }
.stock-research-workflow > span { margin-right: 4px; color: var(--text-muted); font-size: 10px; font-weight: 800; white-space: nowrap; }
.stock-research-workflow button { display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 9px; border: 0; border-radius: 5px; background: transparent; color: var(--text-secondary); font-size: 10px; font-weight: 800; white-space: nowrap; cursor: pointer; }
.stock-research-workflow button:hover { background: var(--accent-cyan-soft); color: var(--accent-cyan); }
.stock-research-workflow b { display: grid; width: 17px; height: 17px; place-items: center; border: 1px solid currentColor; border-radius: 50%; font: 800 8px/1 var(--font-mono); }
.stock-research-workflow i { color: var(--text-muted); font-size: 10px; font-style: normal; }
.stock-research-modal { max-width: 840px; max-height: min(680px, 76vh); }
.stock-research-modal .stock-modal-head h3 svg { color: var(--accent-cyan); }
.stock-research-modal-tabs { display: flex; flex: 0 0 auto; gap: 4px; padding: 6px 16px 0; border-bottom: 1px solid var(--border-color); overflow-x: auto; }
.stock-research-modal-tabs button { height: 34px; padding: 0 12px; border: 0; border-bottom: 2px solid transparent; background: transparent; color: var(--text-muted); font-size: 11px; font-weight: 800; cursor: pointer; }
.stock-research-modal-tabs button.active { border-bottom-color: var(--accent-cyan); color: var(--accent-cyan); }
.stock-research-modal .stock-modal-body { padding: 12px 14px; overscroll-behavior: contain; }
.stock-research-modal .stock3-panel { border: 0; padding: 4px; background: transparent; }
.stock-scenario-tool, .stock-research-checklist { display: flex; flex-direction: column; gap: 10px; }
.stock-scenario-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.stock-scenario-card { display: grid; grid-template-columns: 1fr 1fr; gap: 7px 8px; min-width: 0; padding: 10px; border: 1px solid var(--border-color); border-top: 2px solid var(--border-color); border-radius: 6px; background: var(--surface-workbench-inset); }
.stock-scenario-card.bear { border-top-color: var(--signal-critical); }
.stock-scenario-card.base { border-top-color: var(--accent-amber); }
.stock-scenario-card.bull { border-top-color: var(--signal-positive); }
.stock-scenario-card > strong { grid-column: 1 / -1; color: var(--text-primary); font-size: 11px; }
.stock-scenario-card label { display: flex; flex-direction: column; gap: 4px; min-width: 0; color: var(--text-muted); font-size: 9px; font-weight: 700; }
.stock-scenario-card input { width: 100%; height: 30px; padding: 0 7px; border: var(--panel-border); border-radius: 5px; background: var(--bg-primary); color: var(--text-primary); font: 700 10px/1 var(--font-mono); }
.stock-scenario-results { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border: var(--panel-border); border-radius: 6px; overflow: hidden; }
.stock-scenario-results > div { display: flex; flex-direction: column; gap: 3px; min-width: 0; padding: 9px; background: var(--surface-workbench-inset); }
.stock-scenario-results > div + div { border-left: var(--panel-border); }
.stock-scenario-results span { color: var(--text-muted); font-size: 9px; }
.stock-scenario-results strong { overflow: hidden; color: var(--text-primary); font: 800 11px/1.25 var(--font-mono); text-overflow: ellipsis; white-space: nowrap; }
.stock-scenario-results strong.up { color: var(--signal-critical); }
.stock-scenario-results strong.down { color: var(--signal-positive); }
.stock-checklist-risk { padding: 4px 7px; border: var(--panel-border); border-radius: 5px; color: var(--text-muted); font-size: 9px; }
.stock-checklist-risk.failed { border-color: rgba(239, 68, 68, .35); color: var(--signal-critical); }
.stock-checklist-notice { padding: 7px 9px; border-left: 2px solid var(--accent-amber); background: var(--accent-amber-soft); color: var(--text-secondary); font-size: 9px; line-height: 1.45; }
.stock-checklist-list { display: flex; flex-direction: column; border: var(--panel-border); border-radius: 6px; overflow: hidden; }
.stock-checklist-row { display: grid; grid-template-columns: 42px minmax(0, 1fr) 88px; align-items: center; gap: 8px; min-height: 38px; padding: 5px 8px; background: var(--surface-workbench-inset); }
.stock-checklist-row + .stock-checklist-row { border-top: var(--panel-border); }
.stock-checklist-row > span { color: var(--text-muted); font-size: 9px; font-weight: 800; }
.stock-checklist-row > strong { color: var(--text-secondary); font-size: 10px; font-weight: 600; line-height: 1.35; }
.stock-checklist-row select { width: 88px; height: 27px; padding: 0 20px 0 6px; border: var(--panel-border); border-radius: 5px; background: var(--bg-primary); color: var(--text-primary); font-size: 9px; }
.stock-checklist-row.passed { box-shadow: inset 2px 0 var(--signal-positive); }
.stock-checklist-row.watch { box-shadow: inset 2px 0 var(--accent-amber); }
.stock-checklist-row.failed { box-shadow: inset 2px 0 var(--signal-critical); }
.stock-checklist-note { display: flex; flex-direction: column; gap: 4px; color: var(--text-muted); font-size: 9px; font-weight: 700; }
.stock-checklist-note textarea { min-height: 58px; resize: vertical; padding: 7px 8px; border: var(--panel-border); border-radius: 5px; background: var(--bg-primary); color: var(--text-primary); font: 10px/1.45 var(--font-sans); }
.stock-research-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.stock-research-head > div:first-child { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.stock-research-head span { color: var(--text-muted); font-size: 10px; font-weight: 700; }
.stock-research-head strong { overflow: hidden; color: var(--text-primary); font-size: 14px; text-overflow: ellipsis; white-space: nowrap; }
.stock-research-actions { display: flex; align-items: center; gap: 5px; }
.stock-research-actions button { display: inline-flex; align-items: center; justify-content: center; gap: 5px; min-width: 30px; height: 30px; padding: 0 8px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); color: var(--text-secondary); font-size: 10px; cursor: pointer; }
.stock-research-actions button:disabled { cursor: not-allowed; opacity: .45; }
.stock-research-actions svg { width: 13px; height: 13px; }
.stock-research-meta { display: flex; align-items: end; gap: 10px; flex-wrap: wrap; padding-bottom: 10px; border-bottom: 1px solid var(--border-color); }
.stock-research-meta label { display: flex; flex-direction: column; gap: 4px; color: var(--text-muted); font-size: 10px; font-weight: 700; }
.stock-research-meta select { min-width: 130px; height: 30px; padding: 0 25px 0 8px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); color: var(--text-primary); font-size: 11px; }
.stock-research-meta > span { margin-left: auto; color: var(--text-muted); font-size: 10px; }
.stock-research-fields { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.stock-research-fields label { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.stock-research-fields label > span { color: var(--text-secondary); font-size: 11px; font-weight: 800; }
.stock-research-fields textarea { width: 100%; min-height: 92px; resize: vertical; padding: 9px 10px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); color: var(--text-primary); font: 11px/1.55 var(--font-sans); outline: none; }
.stock-research-fields textarea:focus { border-color: var(--accent-cyan); }
.stock-research-fields textarea::placeholder { color: var(--text-muted); }
.stock-research-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.stock-research-foot > span { color: var(--text-muted); font-size: 10px; }
.stock-research-foot > span.error { color: var(--signal-critical); }
.stock-research-save { height: 32px; padding: 0 13px; border: 1px solid var(--accent-cyan-border); border-radius: 6px; background: var(--accent-cyan-soft); color: var(--accent-cyan); font-size: 11px; font-weight: 800; cursor: pointer; }
.stock-research-history { display: flex; flex-direction: column; gap: 5px; padding-top: 10px; border-top: 1px solid var(--border-color); }
.stock-research-history-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.stock-research-history-head strong { color: var(--text-secondary); font-size: 11px; }
.stock-research-history-head span, .stock-research-history > p { margin: 0; color: var(--text-muted); font-size: 9px; }
.stock-research-history > button { display: grid; grid-template-columns: minmax(145px, 1fr) minmax(110px, .8fr) 72px; align-items: center; gap: 8px; min-width: 0; padding: 7px 9px; border: var(--panel-border); border-radius: 5px; background: var(--bg-primary); color: var(--text-secondary); text-align: left; cursor: pointer; }
.stock-research-history > button:hover { border-color: var(--accent-cyan-border); }
.stock-research-history > button span { font: 9px/1.2 var(--font-mono); }
.stock-research-history > button strong { overflow: hidden; color: var(--text-primary); font: 700 10px/1.2 var(--font-mono); text-overflow: ellipsis; white-space: nowrap; }
.stock-research-history > button em { color: var(--text-muted); font-size: 9px; font-style: normal; text-align: right; }
.stock-tool-note { margin-left: auto; color: var(--text-muted); font-size: 9px; }
.stock-risk-tool { display: flex; flex-direction: column; gap: 11px; }
.stock-risk-inputs { display: grid; grid-template-columns: repeat(4, minmax(120px, 1fr)); gap: 8px; }
.stock-risk-inputs label { display: flex; flex-direction: column; gap: 4px; color: var(--text-muted); font-size: 10px; font-weight: 700; }
.stock-risk-inputs input { width: 100%; height: 32px; padding: 0 9px; border: var(--panel-border); border-radius: 6px; background: var(--bg-primary); color: var(--text-primary); font: 700 11px/1 var(--font-mono); outline: none; }
.stock-risk-inputs input:focus { border-color: var(--accent-cyan); }
.stock-risk-inputs input:read-only { color: var(--text-secondary); cursor: default; }
.stock-risk-inputs.disabled { opacity: .55; }
.stock-risk-results { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border: var(--panel-border); border-radius: 7px; overflow: hidden; }
.stock-risk-results > div { display: flex; flex-direction: column; gap: 4px; padding: 9px 10px; background: var(--surface-workbench-inset); }
.stock-risk-results > div + div { border-left: var(--panel-border); }
.stock-risk-results span { color: var(--text-muted); font-size: 9px; }
.stock-risk-results strong { color: var(--text-primary); font: 800 12px/1.2 var(--font-mono); }
.stock-risk-results > div:nth-child(4) strong { color: var(--signal-critical); }
.stock-risk-warning { padding: 9px 10px; border-left: 3px solid var(--accent-amber); background: var(--accent-amber-soft); color: var(--accent-amber); font-size: 11px; }
.stock-risk-disclaimer { color: var(--text-muted); font-size: 9px; line-height: 1.5; }

@media (max-width: 760px) {
  .stock-analysis-summary { grid-template-columns: 1fr; }
  .stock-analysis-summary > div + div { border-top: var(--panel-border); border-left: 0; }
  .stock-analysis-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stock-thesis-grid { grid-template-columns: 1fr; }
  .stock-research-fields { grid-template-columns: 1fr; }
  .stock-research-meta > span { width: 100%; margin-left: 0; }
  .stock-research-foot { align-items: stretch; flex-direction: column; }
  .stock-research-history > button { grid-template-columns: 1fr 72px; }
  .stock-research-history > button span { grid-column: 1 / -1; }
  .stock-risk-inputs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stock-risk-results { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stock-risk-results > div + div { border-left: 0; }
  .stock-risk-results > div:nth-child(even) { border-left: var(--panel-border); }
  .stock-risk-results > div:nth-child(n+3) { border-top: var(--panel-border); }
  .stock-scenario-grid { grid-template-columns: 1fr; }
  .stock-scenario-results { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stock-scenario-results > div + div { border-left: 0; }
  .stock-scenario-results > div:nth-child(even) { border-left: var(--panel-border); }
  .stock-scenario-results > div:nth-child(n+3) { border-top: var(--panel-border); }
  .stock-checklist-row { grid-template-columns: 34px minmax(0, 1fr) 78px; gap: 5px; }
  .stock-checklist-row select { width: 78px; }
}

@media (max-width: 768px) {
  .main-workbench .feed { margin-right: 0; }
  .ai-chat-panel { display: none; width: 100% !important; border-left: 0; }
  .ai-chat-panel.mobile-open { display: flex; inset: 0; }
}

@media (max-width: 1024px) {
  .app.sidebar-collapsed .main-workbench,
  .app .main-workbench { margin-left: 0 !important; margin-right: 0 !important; }
  .main-workbench .feed { margin-right: 0; }
  .ai-chat-panel { display: none; width: 100% !important; border-left: 0; }
  .ai-chat-panel.mobile-open { display: flex; inset: 0; }
  .ai-home-header, .recommendation-page-header { flex-direction: column; }
  .ai-home-actions { width: 100%; }
  .ai-home-actions button { flex: 1; }
  .ai-home-lanes, .ai-home-signals { grid-template-columns: 1fr; }
}

@media (max-width: 620px) {
  .ai-home-header p { max-width: 100%; overflow-wrap: anywhere; }
  .ai-home-actions { flex-direction: column; }
  .ai-home-actions button { width: 100%; min-width: 0; }
  .ai-home-shortcuts { display: grid; grid-template-columns: 1fr; }
  .ai-home-shortcuts button { width: 100%; min-width: 0; padding-inline: 6px; }
}

@media (max-width: 760px) {
  .today-newspaper { padding: 16px 16px 44px; }
  .newspaper-masthead { grid-template-columns: 1fr auto; }
  .newspaper-edition { display: none; }
  .newspaper-columns, .newspaper-judgement-band { grid-template-columns: 1fr; }
  .newspaper-columns > section + section, .newspaper-judgement-band section + section { border-left: 0; border-top: 1px solid var(--text-primary); }
  .newspaper-lead { padding: 22px 0; }
  .newspaper-sources ol { columns: 1; }
}

/* Persistent community */
.community-page { width: 100%; max-width: 1320px; min-width: 0; margin: 0 auto; padding: 28px 28px 64px; box-sizing: border-box; overflow-x: hidden; }
.community-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; padding: 4px 0 24px; border-bottom: 1px solid var(--border-color); }
.community-header h1 { margin: 5px 0 8px; font-size: 30px; letter-spacing: 0; }
.community-header > div { min-width: 0; }
.community-header p { max-width: 680px; margin: 0; color: var(--text-secondary); line-height: 1.7; overflow-wrap: anywhere; word-break: break-word; }
.community-header .ai-primary-action { width: auto; min-width: 148px; padding-inline: 20px; flex: 0 0 auto; }
.community-error { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin: 18px 0; padding: 13px 15px; border-left: 3px solid #ef4444; background: rgba(239,68,68,.08); color: var(--text-secondary); }
.community-error > * { min-width: 0; }
.community-error span { overflow-wrap: anywhere; word-break: break-all; white-space: normal; }
.community-error strong { color: #ef4444; }
.community-error button { border: 1px solid var(--border-color); background: transparent; color: var(--text-primary); padding: 7px 12px; cursor: pointer; }
.community-composer { margin: 20px 0; padding: 18px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-card); }
.community-composer-head, .community-compose-footer, .community-compose-options { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.community-composer-head h2 { margin: 0 0 12px; font-size: 17px; }
.community-composer-head button, .community-detail-toolbar button { width: 34px; height: 34px; border: 0; background: transparent; color: var(--text-secondary); font-size: 25px; cursor: pointer; }
.community-compose-options { justify-content: flex-start; }
.community-composer select, .community-composer input, .community-composer textarea, .community-comment-compose textarea { border: 1px solid var(--border-color); border-radius: 4px; background: var(--bg-primary); color: var(--text-primary); font: inherit; }
.community-composer select { min-width: 140px; padding: 9px; }
.community-composer input { display: block; width: 100%; margin-top: 10px; padding: 11px 12px; box-sizing: border-box; font-weight: 700; }
.community-composer textarea { display: block; width: 100%; min-height: 180px; margin-top: 10px; padding: 12px; box-sizing: border-box; resize: vertical; line-height: 1.7; }
.community-compose-footer { margin-top: 10px; color: var(--text-muted); font-size: 12px; }
.community-compose-footer button, .community-comment-compose button { border: 0; border-radius: 4px; background: var(--accent-cyan); color: #041013; padding: 9px 16px; font-weight: 800; cursor: pointer; }
.community-compose-footer button:disabled { opacity: .45; cursor: not-allowed; }
.community-layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; margin-top: 22px; }
.community-layout.has-detail { grid-template-columns: minmax(360px, .9fr) minmax(420px, 1.1fr); align-items: start; }
.community-feed { display: grid; gap: 10px; min-width: 0; }
.community-state { display: grid; gap: 7px; padding: 46px 20px; border-top: 1px solid var(--border-color); border-bottom: 1px solid var(--border-color); color: var(--text-secondary); text-align: center; }
.community-post {
  position: relative;
  padding: 18px 14px 17px 18px;
  border-bottom: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  outline: none;
  /* 列表式水墨质感：hover 时浮起微光底 */
  background: transparent;
  transition: background .25s ease, transform .2s ease, box-shadow .2s ease;
}
.community-post::before {
  /* 左侧 2px 描金渐隐竖线，hover 时点亮 */
  content: "";
  position: absolute;
  left: 0; top: 12px; bottom: 12px;
  width: 2px;
  border-radius: 2px;
  background: linear-gradient(180deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 18%, transparent) 50%, transparent) 30%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 12%, transparent) 50%, transparent) 70%,
    transparent 100%);
  opacity: 0;
  transition: opacity .25s ease;
  pointer-events: none;
}
.community-post:hover {
  background: linear-gradient(90deg,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 4.5%, transparent) 70%, transparent) 0%,
    transparent 60%);
  transform: translateX(2px);
  box-shadow: 0 4px 14px -6px rgba(0,0,0,.18);
}
.community-post:hover::before { opacity: 1; }
.community-post:hover h2, .community-post:focus h2 { color: var(--accent-cyan); }
.community-post-meta { display: flex; justify-content: space-between; gap: 12px; color: var(--text-muted); font-size: 12px; }
.community-post-meta span:first-child { color: var(--accent-cyan); font-weight: 800; }
.community-post h2 { margin: 9px 0 7px; font-size: 19px; line-height: 1.35; letter-spacing: 0; }
.community-post > p { display: -webkit-box; overflow: hidden; margin: 0; color: var(--text-secondary); line-height: 1.65; -webkit-box-orient: vertical; -webkit-line-clamp: 3; white-space: pre-wrap; }
.community-post-actions, .community-detail-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.community-post-actions button, .community-detail-actions button { min-height: 32px; border: 1px solid var(--border-color); border-radius: 4px; background: transparent; color: var(--text-secondary); padding: 5px 10px; cursor: pointer; }
.community-post-actions button.active, .community-detail-actions button.active { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.community-post-actions button.liked, .community-detail-actions button.liked { border-color: rgba(239,68,68,.55); color: #ef4444; }
.community-detail { position: sticky; top: 18px; max-height: calc(100vh - 36px); overflow: auto; padding: 18px 20px 28px; border-left: 1px solid var(--border-color); background: var(--bg-card); }
.community-detail-toolbar { display: flex; align-items: center; justify-content: space-between; color: var(--accent-cyan); font-size: 12px; font-weight: 800; }
.community-author-row { display: grid; grid-template-columns: 38px 1fr auto; align-items: center; gap: 10px; margin: 10px 0 18px; }
.community-avatar { display: grid; width: 38px; height: 38px; place-items: center; border-radius: 50%; background: var(--accent-cyan-soft); color: var(--accent-cyan); font-weight: 800; }
.community-author-row > div:nth-child(2) { display: grid; gap: 3px; }
.community-author-row span { color: var(--text-muted); font-size: 11px; }
.community-author-row button { border: 1px solid var(--border-color); border-radius: 4px; background: transparent; color: var(--text-primary); padding: 6px 10px; cursor: pointer; }
.community-author-row button.active { color: var(--accent-cyan); border-color: var(--accent-cyan); }
.community-detail h2 { margin: 0 0 14px; font-size: 24px; line-height: 1.35; letter-spacing: 0; overflow-wrap: anywhere; }
.community-post-body { color: var(--text-primary); line-height: 1.8; white-space: pre-wrap; overflow-wrap: anywhere; }
.community-sources { display: grid; gap: 7px; margin-top: 18px; padding: 12px 0; border-top: 1px solid var(--border-color); }
.community-sources a { color: var(--accent-cyan); overflow-wrap: anywhere; }
.community-detail-actions { align-items: center; padding-bottom: 16px; border-bottom: 1px solid var(--border-color); }
.community-detail-actions span { color: var(--text-muted); font-size: 12px; }
.community-comments h3 { margin: 18px 0 10px; font-size: 15px; }
.community-empty-copy { color: var(--text-muted); }
.community-comment { padding: 12px 0; border-bottom: 1px solid var(--border-color); }
.community-comment > div { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; }
.community-comment span { color: var(--text-muted); }
.community-comment p { margin: 7px 0 0; color: var(--text-secondary); line-height: 1.65; white-space: pre-wrap; }
.community-comment-compose { display: grid; grid-template-columns: 1fr auto; align-items: end; gap: 8px; margin-top: 14px; }
.community-comment-compose textarea { min-height: 72px; padding: 9px; resize: vertical; }

@media (max-width: 980px) {
  .community-layout.has-detail { grid-template-columns: 1fr; }
  .community-detail { position: relative; top: auto; max-height: none; border-left: 0; border-top: 1px solid var(--border-color); }
}
@media (max-width: 640px) {
  .community-page { padding: 18px 16px 50px; }
  .community-header { align-items: stretch; flex-direction: column; }
  .community-header .ai-primary-action { width: 100%; max-width: 100%; box-sizing: border-box; }
  .community-error { grid-template-columns: 1fr; }
  .community-compose-options { align-items: stretch; flex-direction: column; }
  .community-composer select { width: 100%; }
  .community-post-meta { flex-direction: column; gap: 4px; }
  .community-detail { padding-inline: 14px; }
  .community-comment-compose { grid-template-columns: 1fr; }
}

/* home 页右栏 panel 适配情报侧栏：放宽并去除顶部渐变干扰 */

.intelligence-sidebar {
  font-size: 13px;
  color: var(--text-primary);
}

/* 时间线区 */
.intel-sidebar-timeline {
  padding: 14px 14px 10px;
  border-bottom: 1px solid var(--border-color);
}
.intel-sidebar-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.intel-sidebar-section-head h3 {
  font-size: 13px;
  font-weight: 700;
  margin: 0;
  color: var(--text-primary);
}
.intel-sidebar-refresh {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all .2s;
}
.intel-sidebar-refresh:hover:not(:disabled) {
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}
.intel-sidebar-refresh:disabled { opacity: .5; cursor: default; }

.intel-timeline-list {
  list-style: none;
  margin: 0;
  padding: 0 0 0 6px;
  position: relative;
}
.intel-timeline-list::before {
  content: '';
  position: absolute;
  left: 11px;
  top: 6px;
  bottom: 6px;
  width: 1px;
  background: var(--border-color);
}
.intel-timeline-node { position: relative; }
.intel-timeline-node button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: 6px;
  font-size: 12px;
  transition: all .15s;
}
.intel-timeline-node button:hover { background: var(--accent-cyan-soft); color: var(--text-primary); }
.intel-timeline-node.active button { color: var(--accent-cyan); font-weight: 600; }
.intel-timeline-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 2px solid var(--border-active);
  flex-shrink: 0;
  z-index: 1;
  transition: all .2s;
}
.intel-timeline-node.active .intel-timeline-dot {
  background: var(--accent-cyan);
  border-color: var(--accent-cyan);
  box-shadow: 0 0 0 4px var(--accent-cyan-soft);
}
.intel-timeline-label { flex: 1; text-align: left; }
.intel-timeline-count {
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 8px;
  background: var(--border-color);
  color: var(--text-muted);
}

/* 当日情报详情 */
.intel-sidebar-detail { padding: 12px 14px 16px; }
.intel-sidebar-detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}
.intel-sidebar-kicker {
  font-size: 10px;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--accent-cyan);
  opacity: .8;
}
.intel-sidebar-detail-head h3 {
  font-size: 15px;
  font-weight: 700;
  margin: 2px 0 0;
  color: var(--text-primary);
}
.intel-sidebar-mode {
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 6px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  white-space: nowrap;
}
.intel-sidebar-oneline {
  margin: 4px 0 12px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-muted);
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--bg-tertiary, rgba(255,255,255,.03));
  border-left: 2px solid var(--accent-cyan);
}

/* Lane 分组 */
.intel-sidebar-lane { margin-bottom: 14px; }
.intel-sidebar-lane header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2px;
}
.intel-sidebar-lane-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}
.intel-sidebar-lane header strong {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
}
.intel-sidebar-lane-hint {
  font-size: 10px;
  color: var(--text-muted);
  margin: 0 0 8px;
  opacity: .8;
}
.intel-sidebar-lane ol {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* 情报条目 */
.intel-sidebar-item {
  display: flex;
  align-items: stretch;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--bg-tertiary, rgba(255,255,255,.03));
  border: 1px solid var(--border-color);
  transition: border-color .15s;
}
.intel-sidebar-item:hover { border-color: var(--border-active); }
.intel-sidebar-item-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: transparent;
  border: none;
  padding: 0;
  text-align: left;
  cursor: pointer;
  min-width: 0;
}
.intel-sidebar-item-title {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.intel-sidebar-item-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 10px;
  color: var(--text-muted);
}
.intel-sidebar-source { font-style: normal; opacity: .85; }
.intel-sidebar-score {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-cyan);
}
.intel-sidebar-reasons {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.intel-sidebar-reasons i {
  font-size: 10px;
  font-style: normal;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  opacity: .85;
}
.intel-sidebar-dissect {
  align-self: center;
  font-size: 11px;
  padding: 4px 10px;
  border-radius: 6px;
  border: 1px solid var(--accent-cyan);
  background: transparent;
  color: var(--accent-cyan);
  cursor: pointer;
  white-space: nowrap;
  transition: all .15s;
  flex-shrink: 0;
}
.intel-sidebar-dissect:hover {
  background: var(--accent-cyan);
  color: var(--bg-primary);
}

.intel-sidebar-empty {
  font-size: 11px;
  color: var(--text-muted);
  opacity: .7;
  padding: 6px 0;
}

/* 机会 / 风险 */
.intel-sidebar-signals {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 10px;
  padding-top: 12px;
  border-top: 1px solid var(--border-color);
}
.intel-sidebar-signals h4 {
  font-size: 11px;
  font-weight: 700;
  margin: 0 0 6px;
  color: var(--text-primary);
}
.intel-sidebar-signals p {
  font-size: 11px;
  line-height: 1.5;
  margin: 0 0 4px;
  color: var(--text-muted);
}

/* home 页对话区 header 副标题 */
.chat-header-titles { display: flex; flex-direction: column; line-height: 1.2; gap: 1px; }
.chat-header-sub { font-size: 10px; color: var(--text-muted); opacity: .75; letter-spacing: .3px; }
.chat-welcome-tip {
  font-size: 11px;
  color: var(--text-muted);
  margin: 8px 0 14px;
  opacity: .7;
  font-style: italic;
  letter-spacing: .4px;
  position: relative;
  padding: 4px 12px;
}
.chat-welcome-tip::before,
.chat-welcome-tip::after {
  content: '·';
  margin: 0 6px;
  color: var(--accent-cyan);
  font-weight: 700;
}

/* 响应式：窄屏隐藏情报侧栏，对话区全宽 */

.panel.panel-recommendations {
  width: var(--panel-recommendations-w, 200px);
  background: var(--bg-secondary);
}
.panel.panel-recommendations .recommendation-date-rail {
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 14px 10px 16px;
}

/* 竖向时间线节点：label 双行（日期 + 周几/条数） */
.recommendation-rail-list .intel-timeline-label {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  line-height: 1.3;
}
.recommendation-rail-list .intel-timeline-label strong {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}
.recommendation-rail-list .intel-timeline-label small {
  font-size: 10px;
  color: var(--text-muted);
  opacity: .8;
}
.recommendation-rail-list .intel-timeline-node button {
  align-items: flex-start;
  padding: 8px 8px 8px 5px;
  gap: 10px;
}
.recommendation-rail-list .newspaper-timeline-diamond {
  margin-top: 3px;
}
.recommendation-rail-list.intel-timeline-list {
  padding-left: 4px;
  margin-top: 4px;
}
/* 精准推荐时间线竖线：贯穿 + 流光，与今日速报一致 */
.recommendation-rail-list.intel-timeline-list::before {
  left: 10px;
  top: 0;
  bottom: 0;
  width: 1px;
  background:
    linear-gradient(180deg, transparent 0%, var(--border-active) 4%, var(--border-active) 96%, transparent 100%);
  opacity: .7;
}
.recommendation-rail-list.intel-timeline-list::after {
  content: '';
  position: absolute;
  left: 9px;
  top: 0;
  width: 3px;
  height: 40px;
  background: linear-gradient(180deg, transparent, var(--accent-cyan) 50%, transparent);
  filter: blur(.5px);
  opacity: 0;
  animation: newspaper-rope-flow 7s linear infinite;
  pointer-events: none;
}
.recommendation-rail-hint {
  margin: 12px 4px 0;
  font-size: 10px;
  color: var(--text-muted);
  opacity: .7;
  line-height: 1.5;
}

/* 精准推荐卡片流骨架占位（RecommendationFeed loading） */
.news-item.skeleton .skeleton-line {
  height: 12px;
  margin: 8px 0;
  border-radius: 4px;
  background: var(--border-color);
  opacity: .5;
  animation: skeleton-pulse 1.4s ease-in-out infinite;
}
.news-item.skeleton .skeleton-line.w-80 { width: 80%; }
.news-item.skeleton .skeleton-line.w-60 { width: 60%; }
.news-item.skeleton .skeleton-line.w-40 { width: 40%; }
@keyframes skeleton-pulse {
  0%, 100% { opacity: .5; }
  50% { opacity: .25; }
}

.today-newspaper.with-timeline {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 6px;
  align-items: start;
}
.newspaper-body { min-width: 0; }

/* 左侧时间线：贯穿整个页面高度，随主体一起滚动，不局限在盒子内 */
.newspaper-timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 0;
  background: transparent;
  border: none;
}
.newspaper-timeline-list {
  list-style: none;
  margin: 0;
  padding: 0;
  position: relative;
}
/* 绳索主线索：连续竖线从顶到底，带微弱绞纹理 */
.newspaper-timeline-list::before {
  content: '';
  position: absolute;
  left: 11px;
  top: 0;
  bottom: 0;
  width: 2px;
  background:
    linear-gradient(180deg, transparent 0%, var(--border-active) 4%, var(--border-active) 96%, transparent 100%),
    repeating-linear-gradient(180deg, rgba(255,255,255,.06) 0 2px, transparent 2px 4px);
  border-radius: 2px;
  opacity: .7;
}
/* 绳索上滑动的光斑：像光顺着绳子流下 */
.newspaper-timeline-list::after {
  content: '';
  position: absolute;
  left: 10px;
  top: 0;
  width: 4px;
  height: 48px;
  background: linear-gradient(180deg, transparent, var(--accent-cyan) 50%, transparent);
  filter: blur(1px);
  opacity: 0;
  animation: newspaper-rope-flow 7s linear infinite;
  pointer-events: none;
}
@keyframes newspaper-rope-flow {
  0% { transform: translateY(0); opacity: 0; }
  6% { opacity: .7; }
  94% { opacity: .7; }
  100% { transform: translateY(calc(100vh - 100px)); opacity: 0; }
}
.newspaper-timeline-empty {
  padding: 14px 6px;
  font-size: 11px;
  color: var(--text-muted);
  opacity: .7;
}
.newspaper-timeline-node { position: relative; }
.newspaper-timeline-node button {
  display: flex;
  align-items: center;
  gap: 5px;
  width: 100%;
  padding: 8px 2px 8px 0;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  text-align: left;
  transition: color .25s;
}
.newspaper-timeline-node button:hover { color: var(--text-primary); }
.newspaper-timeline-node.active button { color: var(--accent-cyan); }
/* 菱形节点：45°旋转的方框描边 + 内核光点，精致优雅 */
.newspaper-timeline-diamond {
  position: relative;
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  transform: rotate(45deg);
  z-index: 1;
}
.newspaper-timeline-diamond-glow {
  position: absolute;
  inset: -3px;
  border: 1px solid var(--border-active);
  border-radius: 2px;
  background: var(--bg-primary);
  transition: all .3s ease;
}
.newspaper-timeline-diamond-core {
  position: relative;
  width: 4px;
  height: 4px;
  border-radius: 1px;
  background: var(--text-muted);
  opacity: .6;
  transition: all .3s ease;
}
.newspaper-timeline-node:hover .newspaper-timeline-diamond-glow {
  border-color: var(--accent-cyan);
  box-shadow: 0 0 8px var(--accent-cyan-soft);
}
.newspaper-timeline-node:hover .newspaper-timeline-diamond-core {
  background: var(--accent-cyan);
  opacity: 1;
}
.newspaper-timeline-node.active .newspaper-timeline-diamond-glow {
  border-color: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan), 0 0 18px var(--accent-cyan-soft);
  animation: newspaper-diamond-breathe 3s ease-in-out infinite;
}
.newspaper-timeline-node.active .newspaper-timeline-diamond-core {
  background: var(--accent-cyan);
  opacity: 1;
  width: 5px;
  height: 5px;
  box-shadow: 0 0 6px var(--accent-cyan);
}
@keyframes newspaper-diamond-breathe {
  0%, 100% { box-shadow: 0 0 8px var(--accent-cyan), 0 0 14px var(--accent-cyan-soft); }
  50% { box-shadow: 0 0 12px var(--accent-cyan), 0 0 22px var(--accent-cyan-soft); }
}
.newspaper-timeline-text {
  display: flex;
  flex-direction: column;
  gap: 1px;
  line-height: 1.2;
  min-width: 0;
}
.newspaper-timeline-text strong {
  font-size: 10px;
  font-weight: 600;
  white-space: nowrap;
  letter-spacing: .02em;
}
.newspaper-timeline-text small {
  font-size: 9px;
  opacity: .65;
  line-height: 1.3;
}

/* 中英对照 */
.newspaper-bilingual-all {
  font-size: 12px;
  padding: 5px 14px;
  border-radius: 6px;
  border: 1px solid var(--accent-cyan);
  background: transparent;
  color: var(--accent-cyan);
  cursor: pointer;
  transition: all .18s;
}
.newspaper-bilingual-all:hover { background: var(--accent-cyan-soft); }
.newspaper-bilingual-all.active {
  background: var(--accent-cyan);
  color: var(--bg-primary);
  box-shadow: 0 0 12px var(--accent-cyan-soft);
}
.newspaper-bilingual-toggle {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all .15s;
  margin-left: auto;
}
.newspaper-bilingual-toggle:hover:not(:disabled) {
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}
.newspaper-bilingual-toggle.active {
  background: var(--accent-cyan-soft);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}
.newspaper-bilingual-toggle:disabled { opacity: .6; cursor: default; }
.newspaper-bilingual {
  margin: 8px 0;
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--accent-cyan-soft);
  border-left: 2px solid var(--accent-cyan);
}
.newspaper-bilingual-zh-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0 0 4px;
}
.newspaper-bilingual-zh-summary {
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-muted);
  margin: 0;
  white-space: pre-wrap;
}
.newspaper-bilingual-loading {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0;
  opacity: .7;
}
.newspaper-bilingual-empty {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0;
  opacity: .6;
}

/* today 页加时间线后，报纸主体限宽 */
.main-workbench[data-nav="today"] .feed-workbench .today-newspaper.with-timeline {
  max-width: 1180px;
  margin: 0 auto;
}
/* 窄屏：时间线折叠为顶部横向 */
@media (max-width: 900px) {
  .today-newspaper.with-timeline {
    grid-template-columns: 1fr;
  }
  .newspaper-timeline {
    position: relative;
    top: auto;
    max-height: none;
  }
  .newspaper-timeline-list {
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    padding-bottom: 6px;
  }
  .newspaper-timeline-list::before { display: none; }
  .newspaper-timeline-node { flex-shrink: 0; }
}

.newspaper-drawer-mask {
  position: fixed;
  inset: 0;
  z-index: 300;
  background: rgba(0, 0, 0, .5);
  backdrop-filter: blur(3px);
  animation: fadeIn .15s ease;
  display: flex;
  justify-content: flex-end;
}
.newspaper-drawer {
  display: flex;
  flex-direction: column;
  width: min(820px, 90vw);
  height: 100vh;
  background: var(--bg-secondary);
  border-left: var(--panel-border);
  box-shadow: -16px 0 48px rgba(0, 0, 0, .4);
  animation: newspaperDrawerIn .25s cubic-bezier(.22, .61, .36, 1);
}
@keyframes newspaperDrawerIn {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}
.newspaper-drawer-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-bottom: 1px solid var(--border-color);
  font-size: 13px;
  color: var(--text-muted);
  flex-shrink: 0;
}
.newspaper-drawer-close {
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  width: 28px;
  height: 28px;
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  transition: background .15s, color .15s;
}
.newspaper-drawer-close:hover {
  background: var(--bg-card);
  color: var(--accent-rose, #f87171);
}
.newspaper-drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px 28px;
}
/* 抽屉内报纸聚焦内容宽度，去掉外围白框盒子 + 伪元素装饰 + 内缩 padding */
.newspaper-drawer-body .today-newspaper.with-timeline {
  max-width: 740px;
  margin: 0 auto;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.newspaper-drawer-body .today-newspaper.with-timeline::before,
.newspaper-drawer-body .today-newspaper.with-timeline::after {
  display: none !important;
}
/* 抽屉内：压缩顶部报头/概览条/总判断的占用，放大正文内容 */
.newspaper-drawer-body .newspaper-body { padding-top: 4px; }
.newspaper-drawer-body .newspaper-masthead { padding: 4px 0 8px !important; }
.newspaper-drawer-body .newspaper-masthead h1 { font-size: 22px !important; }
.newspaper-drawer-body .newspaper-digest-strip > div { padding: 5px 6px !important; }
.newspaper-drawer-body .newspaper-digest-strip dt { font-size: 8px !important; }
.newspaper-drawer-body .newspaper-digest-strip dd { font-size: 12px !important; }
.newspaper-drawer-body .newspaper-lead { padding: 16px 0 14px !important; }
.newspaper-drawer-body .newspaper-lead h2 { font-size: 20px !important; margin: 8px auto 10px !important; }
.newspaper-drawer-body .newspaper-lead > button { font-size: 14px !important; }
.newspaper-drawer-body .newspaper-lead p { font-size: 13px !important; line-height: 1.7 !important; }
.newspaper-drawer-body .newspaper-columns > section { padding: 14px 12px !important; }
.newspaper-drawer-body .newspaper-columns h2 { font-size: 16px !important; }
.newspaper-drawer-body .newspaper-story-title { font-size: 15px !important; }
.newspaper-drawer-body .newspaper-story p { font-size: 12.5px !important; line-height: 1.7 !important; -webkit-line-clamp: 4; }
.newspaper-drawer-body .newspaper-story { padding: 12px 0 !important; }

.llm-preset-select {
  flex: 1 1 160px; min-width: 140px;
  padding: 7px 10px; border-radius: 8px;
  border: 1px solid var(--border-active);
  background: var(--bg-secondary); color: var(--text-primary);
  font-size: 13px; cursor: pointer;
}
.llm-preset-select:focus { border-color: var(--accent-cyan); outline: none; }
.llm-preset-name-input {
  flex: 1 1 120px; min-width: 100px;
  padding: 7px 10px; border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--bg-secondary); color: var(--text-primary);
  font-size: 13px;
}
.llm-preset-name-input:focus { border-color: var(--accent-cyan); outline: none; }

/* 模型 field 头部：label + 拉取按钮 */
.llm-field-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; }

.modal-overlay.llm-config-overlay {
  background: rgba(0, 0, 0, .55);
  backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  z-index: 1000;
}
.llm-config-modal {
  width: 520px; max-width: calc(100vw - 40px); max-height: 88vh;
  display: flex; flex-direction: column;
  background: var(--bg-secondary);
  border: 1px solid var(--border-active);
  border-radius: 16px;
  box-shadow: 0 24px 60px rgba(0,0,0,.4), 0 0 0 1px var(--border-color);
  overflow: hidden;
}

/* Header */
.llm-config-header {
  display: flex; align-items: flex-start; justify-content: space-between;
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--border-color);
  background: linear-gradient(180deg, var(--accent-cyan-soft), transparent 80%);
}
.llm-config-title { display: flex; align-items: center; gap: 12px; }
.llm-config-title h3 { font-size: 16px; font-weight: 700; color: var(--text-primary); margin: 0; }
.llm-config-title p { font-size: 12px; color: var(--text-muted); margin: 3px 0 0; }
.llm-config-close {
  width: 30px; height: 30px; flex-shrink: 0;
  display: grid; place-items: center;
  border: 1px solid var(--border-color); border-radius: 8px;
  background: transparent; color: var(--text-muted);
  cursor: pointer; transition: all .15s;
}
.llm-config-close:hover { color: var(--text-primary); border-color: var(--border-active); background: var(--accent-cyan-soft); }

/* Body */
.llm-config-body { padding: 18px 24px; overflow-y: auto; flex: 1; }

/* Provider grid */
.llm-provider-grid {
  display: none; grid-template-columns: repeat(3, 1fr); gap: 8px;
  margin-bottom: 18px;
}
.llm-provider-card {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 12px 6px;
  border: 1.5px solid var(--border-color); border-radius: 10px;
  background: var(--bg-primary);
  cursor: pointer; transition: all .18s ease;
  text-align: center;
}
.llm-provider-card:hover { border-color: var(--border-active); background: var(--accent-cyan-soft); }
.llm-provider-card.active {
  border-color: var(--accent-cyan);
  background: var(--accent-cyan-soft);
  box-shadow: 0 0 0 1px var(--accent-cyan), 0 4px 14px var(--border-glow, color-mix(in srgb, var(--accent-cyan) 18%, transparent));
}
.provider-card-badge {
  display: grid; place-items: center;
  width: 30px; height: 30px;
  border-radius: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-active);
  color: var(--accent-cyan);
  font-size: 11px; font-weight: 700; letter-spacing: .02em;
  transition: all .18s;
}
.llm-provider-card.active .provider-card-badge {
  background: var(--accent-cyan); color: var(--bg-primary); border-color: var(--accent-cyan);
}
.provider-card-name { font-size: 12px; font-weight: 600; color: var(--text-muted); }
.llm-provider-card.active .provider-card-name { color: var(--text-primary); }
.provider-card-tag { font-size: 9px; color: var(--text-muted); opacity: .6; letter-spacing: .04em; }

/* Fields */
.llm-config-fields { display: flex; flex-direction: column; gap: 14px; }
.llm-field { display: flex; flex-direction: column; gap: 6px; }
.llm-field label { font-size: 11px; font-weight: 600; color: var(--text-muted); letter-spacing: .02em; }
.llm-field-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.llm-field-head label { margin: 0; }
.llm-saved-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}
.llm-input, .llm-model-select, .llm-preset-select, .llm-preset-name-input {
  width: 100%; height: 38px; padding: 0 12px;
  border: 1px solid var(--border-color); border-radius: 8px;
  background: var(--bg-primary); color: var(--text-primary);
  font-size: 13px; font-family: inherit;
  transition: border-color .15s, box-shadow .15s;
}
.llm-input:focus, .llm-model-select:focus, .llm-preset-select:focus, .llm-preset-name-input:focus {
  outline: none; border-color: var(--accent-cyan);
  box-shadow: 0 0 0 3px var(--accent-cyan-soft);
}
.llm-input::placeholder, .llm-preset-name-input::placeholder { color: var(--text-muted); opacity: .7; }
.llm-model-select { cursor: pointer; }

/* 拉取模型按钮 */
.llm-fetch-btn {
  flex-shrink: 0; padding: 6px 12px; height: 28px;
  border: 1px solid var(--border-active); border-radius: 6px;
  background: transparent; color: var(--accent-cyan);
  font-size: 11px; font-weight: 600; cursor: pointer;
  transition: all .15s;
}
.llm-fetch-btn:hover:not(:disabled) { background: var(--accent-cyan-soft); }
.llm-fetch-btn:disabled { opacity: .4; cursor: default; }
.llm-fetch-error { color: #ef4444; font-size: 11px; margin: 2px 0 0; }

/* 测试结果 */
.llm-test-result {
  margin-top: 12px; padding: 10px 12px; border-radius: 8px;
  font-size: 12px; line-height: 1.5;
}
.llm-test-result.success { background: rgba(168,134,67,.12); border-left: 3px solid var(--accent-emerald); color: var(--text-primary); }
.llm-test-result.fail { background: rgba(239,68,68,.1); border-left: 3px solid #ef4444; color: var(--text-primary); }
.llm-test-result .result-icon {
  display: none;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  margin-right: 6px;
  vertical-align: -2px;
}
.llm-test-result .result-icon svg {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
}

/* Footer */
.llm-config-footer {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  padding: 14px 24px;
  border-top: 1px solid var(--border-color);
  background: var(--bg-primary);
}
.llm-config-footer > .llm-preset-select,
.llm-config-footer > .llm-btn-preset-save {
  display: none;
}
.llm-preset-select { flex: 1 1 140px; min-width: 130px; height: 34px; }
.llm-preset-name-input { flex: 1 1 120px; min-width: 100px; height: 34px; }
.llm-btn-preset-save {
  padding: 0 14px; height: 34px;
  border: 1px solid var(--accent-cyan); border-radius: 8px;
  background: var(--accent-cyan-soft); color: var(--accent-cyan);
  font-size: 12px; font-weight: 600; cursor: pointer; transition: all .15s;
}
.llm-btn-preset-save:hover:not(:disabled) { background: var(--accent-cyan); color: var(--bg-primary); }
.llm-btn-preset-save:disabled { opacity: .4; cursor: default; }
.llm-btn-preset-del {
  padding: 0 12px; height: 34px;
  border: 1px solid var(--border-color); border-radius: 8px;
  background: transparent; color: var(--text-muted);
  font-size: 12px; cursor: pointer; transition: all .15s;
}
.llm-btn-preset-del:hover { border-color: #ef4444; color: #ef4444; }

.llm-btn-secondary, .llm-btn-test, .llm-btn-primary {
  height: 36px; padding: 0 18px; border-radius: 8px;
  font-size: 13px; font-weight: 600; cursor: pointer; transition: all .15s;
}
.llm-btn-secondary {
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted);
  margin-left: auto;
}
.llm-btn-secondary:hover { color: var(--text-primary); border-color: var(--border-active); }
.llm-btn-test {
  border: 1px solid var(--border-active); background: transparent; color: var(--accent-cyan);
}
.llm-btn-test:hover:not(:disabled) { background: var(--accent-cyan-soft); }
.llm-btn-test:disabled { opacity: .4; cursor: default; }
.llm-btn-primary {
  border: none; background: var(--accent-cyan); color: var(--bg-primary);
}
.llm-btn-primary:hover:not(:disabled) { background: var(--accent-emerald); }
.llm-btn-primary:disabled { opacity: .4; cursor: default; }

/* 另存为预设按钮 */
.llm-btn-save-as {
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 500;
  border: 1px solid var(--border-active);
  border-radius: 6px;
  background: var(--accent-cyan);
  color: var(--bg-primary);
  cursor: pointer;
  transition: all .15s ease;
  white-space: nowrap;
}
.llm-btn-save-as:hover:not(:disabled) {
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
  border-color: var(--accent-cyan);
}
.llm-btn-save-as:disabled {
  opacity: .4;
  cursor: default;
}

/* 另存为预设输入框 */
.llm-preset-name-input {
  height: 34px;
  padding: 0 10px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
  outline: none;
  transition: border-color .15s ease;
}
.llm-preset-name-input:focus {
  border-color: var(--accent-cyan);
}
.llm-preset-name-input::placeholder {
  color: var(--text-muted);
  opacity: .7;
}

/* 底部操作栏 */
.llm-config-footer {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 20px;
  border-top: 1px solid var(--border-color);
  background: var(--bg-secondary);
}
.llm-footer-spacer {
  flex: 1;
}

/* ============ 三段式 LLM 配置 UI（服务商模板 / 我的预设 / 当前配置）============ */
.llm-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.llm-tab-root {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 4px 0;
}
/* ===== v13 一卡式：我的预设 chips（点击切换，命名稳定） ===== */
.llm-presets-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.llm-preset-chip {
  display: inline-flex; align-items: center; gap: 2px;
  border: 1px solid var(--border-color); border-radius: 999px;
  background: var(--bg-secondary);
  transition: all var(--ease-fast);
}
.llm-preset-chip:hover { border-color: var(--accent-cyan); }
.llm-preset-chip.in-use {
  border-color: color-mix(in srgb, var(--accent-cyan) 55%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}
.llm-preset-chip-main {
  border: 0; background: transparent; padding: 5px 6px 5px 13px;
  color: var(--text-primary); font-size: 12px; cursor: pointer;
  max-width: 220px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.llm-preset-chip.in-use .llm-preset-chip-main { color: var(--accent-cyan); font-weight: 700; cursor: default; }
.llm-preset-chip-main:disabled { cursor: default; }
.llm-preset-chip-del {
  border: 0; background: transparent; color: var(--text-muted);
  font-size: 13px; line-height: 1; padding: 4px 9px 4px 4px; cursor: pointer;
  border-radius: 999px;
}
.llm-preset-chip-del:hover { color: var(--status-critical, #f85149); }
/* 联网搜索折叠区 */
.llm-websearch-details {
  border: 1px dashed var(--border-color); border-radius: 10px;
  padding: 10px 14px;
}
.llm-websearch-details summary {
  cursor: pointer; font-size: 12.5px; color: var(--text-muted);
  user-select: none;
}
.llm-websearch-details summary:hover { color: var(--text-primary); }
.llm-websearch-body {
  display: flex; flex-direction: column; gap: 10px;
  margin-top: 12px; padding-top: 4px;
}
.llm-section-head {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 4px;
}
.llm-section-head label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.llm-section-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent-cyan);
  color: var(--bg-primary);
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  flex-shrink: 0;
}
.llm-section-hint {
  font-size: 12px;
  color: var(--text-muted);
}

/* 服务商模板下拉列表 */
.llm-provider-select-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.llm-provider-select {
  flex: 1;
  height: 36px;
  padding: 0 12px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  cursor: pointer;
  transition: border-color .15s ease;
}
.llm-provider-select:hover {
  border-color: var(--border-active);
}
.llm-provider-select:focus {
  border-color: var(--accent-cyan);
  box-shadow: 0 0 0 1px var(--accent-cyan) inset;
}

/* 我的预设列表（紧凑行布局） */
.llm-user-presets-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.llm-preset-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  font-size: 12px;
  transition: all .12s ease;
}
.llm-preset-row:hover {
  border-color: var(--border-active);
  background: var(--accent-cyan-soft);
}
.llm-preset-row.in-use {
  border-color: var(--accent-cyan);
  background: var(--accent-cyan-soft);
  box-shadow: 0 0 0 1px var(--accent-cyan) inset;
}
.llm-preset-row-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
  min-width: 0;
}
.llm-preset-row .llm-preset-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.llm-preset-row .llm-preset-sub {
  font-size: 11px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.llm-preset-row .llm-preset-badge {
  width: 22px;
  height: 22px;
  font-size: 10px;
  border-radius: 4px;
  flex-shrink: 0;
}
.llm-preset-row .llm-preset-chip {
  padding: 1px 5px;
  font-size: 10px;
  border-radius: 3px;
  flex-shrink: 0;
}
.llm-preset-row .llm-preset-updated {
  font-size: 11px;
  color: var(--text-muted);
  flex-shrink: 0;
  margin-right: auto;
}
.llm-preset-row .llm-btn-apply,
.llm-preset-row .llm-btn-del {
  padding: 3px 8px;
  font-size: 11px;
  flex-shrink: 0;
}

/* 空状态 */
.llm-empty-state {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: var(--bg-secondary);
  border: 1px dashed var(--border-color);
  border-radius: 10px;
}
.llm-empty-icon {
  font-size: 24px;
  opacity: .5;
}
.llm-empty-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0 0 2px;
}
.llm-empty-desc {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0;
}

/* 手动添加模型行 */
.llm-manual-add-row {
  display: flex;
  gap: 10px;
  align-items: center;
}
.llm-add-btn {
  padding: 6px 12px;
  font-size: 12px;
  border: 1px solid var(--border-active);
  border-radius: 6px;
  background: var(--accent-cyan);
  color: var(--bg-primary);
  cursor: pointer;
  transition: all .15s ease;
  white-space: nowrap;
}
.llm-add-btn:hover:not(:disabled) {
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}
.llm-add-btn:disabled {
  opacity: .4;
  cursor: default;
}

/* 联网搜索开关 */
.llm-toggle-wrap {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
}
.llm-toggle-wrap input[type="checkbox"] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: var(--accent-cyan, #22d3ee);
}

/* 羊皮纸底色 + 褶皱纹理 + 泛黄晕染 */
.today-newspaper {
  position: relative;
  --text-primary: #302417;
  --text-secondary: #51402a;
  --text-muted: #786545;
  --border-color: rgba(86, 61, 29, .35);
  --border-active: #765126;
  --panel-border: 2px solid rgba(86, 61, 29, .35);
  --accent-cyan: #70471f;
  --accent-cyan-soft: rgba(112, 71, 31, .12);
  --accent-cyan-border: rgba(112, 71, 31, .42);
  --bg-primary: #dbc590;
  --bg-secondary: #e4d19f;
  background:
    /* 不规则纵向折痕 */
    linear-gradient(88deg, transparent 0 27%, rgba(92, 63, 24, .09) 27.4%, rgba(255, 246, 207, .22) 27.8%, transparent 28.5%),
    linear-gradient(93deg, transparent 0 71%, rgba(255, 245, 202, .18) 71.3%, rgba(93, 65, 27, .08) 71.8%, transparent 72.6%),
    /* 横向压痕 */
    linear-gradient(177deg, transparent 0 44%, rgba(82, 56, 20, .08) 44.4%, rgba(255, 243, 197, .16) 44.8%, transparent 45.5%),
    /* 纤维横纹 */
    repeating-linear-gradient(
      2deg,
      transparent,
      transparent 2px,
      rgba(93, 67, 31, .035) 2px,
      rgba(93, 67, 31, .035) 3px
    ),
    /* 褶皱斜纹（模拟纸张褶皱） */
    repeating-linear-gradient(
      137deg,
      transparent,
      transparent 8px,
      rgba(120,100,50,.02) 8px,
      rgba(120,100,50,.02) 9px
    ),
    /* 泛黄晕染（中心亮，边缘暗） */
    radial-gradient(ellipse at 18% 22%, rgba(116, 77, 27, .12), transparent 28%),
    radial-gradient(ellipse at 74% 68%, rgba(109, 72, 25, .10), transparent 34%),
    radial-gradient(ellipse at 48% 38%, rgba(255, 243, 199, .28), transparent 62%),
    /* 基础纸张底色 */
    linear-gradient(175deg, #e5d3a5, #d8bf85 28%, #ddc894 72%, #c9a968);
  border: 1px solid rgba(91, 63, 27, .42);
  border-radius: 4px;
  box-shadow:
    0 2px 8px rgba(0,0,0,.25),
    0 12px 32px rgba(0,0,0,.12),
    inset 0 0 120px rgba(83, 54, 19, .13),
    inset 0 1px 0 rgba(255, 248, 216, .5);
}
/* 羊皮纸边缘泛黄加深 */
.today-newspaper::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 4px;
  pointer-events: none;
  background:
    /* 上下边缘泛黄 */
    linear-gradient(180deg, rgba(104, 69, 24, .16), transparent 15%),
    linear-gradient(0deg, rgba(91, 58, 18, .18), transparent 12%),
    /* 左右边缘泛黄 */
    linear-gradient(90deg, rgba(100, 65, 20, .16), transparent 8%),
    linear-gradient(270deg, rgba(100, 65, 20, .14), transparent 8%);
  z-index: 0;
}
/* 羊皮纸褶皱阴影条（更逼真的褶皱） */
.today-newspaper::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 4px;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      175deg,
      transparent,
      transparent 40px,
      rgba(0,0,0,.015) 40px,
      transparent 42px,
      transparent 80px
    ),
    repeating-linear-gradient(
      165deg,
      transparent,
      transparent 60px,
      rgba(255,255,255,.008) 60px,
      transparent 61px,
      transparent 90px
    );
  z-index: 0;
}
.newspaper-body { position: relative; z-index: 1; }
/* 顶部装饰双线：经典报纸 masthead */
.newspaper-masthead {
  border-top: 3px double var(--text-primary) !important;
  border-bottom: 1px solid var(--text-primary) !important;
  position: relative;
}
.newspaper-masthead::before {
  content: '';
  position: absolute;
  bottom: -3px;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--text-primary);
}
.newspaper-masthead > div:first-child > span:first-child {
  display: block;
  font: 400 9px/1 Georgia, 'Noto Serif SC', serif;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 4px;
}
.newspaper-masthead h1 {
  font-family: Georgia, 'Noto Serif SC', 'Playfair Display', serif !important;
  font-size: 32px !important;
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1;
}
/* 版次信息 */
.newspaper-edition {
  font-family: Georgia, 'Noto Serif SC', serif;
  text-align: center;
}
.newspaper-edition time {
  display: block;
  font-family: Georgia, 'Noto Serif SC', serif;
  font-size: 12px;
  color: var(--text-primary);
}
.newspaper-edition > span {
  font-size: 10px;
  color: var(--text-muted);
}
/* 操作按钮：报纸风格 */
.newspaper-actions button {
  font-family: Georgia, 'Noto Serif SC', serif;
  letter-spacing: .02em;
}
/* 今日总判断：头版头条 */
.newspaper-lead {
  border-bottom: 2px solid var(--text-primary) !important;
  padding: 32px max(0px, 6vw) 28px !important;
  position: relative;
}
.newspaper-lead::after {
  content: '';
  position: absolute;
  bottom: 3px;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--text-primary);
}
.newspaper-label {
  font: 700 9px/1 Georgia, 'Noto Serif SC', serif !important;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--accent-cyan) !important;
}
.newspaper-lead h2 {
  font-family: Georgia, 'Noto Serif SC', 'Playfair Display', serif !important;
  font-size: 26px !important;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -.01em;
  margin: 12px auto 16px !important;
}
.newspaper-lead > button {
  font-family: Georgia, 'Noto Serif SC', serif !important;
  font-size: 16px !important;
  font-weight: 700;
  letter-spacing: 0;
}
.newspaper-lead p {
  font-family: Georgia, 'Noto Serif SC', serif;
  font-size: 14px !important;
  line-height: 1.8 !important;
  color: var(--text-secondary);
  text-align: justify;
  text-justify: inter-ideograph;
}
.newspaper-lead footer {
  font: 500 10px/1 Georgia, 'Noto Serif SC', serif;
  letter-spacing: .03em;
}
/* 分栏：加粗分隔线 + 栏标题 */
.newspaper-columns {
  border-bottom: 2px solid var(--text-primary) !important;
  border-top: 1px solid var(--text-primary);
}
.newspaper-columns > section + section {
  border-left: 2px solid var(--text-primary) !important;
}
.newspaper-columns > section > header {
  border-bottom: 2px solid var(--text-primary) !important;
}
.newspaper-columns > section > header > span {
  font: 600 9px/1 Georgia, 'Noto Serif SC', serif !important;
  letter-spacing: .16em;
  text-transform: uppercase;
}
.newspaper-columns h2 {
  font-family: Georgia, 'Noto Serif SC', 'Playfair Display', serif !important;
  font-size: 17px !important;
  letter-spacing: -.01em;
}
/* 资讯条目：报纸文章风格 */
.newspaper-story {
  border-bottom: 1px solid var(--border-color) !important;
}
.newspaper-story:last-child {
  border-bottom: none;
}
.newspaper-story-rank {
  font: 700 12px/1.6 Georgia, 'Noto Serif SC', serif !important;
  color: var(--accent-cyan) !important;
}
.newspaper-story-title {
  font-family: Georgia, 'Noto Serif SC', 'Playfair Display', serif !important;
  font-size: 15px !important;
  font-weight: 700;
  line-height: 1.4 !important;
  letter-spacing: -.01em;
}
.newspaper-story p {
  font-family: Georgia, 'Noto Serif SC', serif;
  font-size: 12px !important;
  line-height: 1.7 !important;
  text-align: justify;
}
.newspaper-story footer {
  font: 400 10px/1 Georgia, 'Noto Serif SC', serif;
}
/* 领域版面 */
.newspaper-domain-band {
  border-bottom: 2px solid var(--text-primary) !important;
  border-top: 1px solid var(--text-primary);
}
.newspaper-domain-band > header {
  border-bottom: 1px solid var(--text-primary);
}
.newspaper-domain-band > div {
  border-top: 1px solid var(--text-primary) !important;
  border-left: 1px solid var(--text-primary) !important;
}
.newspaper-domain-band section {
  border-right: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}
.newspaper-domain-band h3 {
  font: 700 11px/1 Georgia, 'Noto Serif SC', serif;
  letter-spacing: .04em;
}
.newspaper-domain-band button {
  font: 400 11px/1.4 Georgia, 'Noto Serif SC', serif;
}
/* 机会与风险 */
.newspaper-judgement-band {
  border-bottom: 2px solid var(--text-primary) !important;
  border-top: 1px solid var(--text-primary);
}
.newspaper-judgement-band section + section {
  border-left: 2px solid var(--text-primary) !important;
}
.newspaper-judgement-band h2 {
  font: 700 12px/1 Georgia, 'Noto Serif SC', serif !important;
  letter-spacing: .06em;
  text-transform: uppercase;
}
.newspaper-judgement-band p {
  font-family: Georgia, 'Noto Serif SC', serif;
}
/* 今日信源 */
.newspaper-sources {
  border-top: 1px solid var(--text-primary);
  padding-top: 16px;
}
.newspaper-sources h2 {
  font: 700 13px/1 Georgia, 'Noto Serif SC', serif !important;
  letter-spacing: .06em;
  text-transform: uppercase;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 8px;
}
.newspaper-sources ol {
  columns: 2 !important;
  font: 400 10px/1.6 Georgia, 'Noto Serif SC', serif;
}
.newspaper-sources li span {
  font-family: Georgia, 'Noto Serif SC', serif;
}
.newspaper-sources a {
  font-family: Georgia, 'Noto Serif SC', serif;
  text-decoration: underline;
  text-decoration-color: var(--border-color);
  text-underline-offset: 2px;
}
.newspaper-sources a:hover {
  text-decoration-color: var(--accent-cyan);
}
/* 空态 */
.newspaper-empty {
  font-family: Georgia, 'Noto Serif SC', serif;
  font-size: 15px;
  color: var(--text-muted);
  padding: 80px 20px;
}
/* 报纸 body 内留白 */
.newspaper-body {
  padding: 0 8px;
}
.newspaper-timeline {
  z-index: 1;
}

/* 版面数据栏：让速报先给出当日信息覆盖面。 */
.newspaper-digest-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin: 0;
  border-bottom: 3px double var(--text-primary);
}
.newspaper-digest-strip > div {
  display: flex;
  min-width: 0;
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  padding: 9px 8px;
}
.newspaper-digest-strip > div + div {
  border-left: 1px solid var(--border-color);
}
.newspaper-digest-strip dt {
  color: var(--text-muted);
  font: 600 9px/1 Georgia, 'Noto Serif SC', serif;
}
.newspaper-digest-strip dd {
  margin: 0;
  color: var(--text-primary);
  font: 700 13px/1 Georgia, 'Noto Serif SC', serif;
  white-space: nowrap;
}

/* 当日快讯：补足头版精选之外的信息密度。 */
.newspaper-briefs {
  padding: 18px 0 20px;
  border-top: 1px solid var(--text-primary);
  border-bottom: 3px double var(--text-primary);
}
.newspaper-briefs > header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: baseline;
  gap: 12px;
  padding-bottom: 9px;
  border-bottom: 2px solid var(--text-primary);
}
.newspaper-briefs > header span {
  color: var(--text-muted);
  font: 600 9px/1 Georgia, 'Noto Serif SC', serif;
  letter-spacing: .14em;
}
.newspaper-briefs > header h2 {
  margin: 0;
  color: var(--text-primary);
  font: 700 18px/1 Georgia, 'Noto Serif SC', serif;
}
.newspaper-briefs > header small {
  color: var(--text-muted);
  font: 400 10px/1 Georgia, 'Noto Serif SC', serif;
}
.newspaper-briefs ol {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
}
.newspaper-briefs li {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 4px 8px;
  min-width: 0;
  padding: 10px 12px 9px 0;
  border-bottom: 1px solid var(--border-color);
}
.newspaper-briefs li:nth-child(even) {
  padding-left: 12px;
  border-left: 1px solid var(--border-color);
}
.newspaper-briefs li > span {
  grid-row: 1 / span 2;
  color: var(--accent-cyan);
  font: 700 10px/1.5 Georgia, 'Noto Serif SC', serif;
}
.newspaper-briefs li > button {
  min-width: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  font: 700 12px/1.45 Georgia, 'Noto Serif SC', serif;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.newspaper-briefs li > button:hover {
  color: var(--accent-cyan);
}
.newspaper-briefs li > small {
  overflow: hidden;
  color: var(--text-muted);
  font: 400 9px/1.3 Georgia, 'Noto Serif SC', serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 760px) {
  .newspaper-masthead {
    grid-template-columns: 1fr !important;
  }
  .newspaper-actions {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: 100%;
  }
  .newspaper-actions button {
    min-width: 0;
    padding: 7px 4px;
    white-space: nowrap;
  }
  .newspaper-digest-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .newspaper-digest-strip > div:nth-child(odd) {
    border-left: 0;
  }
  .newspaper-digest-strip > div:last-child {
    grid-column: 1 / -1;
    border-top: 1px solid var(--border-color);
  }
  .newspaper-briefs ol {
    grid-template-columns: 1fr;
  }
  .newspaper-briefs li:nth-child(even) {
    padding-left: 0;
    border-left: 0;
  }
  .newspaper-briefs > header {
    grid-template-columns: auto 1fr;
  }
  .newspaper-briefs > header small {
    display: none;
  }
}

/* 细分模块改为横向标签（flex-wrap），节省纵向空间 */
.nav-context-group .nav-group-title-static {
  padding: 4px 4px 6px;
  font-size: 9px;
  letter-spacing: .06em;
}
.nav-context-group .nav-item.nav-sub-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  padding: 0 10px;
  margin: 0 4px 4px 0;
  border: 1px solid var(--border-color);
  border-radius: 14px;
  font-size: 11px;
  background: var(--bg-primary);
  transition: all .15s;
}
.nav-context-group .nav-item.nav-sub-item:hover {
  border-color: var(--border-active);
  background: var(--accent-cyan-soft);
}
.nav-context-group .nav-item.nav-sub-item.active {
  border-color: var(--accent-cyan);
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}
.nav-context-group .nav-item.nav-sub-item .nav-icon {
  width: 14px;
  height: 14px;
  display: inline-flex;
}
.nav-context-group .nav-item.nav-sub-item .nav-icon svg {
  width: 13px;
  height: 13px;
}
.nav-context-group .nav-item.nav-sub-item .nav-count {
  font-size: 9px;
  padding: 0 5px;
  min-width: auto;
  height: 14px;
  line-height: 14px;
}
/* 侧边栏整体更紧凑 */
.sidebar { font-size: 12px; }
.sidebar-header { padding: 10px 12px !important; }
.sidebar-footer { padding: 8px 8px !important; }
.sidebar-action { min-height: 34px !important; }
.nav-item { padding: 0 10px; }
.nav-label { font-size: 12px; }

.nav-context-group { margin-bottom: 8px; padding: 0 8px; }
.nav-context-group.collapsed .nav-item.nav-sub-item { display: none; }

/* Keep each submenu attached to the primary item that opened it. */
.nav-primary-entry {
  position: relative;
}
.nav-primary-chevron {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  color: var(--text-muted);
  transition: transform .18s ease, color .18s ease;
}
.nav-primary-chevron svg {
  width: 14px;
  height: 14px;
}
.nav-primary-chevron.open {
  color: var(--accent-cyan);
  transform: rotate(180deg);
}
.nav-context-group.nav-context-inline {
  display: block;
  margin: -1px 0 6px 21px;
  padding: 3px 0 3px 10px;
  border-left: 1px solid var(--accent-cyan-border);
}
.nav-context-group.nav-context-inline .nav-item.nav-sub-item {
  display: flex;
  width: calc(100% - 4px);
  min-height: 30px;
  margin: 1px 0;
  padding: 4px 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
}
.nav-context-group.nav-context-inline .nav-item.nav-sub-item:hover {
  background: var(--bg-hover);
}
.nav-context-group.nav-context-inline .nav-item.nav-sub-item.active {
  background: var(--accent-cyan-soft);
  color: var(--accent-cyan);
}

.session-sidebar {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  /* 暖墨底：左侧会话栏偏金色，呼应"沉淀/历史"语义 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 4%, transparent) 60%, var(--bg-secondary)) 0%,
      var(--bg-secondary) 40%,
      color-mix(in srgb, rgba(120,90,60,.03) 50%, var(--bg-secondary)) 100%);
  overflow: hidden;
  position: relative;
}
.session-sidebar::before {
  /* 右侧 1px 描金分隔线 */
  content: "";
  position: absolute;
  top: 0; bottom: 0; right: 0;
  width: 1px;
  background: linear-gradient(180deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 22%, transparent) 60%, transparent) 30%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 18%, transparent) 50%, transparent) 70%,
    transparent 100%);
  pointer-events: none;
  z-index: 1;
}
.session-sidebar-top {
  flex-shrink: 0;
  padding: 12px 10px 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.session-new-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--accent-cyan-border, var(--border-color));
  border-radius: 8px;
  background: var(--accent-cyan-softer);
  color: var(--accent-cyan);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s;
}
.session-new-btn:hover { background: var(--accent-cyan-soft); }
.session-search {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-card);
  color: var(--text-muted);
}
.session-search input {
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  outline: none;
}
.session-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 4px 6px;
}
.session-list-empty {
  padding: 24px 10px;
  text-align: center;
  color: var(--text-muted);
  font-size: 12px;
}
.session-group {
  position: relative;
  margin-bottom: 8px;
  /* 时间轨道：组内竖向细轨，会话小点挂在轨上（时间轴语义） */
  padding-left: 2px;
}
.session-group::before {
  content: '';
  position: absolute;
  left: 7px;
  top: 26px;
  bottom: 6px;
  width: 1.5px;
  background: var(--border-subtle, rgba(128, 128, 128, .18));
  border-radius: 1px;
}
.session-group-label {
  padding: 6px 8px 4px 10px;
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: .04em;
}
/* 会话项：单行紧凑（原两行标题+时间行高减半）；左侧轨道小点 + 标题 + 淡色时间 */
.session-item {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding: 6px 36px 6px 18px;
  margin-left: 8px;
  border-radius: 7px;
  cursor: pointer;
  transition: background .12s;
}
.session-item:hover { background: var(--bg-card); }
.session-item.active { background: var(--accent-cyan-softer); }
.session-item.active .session-item-title { color: var(--accent-cyan); }
.session-item.is-editing {
  cursor: default;
  padding-right: 10px;
  background: var(--bg-card);
}
.session-item.is-editing.active { background: var(--accent-cyan-softer); }
/* 轨道小点：默认暗点，当前会话点亮并发光 */
.session-dot {
  position: absolute;
  left: -8.5px;
  top: 50%;
  transform: translateY(-50%);
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--border-color, #666);
  border: 1.5px solid var(--bg-primary, transparent);
  transition: background .15s, box-shadow .15s, transform .15s;
  flex: none;
}
.session-item:hover .session-dot { background: var(--text-muted); }
.session-item.active .session-dot {
  background: var(--accent-cyan, #22d3ee);
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan, #22d3ee) 70%, transparent);
  transform: translateY(-50%) scale(1.15);
}
.session-item-title {
  flex: 1;
  min-width: 0;
  font-size: 12.5px;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.session-item-meta {
  flex: none;
  font-size: 10px;
  color: var(--text-muted);
  opacity: .75;
  font-variant-numeric: tabular-nums;
}
/* hover 时右侧浮出操作按钮，时间淡出避让 */
.session-item:hover .session-item-meta,
.session-item.active .session-item-meta { opacity: 0; }
/* 操作按钮容器：重命名 + 删除，hover 时浮现 */
.session-item-actions {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  gap: 2px;
  opacity: 0;
  transition: opacity .12s;
}
.session-item:hover .session-item-actions,
.session-item.active .session-item-actions { opacity: 1; }
.session-item-btn {
  width: 20px;
  height: 20px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background .12s, color .12s;
}
.session-item-btn svg {
  width: 12px;
  height: 12px;
  display: block;
}
.session-item-rename:hover {
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 18%, transparent);
  color: var(--accent-cyan);
}
.session-item-del:hover { background: rgba(239,68,68,.15); color: var(--accent-rose, #f87171); }
/* inline 重命名 input */
.session-item-edit-input {
  width: 100%;
  font-size: 13px;
  font-family: inherit;
  color: var(--text-primary);
  background: var(--bg-base, var(--bg-secondary));
  border: 1px solid var(--accent-cyan, #06b6d4);
  border-radius: 4px;
  padding: 3px 6px;
  outline: none;
  margin: 0;
}
.session-item-edit-input:focus {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-cyan, #06b6d4) 25%, transparent);
}
.session-sidebar-bottom {
  flex-shrink: 0;
  padding: 10px;
  border-top: 1px solid var(--border-color);
}
.session-newspaper-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px;
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--bg-card);
  color: var(--accent-cyan);
  cursor: pointer;
  transition: border-color .15s, background .15s;
}
.session-newspaper-btn:hover { border-color: var(--accent-cyan); background: var(--accent-cyan-softer); }
.session-newspaper-btn span {
  display: flex;
  flex-direction: column;
  gap: 1px;
  text-align: left;
}
.session-newspaper-btn strong { font-size: 13px; color: var(--text-primary); }
.session-newspaper-btn small { font-size: 10px; color: var(--text-muted); }

.agent-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  /* 冷墨底：右侧偏青色，呼应"工具/控制"语义 */
  background:
    linear-gradient(180deg,
      color-mix(in srgb, rgba(60,80,100,.045) 60%, var(--bg-secondary)) 0%,
      var(--bg-secondary) 40%,
      color-mix(in srgb, rgba(40,55,75,.035) 50%, var(--bg-secondary)) 100%);
  overflow: hidden; /* 由内部 panes 自己滚动 */
  gap: 0;
  position: relative;
}
.agent-panel::before {
  /* 左侧 1px 描青渐隐分隔线 */
  content: "";
  position: absolute;
  top: 0; bottom: 0; left: 0;
  width: 1px;
  background: linear-gradient(180deg,
    transparent 0%,
    color-mix(in srgb, rgba(96,165,250,.22) 60%, transparent) 30%,
    color-mix(in srgb, rgba(96,165,250,.16) 50%, transparent) 70%,
    transparent 100%);
  pointer-events: none;
  z-index: 1;
}

.agent-topcard {
  position: relative;
  flex-shrink: 0;
  padding: 12px 12px 10px 14px;
  /* 水墨渐变边框：左侧金色重 → 右侧渐隐至透明 */
  border-bottom: 1px solid transparent;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--accent-cyan, #06b6d4) 5%, var(--bg-base, var(--bg-secondary))) 0%,
      var(--bg-base, var(--bg-secondary)) 100%) padding-box,
    linear-gradient(90deg,
      color-mix(in srgb, var(--accent-cyan, #06b6d4) 38%, transparent) 0%,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 55%, transparent) 30%, transparent) 28%,
      color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 22%, transparent) 60%, transparent) 60%,
      transparent 100%) border-box;
  background-origin: border-box;
  background-clip: padding-box, border-box;
  border-image: none; /* 用 background 双层模拟，避免 border-image 在圆角下溢出 */
  overflow: hidden;
  transition: background .3s, box-shadow .25s ease;
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 5%, transparent),
    0 2px 8px -4px rgba(0,0,0,.18);
}
.agent-topcard::after {
  /* 顶部细金线：模拟宣纸描金，呼应水墨主题 */
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 45%, transparent) 50%, transparent) 18%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 70%, transparent) 60%, transparent) 50%,
    color-mix(in srgb, color-mix(in srgb, var(--accent-cyan) 35%, transparent) 50%, transparent) 82%,
    transparent 100%);
  opacity: .8;
  pointer-events: none;
}
.agent-topcard:hover {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 8%, transparent),
    0 4px 14px -4px rgba(0,0,0,.22);
}
/* 左侧状态竖条：默认金色，运行/草稿/未配置分别变色 */
.agent-topcard-stripe {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, var(--accent-cyan, #06b6d4), color-mix(in srgb, var(--accent-cyan, #06b6d4) 40%, transparent));
  transition: background .3s;
}
.agent-topcard.is-streaming .agent-topcard-stripe {
  background: linear-gradient(180deg, #60a5fa, #3b82f6);
  animation: agent-stripe-flow 1.6s ease-in-out infinite;
}
.agent-topcard.is-draft .agent-topcard-stripe {
  background: linear-gradient(180deg, var(--accent-amber, #f59e0b), color-mix(in srgb, var(--accent-amber, #f59e0b) 40%, transparent));
}
.agent-topcard.is-warn .agent-topcard-stripe {
  background: linear-gradient(180deg, var(--accent-rose, #f87171), color-mix(in srgb, var(--accent-rose, #f87171) 40%, transparent));
}
@keyframes agent-stripe-flow {
  0%, 100% { opacity: 1; box-shadow: 0 0 6px rgba(96, 165, 250, .6); }
  50% { opacity: .55; box-shadow: 0 0 12px rgba(96, 165, 250, .9); }
}

/* 主任务区：head 行 + 标题 + 模型行 */
.agent-topcard-main {
  min-width: 0;
  margin-bottom: 10px;
}
.agent-topcard-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
  min-width: 0;
}
.agent-topcard-head-left {
  min-width: 0;
  display: flex;
  align-items: center;
}
.agent-topcard-label {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 9px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .7px;
  font-weight: 700;
}
/* 状态点：与状态条同步变色，运行中呼吸 */
.agent-topcard-led {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-cyan, #06b6d4);
  box-shadow: 0 0 4px color-mix(in srgb, var(--accent-cyan, #06b6d4) 60%, transparent);
  flex-shrink: 0;
  display: inline-block;
  transition: background .3s, box-shadow .3s;
}
.agent-topcard.is-streaming .agent-topcard-led {
  background: #60a5fa;
  box-shadow: 0 0 6px rgba(96, 165, 250, .7);
  animation: agent-led-breathe 1.2s ease-in-out infinite;
}
.agent-topcard.is-draft .agent-topcard-led {
  background: var(--accent-amber, #f59e0b);
  box-shadow: 0 0 4px color-mix(in srgb, var(--accent-amber, #f59e0b) 60%, transparent);
}
.agent-topcard.is-warn .agent-topcard-led {
  background: var(--accent-rose, #f87171);
  box-shadow: 0 0 4px color-mix(in srgb, var(--accent-rose, #f87171) 60%, transparent);
}
@keyframes agent-led-breathe {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .5; transform: scale(1.35); }
}

.agent-topcard-title {
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
  transition: color .25s;
}
.agent-topcard-title.is-draft {
  color: var(--text-muted);
  font-style: italic;
  font-weight: 500;
  animation: agent-draft-pulse 2s ease-in-out infinite;
}
@keyframes agent-draft-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .55; }
}

/* 模型行：单独一行带点 + 名称 */
.agent-topcard-model-row {
  display: flex;
  align-items: center;
}
.agent-topcard-model {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 600;
  background: var(--bg-tertiary, var(--bg-card));
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
  max-width: 200px;
}
.agent-topcard-model-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent-cyan, #06b6d4);
  flex-shrink: 0;
}
.agent-topcard-model {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 状态徽章 */
.agent-topcard-badge {
  flex-shrink: 0;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .3px;
  background: color-mix(in srgb, var(--accent-amber, #f59e0b) 16%, transparent);
  color: var(--accent-amber, #f59e0b);
  border: 1px solid color-mix(in srgb, var(--accent-amber, #f59e0b) 40%, transparent);
  white-space: nowrap;
}
.agent-topcard-badge.is-running {
  background: color-mix(in srgb, #3b82f6 18%, transparent);
  color: #60a5fa;
  border-color: color-mix(in srgb, #3b82f6 40%, transparent);
  animation: agent-badge-glow 1.4s ease-in-out infinite;
}
@keyframes agent-badge-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(96, 165, 250, .4); }
  50% { box-shadow: 0 0 0 4px rgba(96, 165, 250, 0); }
}

/* 指标条：单行迷你胶囊（原 2×2 大格子占 ~90px 且多为 0，胶囊化省出技能区空间） */
.agent-topcard-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 8px;
}
.agent-metric-pill {
  display: inline-flex;
  align-items: baseline;
  gap: 3px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  color: var(--text-muted);
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 5%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan, #06b6d4) 12%, transparent);
  transition: background .15s, border-color .15s;
}
.agent-metric-pill:hover {
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan, #06b6d4) 30%, transparent);
}
.agent-metric-pill b {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  transition: color .25s;
}
/* 运行中给指标值加青色，强化"活跃"感 */
.agent-topcard.is-streaming .agent-metric-pill b {
  color: var(--accent-cyan, #06b6d4);
}
.agent-topcard-metric-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.1;
  transition: color .25s;
}
.agent-topcard-metric-label {
  font-size: 9px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .3px;
}
/* P4 自进化记忆健康度条：紧凑横向指标，与 stats 行同卡但独立分组 */
.agent-topcard-evolution {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding: 6px 10px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 5%, transparent);
  font-size: 11px;
  flex-wrap: wrap;
}
.agent-evolution-label {
  font-weight: 700;
  color: var(--accent-cyan);
  letter-spacing: .5px;
  flex-shrink: 0;
}
.agent-evolution-stat {
  display: inline-flex;
  align-items: baseline;
  gap: 2px;
}
.agent-evolution-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}
.agent-evolution-unit {
  font-size: 10px;
  color: var(--text-muted);
}
.agent-evolution-divider {
  width: 1px;
  height: 12px;
  background: var(--border-color);
  flex-shrink: 0;
}
.agent-evolution-time {
  font-size: 10px;
  color: var(--text-muted);
  margin-left: auto;
  white-space: nowrap;
}
.agent-status-led {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}
.agent-status-led.ok { background: #22c55e; box-shadow: 0 0 4px rgba(34,197,94,.5); }
.agent-status-led.warn { background: #f59e0b; }
.agent-status-led.run { background: #3b82f6; animation: agent-led-pulse 1.2s ease-in-out infinite; }
.agent-status-led.idle { background: var(--text-muted); }
@keyframes agent-led-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .4; }
}

.agent-tabs {
  flex-shrink: 0;
  display: flex;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-base, var(--bg-secondary));
  padding: 0 4px;
}
.agent-tab {
  flex: 1 1 0;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  padding: 10px 4px 8px;
  cursor: pointer;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: all .15s;
  position: relative;
}
.agent-tab:hover { color: var(--text-secondary); }
.agent-tab.is-active {
  color: var(--text-primary);
  border-bottom-color: var(--accent, #3b82f6);
  font-weight: 600;
}
.agent-tab-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}
.agent-tab-icon svg {
  width: 14px;
  height: 14px;
  display: block;
}
.agent-tab-empty-icon svg {
  width: 28px;
  height: 28px;
  display: block;
  margin: 0 auto 8px;
}
.agent-tab-label {
  font-size: 11px;
}
.agent-tab-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 14px;
  height: 14px;
  padding: 0 4px;
  border-radius: 7px;
  background: var(--accent, #3b82f6);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  margin-left: 2px;
}

.agent-tab-panes {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 12px 14px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 0;
}
.agent-tab-pane {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.agent-tab-empty {
  text-align: center;
  padding: 32px 16px;
  color: var(--text-muted);
}
.agent-tab-empty-icon {
  font-size: 28px;
  margin-bottom: 8px;
}
.agent-tab-empty-text {
  font-size: 12px;
  line-height: 1.6;
}

/* 恢复 .agent-section 基础样式（之前被 .agent-panel 的 gap 接管） */
.agent-section { display: flex; flex-direction: column; gap: 8px; }
.agent-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.agent-section-head h3 {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}
.agent-live-dot {
  font-size: 10px;
  color: var(--accent-cyan);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.agent-live-dot::before {
  content: '';
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--accent-cyan);
  animation: agentPulse 1.2s ease-in-out infinite;
}
@keyframes agentPulse { 0%,100% { opacity: .3; } 50% { opacity: 1; } }
.agent-badge {
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--accent-rose, #f87171);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.agent-badge-tool {
  background: rgba(6, 182, 212, .18);
  color: var(--accent-cyan, #06b6d4);
}

.agent-capabilities {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 10px 12px;
}

.agent-capability-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border: 1px solid var(--border-color);
  border-radius: 12px;
  background: var(--bg-card);
  font-size: 11px;
  color: var(--text-primary);
  cursor: pointer;
  user-select: none;
  transition: border-color .15s, background .15s, transform .1s;
}

.agent-capability-chip:hover {
  border-color: var(--accent-cyan, #06b6d4);
  background: rgba(6, 182, 212, .06);
}

.agent-capability-chip:active {
  transform: scale(0.97);
  border-color: var(--accent-cyan, #06b6d4);
  background: rgba(6, 182, 212, .1);
}

.agent-capability-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  color: var(--accent-cyan, #06b6d4);
}
.agent-capability-icon svg {
  width: 14px;
  height: 14px;
  display: block;
}

/* 小尺寸 SVG 图标容器：用于上下文召回等需要行内嵌入 SVG 的位置 */
.icon-sm {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  vertical-align: middle;
  flex-shrink: 0;
}
.icon-sm svg {
  width: 14px;
  height: 14px;
  display: block;
}

.agent-capability-name {
  font-weight: 500;
}

.agent-capabilities-hint {
  flex-basis: 100%;
  margin: 6px 0 0;
  font-size: 10px;
  color: var(--text-muted);
  line-height: 1.4;
  font-style: italic;
}

/* P5 Skills 菜单：输入框左上角 skill 按钮 + 弹出可滚动菜单 */
.chat-skill-wrap {
  position: relative;
  flex-shrink: 0;
}
.chat-skill-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--surface-workbench-control);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  transition: color .15s, border-color .15s, background .15s;
  white-space: nowrap;
}
.chat-skill-btn:hover:not(:disabled) {
  color: var(--text-primary);
  border-color: var(--border-active);
}
.chat-skill-btn.active {
  color: var(--accent-cyan);
  border-color: color-mix(in srgb, var(--accent-cyan, #06b6d4) 45%, var(--border-color));
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 10%, transparent);
}
.chat-skill-btn.open {
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}
.chat-skill-btn:disabled {
  opacity: .5;
  cursor: not-allowed;
}
.chat-skill-btn svg {
  width: 14px;
  height: 14px;
}
.chat-skill-badge {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-cyan);
  flex-shrink: 0;
}
.chat-skill-caret {
  display: inline-flex;
  align-items: center;
  margin-left: 2px;
}
.chat-skill-caret svg {
  width: 10px;
  height: 10px;
}
/* 弹出菜单：portal 渲染到 body，fixed 定位由 inline style 控制 */
.chat-skill-menu {
  min-width: 300px;
  max-width: 380px;
  max-height: 420px;
  overflow-y: auto;
  background: var(--bg-primary, #1a1a2e);
  border: 1px solid var(--border-active, #444);
  border-radius: 10px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, .55);
  z-index: 9999;
  padding: 6px;
  opacity: 1;
}
.chat-skill-menu-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 6px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 4px;
}
.chat-skill-menu-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}
.chat-skill-menu-refresh {
  padding: 2px 6px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  transition: color .15s, border-color .15s;
}
.chat-skill-menu-refresh:hover {
  color: var(--accent-cyan);
  border-color: var(--border-active);
}
.chat-skill-menu-refresh svg {
  width: 12px;
  height: 12px;
}
.chat-skill-group {
  margin-bottom: 6px;
}
.chat-skill-group-label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 2px;
}
.chat-skill-group-tag {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 8px;
  border-radius: 999px;
  letter-spacing: .3px;
}
.chat-skill-source-builtin {
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 15%, transparent);
  color: var(--accent-cyan);
  border: 1px solid color-mix(in srgb, var(--accent-cyan, #06b6d4) 35%, var(--border-color));
}
.chat-skill-source-work {
  background: color-mix(in srgb, var(--accent-green, #10b981) 15%, transparent);
  color: var(--accent-green, #10b981);
  border: 1px solid color-mix(in srgb, var(--accent-green, #10b981) 35%, var(--border-color));
}
.chat-skill-source-user {
  background: color-mix(in srgb, var(--accent-purple, #8b5cf6) 15%, transparent);
  color: var(--accent-purple, #8b5cf6);
  border: 1px solid color-mix(in srgb, var(--accent-purple, #8b5cf6) 35%, var(--border-color));
}
.chat-skill-group-count {
  font-size: 10px;
  color: var(--text-muted);
}
.chat-skill-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 100%;
  text-align: left;
  padding: 6px 8px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
  transition: background .12s, border-color .12s;
}
.chat-skill-item:hover {
  background: var(--surface-workbench-control);
  border-color: var(--border-color);
}
.chat-skill-item.selected {
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan, #06b6d4) 40%, var(--border-color));
}
.chat-skill-item-title {
  font-size: 12px;
  font-weight: 600;
}
.chat-skill-item-desc {
  font-size: 10px;
  color: var(--text-muted);
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-skill-item-triggers {
  font-size: 9px;
  color: var(--text-muted);
  font-family: var(--font-mono, monospace);
}
.chat-skill-empty {
  padding: 12px 8px;
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  line-height: 1.5;
}
.chat-skill-empty code {
  font-size: 10px;
  padding: 1px 4px;
  border-radius: 3px;
  background: var(--surface-workbench-control);
}
.chat-skill-error {
  padding: 8px;
  font-size: 11px;
  color: var(--accent-red, #ef4444);
  text-align: center;
}

/* ============================================================
 * SkillsPanel - 右栏技能管理面板（嵌入 AgentPanel 的 skills tab）
 * 视图：list / detail / edit / new
 * ============================================================ */

.agent-tab-pane-skills {
  padding: 0 !important;
  gap: 0 !important;
}

.skills-panel-list,
.skills-panel-detail,
.skills-panel-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
  height: 100%;
}

/* ---------- 顶部工具条 ---------- */
.skills-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 0 8px;
  border-bottom: 1px solid var(--border-color);
}
.skills-search {
  flex: 1 1 auto;
  position: relative;
  display: flex;
  align-items: center;
}
.skills-search-icon {
  position: absolute;
  left: 8px;
  color: var(--text-muted);
  pointer-events: none;
  display: inline-flex;
}
.skills-search-icon svg { width: 13px; height: 13px; }
.skills-search-input {
  flex: 1 1 auto;
  width: 100%;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 12px;
  padding: 6px 28px 6px 26px;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.skills-search-input:focus {
  border-color: var(--accent, #3b82f6);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent, #3b82f6) 20%, transparent);
}
.skills-search-clear {
  position: absolute;
  right: 4px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px;
  border-radius: 4px;
  display: inline-flex;
}
.skills-search-clear:hover { color: var(--text-primary); background: var(--surface-hover, rgba(255,255,255,.05)); }
.skills-search-clear svg { width: 12px; height: 12px; }

.skills-new-btn,
.skills-refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-primary);
  font-size: 11px;
  font-weight: 600;
  padding: 6px 10px;
  cursor: pointer;
  transition: all .15s;
  white-space: nowrap;
}
.skills-new-btn:hover,
.skills-refresh-btn:hover {
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}
.skills-new-btn:disabled,
.skills-refresh-btn:disabled {
  opacity: .5;
  cursor: not-allowed;
}
.skills-new-btn svg,
.skills-refresh-btn svg { width: 13px; height: 13px; }

/* ---------- 过滤标签行 ---------- */
.skills-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 2px 0 4px;
}
.skills-filter-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  cursor: pointer;
  transition: all .12s;
}
.skills-filter-pill:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}
.skills-filter-pill.active {
  background: color-mix(in srgb, var(--accent, #3b82f6) 12%, transparent);
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}
.skills-filter-pill.active.chat-skill-source-builtin {
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 12%, transparent);
  border-color: var(--accent-cyan, #06b6d4);
  color: var(--accent-cyan, #06b6d4);
}
.skills-filter-pill.active.chat-skill-source-work {
  background: color-mix(in srgb, var(--accent-green, #10b981) 12%, transparent);
  border-color: var(--accent-green, #10b981);
  color: var(--accent-green, #10b981);
}
.skills-filter-pill.active.chat-skill-source-user {
  background: color-mix(in srgb, var(--accent-purple, #8b5cf6) 12%, transparent);
  border-color: var(--accent-purple, #8b5cf6);
  color: var(--accent-purple, #8b5cf6);
}
.skills-filter-count {
  font-size: 9px;
  opacity: .8;
  padding: 0 4px;
  background: color-mix(in srgb, currentColor 18%, transparent);
  border-radius: 6px;
  min-width: 14px;
  text-align: center;
}

/* ---------- 列表区 ---------- */
.skills-list {
  flex: 1 1 auto;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  padding-right: 2px;
}
.skills-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.skills-group-label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0 4px;
}
.skills-group-count {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 600;
}
.skills-group-desc {
  font-size: 10px;
  color: var(--text-muted);
  margin-left: auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 140px;
}
.skills-group-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.skills-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 100%;
  text-align: left;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 8px 10px;
  cursor: pointer;
  color: var(--text-primary);
  transition: all .12s;
}
.skills-card:hover {
  border-color: var(--accent, #3b82f6);
  background: color-mix(in srgb, var(--accent, #3b82f6) 6%, var(--surface-workbench-control, var(--bg-secondary)));
}
.skills-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.skills-card-title {
  font-size: 12px;
  font-weight: 600;
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.skills-card-arrow {
  color: var(--text-muted);
  flex-shrink: 0;
  display: inline-flex;
}
.skills-card-arrow svg { width: 12px; height: 12px; }
.skills-card-desc {
  margin: 0;
  font-size: 10px;
  color: var(--text-muted);
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.skills-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 9px;
  color: var(--text-muted);
  font-family: var(--font-mono, monospace);
}
.skills-card-triggers {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1 1 auto;
}
.skills-card-tools {
  flex-shrink: 0;
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--surface-hover, rgba(255,255,255,.05));
}

.skills-list-empty,
.skills-list-error {
  padding: 24px 12px;
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  line-height: 1.6;
}
.skills-list-empty code {
  font-size: 10px;
  padding: 1px 4px;
  border-radius: 3px;
  background: var(--surface-workbench-control);
}
.skills-list-error { color: var(--accent-red, #ef4444); }

/* ---------- detail 视图 ---------- */
.skills-panel-back {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 0 8px;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.skills-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 4px;
  transition: all .12s;
}
.skills-back-btn:hover {
  color: var(--text-primary);
  background: var(--surface-hover, rgba(255,255,255,.05));
}
.skills-back-btn svg { width: 12px; height: 12px; }

.skills-detail-actions {
  display: flex;
  gap: 4px;
}
.skills-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
  padding: 4px 8px;
  cursor: pointer;
  transition: all .12s;
}
.skills-action-btn:hover {
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}
.skills-action-btn.delete:hover {
  border-color: var(--accent-red, #ef4444);
  color: var(--accent-red, #ef4444);
}
.skills-action-btn:disabled {
  opacity: .5;
  cursor: not-allowed;
}
.skills-action-btn svg { width: 11px; height: 11px; }

.skills-detail-head {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 4px 0 10px;
  border-bottom: 1px solid var(--border-color);
  flex-shrink: 0;
}
.skills-detail-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.skills-detail-title {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  flex: 1 1 auto;
}
.skills-detail-desc {
  margin: 0;
  font-size: 11px;
  color: var(--text-secondary);
  line-height: 1.4;
}
.skills-detail-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 4px;
}
.skills-meta-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 10px;
}
.skills-meta-label {
  color: var(--text-muted);
  min-width: 48px;
  font-weight: 600;
  padding-top: 1px;
}
.skills-meta-value {
  color: var(--text-primary);
  word-break: break-all;
}
.skills-meta-value code {
  font-family: var(--font-mono, monospace);
  font-size: 10px;
  padding: 1px 5px;
  border-radius: 3px;
  background: var(--surface-workbench-control);
}
.skills-meta-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  flex: 1 1 auto;
}
.skills-meta-tag {
  font-size: 9px;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-family: var(--font-mono, monospace);
}
.skills-meta-tag.tool {
  background: color-mix(in srgb, var(--accent-cyan, #06b6d4) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan, #06b6d4) 30%, var(--border-color));
  color: var(--accent-cyan, #06b6d4);
}
.skills-readonly-hint {
  font-size: 10px;
  color: var(--text-muted);
  padding: 4px 8px;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border-radius: 4px;
  border-left: 2px solid var(--text-muted);
  margin-top: 4px;
}

.skills-detail-body {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
  padding: 8px 0;
}
.skills-md-pre {
  font-family: var(--font-mono, 'SF Mono', Consolas, Monaco, monospace);
  font-size: 11px;
  line-height: 1.55;
  color: var(--text-primary);
  white-space: pre-wrap;
  word-break: break-word;
  margin: 0;
  padding: 8px 10px;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: 6px;
}

/* ---------- edit / new 表单视图 ---------- */
.skills-form-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}
.skills-form-body {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-right: 2px;
}
.skills-form-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.skills-form-row.two-col {
  flex-direction: row;
  gap: 8px;
}
.skills-form-row.two-col > div {
  flex: 1 1 50%;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.skills-form-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-secondary);
  letter-spacing: .3px;
}
.skills-form-required {
  color: var(--accent-red, #ef4444);
}
.skills-form-hint {
  font-size: 9px;
  color: var(--text-muted);
}
.skills-form-input,
.skills-form-select,
.skills-form-textarea {
  width: 100%;
  background: var(--surface-workbench-control, var(--bg-secondary));
  border: 1px solid var(--border-color);
  border-radius: 5px;
  color: var(--text-primary);
  font-size: 11px;
  padding: 6px 8px;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
  font-family: inherit;
}
.skills-form-input:focus,
.skills-form-select:focus,
.skills-form-textarea:focus {
  border-color: var(--accent, #3b82f6);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent, #3b82f6) 18%, transparent);
}
.skills-form-input:disabled,
.skills-form-select:disabled {
  opacity: .6;
  cursor: not-allowed;
}
.skills-form-textarea {
  resize: vertical;
  min-height: 180px;
  font-family: var(--font-mono, 'SF Mono', Consolas, Monaco, monospace);
  line-height: 1.5;
}
/* 源码模式切换按钮 */
.skills-mode-toggle {
  margin-left: auto;
  padding: 3px 8px;
  font-size: 10px;
  font-weight: 600;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: var(--bg-secondary, transparent);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all .12s;
  white-space: nowrap;
}
.skills-mode-toggle:hover {
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}
.skills-mode-toggle.is-raw {
  background: color-mix(in srgb, var(--accent, #3b82f6) 14%, transparent);
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}
/* 源码模式 textarea：更大、等宽字体、深色背景 */
.skills-raw-textarea {
  width: 100%;
  resize: vertical;
  min-height: 360px;
  padding: 10px 12px;
  font-family: var(--font-mono, 'SF Mono', Consolas, Monaco, monospace);
  font-size: 11px;
  line-height: 1.6;
  background: var(--bg-tertiary, var(--bg-secondary, #0f0f1a));
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  outline: none;
  tab-size: 2;
  white-space: pre;
  overflow-x: auto;
}
.skills-raw-textarea:focus {
  border-color: var(--accent, #3b82f6);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent, #3b82f6) 18%, transparent);
}
.skills-raw-editor-wrap {
  flex: 1;
}
.skills-form-error {
  font-size: 10px;
  color: var(--accent-red, #ef4444);
  padding: 6px 8px;
  background: color-mix(in srgb, var(--accent-red, #ef4444) 8%, transparent);
  border-radius: 4px;
  border-left: 2px solid var(--accent-red, #ef4444);
  flex-shrink: 0;
}
.skills-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--border-color);
  flex-shrink: 0;
}
.skills-form-cancel,
.skills-form-submit {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 600;
  padding: 6px 14px;
  cursor: pointer;
  transition: all .12s;
  border: 1px solid var(--border-color);
}
.skills-form-cancel {
  background: transparent;
  color: var(--text-secondary);
}
.skills-form-cancel:hover {
  background: var(--surface-hover, rgba(255,255,255,.05));
  color: var(--text-primary);
}
.skills-form-submit {
  background: var(--accent, #3b82f6);
  color: #fff;
  border-color: var(--accent, #3b82f6);
}
.skills-form-submit:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent, #3b82f6) 88%, #000);
}
.skills-form-submit:disabled,
.skills-form-cancel:disabled {
  opacity: .5;
  cursor: not-allowed;
}

.persona-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, .45);
  z-index: 9999;
  display: flex;
  justify-content: flex-end;
  animation: persona-overlay-in .18s ease-out;
}

@keyframes persona-overlay-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.persona-drawer {
  width: min(480px, 100vw);
  height: 100vh;
  background: var(--bg-base, #fff);
  border-left: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  box-shadow: -8px 0 24px rgba(0, 0, 0, .12);
  animation: persona-slide-in .22s cubic-bezier(.2, .8, .2, 1);
}

@keyframes persona-slide-in {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.persona-drawer-header {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.persona-drawer-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.persona-drawer-icon {
  font-size: 18px;
}

.persona-drawer-close {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  width: 30px;
  height: 30px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all .15s;
  padding: 0;
}
.persona-drawer-close svg {
  width: 16px;
  height: 16px;
  display: block;
}
.persona-drawer-close:hover {
  background: var(--bg-elevated, rgba(0,0,0,.06));
  color: var(--text-primary);
}

.persona-drawer-content {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px 18px;
}

.persona-drawer-footer {
  padding: 12px 18px;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: flex-start;
  gap: 8px;
  flex-shrink: 0;
  background: var(--bg-base, #fff);
}

.persona-drawer-btn {
  padding: 6px 16px;
  border-radius: 4px;
  font-size: 12px;
  cursor: pointer;
  font-weight: 500;
  border: 1px solid var(--border-color);
  transition: all .15s;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.persona-drawer-btn-cancel {
  background: transparent;
  color: var(--text-secondary);
}
.persona-drawer-btn-cancel:hover {
  background: var(--bg-elevated, rgba(0,0,0,.04));
}

.persona-drawer-btn-save {
  background: var(--accent, #3b82f6);
  color: #fff;
  border-color: var(--accent, #3b82f6);
}
.persona-drawer-btn-save:hover {
  opacity: .9;
}

/* PersonaEditor 内容 */
.persona-editor {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.persona-editor-header {
  display: none; /* drawer 已有 header，这里不重复 */
}

.persona-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  background: var(--bg-elevated, rgba(0,0,0,.02));
  border: 1px solid var(--border-color);
  border-radius: 8px;
}

.persona-section-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  padding-bottom: 4px;
  border-bottom: 1px solid var(--border-color);
}

.persona-section-icon {
  font-size: 14px;
}

.persona-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.persona-field label {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.persona-field-label-with-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.persona-hint {
  font-size: 10px;
  font-weight: 400;
  color: var(--text-muted);
  font-style: italic;
}

.persona-input {
  width: 100%;
  padding: 6px 10px;
  background: var(--bg-input, var(--bg-base, #fff));
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 12px;
  box-sizing: border-box;
}
.persona-input:focus {
  outline: none;
  border-color: var(--accent, #3b82f6);
}

.persona-textarea {
  width: 100%;
  padding: 6px 10px;
  background: var(--bg-input, var(--bg-base, #fff));
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 12px;
  resize: vertical;
  font-family: inherit;
  box-sizing: border-box;
  line-height: 1.5;
}
.persona-textarea:focus {
  outline: none;
  border-color: var(--accent, #3b82f6);
}

.persona-voice-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

@media (max-width: 480px) {
  .persona-voice-grid {
    grid-template-columns: 1fr;
  }
  .persona-drawer {
    width: 100vw;
  }
}

/* chat-header 角色设定按钮（在 SiliconStream 智能体 header 中） */
.chat-header-persona-btn {
  position: relative;
}
.chat-header-persona-btn:disabled {
  opacity: .4;
  cursor: not-allowed;
}

.agent-jobs-section {
  /* 复用 .agent-section 基础样式 */
}

.agent-jobs-add-btn {
  margin-left: auto;
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--accent, var(--text-primary));
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 11px;
  cursor: pointer;
  transition: all .15s;
}
.agent-jobs-add-btn:hover {
  background: var(--accent, #3b82f6);
  color: #fff;
  border-color: var(--accent, #3b82f6);
}

.agent-jobs-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  margin-bottom: 8px;
  background: var(--bg-elevated, rgba(0,0,0,.03));
  border: 1px dashed var(--border-color);
  border-radius: 6px;
}

.agent-jobs-form-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.agent-jobs-input {
  flex: 1 1 auto;
  min-width: 120px;
  padding: 6px 10px;
  background: var(--bg-input, var(--bg-base, #fff));
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 12px;
}

.agent-jobs-input:focus {
  outline: none;
  border-color: var(--accent, #3b82f6);
}

.agent-jobs-cron-input {
  font-family: ui-monospace, SFMono-Regular, monospace;
  font-size: 11px;
}

.agent-jobs-preview {
  font-size: 11px;
  color: var(--text-muted);
  background: rgba(0,0,0,.04);
  padding: 3px 8px;
  border-radius: 3px;
  white-space: nowrap;
}

.agent-jobs-preview-error {
  color: #dc2626;
  background: rgba(220, 38, 38, .08);
}

.agent-jobs-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.agent-jobs-preset {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 3px 8px;
  border-radius: 12px;
  font-size: 10px;
  cursor: pointer;
  transition: all .15s;
}
.agent-jobs-preset:hover {
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}
.agent-jobs-preset.is-active {
  background: var(--accent, #3b82f6);
  color: #fff;
  border-color: var(--accent, #3b82f6);
}

.agent-jobs-textarea {
  width: 100%;
  min-height: 60px;
  padding: 6px 10px;
  background: var(--bg-input, var(--bg-base, #fff));
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 12px;
  resize: vertical;
  font-family: inherit;
}
.agent-jobs-textarea:focus {
  outline: none;
  border-color: var(--accent, #3b82f6);
}

.agent-jobs-create-btn {
  align-self: flex-end;
  background: var(--accent, #3b82f6);
  color: #fff;
  border: none;
  padding: 6px 16px;
  border-radius: 4px;
  font-size: 12px;
  cursor: pointer;
  font-weight: 500;
  transition: opacity .15s;
}
.agent-jobs-create-btn:disabled {
  opacity: .5;
  cursor: not-allowed;
}

.agent-jobs-error {
  color: #dc2626;
  font-size: 11px;
  padding: 4px 6px;
  background: rgba(220, 38, 38, .06);
  border-radius: 3px;
}

.agent-jobs-empty {
  padding: 14px 8px;
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  line-height: 1.5;
  background: var(--bg-elevated, rgba(0,0,0,.02));
  border-radius: 4px;
}

.agent-jobs-empty-error {
  color: #dc2626;
  background: rgba(220, 38, 38, .04);
}

.agent-jobs-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.agent-job-item {
  padding: 8px 10px;
  background: var(--bg-elevated, rgba(0,0,0,.02));
  border: 1px solid var(--border-color);
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  position: relative;
  transition: opacity .15s;
}

.agent-job-item.is-disabled {
  opacity: .5;
}

.agent-job-item.is-other-agent {
  border-left: 2px solid var(--text-muted);
}

.agent-job-item-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.agent-job-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1 1 auto;
}

.agent-job-toggle {
  position: relative;
  display: inline-block;
  width: 28px;
  height: 16px;
  flex-shrink: 0;
  cursor: pointer;
}
.agent-job-toggle input {
  opacity: 0;
  width: 0;
  height: 0;
}
.agent-job-toggle-slider {
  position: absolute;
  inset: 0;
  background: var(--border-color);
  border-radius: 16px;
  transition: background .15s;
}
.agent-job-toggle-slider::before {
  content: '';
  position: absolute;
  width: 12px;
  height: 12px;
  left: 2px;
  top: 2px;
  background: #fff;
  border-radius: 50%;
  transition: transform .15s;
}
