.workspace-tree-dir { color: var(--text-secondary); font-weight: 600; }
/* 工作空间树视图工具栏：全部展开 / 全部折叠 */
.workspace-tree-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 8px;
  border-bottom: 1px solid var(--border-subtle, rgba(255,255,255,.04));
  margin-bottom: 4px;
}
.workspace-tree-tool-btn {
  flex: 0 0 auto;
  padding: 3px 10px;
  border: 1px solid var(--border-subtle, rgba(255,255,255,.08));
  border-radius: 4px;
  background: var(--bg-card, rgba(255,255,255,.03));
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.4;
  cursor: pointer;
  transition: all .15s;
  user-select: none;
}
.workspace-tree-tool-btn:hover {
  background: var(--accent-cyan-softer, rgba(34,211,238,.12));
  color: var(--accent-cyan, #22d3ee);
  border-color: var(--accent-cyan, #22d3ee);
}
.workspace-tree-tool-btn:active { transform: translateY(1px); }
.workspace-tree-tool-btn:disabled {
  opacity: .4;
  cursor: not-allowed;
  transform: none;
}
.workspace-tree-file:hover { background: var(--bg-card); }
.workspace-tree-file.selected { background: var(--accent-cyan-softer); color: var(--accent-cyan); }
.workspace-tree-arrow { width: 12px; flex-shrink: 0; font-size: 10px; color: var(--text-muted); }
.workspace-tree-file-icon { flex-shrink: 0; font-size: 11px; }
.workspace-tree-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.workspace-bottom {
  flex-shrink: 0;
  padding: 10px;
  border-top: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.workspace-selected-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}
.workspace-action-btn {
  padding: 7px 10px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-card);
  color: var(--text-primary);
  font-size: 12px;
  cursor: pointer;
}
.workspace-action-btn.primary {
  background: var(--accent-cyan);
  border-color: var(--accent-cyan);
  color: var(--bg-primary, #fff);
  font-weight: 600;
}
.workspace-action-btn.primary:hover { opacity: .85; }
.workspace-action-btn:disabled { opacity: .4; cursor: not-allowed; }
.workspace-link-btn {
  border: none;
  background: transparent;
  color: var(--accent-cyan);
  font-size: 11px;
  cursor: pointer;
  padding: 2px;
}
.intelligence-feed-panel {
  width: min(980px, calc(100% - 32px));
  margin: 18px auto 14px;
  padding: 18px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: color-mix(in srgb, var(--card-bg) 92%, transparent);
  box-shadow: var(--shadow-sm);
}

.intelligence-feed-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.intelligence-feed-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

.intelligence-feed-head h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: 20px;
  line-height: 1.25;
  letter-spacing: 0;
}

.intelligence-feed-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-muted);
  font-size: 13px;
  white-space: nowrap;
}

.intelligence-feed-actions button {
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: var(--surface-bg);
  color: var(--text-primary);
  font-size: 13px;
  cursor: pointer;
}

.intelligence-feed-actions button:disabled {
  cursor: wait;
  opacity: .65;
}

.intelligence-hero-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 160px;
  gap: 16px;
  padding: 20px 22px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  background: linear-gradient(135deg, var(--surface-bg) 0%, rgba(59,130,246,.04) 100%);
  position: relative;
  overflow: hidden;
}
.intelligence-hero-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(180deg, var(--accent-color, #3b82f6) 0%, rgba(59,130,246,.3) 100%);
}
.intelligence-hero-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.intelligence-hero-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}
.intelligence-hero-category {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  border-radius: 10px;
  background: rgba(59, 130, 246, .12);
  color: #3b82f6;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .5px;
}
.intelligence-hero-score {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 8px;
  background: var(--accent-color, #3b82f6);
  color: #fff;
  font-size: 11px;
}
.intelligence-hero-score strong {
  font-size: 14px;
  font-weight: 800;
}
.intelligence-hero-score em {
  font-style: normal;
  opacity: .85;
  font-size: 10px;
}
.intelligence-hero-title {
  margin: 0;
  color: var(--text-primary);
  font-size: 20px;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -.01em;
}
.intelligence-hero-summary {
  margin: 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.65;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}
.intelligence-hero-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 4px;
  color: var(--text-muted);
  font-size: 12px;
}
.intelligence-hero-source {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.intelligence-hero-link {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 10px;
  border-radius: 6px;
  background: var(--accent-color, #3b82f6);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  text-decoration: none;
  flex-shrink: 0;
  transition: all .15s;
}
.intelligence-hero-link:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
}

/* 右侧指标条 */
.intelligence-hero-metrics {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: stretch;
  justify-content: center;
}
.intelligence-hero-metric {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--surface-bg);
  border: 1px solid var(--border-color);
}
.intelligence-hero-metric-label {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 600;
}
.intelligence-hero-metric-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}
.intelligence-hero-metric-primary {
  background: linear-gradient(135deg, rgba(59,130,246,.1), rgba(168,85,247,.08));
  border-color: rgba(59,130,246,.3);
}
.intelligence-hero-metric-primary .intelligence-hero-metric-value {
  color: #3b82f6;
  font-size: 22px;
}

/* 响应式：窄屏堆叠 */
@media (max-width: 720px) {
  .intelligence-hero-card {
    grid-template-columns: 1fr;
  }
  .intelligence-hero-metrics {
    flex-direction: row;
  }
  .intelligence-hero-metric {
    flex: 1;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
  }
}

.intelligence-alert-strip {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 12px;
}

.intelligence-alert {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 32px;
  gap: 3px 8px;
  align-items: center;
  min-height: 58px;
  padding: 8px 9px;
  border: 1px solid var(--border-color);
  border-left: 3px solid var(--accent-cyan);
  border-radius: 8px;
  background: var(--surface-bg);
}

.intelligence-alert span {
  grid-column: 1 / -1;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 750;
}

.intelligence-alert strong {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.intelligence-alert em {
  display: grid;
  place-items: center;
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  color: var(--accent-cyan);
  font-size: 11px;
  font-style: normal;
  font-weight: 850;
}

@media (max-width: 860px) {
  .intelligence-alert-strip { grid-template-columns: 1fr; }
}

.intelligence-feed-error,
.intelligence-feed-empty {
  display: flex;
  gap: 10px;
  align-items: center;
  min-height: 56px;
  padding: 12px 14px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--surface-bg);
  color: var(--text-secondary);
}

.intelligence-feed-error strong {
  color: var(--text-primary);
}

.intelligence-feed-skeleton {
  display: grid;
  gap: 10px;
}

.intelligence-feed-skeleton span {
  height: 56px;
  border-radius: 8px;
  background: linear-gradient(90deg, var(--surface-bg), color-mix(in srgb, var(--surface-bg) 70%, var(--text-muted) 12%), var(--surface-bg));
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.4s infinite linear;
}

@media (max-width: 900px) {
  .intelligence-feed-panel {
    width: calc(100% - 20px);
    margin-top: 10px;
    padding: 14px;
  }

  .intelligence-feed-head {
    align-items: flex-start;
    flex-direction: column;
  }

}

.creative-workspace {
  display: grid;
  gap: 16px;
  padding: 18px;
  border: var(--panel-border);
  border-radius: var(--radius-card);
  background: var(--surface-workbench, var(--surface-card));
  box-shadow: var(--shadow-card);
}

.creative-workspace-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.creative-workspace-head span {
  display: block;
  margin-bottom: 4px;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

.creative-workspace-head h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: 22px;
  line-height: 1.2;
}

.creative-workspace-stats {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.creative-workspace-stats strong {
  min-width: 74px;
  padding: 9px 10px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-control, var(--surface-bg));
  color: var(--text-primary);
  font-size: 18px;
  line-height: 1;
  text-align: center;
}

.creative-workspace-stats strong span {
  margin: 5px 0 0;
  color: var(--text-muted);
  font-size: 11px;
  text-transform: none;
}

.creative-sync-button {
  min-width: 74px;
  min-height: 50px;
  padding: 8px 10px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-workbench-action, var(--surface-card));
  color: var(--text-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.creative-sync-button:hover:not(:disabled) {
  border-color: var(--accent-cyan-border, var(--border-active));
  color: var(--text-primary);
}

.creative-sync-button:disabled {
  opacity: .5;
  cursor: not-allowed;
}

.creative-sync-alert {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 9px 11px;
  border: 1px solid color-mix(in srgb, var(--accent-amber, #f59e0b) 45%, var(--border-color));
  border-radius: 7px;
  background: color-mix(in srgb, var(--accent-amber, #f59e0b) 12%, transparent);
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}

.creative-sync-alert span {
  flex: 1;
  min-width: 180px;
}

.creative-sync-alert button {
  min-height: 30px;
  padding: 5px 9px;
  border: var(--panel-border);
  border-radius: 6px;
  background: var(--surface-workbench-action, var(--surface-card));
  color: var(--text-secondary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.creative-sync-alert.error {
  border-color: color-mix(in srgb, var(--accent-rose, #f87171) 45%, var(--border-color));
  background: color-mix(in srgb, var(--accent-rose, #f87171) 12%, transparent);
}

.creative-workspace-grid {
  display: grid;
  grid-template-columns: minmax(220px, .9fr) minmax(280px, 1.1fr) minmax(260px, 1fr);
  gap: 14px;
  align-items: stretch;
}

.creative-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 320px;
  gap: 12px;
  padding: 14px;
  border: var(--panel-border);
  border-radius: 8px;
  background: var(--surface-bg, rgba(255, 255, 255, .02));
}

.creative-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 32px;
}

.creative-panel-head h3 {
  margin: 0;
  color: var(--text-primary);
  font-size: 15px;
  line-height: 1.3;
}

.creative-panel-head button,
.creative-export-row button,
.creative-primary {
  min-height: 34px;
  padding: 7px 11px;
  border: var(--panel-border);
  border-radius: 7px;
  background: var(--surface-workbench-action, var(--surface-card));
  color: var(--text-secondary);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.creative-panel-head button:hover,
.creative-export-row button:hover {
  border-color: var(--border-active);
  color: var(--text-primary);
}

.creative-panel-head span {
  color: var(--text-muted);
  font-size: 12px;
}

.creative-asset-list {
  display: grid;
  gap: 8px;
  min-height: 0;
}

.creative-asset-list button {
  display: grid;
  gap: 4px;
  width: 100%;
  min-height: 58px;
  padding: 9px 10px;
  border: var(--panel-border);
  border-radius: 7px;
  background: transparent;
  color: var(--text-secondary);
  text-align: left;
  cursor: pointer;
}

.creative-asset-list button.active,
.creative-asset-list button:hover {
  border-color: var(--accent-cyan-border, var(--border-active));
  background: var(--accent-cyan-softer, rgba(34, 211, 238, .08));
}

.creative-asset-list strong {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.creative-asset-list span,
.creative-asset-provenance,
.creative-empty {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.creative-asset-provenance {
  display: grid;
  gap: 4px;
  margin: auto 0 0;
  padding-top: 8px;
  border-top: var(--panel-border);
}

.creative-asset-provenance a {
  overflow-wrap: anywhere;
  color: var(--accent-cyan, #22d3ee);
  text-decoration: none;
}

.creative-asset-provenance a:hover {
  text-decoration: underline;
}

.creative-primary {
  border-color: var(--accent-cyan-border, var(--border-active));
  background: var(--accent-cyan, #22d3ee);
  color: var(--bg-primary, #061018);
  font-weight: 700;
}

.creative-primary:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.creative-document-panel h4 {
  margin: 0;
  color: var(--text-primary);
  font-size: 18px;
  line-height: 1.35;
}

.creative-document-panel p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.7;
  word-break: break-word;
}

.creative-document-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

.creative-document-meta span {
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--surface-workbench-control, var(--surface-card));
  color: var(--text-muted);
  font-size: 12px;
}

.creative-export-row {
  display: flex;
  gap: 8px;
  align-items: center;
}

.creative-export-row select {
  min-height: 34px;
  flex: 1;
  min-width: 0;
  padding: 7px 10px;
  border: var(--panel-border);
  border-radius: 7px;
  background: var(--surface-workbench-control, var(--surface-card));
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
}

.creative-version-list {
  display: grid;
  gap: 8px;
}

.creative-version-list button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 8px 10px;
  border: var(--panel-border);
  border-radius: 7px;
  background: var(--surface-workbench-control, var(--surface-card));
  color: var(--text-secondary);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.creative-version-list button:hover {
  border-color: var(--accent-cyan-border, var(--border-active));
  color: var(--text-primary);
}

.creative-version-list strong {
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1;
}

.creative-version-list span {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.creative-proposal-panel textarea {
  min-height: 170px;
  flex: 1;
  padding: 10px;
  border: var(--panel-border);
  border-radius: 7px;
  background: var(--surface-workbench-control, var(--surface-card));
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  line-height: 1.6;
  resize: vertical;
}

.creative-proposal-panel textarea:focus,
.creative-export-row select:focus {
  border-color: var(--accent-cyan-border, var(--border-active));
  outline: none;
}

.creative-citation-error {
  padding: 8px 10px;
  border: 1px solid color-mix(in srgb, var(--accent-rose, #f87171) 45%, var(--border-color));
  border-radius: 7px;
  background: color-mix(in srgb, var(--accent-rose, #f87171) 12%, transparent);
  color: var(--accent-rose, #f87171);
  font-size: 12px;
  line-height: 1.5;
}

@media (max-width: 980px) {
  .creative-workspace-grid {
    grid-template-columns: 1fr;
  }

  .creative-panel {
    min-height: 0;
  }
}

@media (max-width: 640px) {
  .creative-workspace {
    padding: 14px;
  }

  .creative-workspace-head,
  .creative-export-row {
    align-items: stretch;
    flex-direction: column;
  }

  .creative-workspace-stats {
    justify-content: flex-start;
  }
}

/* Phase 2: AI 主动学习闭环 UI */
.profile-pending-suggestions,
.profile-agent-memory {
  margin: 16px 0;
  padding: 20px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  position: relative;
}
.profile-agent-memory::before {
  content: "";
  position: absolute;
  top: 0; left: 16px; right: 16px;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 20%, transparent), transparent);
}
.profile-pending-suggestions .pending-count {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 10px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  color: var(--accent-cyan);
  font-size: 12px;
  font-weight: 600;
  font-family: 'Courier New', monospace;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.pending-suggestions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
  margin-top: 12px;
}
.pending-suggestion-card {
  padding: 14px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  transition: all 0.2s ease;
}
.pending-suggestion-card:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 6%, transparent);
}
.suggestion-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}
.suggestion-type {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}
.suggestion-type.type-track { background: rgba(59,130,246,0.15); color: #60a5fa; }
.suggestion-type.type-boost { background: rgba(234,88,12,0.15); color: #fb923c; }
.suggestion-type.type-mute  { background: rgba(100,116,139,0.15); color: #94a3b8; }
.suggestion-target { font-weight: 600; }
.suggestion-reason {
  font-size: 13px;
  color: var(--text-muted, #94a3b8);
  margin: 8px 0;
}
.suggestion-confidence {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 0;
  font-size: 12px;
}
.confidence-bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: var(--bg-elevated, rgba(255,255,255,0.06));
  overflow: hidden;
}
.confidence-fill {
  height: 100%;
  background: linear-gradient(90deg, #fbbf24, #f59e0b);
  border-radius: 3px;
}
.suggestion-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}
.suggestion-accept-editor {
  padding: 12px;
  border-radius: 8px;
  background: var(--bg-elevated, rgba(255,255,255,0.04));
  border: 1px solid var(--accent-border, rgba(251,191,36,0.3));
}
.editor-title { font-weight: 600; margin-bottom: 8px; }
.editor-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 8px;
}
.editor-field > span { font-size: 12px; color: var(--text-muted, #94a3b8); }
.editor-field input[type="text"] {
  padding: 6px 8px;
  border-radius: 4px;
  border: 1px solid var(--border-color, rgba(255,255,255,0.1));
  background: var(--bg-input, rgba(0,0,0,0.2));
  color: var(--text-primary, #fff);
}
.editor-readonly {
  font-weight: 600;
  padding: 4px 0;
}
.editor-radio-group {
  display: flex;
  gap: 12px;
  margin-top: 4px;
}
.editor-radio-group label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  cursor: pointer;
}
.editor-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}
.profile-empty-state {
  padding: 24px;
  text-align: center;
  color: var(--text-muted, #94a3b8);
  font-size: 14px;
}

/* AgentMemorySection */
.memory-toolbar {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
  flex-wrap: wrap;
  align-items: center;
}
.memory-type-filter {
  padding: 6px 8px;
  border-radius: 4px;
  border: 1px solid var(--border-color, rgba(255,255,255,0.1));
  background: var(--bg-input, rgba(0,0,0,0.2));
  color: var(--text-primary, #fff);
}
.memory-search-form {
  display: flex;
  gap: 4px;
  flex: 1;
  min-width: 200px;
}
.memory-search-input {
  flex: 1;
  padding: 6px 8px;
  border-radius: 4px;
  border: 1px solid var(--border-color, rgba(255,255,255,0.1));
  background: var(--bg-input, rgba(0,0,0,0.2));
  color: var(--text-primary, #fff);
}
.memory-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.memory-item {
  padding: 12px;
  border-radius: 6px;
  background: var(--bg-elevated, rgba(255,255,255,0.03));
  border: 1px solid var(--border-color, rgba(255,255,255,0.06));
}
.memory-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  font-size: 12px;
}
.memory-type-tag {
  padding: 2px 6px;
  border-radius: 3px;
  font-weight: 600;
}
.memory-type-tag.type-user_habit { background: rgba(34,197,94,0.15); color: #4ade80; }
.memory-type-tag.type-user_thought { background: rgba(168,85,247,0.15); color: #c084fc; }
.memory-type-tag.type-user_trait { background: rgba(59,130,246,0.15); color: #60a5fa; }
.memory-type-tag.type-user_need { background: rgba(234,88,12,0.15); color: #fb923c; }
.memory-type-tag.type-agent_insight { background: rgba(251,191,36,0.15); color: #fbbf24; }
.memory-weight, .memory-created {
  color: var(--text-muted, #94a3b8);
}
.memory-delete {
  margin-left: auto;
}
.memory-content {
  font-size: 14px;
  line-height: 1.5;
  margin-bottom: 6px;
}
.memory-expand {
  font-size: 12px;
  padding: 2px 8px;
}
.memory-evidence {
  margin-top: 8px;
  padding: 8px;
  border-radius: 4px;
  background: var(--bg-elevated, rgba(0,0,0,0.15));
  border-left: 3px solid var(--accent-border, rgba(251,191,36,0.3));
}
.evidence-item {
  font-size: 12px;
  margin-bottom: 4px;
}
.evidence-type {
  display: inline-block;
  margin-right: 6px;
  padding: 1px 4px;
  border-radius: 2px;
  background: rgba(255,255,255,0.06);
  font-weight: 600;
}
.memory-error, .memory-loading {
  padding: 16px;
  text-align: center;
  color: var(--text-muted, #94a3b8);
}
.memory-error { color: #f87171; }
.memory-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 12px;
}
.page-indicator { font-size: 13px; color: var(--text-muted, #94a3b8); }

/* 按钮基础样式 */
.btn { cursor: pointer; border: none; border-radius: 4px; padding: 6px 12px; font-size: 13px; transition: opacity 0.15s; }
.btn:hover { opacity: 0.85; }
.btn:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-sm { padding: 4px 10px; font-size: 12px; }
.btn-primary { background: var(--accent-bg, #f59e0b); color: #fff; }
.btn-ghost { background: transparent; color: var(--text-muted, #94a3b8); border: 1px solid var(--border-color, rgba(255,255,255,0.1)); }

/* ============ Phase 3: Persona Summary ============ */
.profile-persona-summary {
  padding: 24px 0;
  border-bottom: 1px solid var(--border-color, rgba(255,255,255,0.08));
}
.profile-persona-summary .section-header {
  margin-bottom: 12px;
}
.profile-persona-summary .section-title {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 4px;
}
.profile-persona-summary .section-desc {
  font-size: 13px;
  color: var(--text-secondary, #888);
  margin: 0;
}
.profile-persona-summary .profile-empty-state {
  padding: 24px;
  text-align: center;
  color: var(--text-muted, #666);
  font-size: 14px;
  background: var(--bg-secondary, rgba(255,255,255,0.03));
  border-radius: 8px;
  margin-top: 12px;
}
.persona-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
  margin-top: 16px;
}
.persona-column h3 {
  font-size: 13px;
  margin: 0 0 12px;
  color: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  font-weight: 600;
  letter-spacing: 0.06em;
  font-family: 'Courier New', monospace;
  display: flex;
  align-items: center;
  gap: 6px;
}
.persona-column h3::before {
  content: "◆";
  font-size: 8px;
  color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.persona-column ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
.persona-item {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--accent-cyan) 5%, transparent);
  font-size: 13px;
}
.persona-content {
  flex: 1;
  margin-right: 12px;
  line-height: 1.5;
}
.persona-weight {
  color: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  font-size: 12px;
  font-family: 'Courier New', monospace;
}

/* ============ Phase 3: Snapshot History ============ */
.profile-snapshot-history {
  padding: 24px 0;
}
.profile-snapshot-history .section-header {
  margin-bottom: 12px;
}
.profile-snapshot-history .section-title {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 4px;
}
.profile-snapshot-history .section-desc {
  font-size: 13px;
  color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  margin: 0;
  font-family: 'Courier New', monospace;
}
.profile-snapshot-history .profile-empty-state {
  padding: 24px;
  text-align: center;
  color: var(--text-muted, #666);
  font-size: 14px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  border: 1px dashed color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 8px;
  margin-top: 12px;
}
.snapshot-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 16px;
}
.snapshot-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  background: var(--bg-secondary, rgba(255,255,255,0.03));
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}
.snapshot-item:hover {
  background: var(--bg-tertiary, rgba(255,255,255,0.06));
}
.snapshot-item:focus-visible {
  outline: 2px solid var(--accent-cyan, #22d3ee);
  outline-offset: 2px;
}
.snapshot-date {
  font-weight: 600;
  min-width: 100px;
}
.snapshot-status {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  white-space: nowrap;
}
.status-merged { background: rgba(34,197,94,0.15); color: #22c55e; }
.status-ai_failed { background: rgba(239,68,68,0.15); color: #ef4444; }
.status-validation_failed { background: rgba(245,158,11,0.15); color: #f59e0b; }
.status-not_requested { background: rgba(100,116,139,0.15); color: #64748b; }
.status-unknown { background: rgba(100,116,139,0.15); color: #64748b; }
.snapshot-oneliner {
  flex: 1;
  color: var(--text-secondary, #888);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.snapshot-updated {
  font-size: 11px;
  color: var(--text-muted, #666);
  white-space: nowrap;
}
.snapshot-detail {
  margin-top: 16px;
  padding: 16px;
  background: var(--bg-secondary, rgba(0,0,0,0.2));
  border-radius: 8px;
}
.snapshot-detail-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}
.snapshot-detail-header h3 {
  margin: 0;
  font-size: 16px;
}
.snapshot-detail-close {
  background: transparent;
  border: 1px solid var(--border-color, rgba(255,255,255,0.1));
  color: var(--text-secondary, #888);
  padding: 4px 12px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
}
.snapshot-detail-close:hover {
  background: var(--bg-tertiary, rgba(255,255,255,0.06));
}
.snapshot-detail-oneliner {
  font-size: 14px;
  color: var(--text-primary, #fff);
  margin: 0 0 12px;
  line-height: 1.6;
}
.snapshot-detail-items {
  list-style: none;
  padding: 0;
  margin: 0 0 12px;
}
.snapshot-detail-items li {
  padding: 6px 0;
  border-bottom: 1px solid var(--border-color, rgba(255,255,255,0.05));
  font-size: 13px;
  display: flex;
  gap: 8px;
  align-items: center;
}
.snapshot-detail-title {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.snapshot-detail-score {
  color: var(--accent-cyan, #22d3ee);
  font-size: 12px;
  font-weight: 600;
}
.snapshot-detail-label {
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 3px;
  background: rgba(34,211,238,0.15);
  color: var(--accent-cyan, #22d3ee);
}
.snapshot-raw {
  margin-top: 12px;
}
.snapshot-raw summary {
  cursor: pointer;
  color: var(--text-muted, #666);
  font-size: 12px;
  padding: 4px 0;
}
.snapshot-raw pre {
  font-size: 12px;
  overflow-x: auto;
  max-height: 400px;
  overflow-y: auto;
  background: var(--bg-tertiary, rgba(0,0,0,0.3));
  padding: 12px;
  border-radius: 6px;
  margin-top: 8px;
}

/* ============ Phase 6: Profile Dashboard Redesign ============ */

/* 顶部 Tab 切换器（保留 Phase 4 但调整样式） */
/* ===== 科幻 HUD 标签页 ===== */
.profile-tabs {
  display: flex;
  gap: 2px;
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  border-radius: 6px;
  padding: 3px;
  margin: 0 0 24px;
  width: fit-content;
  position: relative;
}
.profile-tabs::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 7px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 20%, transparent), transparent 40%, transparent 60%, color-mix(in srgb, var(--accent-cyan) 15%, transparent));
  pointer-events: none;
  z-index: 0;
}
.profile-tab {
  padding: 6px 18px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--text-muted, #8B94A0);
  cursor: pointer;
  transition: all 0.25s ease;
  border: 1px solid transparent;
  background: transparent;
  font-family: inherit;
  position: relative;
  z-index: 1;
}
.profile-tab:hover {
  color: color-mix(in srgb, var(--accent-cyan) 80%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 6%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}
.profile-tab.active {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 12%, transparent), color-mix(in srgb, var(--accent-cyan) 6%, transparent));
  color: var(--accent-cyan);
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 15%, transparent), inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  text-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}

/* 双栏布局 — 赛博网格 */
.profile-dashboard-v2 .dashboard-layout {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 24px;
  align-items: start;
}
@media (max-width: 960px) {
  .profile-dashboard-v2 .dashboard-layout { grid-template-columns: 1fr; }
}
.dashboard-content {
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-width: 0;
}
.dashboard-row-2 {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 18px;
}
@media (max-width: 960px) {
  .dashboard-row-2 { grid-template-columns: 1fr; }
}

/* ===== 时间轴 — HUD 侧边栏 ===== */
.timeline-rail {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 3%, transparent) 0%, color-mix(in srgb, var(--accent-cyan) 1%, transparent) 100%),
    var(--bg-card-solid, #14181C);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  border-radius: 12px;
  padding: 20px 16px;
  position: sticky;
  top: 24px;
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  /* 扫描线叠加 */
  background-image:
    repeating-linear-gradient(0deg, transparent, transparent 3px, color-mix(in srgb, var(--accent-cyan) 1.5%, transparent) 3px, color-mix(in srgb, var(--accent-cyan) 1.5%, transparent) 4px),
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 3%, transparent) 0%, color-mix(in srgb, var(--accent-cyan) 1%, transparent) 100%);
  /* HUD 左上角标 */
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
}
.timeline-header {
  font-size: 10px;
  color: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  font-family: 'Courier New', monospace;
  display: flex;
  align-items: center;
  gap: 6px;
}
.timeline-header::before {
  content: "▸";
  color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
}
.timeline-loading,
.timeline-empty {
  padding: 16px 0;
  text-align: center;
  color: var(--text-muted, #8B94A0);
  font-size: 11px;
  font-family: 'Courier New', monospace;
}
.timeline-list {
  position: relative;
  padding-left: 4px;
}
.timeline-list::before {
  content: "";
  position: absolute;
  left: 11px;
  top: 8px;
  bottom: 8px;
  width: 1px;
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--accent-cyan) 25%, transparent) 10%, color-mix(in srgb, var(--accent-cyan) 25%, transparent) 90%, transparent);
}
.timeline-node {
  position: relative;
  padding: 8px 0 8px 28px;
  cursor: pointer;
  transition: all 0.25s ease;
  border-radius: 4px;
}
.timeline-node:hover {
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
}
.timeline-node::before {
  content: "";
  position: absolute;
  left: 7px;
  top: 14px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--bg-card-solid, #14181C);
  border: 2px solid color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  transition: all 0.25s ease;
  z-index: 1;
}
.timeline-node:hover::before {
  border-color: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.timeline-node.active::before {
  background: var(--accent-cyan);
  border-color: var(--accent-cyan);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-cyan) 15%, transparent), 0 0 16px color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  animation: hud-pulse-dot 2s ease-in-out infinite;
}
@keyframes hud-pulse-dot {
  0%, 100% { box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-cyan) 15%, transparent), 0 0 16px color-mix(in srgb, var(--accent-cyan) 50%, transparent); }
  50% { box-shadow: 0 0 0 6px color-mix(in srgb, var(--accent-cyan) 10%, transparent), 0 0 24px color-mix(in srgb, var(--accent-cyan) 60%, transparent); }
}
.timeline-node-date {
  font-size: 12px;
  color: var(--text-secondary, #C4C9D0);
  font-weight: 500;
}
.timeline-node.active .timeline-node-date {
  color: var(--accent-cyan);
  font-weight: 600;
  text-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.timeline-node-meta {
  font-size: 10px;
  color: #5A6370;
  margin-top: 3px;
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: 'Courier New', monospace;
}
.timeline-node.active .timeline-node-meta { color: color-mix(in srgb, var(--accent-cyan) 50%, transparent); }
.delta-chip {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 3px;
  font-weight: 600;
  font-family: 'Courier New', monospace;
}
.delta-chip.positive { background: rgba(0,255,136,0.12); color: #00ff88; }
.delta-chip.negative { background: rgba(255,51,102,0.12); color: #ff3366; }
.timeline-footer {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  font-size: 10px;
  color: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  text-align: center;
  font-family: 'Courier New', monospace;
  letter-spacing: 0.1em;
}

/* ===== Persona Hero Card — 全息主卡 ===== */
.persona-hero {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 4%, transparent) 0%, color-mix(in srgb, var(--accent-cyan) 1%, transparent) 40%, var(--bg-card-solid, #14181C) 100%);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  border-radius: 12px;
  padding: 28px 32px;
  position: relative;
  overflow: hidden;
  box-shadow:
    0 20px 60px rgba(0,0,0,0.5),
    0 0 30px color-mix(in srgb, var(--accent-cyan) 8%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  /* HUD 切角 */
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
}
/* 顶部扫描线 */
.persona-hero::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
  opacity: 0.6;
}
/* 右上角全息光晕 */
.persona-hero::after {
  content: "";
  position: absolute;
  top: -40%;
  right: -15%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent-cyan) 8%, transparent), transparent 65%);
  pointer-events: none;
  animation: hero-holo-glow 6s ease-in-out infinite;
}
@keyframes hero-holo-glow {
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.1); }
}
.hero-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
  position: relative;
  z-index: 1;
}
.hero-label {
  font-size: 10px;
  color: color-mix(in srgb, var(--accent-cyan) 70%, transparent);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'Courier New', monospace;
}
.hero-label::before {
  content: "";
  width: 16px;
  height: 1px;
  background: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
}
.hero-label::after {
  content: "";
  width: 4px;
  height: 4px;
  background: var(--accent-cyan);
  border-radius: 1px;
  transform: rotate(45deg);
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 50%, transparent);
}
.hero-title {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-primary, #EDEFF2);
  text-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}
.hero-subtitle {
  font-size: 12px;
  color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  margin-top: 6px;
  font-family: 'Courier New', monospace;
}
.hero-empty {
  padding: 32px;
  text-align: center;
  color: var(--text-muted, #8B94A0);
  font-size: 13px;
  position: relative;
  z-index: 1;
  border: 1px dashed color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
}
.hero-clear-diff {
  background: transparent;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  color: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  padding: 6px 10px;
  border-radius: 4px;
  transition: all 0.25s ease;
  font-family: inherit;
}
.hero-clear-diff:hover {
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  color: var(--accent-cyan);
  border-color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
}

/* 置信度环 — 青光脉冲 */
.confidence-ring {
  width: 80px;
  height: 80px;
  position: relative;
  flex-shrink: 0;
}
.confidence-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.confidence-value {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.confidence-value strong {
  font-size: 24px;
  font-weight: 700;
  color: var(--accent-cyan);
  line-height: 1;
  text-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 40%, transparent);
}
.confidence-value span {
  font-size: 8px;
  color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  margin-top: 3px;
  letter-spacing: 0.12em;
  font-family: 'Courier New', monospace;
}

/* 三栏画像 — 数据面板风格 */
.persona-cols {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  position: relative;
  z-index: 1;
}
.persona-col {
  position: relative;
  padding: 14px 14px 14px 18px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border-radius: 8px;
  /* 左侧发光线 */
  border-left: 2px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent);
}
.persona-col:hover {
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.persona-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid color-mix(in srgb, var(--accent-cyan) 8%, transparent);
}
.persona-col-title {
  font-size: 11px;
  color: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-family: 'Courier New', monospace;
}
.persona-col-count {
  font-size: 11px;
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  padding: 2px 8px;
  border-radius: 4px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: 'Courier New', monospace;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.count-added {
  background: rgba(0,255,136,0.15);
  color: #00ff88;
  padding: 1px 6px;
  border-radius: 3px;
  border: 1px solid rgba(0,255,136,0.2);
}
.count-removed {
  background: rgba(255,51,102,0.15);
  color: #ff3366;
  padding: 1px 6px;
  border-radius: 3px;
  border: 1px solid rgba(255,51,102,0.2);
}
.count-none {
  color: #5A6370;
  background: rgba(255,255,255,0.03);
  padding: 1px 6px;
  border-radius: 3px;
  font-weight: 400;
}
.persona-col-empty {
  font-size: 12px;
  color: #5A6370;
  margin: 0;
  font-style: italic;
}
.persona-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 12.5px;
}
.persona-col li {
  padding: 5px 0;
  line-height: 1.45;
  color: var(--text-primary, #EDEFF2);
  display: flex;
  align-items: flex-start;
  gap: 6px;
}
.persona-col li::before {
  content: "▹";
  color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  font-weight: 700;
  flex-shrink: 0;
  font-size: 11px;
}
.persona-col li.added { color: #00ff88; }
.persona-col li.added::before { content: "+"; color: #00ff88; }
.persona-col li.removed { color: #ff3366; text-decoration: line-through; opacity: 0.7; }
.persona-col li.removed::before { content: "−"; color: #ff3366; }

/* ===== 通用 info-card — 赛博玻璃面板 ===== */
.info-card {
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--accent-cyan) 3%, transparent) 0%,
      color-mix(in srgb, var(--accent-cyan) 1%, transparent) 40%,
      var(--bg-card-solid, #14181C) 100%);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 10px;
  padding: 18px 20px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: border-color .25s ease, box-shadow .3s ease, transform .2s ease;
  box-shadow: 0 2px 10px -4px rgba(0,0,0,.2);
  position: relative;
  overflow: hidden;
}
/* 顶部扫描线 */
.info-card::before {
  content: "";
  position: absolute;
  top: 0; left: 16px; right: 16px;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 25%, transparent), transparent);
  opacity: 0.8;
}
/* 右下角装饰点 */
.info-card::after {
  content: "";
  position: absolute;
  bottom: 8px;
  right: 10px;
  width: 4px;
  height: 4px;
  background: color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  border-radius: 1px;
  transform: rotate(45deg);
}
.info-card:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px -4px rgba(0,0,0,.3), 0 0 20px color-mix(in srgb, var(--accent-cyan) 8%, transparent);
}
.info-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}
.info-card-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary, #EDEFF2);
  display: flex;
  align-items: center;
  gap: 8px;
}
.info-card-title::before {
  content: "";
  width: 3px;
  height: 14px;
  background: linear-gradient(180deg, var(--accent-cyan), color-mix(in srgb, var(--accent-cyan) 20%, transparent));
  border-radius: 2px;
}
.info-card-meta {
  font-size: 10px;
  color: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  font-family: 'Courier New', monospace;
}
.card-loading,
.card-empty,
.card-desc {
  font-size: 12px;
  color: var(--text-muted, #8B94A0);
  margin: 0 0 12px;
  line-height: 1.5;
}
.card-loading, .card-empty { padding: 8px 0; }

/* 行为观测卡 */
.prefs-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.pref-tag {
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  color: color-mix(in srgb, var(--accent-cyan) 80%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 11px;
  display: inline-flex;
  align-items: center;
  transition: all 0.2s ease;
}
.pref-tag:hover {
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.prefs-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  border-top: 1px solid color-mix(in srgb, var(--accent-cyan) 5%, transparent);
  font-size: 12px;
}
.prefs-row:first-of-type { border-top: none; }
.prefs-row .label { color: var(--text-muted, #8B94A0); }
.prefs-row .value {
  color: var(--accent-cyan);
  font-weight: 500;
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  padding: 2px 10px;
  border-radius: 4px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  font-family: 'Courier New', monospace;
}

/* PreheatCard */
.preheat-card .preheat-btn {
  width: 100%;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 12%, transparent), color-mix(in srgb, var(--accent-cyan) 4%, transparent));
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  color: var(--accent-cyan);
  padding: 10px 14px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.25s ease;
  font-family: inherit;
  letter-spacing: 0.04em;
}
.preheat-card .preheat-btn:hover:not(:disabled) {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 20%, transparent), color-mix(in srgb, var(--accent-cyan) 8%, transparent));
  transform: translateY(-1px);
  box-shadow: 0 4px 16px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  text-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.preheat-card .preheat-btn:disabled { opacity: 0.5; cursor: not-allowed; }
.preheat-card .preheat-error {
  margin-top: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 11px;
  line-height: 1.5;
  background: rgba(255,51,102,0.06);
  color: #ff3366;
  border: 1px solid rgba(255,51,102,0.15);
  display: flex;
  align-items: flex-start;
  gap: 6px;
}
/* 红叉限成小图标，不再撑满一行 */
.preheat-card .preheat-error-icon {
  flex: 0 0 auto;
  display: inline-flex;
  width: 13px;
  height: 13px;
  margin-top: 1px;
}
.preheat-card .preheat-error-icon svg {
  width: 13px;
  height: 13px;
}
.preheat-card .preheat-error-text {
  flex: 1 1 auto;
}
.preheat-card .preheat-success {
  margin-top: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 11px;
  background: rgba(0,255,136,0.06);
  color: #00ff88;
  border: 1px solid rgba(0,255,136,0.15);
}

/* ===== KPI 细条 — 数据仪表 ===== */
.kpi-strip {
  background: var(--bg-card-solid, #14181C);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 10px;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  gap: 16px;
  position: relative;
  overflow: hidden;
}
.kpi-strip::before {
  content: "";
  position: absolute;
  top: 0;
  left: 10%;
  right: 10%;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 30%, transparent), transparent);
}
.kpi-item {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex: 1;
  justify-content: center;
  position: relative;
}
.kpi-item:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 20px;
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--accent-cyan) 15%, transparent), transparent);
}
.kpi-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--accent-cyan);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  font-family: 'Courier New', monospace;
  text-shadow: 0 0 10px color-mix(in srgb, var(--accent-cyan) 25%, transparent);
}
.kpi-label {
  font-size: 11px;
  color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  letter-spacing: 0.06em;
  font-family: 'Courier New', monospace;
}

/* ===== 进化趋势 mini chart — 赛博图表 ===== */
.evolution-card {
  background: var(--bg-card-solid, #14181C);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 10px;
  padding: 18px 20px;
  position: relative;
}
.evolution-chart {
  height: 80px;
  position: relative;
  margin-top: 8px;
}
.evolution-chart svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}
.evolution-legend {
  display: flex;
  gap: 16px;
  margin-top: 10px;
  font-size: 11px;
  color: var(--text-muted, #8B94A0);
  font-family: 'Courier New', monospace;
}
.legend-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 2px;
  margin-right: 4px;
  vertical-align: middle;
  box-shadow: 0 0 4px currentColor;
}

/* ===== HUD 扫描线叠加层 ===== */
.profile-hud-page {
  position: relative;
}
/* Compact hero for profile page */
.profile-hero-compact { padding: 12px 24px 8px; }
.profile-hero-compact h1 { font-size: 20px; margin: 0; }
.profile-hero-compact .product-hero-actions { gap: 8px; }
.profile-hero-compact .ai-primary-action,
.profile-hero-compact .secondary-action { padding: 6px 14px; font-size: 12px; }
.hud-scanlines {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 100;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    color-mix(in srgb, var(--accent-cyan) 0.8%, transparent) 2px,
    color-mix(in srgb, var(--accent-cyan) 0.8%, transparent) 4px
  );
  animation: scanline-drift 8s linear infinite;
}
@keyframes scanline-drift {
  0% { background-position: 0 0; }
  100% { background-position: 0 40px; }
}
/* HUD 装饰角标 */
.hud-corner {
  position: fixed;
  width: 40px;
  height: 40px;
  pointer-events: none;
  z-index: 101;
}
.hud-corner-tl {
  top: 12px;
  left: 12px;
  border-top: 1px solid color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  border-left: 1px solid color-mix(in srgb, var(--accent-cyan) 25%, transparent);
}
.hud-corner-tl::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 6px;
  height: 6px;
  background: var(--accent-cyan);
  opacity: 0.5;
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 40%, transparent);
}
.hud-corner-br {
  bottom: 12px;
  right: 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  border-right: 1px solid color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.hud-corner-br::after {
  content: "";
  position: absolute;
  bottom: 0;
  right: 0;
  width: 6px;
  height: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  box-shadow: 0 0 6px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
}

/* ===== section-header 科幻风格 ===== */
.profile-center-page .section-header {
  margin-bottom: 16px;
}
.profile-center-page .section-title {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 6px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-primary, #EDEFF2);
}
.profile-center-page .section-title::before {
  content: "";
  width: 3px;
  height: 16px;
  background: linear-gradient(180deg, var(--accent-cyan), color-mix(in srgb, var(--accent-cyan) 20%, transparent));
  border-radius: 2px;
}
.profile-center-page .section-desc {
  font-size: 12px;
  color: color-mix(in srgb, var(--accent-cyan) 35%, transparent);
  margin: 0;
  line-height: 1.5;
  font-family: 'Courier New', monospace;
}

/* ===== 特别关注列表 — 赛博风格 ===== */
.profile-special-follows .special-follows-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}
.profile-special-follows .special-follow-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  transition: all 0.2s ease;
}
.profile-special-follows .special-follow-item:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
}
.profile-special-follows .special-follow-type {
  font-size: 10px;
  padding: 2px 8px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  color: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  font-family: 'Courier New', monospace;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.profile-special-follows .special-follow-name {
  font-weight: 500;
  color: var(--text-primary);
  font-size: 13px;
}
.profile-special-follows .special-follow-note {
  font-size: 12px;
  color: var(--text-muted);
  flex: 1;
}
.profile-special-follows .special-follow-edit,
.profile-special-follows .special-follow-remove {
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  background: transparent;
  color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: inherit;
}
.profile-special-follows .special-follow-edit:hover {
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  color: var(--accent-cyan);
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.profile-special-follows .special-follow-remove:hover {
  background: rgba(255,51,102,0.08);
  color: #ff3366;
  border-color: rgba(255,51,102,0.3);
}
.profile-special-follows .special-follow-form {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  flex-wrap: wrap;
}
.profile-special-follows .special-follow-form select,
.profile-special-follows .special-follow-form input {
  padding: 8px 12px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  color: var(--text-primary);
  font-size: 12px;
  outline: none;
  transition: border-color 0.2s ease;
  font-family: inherit;
}
.profile-special-follows .special-follow-form select:focus,
.profile-special-follows .special-follow-form input:focus {
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}
.profile-special-follows .special-follow-form button {
  padding: 8px 16px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 6%, transparent);
  color: var(--accent-cyan);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: inherit;
}
.profile-special-follows .special-follow-form button:hover {
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
