/* ===== AI 画像相关 section 通用 ===== */
.profile-center-page .profile-learning-panel,
.profile-center-page .profile-control-layout,
.profile-center-page .profile-calibration-panel,
.profile-center-page .profile-memory-panel {
  background: var(--bg-card-solid, #14181C);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 10px;
  padding: 20px 24px;
  position: relative;
  overflow: hidden;
}
.profile-center-page .profile-learning-panel::before,
.profile-center-page .profile-control-layout::before,
.profile-center-page .profile-calibration-panel::before,
.profile-center-page .profile-memory-panel::before {
  content: "";
  position: absolute;
  top: 0; left: 16px; right: 16px;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 20%, transparent), transparent);
}
.profile-center-page .empty-state {
  padding: 24px;
  text-align: center;
  color: var(--text-muted);
  border: 1px dashed color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
}
.profile-center-page .empty-state-hint {
  font-size: 12px;
  color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  margin-top: 4px;
}
.profile-center-page .priority-list {
  display: grid;
  gap: 6px;
}
.profile-center-page .priority-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 12px;
  align-items: center;
  padding: 8px 12px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 5%, transparent);
  border-radius: 6px;
  transition: all 0.2s ease;
  font-size: 13px;
}
.profile-center-page .priority-row:hover {
  background: color-mix(in srgb, var(--accent-cyan) 3%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}

/* ===== 推荐校准卡片 ===== */
.profile-calibration-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
  margin-top: 12px;
}
.profile-calibration-card {
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  transition: all 0.2s ease;
}
.profile-calibration-card:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.profile-calibration-card span {
  font-size: 11px;
  color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  font-family: 'Courier New', monospace;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.profile-calibration-card strong {
  display: block;
  font-size: 20px;
  font-weight: 700;
  color: var(--accent-cyan);
  margin: 4px 0;
  text-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
}
.profile-calibration-card p {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0;
  line-height: 1.4;
}

/* ===== 每日画像记录列表 ===== */
.profile-snapshot-list .profile-snapshot {
  margin-bottom: 8px;
}

/* ===== AI 仪表盘操作按钮 ===== */
.profile-hero .ai-primary-action,
.profile-hero .secondary-action {
  padding: 8px 20px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.25s ease;
  font-family: inherit;
  border: 1px solid;
}
.profile-hero .ai-primary-action {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 15%, transparent), color-mix(in srgb, var(--accent-cyan) 5%, transparent));
  border-color: color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  color: var(--accent-cyan);
}
.profile-hero .ai-primary-action:hover {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 25%, transparent), color-mix(in srgb, var(--accent-cyan) 10%, transparent));
  box-shadow: 0 4px 16px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  text-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}
.profile-hero .secondary-action {
  background: transparent;
  border-color: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
}
.profile-hero .secondary-action:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 25%, transparent);
