}

/* ============ 水墨氛围视觉层 ============ */

/* BackgroundLayer：墨色渐变背景 */
.visual-bg-layer {
  position: fixed;
  inset: 0;
  z-index: -3;
  pointer-events: none;
  background:
    radial-gradient(ellipse 80% 60% at 20% 10%, color-mix(in srgb, var(--accent-cyan) 10%, transparent) 0%, transparent 50%),
    radial-gradient(ellipse 60% 50% at 80% 90%, rgba(120,108,140,.08) 0%, transparent 50%),
    linear-gradient(180deg, #141820 0%, #11151A 50%, #0F1318 100%);
  overflow: hidden;
}
:root[data-mode="light"] .visual-bg-layer {
  /* v16：底色与光晕全部跟随调色板（暖 palette 得暖纸，冷 palette 得冷白） */
  background:
    radial-gradient(ellipse 80% 60% at 15% 5%, color-mix(in srgb, var(--accent-cyan) 4.5%, transparent) 0%, transparent 55%),
    radial-gradient(ellipse 60% 40% at 85% 95%, color-mix(in srgb, var(--accent-violet) 3%, transparent) 0%, transparent 50%),
    linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 45%, color-mix(in srgb, var(--bg-primary) 92%, var(--accent-cyan)) 100%);
}
.visual-bg-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(42px);
  animation: visual-bg-breathe 25s ease-in-out infinite;
}
.visual-bg-glow-1 {
  top: -15%;
  left: -10%;
  width: 55%;
  height: 55%;
  background: radial-gradient(circle, var(--ink-glow-1) 0%, transparent 70%);
}
.visual-bg-glow-2 {
  bottom: -20%;
  right: -10%;
  width: 50%;
  height: 50%;
  background: radial-gradient(circle, var(--ink-glow-2) 0%, transparent 70%);
  animation-delay: -8s;
}
.visual-bg-glow-3 {
  top: 40%;
  left: 30%;
  width: 45%;
  height: 45%;
  background: radial-gradient(circle, var(--ink-glow-3) 0%, transparent 70%);
  animation-delay: -16s;
}
@keyframes visual-bg-breathe {
  0%, 100% { opacity: .7; }
  50% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .visual-bg-glow { animation: none; opacity: .85; }
}

/* NoiseLayer：宣纸噪点质感 */
.visual-noise-layer {
  position: fixed;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  opacity: 0.03;
  background-repeat: repeat;
  background-size: 80px 80px;
  mix-blend-mode: overlay;
}
:root[data-mode="light"] .visual-noise-layer {
  opacity: 0.025;
  mix-blend-mode: multiply;
}

/* ============================================================
 * 旧 span 粒子层（App.jsx L2021-2023 的 24 个 .particle）现在隐藏。
 * 背景粒子统一由 ParticleField Canvas 接管，并按 12 配色主题切形态。
 * ============================================================ */
.particle-layer { display: none !important; }

/* ============================================================
 * ParticleField 主题驱动引擎（读 :root 级 CSS 变量）
 * 变量全部挂在 :root（<html data-palette="xxx">）上，
 * 由 ParticleField.jsx 的 readCssVar() 直接读取，fallback 永不挂空。
 * 蓝色主题（neon / cosmos / arctic / twilight）→ bubble 泡泡；
 * 粉→花瓣，绿→叶片，金银→金箔点/光晕，橙陶→六角，紫→极光。
 * ============================================================ */

/* ---------- 默认（无 data-palette 属性 = champagne 兼容层） ---------- */
:root {
  --particle-shape: network;
  --particle-c1: color-mix(in srgb, var(--accent-cyan) 80%, transparent);
  --particle-c2: color-mix(in srgb, var(--accent-amber) 72%, transparent);
  --particle-count: 72;
  --particle-network-min: 1;
  --particle-network-max: 2.8;
  --particle-speed-mul: 1;
  --particle-size-min: 0.5;
  --particle-size-max: 2.2;
  /* 泡泡专用（蓝色主题会覆盖） */
  --particle-bubble-min: 3;
  --particle-bubble-max: 14;
  --particle-bubble-hl: rgba(255,255,255,.65);
  --particle-bubble-edge: rgba(255,255,255,.18);
  /* 其余形态专用 size 变量（按需要覆盖） */
  --particle-petal-min: 5;   --particle-petal-max: 11;
  --particle-leaf-min: 4;    --particle-leaf-max: 9;
  --particle-hex-min: 3;     --particle-hex-max: 9;
  --particle-halo-min: 8;    --particle-halo-max: 22;
  --particle-aurora-min: 18; --particle-aurora-max: 48;
  --particle-stardust-min:.4;--particle-stardust-max: 1.6;
  /* network 形态专用（科技蓝主题） */
  --particle-network-min: 0.9;
  --particle-network-max: 2.6;
}

/* ---------- 1. champagne 香槟金（默认）→ 金箔星点 ---------- */
:root[data-palette="champagne"] {
  --particle-shape: network;
  --particle-c1: color-mix(in srgb, var(--accent-cyan) 80%, transparent);
  --particle-c2: rgba(232,205,140,.68);
  --particle-count: 76;
  --particle-network-min: 1.1;
  --particle-network-max: 3;
  --particle-speed-mul: 1.05;
  --scrollbar-thumb: color-mix(in srgb, var(--accent-cyan) 36%, transparent);
  --scrollbar-thumb-hover: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
}
:root[data-mode="light"][data-palette="champagne"] {
  --scrollbar-thumb: rgba(154,123,63,.3);
  --scrollbar-thumb-hover: rgba(154,123,63,.52);
}

