/* ParticleField：金箔粒子画布 */
.visual-particle-layer {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  width: 100vw;
  height: 100vh;
}
/* v20 深浅模式适配：浅色下整体降透明度（浅背景对彩色粒子更敏感），
   并把泡泡高光/描边换成浅底可读的版本（纯白高光在浅背景洗白消失）
   v26.8：0.72 → 0.88 —— 浅色粒子本就颜色淡，再砍一刀会连侧栏透出区域都不可见 */
:root[data-mode="light"] .visual-particle-layer { opacity: 0.88; }
:root[data-mode="light"] {
  --particle-bubble-hl: rgba(255,255,255,.95);
  --particle-bubble-edge: rgba(30,41,59,.14);
}
/* v21 深浅模式动效差异：深色粒子迅捷有能量感（×1.15），浅色舒缓优雅（×0.75）。
   与调色板各自的 --particle-speed-mul 相乘，同一主题在两种模式下速度体感明显不同 */
:root { --particle-mode-speed: 1.15; }
:root[data-mode="light"] { --particle-mode-speed: 0.75; }

/* ============ 全局卡片质感升级 ============ */

/* 卡片微玻璃态：--bg-card 已是 rgba，配合 backdrop-filter */
.card,
.news-item,
.workspace-panel,
.agent-panel,
.skills-panel,
.session-sidebar,
.stock-panel {
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: border-color .2s, transform .2s, box-shadow .2s;
}

/* 卡片 hover：边框金色加深 + 上浮 + 阴影加深 */
.news-item:hover,
.workspace-panel:hover,
.skills-panel-section:hover {
  border-color: color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,.25), 0 0 0 1px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
:root[data-mode="light"] .news-item:hover,
:root[data-mode="light"] .workspace-panel:hover,
:root[data-mode="light"] .skills-panel-section:hover {
  border-color: rgba(154,123,63,.45);
  box-shadow: 0 8px 24px rgba(120,100,60,.15), 0 0 0 1px rgba(154,123,63,.12);
}

/* 低端设备降级：不支持 backdrop-filter 时移除玻璃态 */
@supports not ((backdrop-filter: blur(8px)) or (-webkit-backdrop-filter: blur(8px))) {
  .card,
  .news-item,
  .workspace-panel,
  .agent-panel,
  .skills-panel,
  .session-sidebar,
  .stock-panel {
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}

/* ============ 滚动条美化（token 化：随 12 配色主题 + dark/light 双模式实时切色）
   目标容器（真实发生 overflow 的元素）：
   - 侧边栏导航：.nav-menu（App.jsx 侧边栏中间部分）
   - 主工作区：.main / .feed
   - 右面板：.panel / .panel-body
   - 其余自定义小区域：.custom-scrollbar（材料卡片/设置等）
   Webkit + Firefox 两边规则都走同一套 --scrollbar-* token。
============ */

/* Webkit 浏览器（Chrome / Safari / Edge / 国内双核）*/
::-webkit-scrollbar {
  width: var(--scrollbar-size, 8px);
  height: var(--scrollbar-size, 8px);
}
::-webkit-scrollbar-track {
  background: var(--scrollbar-track, transparent);
}
::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb, color-mix(in srgb, var(--accent-cyan) 35%, transparent));
  border-radius: 4px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover, color-mix(in srgb, var(--accent-cyan) 58%, transparent));
  background-clip: padding-box;
}

/* 滚动条尺寸分级：侧栏 / 右面板窄一些，视觉不打架 */
.nav-menu::-webkit-scrollbar,
.panel::-webkit-scrollbar,
.panel > .panel-body::-webkit-scrollbar,
.sidebar-footer + div::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.nav-menu::-webkit-scrollbar-thumb,
.panel::-webkit-scrollbar-thumb,
.panel > .panel-body::-webkit-scrollbar-thumb {
  border-width: 1.5px;
}

/* Firefox */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb, color-mix(in srgb, var(--accent-cyan) 35%, transparent)) var(--scrollbar-track, transparent);
}
*::-moz-scrollbar-thumb:hover {
  scrollbar-color: var(--scrollbar-thumb-hover, color-mix(in srgb, var(--accent-cyan) 58%, transparent)) var(--scrollbar-track, transparent);
}

/* ============================================================
 * Profile Module — Cinematic Tech Panel Theme
 * 电影/影视级科技面板风格：全息 HUD、青光霓虹、扫描线、切角
 * ============================================================ */

.profile-center-page {
  --hud-cyan: var(--accent-cyan);
  --hud-cyan-dim: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  --hud-cyan-faint: color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  --hud-cyan-ghost: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  --hud-bg: #0d1116;
  --hud-panel: rgba(13, 17, 22, 0.82);
  --hud-grid: color-mix(in srgb, var(--accent-cyan) 3.5%, transparent);
  --hud-font-mono: 'Courier New', 'SFMono-Regular', Consolas, monospace;
  --hud-radius: 12px;
  --hud-cut: 16px;
}

/* ---- 顶部英雄区：电影开场面板 ---- */
.profile-center-page .profile-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 24px;
  padding: 28px 32px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: var(--hud-radius);
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 6%, transparent) 0%, transparent 40%),
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 4%, transparent) 0%, transparent 60%),
    var(--hud-panel);
  box-shadow:
    0 24px 70px rgba(0,0,0,0.55),
    0 0 40px color-mix(in srgb, var(--accent-cyan) 6%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  clip-path: polygon(
    0 0,
    calc(100% - var(--hud-cut)) 0,
    100% var(--hud-cut),
    100% 100%,
    var(--hud-cut) 100%,
    0 calc(100% - var(--hud-cut))
  );
  overflow: hidden;
}

/* 扫描线动画 */
.profile-center-page .profile-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      color-mix(in srgb, var(--accent-cyan) 2%, transparent) 2px,
      color-mix(in srgb, var(--accent-cyan) 2%, transparent) 3px
    );
  pointer-events: none;
  animation: hud-scanline 6s linear infinite;
}

@keyframes hud-scanline {
  0% { transform: translateY(-100%); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(100%); opacity: 0; }
}

/* 顶部高光 */
.profile-center-page .profile-hero::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--hud-cyan), transparent);
  opacity: 0.7;
}

.profile-center-page .profile-hero .workbench-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 4px;
  background: var(--hud-cyan-ghost);
  color: var(--hud-cyan-dim);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-family: var(--hud-font-mono);
  width: fit-content;
}

.profile-center-page .profile-hero .workbench-kicker::before {
  content: "";
  width: 6px;
  height: 6px;
  background: var(--hud-cyan);
  border-radius: 50%;
  box-shadow: 0 0 8px var(--hud-cyan);
  animation: hud-pulse 2s ease-in-out infinite;
}

@keyframes hud-pulse {
  0%, 100% { opacity: 1; box-shadow: 0 0 8px var(--hud-cyan); }
  50% { opacity: 0.5; box-shadow: 0 0 16px var(--hud-cyan); }
}

.profile-center-page .profile-hero h1 {
  margin: 12px 0 10px;
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  text-shadow: 0 0 24px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}

.profile-center-page .profile-hero p {
  max-width: 620px;
  font-size: 13px;
  line-height: 1.7;
  color: var(--text-secondary);
}

.profile-center-page .profile-hero-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* 主按钮：青光触发器 */
.profile-center-page .ai-primary-action {
  position: relative;
  min-height: 40px;
  padding: 0 20px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 6px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 16%, transparent), color-mix(in srgb, var(--accent-cyan) 6%, transparent)),
    var(--hud-panel);
  color: var(--hud-cyan);
  font-weight: 800;
  font-size: 13px;
  letter-spacing: 0.04em;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.25s ease;
  box-shadow: 0 0 16px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}

.profile-center-page .ai-primary-action::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-cyan) 15%, transparent), transparent);
  transform: translateX(-100%);
  transition: transform 0.5s ease;
}

.profile-center-page .ai-primary-action:hover {
  border-color: var(--hud-cyan-dim);
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 24%, transparent), color-mix(in srgb, var(--accent-cyan) 10%, transparent));
  box-shadow: 0 0 24px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  text-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 40%, transparent);
}

.profile-center-page .ai-primary-action:hover::before {
  transform: translateX(100%);
}

.profile-center-page .secondary-action {
  position: relative;
  min-height: 40px;
  padding: 0 18px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.profile-center-page .secondary-action:hover {
  border-color: var(--hud-cyan-dim);
  background: var(--hud-cyan-ghost);
  color: var(--hud-cyan);
}

/* ---- Tab 切换器增强 ---- */
.profile-center-page .profile-tabs {
  margin-bottom: 24px;
  background: var(--hud-cyan-ghost);
  border: 1px solid var(--hud-cyan-faint);
}

.profile-center-page .profile-tab.active {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 18%, transparent), color-mix(in srgb, var(--accent-cyan) 8%, transparent));
  color: var(--hud-cyan);
  border-color: var(--hud-cyan-dim);
  box-shadow: 0 0 16px color-mix(in srgb, var(--accent-cyan) 18%, transparent), inset 0 1px 0 color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}

/* ---- 通用科技面板容器 ---- */
.profile-center-page .profile-persona-summary,
.profile-center-page .profile-pending-suggestions,
.profile-center-page .profile-learning-panel,
.profile-center-page .profile-control-panel,
.profile-center-page .profile-calibration-panel,
.profile-center-page .profile-memory-panel,
.profile-center-page .profile-special-follows,
.profile-center-page .profile-agent-memory,
.profile-center-page .profile-snapshot-history {
  position: relative;
  padding: 22px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: var(--hud-radius);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 3%, transparent) 0%, transparent 50%),
    var(--hud-panel);
  box-shadow: 0 12px 40px rgba(0,0,0,0.35);
  overflow: hidden;
}

/* 面板左上角标识 */
.profile-center-page .profile-persona-summary::before,
.profile-center-page .profile-pending-suggestions::before,
.profile-center-page .profile-learning-panel::before,
.profile-center-page .profile-control-panel::before,
.profile-center-page .profile-calibration-panel::before,
.profile-center-page .profile-memory-panel::before,
.profile-center-page .profile-special-follows::before,
.profile-center-page .profile-agent-memory::before,
.profile-center-page .profile-snapshot-history::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 48px;
  height: 1px;
  background: linear-gradient(90deg, var(--hud-cyan), transparent);
  opacity: 0.8;
}

/* 面板右下角装饰 */
.profile-center-page .profile-persona-summary::after,
.profile-center-page .profile-pending-suggestions::after,
.profile-center-page .profile-learning-panel::after,
.profile-center-page .profile-control-panel::after,
.profile-center-page .profile-calibration-panel::after,
.profile-center-page .profile-memory-panel::after,
.profile-center-page .profile-special-follows::after,
.profile-center-page .profile-agent-memory::after,
.profile-center-page .profile-snapshot-history::after {
  content: "";
  position: absolute;
  bottom: 0;
  right: 0;
  width: 48px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--hud-cyan));
  opacity: 0.5;
}

/* 区块标题统一 */
.profile-center-page .section-header {
  margin-bottom: 18px;
}

.profile-center-page .section-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 6px;
}

.profile-center-page .section-title::before {
  content: "";
  width: 4px;
  height: 16px;
  background: linear-gradient(180deg, var(--hud-cyan), transparent);
  border-radius: 2px;
}

.profile-center-page .section-title svg {
  width: 16px;
  height: 16px;
  color: var(--hud-cyan);
}

.profile-center-page .section-desc {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.6;
  margin: 0;
}

/* ---- 顶部统计网格 ---- */
.profile-center-page .profile-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.profile-center-page .profile-summary-grid > div {
  position: relative;
  min-height: 120px;
  padding: 16px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 10px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 3%, transparent) 0%, transparent 60%),
    color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  transition: all 0.25s ease;
}

.profile-center-page .profile-summary-grid > div:hover {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  transform: translateY(-2px);
}

.profile-center-page .profile-summary-grid span {
  font-family: var(--hud-font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--hud-cyan-dim);
}

.profile-center-page .profile-summary-grid strong {
  font-size: 32px;
  font-weight: 800;
  color: var(--hud-cyan);
  text-shadow: 0 0 16px color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  font-variant-numeric: tabular-nums;
}

.profile-center-page .profile-summary-grid p {
  color: var(--text-muted);
  font-size: 11px;
}

/* BlockStat 卡片在画像页的统一科技风 */
.profile-center-page .block-grid {
  gap: 14px;
}

.profile-center-page .block-stat-card {
  position: relative;
  min-height: 120px;
  padding: 16px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 10px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 3%, transparent) 0%, transparent 60%),
    color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  box-shadow: none;
  transition: all 0.25s ease;
}

.profile-center-page .block-stat-card:hover {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
  box-shadow: 0 0 20px color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  transform: translateY(-2px);
}

.profile-center-page .block-stat-card-label {
  font-family: var(--hud-font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--hud-cyan-dim);
}

.profile-center-page .block-stat-card-value {
  font-size: 32px;
  font-weight: 800;
  color: var(--hud-cyan);
  text-shadow: 0 0 16px color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  font-variant-numeric: tabular-nums;
}

.profile-center-page .block-stat-card-desc {
  color: var(--text-muted);
  font-size: 11px;
}

/* ---- 画像学习引擎面板 ---- */
.profile-center-page .profile-learning-panel {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: 24px;
}

.profile-center-page .profile-learning-score strong {
  font-size: 44px;
  font-weight: 800;
  color: var(--hud-cyan);
  text-shadow: 0 0 24px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}

.profile-center-page .profile-learning-score span {
  font-family: var(--hud-font-mono);
  font-size: 12px;
  color: var(--hud-cyan-dim);
  letter-spacing: 0.04em;
}

.profile-center-page .profile-learning-score p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.7;
}

.profile-center-page .profile-learning-actions button {
  border: 1px solid var(--hud-cyan-faint);
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  transition: all 0.2s ease;
}

.profile-center-page .profile-learning-actions button:hover {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  color: var(--hud-cyan);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}

.profile-center-page .profile-learning-side {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.profile-center-page .profile-learning-side div {
  padding: 12px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
}

.profile-center-page .profile-learning-side span {
  font-family: var(--hud-font-mono);
  font-size: 10px;
  color: var(--hud-cyan-dim);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.profile-center-page .profile-learning-side p {
  color: var(--text-secondary);
  font-size: 12px;
}

/* ---- 优先级控制面板 ---- */
.profile-center-page .profile-control-layout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.profile-center-page .priority-row {
  padding: 12px 14px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
  transition: all 0.2s ease;
}

.profile-center-page .priority-row:hover {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
}

.profile-center-page .priority-row span {
  color: var(--text-primary);
  font-weight: 700;
}

.profile-center-page .priority-row strong {
  color: var(--hud-cyan);
  font-family: var(--hud-font-mono);
}

.profile-center-page .profile-tier-control button {
  border: 1px solid var(--hud-cyan-faint);
  background: color-mix(in srgb, var(--accent-cyan) 3%, transparent);
  color: var(--text-muted);
  transition: all 0.2s ease;
}

.profile-center-page .profile-tier-control button:hover,
.profile-center-page .profile-tier-control button:focus-visible {
  border-color: var(--hud-cyan-dim);
  color: color-mix(in srgb, var(--accent-cyan) 80%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 6%, transparent);
}

.profile-center-page .profile-tier-control button.active {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  color: var(--hud-cyan);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 15%, transparent);
  text-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 30%, transparent);
}

/* ---- 特别关注 ---- */
.profile-center-page .special-follows-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.profile-center-page .special-follow-item {
  display: grid;
  grid-template-columns: auto 1fr auto auto auto;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-cyan) 2%, transparent);
}

.profile-center-page .special-follow-type {
  padding: 3px 8px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border: 1px solid var(--hud-cyan-faint);
  color: var(--hud-cyan);
  font-size: 10px;
  font-weight: 700;
  font-family: var(--hud-font-mono);
  text-transform: uppercase;
}

.profile-center-page .special-follow-name {
  color: var(--text-primary);
  font-weight: 700;
  font-size: 13px;
}

.profile-center-page .special-follow-note {
  color: var(--text-muted);
  font-size: 12px;
}

.profile-center-page .special-follow-edit,
.profile-center-page .special-follow-remove {
  padding: 5px 12px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 5px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.profile-center-page .special-follow-edit:hover {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 6%, transparent);
  color: var(--hud-cyan);
}

.profile-center-page .special-follow-remove:hover {
  border-color: rgba(255, 51, 102, 0.4);
  background: rgba(255, 51, 102, 0.08);
  color: #ff3366;
}

.profile-center-page .special-follow-form {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--hud-cyan-faint);
}

.profile-center-page .special-follow-form select,
.profile-center-page .special-follow-form input {
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 3%, transparent);
  color: var(--text-primary);
  font-size: 13px;
  outline: none;
  transition: all 0.2s ease;
}

.profile-center-page .special-follow-form select:focus,
.profile-center-page .special-follow-form input:focus {
  border-color: var(--hud-cyan-dim);
  box-shadow: 0 0 12px color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}

.profile-center-page .special-follow-form button {
  min-height: 38px;
  padding: 0 18px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  color: var(--hud-cyan);
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.profile-center-page .special-follow-form button:hover {
  border-color: var(--hud-cyan-dim);
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  box-shadow: 0 0 16px color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}

/* ---- 推荐校准状态 ---- */
.profile-center-page .profile-calibration-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

