/* ============================================================
 * Profile Modal — 全息身份面板
 * ============================================================ */

.profile-modal {
  /* HUD 变量兜底：ProfileModal 是全局弹窗，渲染在 .profile-center-page 容器之外，
     必须在此自行定义全套 --hud-* 令牌，否则背景/边框变量失效导致透明。
     深色模式用青黑面板；浅色模式在下方 [data-mode="light"] 覆盖为白玻璃。 */
  --hud-cyan: var(--accent-cyan);
  --hud-cyan-dim: color-mix(in srgb, var(--accent-cyan) 60%, transparent);
  --hud-cyan-faint: color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  --hud-cyan-ghost: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  --hud-panel: rgba(13, 17, 22, 0.94);
  --hud-panel-deep: rgba(10, 14, 20, 0.98);
  --hud-grid: color-mix(in srgb, var(--accent-cyan) 3.5%, transparent);
  --hud-text: var(--text-primary);
  --hud-dim: var(--text-muted);
  --hud-font-mono: 'Share Tech Mono', 'JetBrains Mono', Consolas, monospace;
  --hud-radius: 12px;
  --hud-cut: 18px;
  position: relative;
  width: 560px;
  max-width: 92vw;
  overflow: hidden;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: var(--hud-radius);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 4%, transparent) 0%, transparent 30%),
    var(--hud-panel);
  box-shadow:
    0 32px 80px rgba(0,0,0,0.6),
    0 0 60px color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  clip-path: polygon(
    0 0,
    calc(100% - var(--hud-cut)) 0,
    100% var(--hud-cut),
    100% 100%,
    var(--hud-cut) 100%,
    0 calc(100% - var(--hud-cut))
  );
}

/* 浅色模式：暖白玻璃面板 + 柔和阴影，保留 HUD 切角骨架 */
:root[data-mode="light"] .profile-modal {
  --hud-cyan: #85652f;
  --hud-cyan-dim: rgba(138, 106, 53, 0.6);
  --hud-cyan-faint: rgba(138, 106, 53, 0.22);
  --hud-cyan-ghost: rgba(138, 106, 53, 0.07);
  --hud-panel: rgba(252, 249, 243, 0.97);
  --hud-panel-deep: rgba(252, 249, 243, 1);
  --hud-grid: rgba(138, 106, 53, 0.04);
  border-color: rgba(138, 106, 53, 0.18);
  background:
    linear-gradient(180deg, rgba(138, 106, 53, 0.06) 0%, transparent 30%),
    var(--hud-panel);
  box-shadow:
    0 24px 64px rgba(70, 45, 15, 0.18),
    0 0 40px rgba(138, 106, 53, 0.07);
}

/* 浅色模式：封面/扫描线改用暖金变量，避免残留高亮青色 */
:root[data-mode="light"] .profile-modal .profile-cover {
  background:
    linear-gradient(120deg, var(--hud-cyan-ghost), rgba(138, 106, 53, 0.04) 55%, transparent),
    linear-gradient(180deg, var(--hud-cyan-ghost), transparent);
}

.profile-modal::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--hud-cyan), transparent);
  opacity: 0.7;
}

.profile-modal .profile-cover {
  position: relative;
  height: 110px;
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--accent-cyan) 18%, transparent), color-mix(in srgb, var(--accent-cyan) 6%, transparent) 55%, transparent),
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 8%, transparent), transparent);
  border-bottom: 1px solid var(--hud-cyan-faint);
}

.profile-modal .profile-cover::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      color-mix(in srgb, var(--accent-cyan) 2%, transparent) 2px,
      color-mix(in srgb, var(--accent-cyan) 2%, transparent) 3px
