/* ============================================================
 * Profile Dashboard V3 — 电影指挥中心布局 / 科技面板
 * ============================================================ */
.profile-center-page .profile-dashboard-v3 {
  position: relative;
  padding: 18px;
  border-radius: var(--hud-radius);
  background:
    radial-gradient(120% 80% at 50% -10%, color-mix(in srgb, var(--accent-cyan) 10%, transparent), transparent 60%),
    rgba(8, 11, 15, 0.55);
  border: 1px solid var(--hud-cyan-faint);
  overflow: hidden;
  isolation: isolate;
}

/* 背景网格 + 晕影 */
.profile-center-page .hud-backgrid {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image:
    linear-gradient(var(--hud-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--hud-grid) 1px, transparent 1px);
  background-size: 40px 40px;
  -webkit-mask-image: radial-gradient(120% 100% at 50% 0%, #000 45%, transparent 100%);
  mask-image: radial-gradient(120% 100% at 50% 0%, #000 45%, transparent 100%);
  pointer-events: none;
}

/* 主网格 */
.profile-center-page .dashboard-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 16px;
  align-items: stretch;
}
.profile-center-page .dash-kpi { grid-column: 1 / -1; }
.profile-center-page .dash-rail { grid-column: 1 / 4; }
.profile-center-page .dash-main { grid-column: 4 / -1; }
.profile-center-page .dash-hero { grid-column: 1 / -1; }
.profile-center-page .dash-behavior { grid-column: 1 / 7; }
.profile-center-page .dash-preheat { grid-column: 7 / -1; }

/* 主内容子网格 */
.profile-center-page .dash-main {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 16px;
  align-content: start;
  min-width: 0;
}
.profile-center-page .dash-main > .hud-panel.trend { grid-column: 1 / -1; }
.profile-center-page .dash-main > .hud-panel.radar { grid-column: 1 / 7; }
.profile-center-page .dash-main > .hud-panel.aistatus { grid-column: 7 / -1; }
.profile-center-page .dash-main > .hud-panel.evolution { grid-column: 1 / 7; }
.profile-center-page .dash-main > .hud-panel.reading { grid-column: 7 / -1; }

/* 时间轴栏：沿用 timeline-rail 面板外观，取消 sticky */
.profile-center-page .profile-dashboard-v3 .timeline-rail {
  position: static;
  top: auto;
  max-height: none;
  border-radius: 10px;
}

/* ---- HUD 面板外壳 ---- */
.profile-center-page .hud-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 28%, transparent);
  border-radius: 10px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 5%, transparent), rgba(8,11,15,0.6));
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04), 0 12px 30px rgba(0,0,0,0.42);
  overflow: hidden;
}
.profile-center-page .hud-panel::after {
  content: "";
  position: absolute;
  left: 0; right: 0; top: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--panel-accent, var(--accent-cyan)), transparent);
  opacity: 0.7;
}
.profile-center-page .hud-corner {
  position: absolute;
  width: 14px; height: 14px;
  border: 2px solid var(--panel-accent, var(--accent-cyan));
  opacity: 0.85;
  z-index: 2;
}
.profile-center-page .hud-corner-tl { top: 7px; left: 7px; border-right: 0; border-bottom: 0; }
.profile-center-page .hud-corner-tr { top: 7px; right: 7px; border-left: 0; border-bottom: 0; }
.profile-center-page .hud-corner-bl { bottom: 7px; left: 7px; border-right: 0; border-top: 0; }
.profile-center-page .hud-corner-br { bottom: 7px; right: 7px; border-left: 0; border-top: 0; }

.profile-center-page .hud-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 5%, transparent), transparent);
}
.profile-center-page .hud-panel-titles { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.profile-center-page .hud-panel-kicker {
  font-family: var(--hud-font-mono);
  font-size: 9.5px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--hud-cyan-dim);
}
.profile-center-page .hud-panel-title {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--text-primary);
}
.profile-center-page .hud-panel-right { flex: none; }
.profile-center-page .hud-panel-tag {
  font-family: var(--hud-font-mono);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--hud-cyan-dim);
  border: 1px solid var(--hud-cyan-faint);
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--hud-cyan-ghost);
  white-space: nowrap;
}
.profile-center-page .hud-panel-tag.diff { color: #ffb74d; border-color: rgba(255,183,77,0.4); }
.profile-center-page .hud-panel-body { padding: 14px; flex: 1; min-width: 0; }

/* 主面板内的子卡去边框，交给 HudPanel 提供框 */
.profile-center-page .hud-panel-body .persona-hero,
.profile-center-page .hud-panel-body .info-card {
  border: 0;
  background: transparent;
  box-shadow: none;
  padding: 0;
}
.profile-center-page .hud-panel-body .info-card::before,
.profile-center-page .hud-panel-body .info-card::after { display: none; }

/* ---- KPI 火花条 ---- */
.profile-center-page .hud-kpi-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.profile-center-page .hud-kpi {
  position: relative;
  padding: 16px 18px 14px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 10px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 5%, transparent), rgba(8,11,15,0.5));
  overflow: hidden;
}
.profile-center-page .hud-kpi::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: var(--kpi-accent);
  box-shadow: 0 0 12px var(--kpi-accent);
}
.profile-center-page .hud-kpi-top { display: flex; align-items: baseline; gap: 8px; }
.profile-center-page .hud-kpi-value {
  font-family: var(--hud-font-mono);
  font-size: 32px;
  font-weight: 800;
  line-height: 1;
  color: var(--text-primary);
  text-shadow: 0 0 14px var(--kpi-accent);
}
.profile-center-page .hud-kpi-trend { font-size: 11px; }
.profile-center-page .hud-kpi-trend.up { color: #37f5b6; }
.profile-center-page .hud-kpi-trend.down { color: #ff6e9c; }
.profile-center-page .hud-kpi-label { display: block; margin-top: 7px; font-size: 12px; color: var(--text-secondary); }
.profile-center-page .hud-kpi-sub {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  color: var(--text-muted);
  font-family: var(--hud-font-mono);
}
.profile-center-page .hud-kpi-foot { margin-top: 10px; height: 34px; }
.profile-center-page .hud-kpi-meter { display: flex; align-items: flex-end; gap: 3px; height: 100%; }
.profile-center-page .hud-kpi-meter i {
  flex: 1;
  height: 100%;
  background: var(--kpi-accent);
  border-radius: 1px;
  box-shadow: 0 0 6px var(--kpi-accent);
  transform-origin: bottom;
  animation: hud-meter 1.1s ease both;
}

/* ---- 图表容器 ---- */
.profile-center-page .hud-linechart,
.profile-center-page .hud-barchart,
.profile-center-page .hud-radar { width: 100%; }
.profile-center-page .hud-linechart { position: relative; }
.profile-center-page .hud-linechart-svg,
.profile-center-page .hud-barchart-svg { width: 100%; height: auto; display: block; }
.profile-center-page .hud-radar-svg {
  width: 100%;
  max-width: 300px;
  height: auto;
  display: block;
  margin: 0 auto;
}
.profile-center-page .hud-axis-text {
  fill: var(--text-muted);
  font-size: 9px;
  font-family: var(--hud-font-mono);
}
.profile-center-page .hud-radar-label {
  fill: var(--hud-cyan-dim);
  font-size: 9.5px;
  font-family: var(--hud-font-mono);
}
.profile-center-page .hud-bar-value {
  fill: var(--text-primary);
  font-size: 10px;
  font-weight: 700;
  font-family: var(--hud-font-mono);
}
.profile-center-page .hud-radar-empty {
  text-align: center;
  color: var(--text-muted);
  font-size: 12px;
  padding: 40px 0;
  font-family: var(--hud-font-mono);
}

/* 悬停游标 tooltip */
.profile-center-page .hud-linechart-tip {
  position: absolute;
  top: 6px;
  transform: translateX(-50%);
  background: rgba(8,11,15,0.92);
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 6px;
  padding: 6px 9px;
  font-family: var(--hud-font-mono);
  font-size: 10px;
  color: var(--text-secondary);
  pointer-events: none;
  white-space: nowrap;
  box-shadow: 0 6px 18px rgba(0,0,0,0.5);
  z-index: 5;
}
.profile-center-page .hud-tip-label { display: block; color: var(--hradar-cyan, var(--accent-cyan)); margin-bottom: 3px; }
.profile-center-page .hud-tip-row { display: flex; align-items: center; gap: 5px; }
.profile-center-page .hud-tip-row i { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }

/* ---- 动画 ---- */
.profile-center-page .hud-draw-line {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: hud-draw 1.6s ease forwards;
}
@keyframes hud-draw { to { stroke-dashoffset: 0; } }
.profile-center-page .hud-draw-poly {
  transform-origin: center;
  animation: hud-pop 0.9s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes hud-pop { from { transform: scale(.2); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.profile-center-page .hud-bar-grow {
  transform-origin: bottom;
  animation: hud-bar 0.9s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes hud-bar { from { transform: scaleY(0); } to { transform: scaleY(1); } }
@keyframes hud-meter { from { transform: scaleY(0); } to { transform: scaleY(1); } }

/* ---- 响应式 ---- */
@media (max-width: 1100px) {
  .profile-center-page .dashboard-grid { grid-template-columns: 1fr; }
  .profile-center-page .dash-rail,
  .profile-center-page .dash-main,
  .profile-center-page .dash-hero,
  .profile-center-page .dash-behavior,
  .profile-center-page .dash-preheat { grid-column: 1 / -1; }
  .profile-center-page .dash-main { grid-template-columns: 1fr; }
  .profile-center-page .dash-main > .hud-panel.trend,
  .profile-center-page .dash-main > .hud-panel.radar,
  .profile-center-page .dash-main > .hud-panel.aistatus,
  .profile-center-page .dash-main > .hud-panel.evolution,
  .profile-center-page .dash-main > .hud-panel.reading { grid-column: 1 / -1; }
  .profile-center-page .hud-kpi-strip { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 560px) {
  .profile-center-page .hud-kpi-strip { grid-template-columns: 1fr; }
}

/* 减少动画 */
@media (prefers-reduced-motion: reduce) {
  .profile-center-page .hud-draw-line,
  .profile-center-page .hud-draw-poly,
  .profile-center-page .hud-bar-grow,
  .profile-center-page .hud-kpi-meter i { animation: none; }
  .profile-center-page .hud-draw-line { stroke-dashoffset: 0; }
  .profile-center-page .hud-draw-poly { transform: none; }
  .profile-center-page .hud-bar-grow { transform: none; }
}

/* ============================================================
 * Profile Settings — 精密网格布局（改造长条往下布局）
 * 把整页"一个 section 占一行"改为 12 栅格多列指挥中心。
 * 各 section 的 HUD 面板框（border / ::before / ::after）已在
 * 23442 段统一定义，这里只负责栅格排布与指标卡的精密化。
 * ============================================================ */
.profile-center-page .profile-settings-grid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
  align-items: start;
}
.profile-center-page .profile-settings-grid > * { min-width: 0; }

/* ---- 栅格跨度：多列排布，告别长条 ---- */
.profile-center-page .profile-settings-grid > .profile-persona-summary { grid-column: 1 / -1; }
.profile-center-page .profile-settings-grid > .profile-pending-suggestions { grid-column: 1 / -1; }
.profile-center-page .profile-settings-grid > .hud-stat-grid { grid-column: 1 / -1; }
.profile-center-page .profile-settings-grid > .profile-learning-panel { grid-column: 1 / span 8; }
.profile-center-page .profile-settings-grid > .profile-special-follows { grid-column: 9 / span 4; }
.profile-center-page .profile-settings-grid > .profile-control-layout { grid-column: 1 / -1; }
.profile-center-page .profile-settings-grid > .profile-calibration-panel { grid-column: 1 / span 6; }
.profile-center-page .profile-settings-grid > .profile-memory-panel { grid-column: 7 / span 6; }
.profile-center-page .profile-settings-grid > .profile-agent-memory { grid-column: 1 / span 6; }
.profile-center-page .profile-settings-grid > .profile-snapshot-history { grid-column: 7 / span 6; }

/* ---- 精密数据指标条（替代原 BlockStat 大卡，更紧凑、带进度条） ---- */
.profile-center-page .hud-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.profile-center-page .hud-stat-tile {
  position: relative;
  padding: 12px 14px 13px;
  border: 1px solid var(--hud-cyan-faint);
  border-radius: 10px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 5%, transparent), rgba(8, 11, 15, 0.5));
  display: flex;
  flex-direction: column;
  gap: 3px;
  overflow: hidden;
}
.profile-center-page .hud-stat-tile::before {
  content: "";
  position: absolute;
  top: 7px; left: 7px;
  width: 11px; height: 11px;
  border-top: 2px solid var(--hud-accent, var(--accent-cyan));
  border-left: 2px solid var(--hud-accent, var(--accent-cyan));
  opacity: 0.8;
  pointer-events: none;
}
.profile-center-page .hud-stat-label {
  font-family: var(--hud-font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--hud-cyan-dim);
  padding-left: 14px;
}
.profile-center-page .hud-stat-value {
  font-family: var(--hud-font-mono);
  font-size: 30px;
  font-weight: 800;
  line-height: 1;
  color: var(--text-primary);
  text-shadow: 0 0 14px color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  padding-left: 14px;
}
.profile-center-page .hud-stat-sub {
  font-size: 11px;
  color: var(--text-muted);
  padding-left: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.profile-center-page .hud-stat-bar {
  display: block;
  height: 4px;
  margin-top: 7px;
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 2px;
  overflow: hidden;
}
.profile-center-page .hud-stat-bar i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--accent-cyan), #37f5b6);
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 50%, transparent);
  border-radius: 2px;
  transition: width 0.6s ease;
}

/* 校准卡片在半宽面板内保持 2 列紧凑 */
.profile-center-page .profile-settings-grid .profile-calibration-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

/* 紧凑化：略减标题留白，体现"精密" */
.profile-center-page .profile-settings-grid .section-header { margin-bottom: 14px; }

/* ---- 响应式：宽屏多列，窄屏单列 ---- */
@media (max-width: 1080px) {
  .profile-center-page .profile-settings-grid > * { grid-column: 1 / -1 !important; }
  .profile-center-page .hud-stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 560px) {
  .profile-center-page .hud-stat-grid { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  .profile-center-page .hud-stat-bar i { transition: none; }
}

/* ============================================================
 * Profile Settings — 长列表滚动容器 / 空状态 / 折叠面板
 * 解决"布局混乱、长内容无限撑开页面"的核心问题。
 * ============================================================ */

/* ---- 长列表固定高度滚动（不再无限撑长页面） ---- */
.profile-center-page .profile-snapshot-list {
  max-height: 300px;
  overflow-y: auto;
  padding-right: 4px;
  /* 细滚动条 */
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--accent-cyan) 25%, transparent) transparent;
}
.profile-center-page .profile-snapshot-list::-webkit-scrollbar { width: 5px; }
.profile-center-page .profile-snapshot-list::-webkit-scrollbar-track { background: transparent; }
.profile-center-page .profile-snapshot-list::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  border-radius: 3px;
}

.profile-center-page .snapshot-list {
  max-height: 280px;
  overflow-y: auto;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--accent-cyan) 25%, transparent) transparent;
}
.profile-center-page .snapshot-list::-webkit-scrollbar { width: 5px; }
.profile-center-page .snapshot-list::-webkit-scrollbar-track { background: transparent; }
.profile-center-page .snapshot-list::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  border-radius: 3px;
}

.profile-center-page .memory-list {
  max-height: 340px;
  overflow-y: auto;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--accent-cyan) 25%, transparent) transparent;
}
.profile-center-page .memory-list::-webkit-scrollbar { width: 5px; }
.profile-center-page .memory-list::-webkit-scrollbar-track { background: transparent; }
.profile-center-page .memory-list::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--accent-cyan) 20%, transparent);
  border-radius: 3px;
}

/* ---- snapshot-item 紧凑化 ---- */
.profile-center-page .profile-snapshot {
  padding: 10px 12px !important;
}
.profile-center-page .profile-snapshot p {
  margin-top: 4px !important;
  font-size: 11px !important;
  line-height: 1.4 !important;
  color: var(--text-muted) !important;
}

/* ---- 空状态瘦身（设置页内不需要 60px padding 的空面板） ---- */
.profile-center-page .profile-settings-grid .profile-empty-state,
.profile-center-page .profile-settings-grid .empty-state {
  padding: 16px 20px !important;
  font-size: 12px !important;
}
.profile-center-page .profile-settings-grid .empty-state-hint {
  font-size: 11px !important;
  margin-top: 2px !important;
}

/* ---- 可折叠面板（<details>）—— 低优先级信息默认收起 ---- */
.profile-center-page .pset-collapsible {
  border: 1px solid var(--hud-cyan-faint, color-mix(in srgb, var(--accent-cyan) 10%, transparent));
  border-left: 2px solid color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  border-radius: var(--hud-radius, 10px);
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 2%, transparent), rgba(8,11,15,0.4));
  overflow: hidden;
}
.profile-center-page .pset-collapsible summary {
  cursor: pointer;
  list-style: none;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--hud-font-mono, 'Courier New', monospace);
  font-size: 13px;
  color: var(--hud-cyan-dim, color-mix(in srgb, var(--accent-cyan) 60%, transparent));
  user-select: none;
  transition: background 0.15s;
}
.profile-center-page .pset-collapsible summary:hover {
  background: color-mix(in srgb, var(--accent-cyan) 4%, transparent);
}
.profile-center-page .pset-collapsible summary::after {
  content: "▸";
  margin-left: auto;
  font-size: 11px;
  transition: transform 0.2s ease;
}
.profile-center-page .pset-collapsible[open] summary::after {
  transform: rotate(90deg);
}
.profile-center-page .pset-collapsible summary::-webkit-details-marker { display: none; }
.profile-center-page .pset-collapsible > *:not(summary) {
  padding: 0 14px 12px;
}
/* 折叠面板内的 section 去掉自带的 HUD 框，避免双层边框 */
.profile-center-page .pset-collapsible > section {
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
}
.profile-center-page .pset-collapsible > section::before,
.profile-center-page .pset-collapsible > section::after {
  display: none !important;
}
.profile-settings-layout{display:flex;gap:20px;align-items:flex-start;padding:0 24px 24px;}
.profile-module-nav{width:180px;flex-shrink:0;position:sticky;top:108px;max-height:calc(100vh - 130px);overflow-y:auto;display:flex;flex-direction:column;gap:2px;padding:10px;background:var(--bg-card);border:var(--panel-border);border-radius:var(--radius-card);backdrop-filter:blur(12px);}
.profile-module-nav-title{font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--text-muted);padding:4px 10px 8px;}
.profile-module-nav-item{display:flex;align-items:center;gap:8px;width:100%;padding:7px 10px;border:none;border-radius:6px;background:transparent;color:var(--text-secondary);font-size:12px;font-weight:600;text-align:left;cursor:pointer;transition:var(--transition-base);}
.profile-module-nav-item svg{width:15px;height:15px;flex-shrink:0;}
.profile-module-nav-item:hover{background:var(--bg-hover);color:var(--text-primary);}
.profile-module-nav-item.active{background:linear-gradient(135deg,var(--accent-cyan-soft),var(--accent-cyan-softer));border:1px solid var(--accent-cyan-border);color:var(--accent-cyan);}
.profile-module-content{flex:1;min-width:0;display:flex;flex-direction:column;gap:16px;}
.profile-module-content > [data-module]{display:none;}
.profile-module-content[data-active="learning"] > [data-module="learning"]{display:block;}
.profile-module-content[data-active="domains"] > [data-module="domains"]{display:block;}
.profile-module-content[data-active="sources"] > [data-module="sources"]{display:block;}
.profile-module-content[data-active="follows"] > [data-module="follows"]{display:block;}
.profile-module-content[data-active="calibration"] > [data-module="calibration"]{display:block;}
.profile-module-content[data-active="persona"] > [data-module="persona"]{display:block;}
.profile-module-content[data-active="suggestions"] > [data-module="suggestions"]{display:block;}
.profile-module-content[data-active="memory"] > [data-module="memory"]{display:block;}
.profile-module-content[data-active="snapshots"] > [data-module="snapshots"]{display:block;}
@media (max-width:900px){.profile-settings-layout{flex-direction:column;}.profile-module-nav{width:100%;position:static;flex-direction:row;flex-wrap:wrap;gap:8px;}.profile-module-nav-title{display:none;}.profile-module-nav-item{width:auto;flex:1;justify-content:center;}}

/* === Profile module page (each module independent) === */
.profile-module-page{padding:16px;border:var(--panel-border);border-radius:var(--radius-card);background:var(--bg-card);}

/* === Compact learning panel (single column, no grid) === */
.profile-learning-compact{display:flex;flex-direction:column;gap:12px;padding:16px;border:1px solid var(--accent-cyan-border);border-radius:var(--radius-card);background:var(--surface-workbench-ai);box-shadow:var(--shadow-card);}
.profile-learning-compact .profile-learning-main{display:flex;flex-direction:column;gap:8px;}
.profile-learning-compact .profile-learning-score{display:flex;align-items:baseline;gap:8px;}
.profile-learning-compact .profile-learning-score strong{font-size:24px;line-height:1;}
.profile-learning-compact .profile-learning-score span{font-size:11px;}
.profile-learning-compact .profile-learning-score p{font-size:12px;margin:0;}
.profile-learning-compact .profile-learning-actions{display:flex;gap:6px;flex-wrap:wrap;}
.profile-learning-compact .profile-learning-actions button{min-height:28px;padding:0 8px;font-size:11px;}
.profile-learning-compact .profile-learning-side{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;}
.profile-learning-compact .profile-learning-side div{padding:8px;border-radius:6px;}
.profile-learning-compact .profile-learning-side span{font-size:10px;margin-bottom:3px;}
.profile-learning-compact .profile-learning-side p{font-size:11px;line-height:1.4;}

/* === Inline calibration (rows instead of big cards) === */
.profile-calibration-inline{display:flex;flex-direction:column;gap:6px;}
.profile-calibration-row{display:flex;align-items:center;gap:12px;padding:8px 12px;border:var(--panel-border);border-radius:6px;background:var(--surface-workbench-control);min-height:auto;}
.profile-calibration-row span{margin-bottom:0;font-size:11px;min-width:80px;}
.profile-calibration-row strong{font-size:14px;}
.profile-calibration-row p{margin:0;font-size:11px;flex:1;min-width:0;}
.profile-calibration-row .calib-jump-hint{font-size:10px;min-width:auto;white-space:nowrap;}

/* === Section nav sticky adjustment for light mode === */
:root[data-mode="light"] .profile-section-nav{background:var(--surface-topbar);border-bottom-color:rgba(var(--hairline-tint),.07);}

/* === Compact section header for module pages === */
.profile-module-page .section-header{margin-bottom:10px;}
.profile-module-page .section-title{font-size:14px;margin:0 0 4px;}
.profile-module-page .section-desc{font-size:11px;}
.aviation-gauge{position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;}
.aviation-gauge svg{display:block;}
.aviation-gauge-value{fill:var(--text-primary);font:800 26px var(--hud-font-mono);}
.aviation-gauge-unit{fill:var(--text-muted);font:600 10px var(--hud-font-mono);letter-spacing:.12em;}
.aviation-gauge-cap{display:flex;flex-direction:column;align-items:center;gap:1px;}
.aviation-gauge-label{font-size:12px;font-weight:600;color:var(--text-secondary);}
.aviation-gauge-sub{font-size:10px;color:var(--text-muted);}
.profile-center-page .dash-aviation{grid-column:1 / -1;}
.profile-center-page .dash-aviation .hud-panel.aviation{background:radial-gradient(120% 120% at 50% 0%,color-mix(in srgb, var(--accent-cyan) 5%, transparent),transparent 60%),var(--hud-panel);}
.aviation-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;justify-items:center;padding:8px 4px;}
@media (max-width:1200px){.aviation-grid{grid-template-columns:repeat(2,1fr);}}
@media (max-width:600px){.aviation-grid{grid-template-columns:repeat(2,1fr);gap:10px;}}

/* ============================================================
 * Profile Overview — 画像总览（AI 眼中的你）
 * ============================================================ */
.profile-section-nav { display: flex; gap: 8px; padding: 8px 24px; flex-wrap: wrap; position: sticky; top: 52px; z-index: 40; background: var(--bg-secondary); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border-bottom: 1px solid var(--border-color); }
.profile-section-tab { display: inline-flex; align-items: center; gap: 6px; padding: 9px 16px; background: var(--bg-card); border: var(--panel-border); border-radius: 9px; color: var(--text-secondary); font-size: 13px; font-weight: 600; cursor: pointer; transition: var(--transition-base); }
.profile-section-tab svg { width: 15px; height: 15px; }
.profile-section-tab:hover { border-color: var(--border-active); color: var(--text-primary); }
.profile-section-tab.active { background: linear-gradient(135deg, var(--accent-cyan-soft), var(--accent-cyan-softer)); border-color: var(--accent-cyan-border); color: var(--accent-cyan); }

.profile-overview { display: flex; flex-direction: column; gap: 20px; padding: 0 24px 32px; }
.profile-overview-hero { display: grid; grid-template-columns: 1.6fr 1fr; gap: 20px; }
.profile-ai-summary, .profile-overview-stats, .profile-persona-card, .profile-radar-card, .profile-topics-card, .profile-prefs-card {
  background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); padding: 20px; backdrop-filter: blur(16px); }
.profile-ai-summary-text { font-size: 15px; line-height: 1.7; color: var(--text-primary); margin: 10px 0 8px; }
.profile-ai-summary-why { font-size: 12px; color: var(--text-muted); line-height: 1.6; }
.profile-confidence-bar { display: flex; align-items: center; gap: 10px; margin-top: 16px; }
.profile-confidence-label { font-size: 12px; color: var(--text-muted); white-space: nowrap; }
.profile-confidence-track { flex: 1; height: 8px; background: var(--bg-hover); border-radius: 99px; overflow: hidden; }
.profile-confidence-track i { display: block; height: 100%; background: linear-gradient(90deg, var(--accent-cyan), var(--accent-emerald)); border-radius: 99px; transition: width .6s ease; }
.profile-confidence-bar strong { font-size: 15px; font-family: var(--font-mono); color: var(--accent-cyan); }
.profile-overview-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; align-content: start; }
.profile-ov-stat { display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 14px 8px; background: var(--bg-hover); border-radius: 10px; }
.profile-ov-stat strong { font-size: 22px; font-weight: 800; color: var(--text-primary); font-family: var(--font-mono); }
.profile-ov-stat span { font-size: 11px; color: var(--text-muted); }

.profile-overview-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.profile-tag-cloud { display: flex; flex-wrap: wrap; gap: 8px; padding: 8px 0; }
.profile-tag-cloud-item { padding: 6px 13px; background: linear-gradient(135deg, var(--accent-cyan-soft), var(--accent-cyan-softer)); border: 1px solid var(--accent-cyan-border); border-radius: 99px; font-size: 13px; color: var(--text-primary); transition: var(--transition-base); }
.profile-empty-hint { color: var(--text-muted); font-size: 13px; padding: 12px 0; }
.profile-pref-rows { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }
.profile-pref-row { display: flex; flex-direction: column; gap: 3px; padding: 10px 14px; background: var(--bg-hover); border-radius: 8px; }
.profile-pref-label { font-size: 11px; color: var(--text-muted); }
.profile-pref-row strong { font-size: 14px; color: var(--text-primary); }

/* ============================================================
 * Profile Insights — 行为洞察
 * ============================================================ */
.profile-insights { display: flex; flex-direction: column; gap: 20px; padding: 0 24px 32px; }
.profile-insight-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
.profile-insight-card { background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); padding: 20px; backdrop-filter: blur(16px); }
.profile-insight-detail { background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); padding: 20px; backdrop-filter: blur(16px); }
.profile-insight-list { display: flex; flex-direction: column; gap: 14px; }
.profile-insight-row { display: flex; align-items: flex-start; gap: 16px; }
.profile-insight-label { width: 84px; flex-shrink: 0; font-size: 12px; color: var(--text-muted); padding-top: 5px; }
.profile-insight-content { flex: 1; min-width: 0; }
.profile-insight-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.profile-insight-tag { padding: 4px 10px; background: var(--bg-hover); border: 1px solid var(--border-color); border-radius: 6px; font-size: 12px; color: var(--text-secondary); }

@media (max-width: 900px) {
  .profile-overview-hero, .profile-overview-grid, .profile-insight-cards { grid-template-columns: 1fr; }
  .profile-insight-row { flex-direction: column; gap: 4px; }
  .profile-insight-label { width: auto; }
}

/* ============================================================
 * Profile Social — 我的社交
 * ============================================================ */
.profile-social { display: flex; flex-direction: column; gap: 20px; padding: 0 24px 32px; max-width: 720px; }
.profile-social-card { background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); overflow: hidden; backdrop-filter: blur(16px); }
.profile-social-cover { height: 96px; background: linear-gradient(120deg, var(--accent-cyan-soft), var(--accent-cyan-softer) 55%, transparent); border-bottom: 1px solid var(--border-color); }
.profile-social-head { padding: 0 24px 20px; margin-top: -40px; display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center; }
.profile-social-avatar { width: 88px; height: 88px; border-radius: 50%; overflow: hidden; border: 3px solid var(--bg-secondary); box-shadow: 0 0 0 3px var(--accent-cyan-border), 0 8px 24px rgba(0,0,0,.25); display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, var(--accent-cyan), var(--accent-blue)); }
.profile-social-avatar img { width: 100%; height: 100%; object-fit: cover; }
.profile-social-initial { font-size: 34px; font-weight: 800; color: #fff; }
.profile-social-name h2 { margin: 0; font-size: 22px; font-weight: 800; color: var(--text-primary); }
.profile-social-username { font-size: 13px; color: var(--text-muted); }
.profile-social-meta { display: flex; flex-direction: column; gap: 4px; align-items: center; }
.profile-social-signature { font-size: 13px; color: var(--text-secondary); font-style: italic; }
.profile-social-joined { font-size: 12px; color: var(--text-muted); display: inline-flex; align-items: center; gap: 4px; }
.profile-social-joined svg { width: 12px; height: 12px; }
.profile-social-stats-lg { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--border-color); }
.profile-social-stat { display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 16px 8px; }
.profile-social-stat strong { font-size: 20px; font-weight: 800; color: var(--accent-cyan); font-family: var(--font-mono); }
.profile-social-stat span { font-size: 11px; color: var(--text-muted); }
.profile-social-interests { background: var(--bg-card); border: var(--panel-border); border-radius: var(--radius-card); padding: 20px; backdrop-filter: blur(16px); }
.profile-social-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.profile-social-tag { display: inline-flex; align-items: center; gap: 5px; padding: 6px 12px; background: linear-gradient(135deg, var(--accent-cyan-soft), var(--accent-cyan-softer)); border: 1px solid var(--accent-cyan-border); border-radius: 99px; font-size: 13px; color: var(--text-primary); }
.profile-social-tag svg { width: 13px; height: 13px; }


/* === Profile section menu in HUD telemetry bar === */
.hud-section-menu{position:relative;display:inline-flex;align-items:center;}
.hud-section-menu-btn{display:flex;align-items:center;justify-content:center;width:28px;height:28px;border:1px solid color-mix(in srgb, var(--accent-cyan) 20%, transparent);border-radius:6px;background:color-mix(in srgb, var(--accent-cyan) 3%, transparent);color:color-mix(in srgb, var(--accent-cyan) 70%, transparent);cursor:pointer;transition:all .2s ease;}
.hud-section-menu-btn:hover{border-color:color-mix(in srgb, var(--accent-cyan) 40%, transparent);background:color-mix(in srgb, var(--accent-cyan) 8%, transparent);color:var(--accent-cyan);}
.hud-section-menu-btn svg{width:14px;height:14px;}
.hud-section-dropdown{position:absolute;top:100%;right:0;margin-top:6px;min-width:160px;background:var(--bg-card);border:1px solid var(--accent-cyan-border);border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,0.4);z-index:100;overflow:hidden;}
.hud-section-opt{display:flex;align-items:center;gap:8px;width:100%;padding:9px 14px;border:none;background:transparent;color:var(--text-secondary);font-size:13px;font-weight:600;text-align:left;cursor:pointer;transition:all .15s ease;}
.hud-section-opt:hover{background:var(--bg-hover);color:var(--text-primary);}
.hud-section-opt.active{background:color-mix(in srgb, var(--accent-cyan) 8%, transparent);color:var(--accent-cyan);}
.hud-section-opt svg{width:14px;height:14px;flex-shrink:0;}
.hud-section-icon{display:flex;align-items:center;}

/* ============================================================
   竞争情报监测面板（MonitorPage / 调研报告 M5）
   纯主题变量驱动，深浅模式自适应
   ============================================================ */
.monitor-page { padding: 20px 24px 40px; max-width: 1200px; margin: 0 auto; }
.monitor-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
.monitor-title { font-size: 22px; font-weight: 800; color: var(--text-primary); margin: 0; letter-spacing: .01em; }
.monitor-sub { margin: 6px 0 0; font-size: 13px; color: var(--text-muted); }
.monitor-stats { display: flex; gap: 12px; }
.monitor-stat { display: flex; flex-direction: column; align-items: center; min-width: 72px; padding: 10px 14px; background: var(--bg-elevated); border: 1px solid var(--panel-border); border-radius: 10px; }
.monitor-stat-val { font-size: 22px; font-weight: 800; color: var(--text-primary); line-height: 1.1; }
.monitor-stat-val.highlight { color: var(--accent-cyan); }
.monitor-stat-label { font-size: 11px; color: var(--text-muted); margin-top: 2px; }

.monitor-add { display: flex; gap: 10px; margin-bottom: 20px; flex-wrap: wrap; }
.monitor-input { flex: 1 1 280px; min-width: 200px; padding: 10px 14px; background: var(--bg-input); border: 1px solid var(--panel-border); border-radius: 10px; color: var(--text-primary); font-size: 14px; outline: none; }
.monitor-input::placeholder { color: var(--text-muted); }
.monitor-input:focus { border-color: var(--accent-cyan); box-shadow: 0 0 0 3px var(--accent-cyan-soft); }
.monitor-select { padding: 10px 12px; background: var(--bg-input); border: 1px solid var(--panel-border); border-radius: 10px; color: var(--text-primary); font-size: 14px; outline: none; cursor: pointer; }
.monitor-add-btn { padding: 10px 20px; border: none; border-radius: 10px; background: var(--accent-cyan); color: #fff; font-size: 14px; font-weight: 700; cursor: pointer; transition: filter .15s ease; }
.monitor-add-btn:hover { filter: brightness(1.08); }

.monitor-empty { padding: 28px; background: var(--bg-elevated); border: 1px dashed var(--panel-border); border-radius: 12px; color: var(--text-muted); font-size: 14px; text-align: center; }

.monitor-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 16px; }
.monitor-card { background: var(--bg-elevated); border: 1px solid var(--panel-border); border-radius: 12px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; cursor: pointer; transition: border-color .15s ease, transform .15s ease, box-shadow .15s ease; }
.monitor-card:hover { border-color: var(--accent-cyan); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-cyan) 35%, transparent); }
.monitor-card.active { border-color: var(--accent-cyan); }
.monitor-card .monitor-card-remove { cursor: pointer; }

/* 监测详情抽屉（点击卡片弹出） */
.monitor-drawer-overlay { position: fixed; inset: 0; z-index: 900; background: rgba(0,0,0,.45); animation: fadeIn .18s ease; }
.monitor-drawer { position: absolute; top: 0; right: 0; height: 100%; width: min(460px, 92vw); background: var(--bg-secondary); border-left: 1px solid var(--panel-border); display: flex; flex-direction: column; animation: slideInRight .22s ease; }
@keyframes monitorDrawerIn { from { transform: translateX(24px); opacity: 0; } to { transform: none; opacity: 1; } }
.monitor-drawer { animation: monitorDrawerIn .22s ease; }
.monitor-drawer-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 18px 20px 12px; border-bottom: 1px solid var(--panel-border); }
.monitor-drawer-title { margin: 6px 0 0; font-size: 18px; color: var(--text-primary); }
.monitor-drawer-close { width: 30px; height: 30px; border: 1px solid var(--panel-border); background: transparent; color: var(--text-muted); border-radius: 8px; font-size: 18px; cursor: pointer; flex-shrink: 0; }
.monitor-drawer-close:hover { color: var(--text-primary); border-color: var(--text-muted); }
.monitor-drawer-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; padding: 12px 20px; border-bottom: 1px solid var(--panel-border); }
.monitor-drawer-stats > div { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border: 1px solid var(--panel-border); border-radius: 8px; background: var(--bg-elevated); }
.monitor-drawer-stats strong { font-size: 15px; color: var(--accent-cyan); }
.monitor-drawer-stats span { font-size: 10px; color: var(--text-muted); }
.monitor-drawer-body { flex: 1; overflow-y: auto; padding: 12px 20px 20px; display: flex; flex-direction: column; gap: 12px; }
.monitor-drawer-item { border: 1px solid var(--panel-border); border-radius: 10px; padding: 12px 14px; background: var(--bg-elevated); }
/* v21：条目可点击 + hover 高亮（与资讯卡片预览一致的手感） */
.monitor-drawer-item.clickable { cursor: pointer; transition: border-color .15s ease, background .15s ease, transform .15s ease; }
.monitor-drawer-item.clickable:hover { border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 7%, var(--bg-elevated)); transform: translateX(3px); }
.monitor-drawer-item.clickable:hover .monitor-drawer-item-title { color: var(--accent-cyan); }
.monitor-drawer-item-hint { margin-left: auto; color: var(--accent-cyan); opacity: 0; transition: opacity .15s ease; font-size: 10px; }
.monitor-drawer-item.clickable:hover .monitor-drawer-item-hint { opacity: 1; }
.monitor-match.clickable { cursor: pointer; border-radius: 6px; padding: 4px 6px 8px; margin: 0 -6px; transition: background .15s ease; }
.monitor-match.clickable:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.monitor-match.clickable:hover .monitor-match-title { color: var(--accent-cyan); }
.monitor-drawer-item-title { margin: 0 0 6px; font-size: 13px; line-height: 1.5; color: var(--text-primary); }
.monitor-drawer-item-summary { margin: 0 0 8px; font-size: 11px; line-height: 1.7; color: var(--text-muted); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.monitor-drawer-item-meta { display: flex; flex-wrap: wrap; gap: 4px; font-size: 10px; color: var(--text-muted); }
.monitor-drawer-item-meta a { color: var(--accent-cyan); text-decoration: none; margin-left: auto; }
.monitor-drawer-item-meta a:hover { text-decoration: underline; }
.monitor-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.monitor-card-id { display: flex; align-items: center; gap: 8px; min-width: 0; }
.monitor-card-tag { flex-shrink: 0; font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 999px; color: var(--accent-cyan); border: 1px solid var(--accent-cyan); background: var(--accent-cyan-soft); }
.monitor-card-keyword { font-size: 15px; font-weight: 700; color: var(--text-primary); margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.monitor-card-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.monitor-card-count { font-size: 12px; color: var(--text-muted); white-space: nowrap; }
.monitor-card-remove { width: 24px; height: 24px; border: 1px solid var(--panel-border); background: transparent; color: var(--text-muted); border-radius: 6px; cursor: pointer; font-size: 16px; line-height: 1; display: flex; align-items: center; justify-content: center; }
.monitor-card-remove:hover { color: var(--accent-red, #ef4444); border-color: var(--accent-red, #ef4444); }
.monitor-card-empty { font-size: 13px; color: var(--text-muted); margin: 0; }
.monitor-matches { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; max-height: 220px; overflow-y: auto; }
.monitor-match { display: flex; flex-direction: column; gap: 2px; padding-bottom: 8px; border-bottom: 1px solid var(--panel-border); }
.monitor-match:last-child { border-bottom: none; padding-bottom: 0; }
.monitor-match-title { font-size: 13px; color: var(--text-secondary); line-height: 1.4; }
.monitor-match-meta { font-size: 11px; color: var(--text-muted); }
:root[data-mode="light"] .hud-section-dropdown{background:#fff;border-color:rgba(0,180,220,0.2);box-shadow:0 4px 16px rgba(0,0,0,0.1);}

/* ============================================================
   设置面板 → 关于 Tab（产品信息 + 作者联系）
   复用 .setting-item / .modal 设计系统；走主题变量随 12 palette + 深浅自动迁移
   ============================================================ */
.about-tab { display: flex; flex-direction: column; gap: 16px; }

/* —— 产品信息卡 —— */
.about-product-card {
  padding: 16px;
  background: var(--bg-secondary, var(--bg-primary));
  border: 1px solid var(--border-color);
  border-radius: 10px;
}
.about-product-head { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.about-brand-mark {
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Ma Shan Zheng', 'Noto Serif SC', serif;
  font-size: 26px; line-height: 1;
  color: var(--bg-primary);
  background: linear-gradient(135deg, var(--accent-cyan), var(--accent-emerald, var(--accent-cyan)));
  border-radius: 10px;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-cyan) 28%, transparent);
  flex-shrink: 0;
}
.about-product-meta { display: flex; flex-direction: column; gap: 2px; }
.about-product-name {
  font-size: 17px; font-weight: 700; color: var(--text-primary);
  letter-spacing: 0.04em;
}
.about-product-tagline {
  font-size: 12px; color: var(--accent-cyan);
  letter-spacing: 0.06em;
}
.about-product-desc { margin: 4px 0 12px; line-height: 1.6; }
.about-feature-list {
  list-style: none; padding: 0; margin: 0 0 14px;
  display: flex; flex-direction: column; gap: 6px;
}
.about-feature-list li {
  display: flex; align-items: flex-start; gap: 8px;
  font-size: 12.5px; color: var(--text-primary);
  line-height: 1.5;
}
.about-feature-glyph {
  color: var(--accent-cyan); font-weight: 700; flex-shrink: 0;
  margin-top: 1px;
}
.about-product-foot {
  display: flex; align-items: center; gap: 10px;
  padding-top: 12px;
  border-top: 1px dashed var(--border-color);
  font-size: 11px; color: var(--text-muted);
}
.about-version-pill {
  padding: 2px 8px;
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  color: var(--accent-cyan);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 36%, transparent);
  border-radius: 999px;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 10.5px;
  letter-spacing: 0.04em;
}
.about-copyright { letter-spacing: 0.03em; }

/* —— 作者联系卡 —— */
.about-author-card {
  padding: 16px;
  background: var(--bg-secondary, var(--bg-primary));
  border: 1px solid var(--border-color);
  border-radius: 10px;
}
.about-author-card > label { margin-bottom: 12px; }
.about-author-head {
  display: flex; align-items: center; gap: 12px;
  padding-bottom: 14px; margin-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}
.about-author-avatar {
  width: 44px; height: 44px;
  display: flex; align-items: center; justify-content: center;
  font-size: 20px; font-weight: 600;
  color: var(--bg-primary);
  background: linear-gradient(135deg, var(--accent-rose, var(--accent-amber, var(--accent-cyan))), var(--accent-amber, var(--accent-cyan)));
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--accent-rose, var(--accent-cyan)) 22%, transparent);
}
.about-author-name { font-size: 15px; font-weight: 600; color: var(--text-primary); line-height: 1.2; }
.about-author-role { font-size: 11.5px; color: var(--text-muted); margin-top: 2px; letter-spacing: 0.02em; }

.about-contact-list { display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px; }
.about-contact-row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  transition: border-color var(--dur-fast, 0.14s) var(--ease-out, ease-out);
}
.about-contact-row:hover { border-color: var(--accent-cyan); }
.about-contact-key {
  flex: 0 0 36px;
  font-size: 11.5px; color: var(--text-muted);
  letter-spacing: 0.04em;
}
.about-contact-value {
  flex: 1; min-width: 0;
  font-size: 13px; color: var(--text-primary);
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  text-decoration: none;
  word-break: break-all;
}
.about-contact-value:hover { color: var(--accent-cyan); }
.about-copy-btn {
  flex-shrink: 0;
  padding: 4px 10px;
  font-size: 11px; font-weight: 500;
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  border-radius: 6px;
  cursor: pointer;
  transition: background var(--dur-fast, 0.14s) var(--ease-out, ease-out), color var(--dur-fast, 0.14s) var(--ease-out, ease-out);
}
.about-copy-btn:hover {
  background: color-mix(in srgb, var(--accent-cyan) 22%, transparent);
  color: var(--text-primary);
}
.about-copy-btn:active { transform: scale(0.96); }

/* —— 微信 QR 区块 —— */
.about-wechat-block {
  display: flex; align-items: center; gap: 14px;
  padding: 12px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
}
.about-wechat-text { flex: 1; min-width: 0; }
.about-wechat-text .about-contact-key { flex: none; margin-bottom: 4px; }
.about-wechat-nick {
  font-size: 13px; color: var(--text-primary);
  font-weight: 500;
  margin-bottom: 4px;
}
.about-wechat-block .setting-note { margin: 0; }
.about-qr-thumb {
  flex-shrink: 0;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 6px;
  background: var(--bg-secondary, var(--bg-primary));
  border: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color var(--dur-fast, 0.14s) var(--ease-out, ease-out), transform var(--dur-fast, 0.14s) var(--ease-out, ease-out);
}
.about-qr-thumb:hover { border-color: var(--accent-cyan); transform: translateY(-1px); }
.about-qr-thumb:active { transform: scale(0.98); }
.about-qr-thumb img {
  width: 92px; height: 92px;
  display: block;
  border-radius: 4px;
  object-fit: cover;
}
.about-qr-hint { font-size: 10.5px; color: var(--text-muted); letter-spacing: 0.02em; }

/* —— QR 放大浮层 —— */
.about-qr-modal {
  position: fixed; inset: 0; z-index: 11000;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(4px);
  animation: aboutQrFadeIn 0.18s var(--ease-out, ease-out) both;
  cursor: zoom-out;
}
.about-qr-modal-card {
  position: relative;
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  padding: 20px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.5);
  cursor: default;
  animation: aboutQrPopIn 0.22s var(--ease-spring, cubic-bezier(0.34, 1.56, 0.64, 1)) both;
}
.about-qr-modal-img {
  width: 280px; height: 280px;
  border-radius: 8px;
  object-fit: contain;
  background: #fff;
  padding: 8px;
}
.about-qr-modal-caption { text-align: center; }
.about-qr-modal-name { font-size: 15px; font-weight: 600; color: var(--text-primary); }
.about-qr-modal-nick { font-size: 12px; color: var(--text-muted); margin-top: 4px; }
.about-qr-modal-close {
  position: absolute; top: 8px; right: 8px;
  width: 28px; height: 28px;
  display: flex; align-items: center; justify-content: center;
  font-size: 20px; line-height: 1;
  color: var(--text-muted);
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  cursor: pointer;
  transition: color var(--dur-fast, 0.14s) var(--ease-out, ease-out), border-color var(--dur-fast, 0.14s) var(--ease-out, ease-out);
}
.about-qr-modal-close:hover { color: var(--text-primary); border-color: var(--accent-cyan); }

@keyframes aboutQrFadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes aboutQrPopIn { from { opacity: 0; transform: scale(0.85); } to { opacity: 1; transform: scale(1); } }
/* ============================================================
   素材仓库（智创中心定位重设计）：storage-only
   参考 Eagle / Notion 数据库 / Google Drive 的仓库形态
   ============================================================ */
.repo-page {
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr);
  gap: 14px;
  width: 100%;
  min-height: 0;
  align-items: start;
}

/* ---- 左栏 ---- */
.repo-rail {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 12px 10px;
  border: var(--panel-border);
  border-radius: 12px;
  background: var(--surface-card, var(--bg-card));
  max-height: calc(100vh - 130px);
  overflow-y: auto;
}
.repo-rail-group { display: flex; flex-direction: column; gap: 2px; }
.repo-rail-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 8px 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  color: var(--text-muted);
  text-transform: uppercase;
}
.repo-rail-add {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  padding: 0 4px;
  border-radius: 4px;
}
.repo-rail-add:hover { color: var(--accent-cyan); background: var(--bg-secondary); }
.repo-rail-item {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  border: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 12.5px;
  padding: 6px 8px;
  border-radius: 7px;
  cursor: pointer;
  text-align: left;
  transition: background .12s;
}
.repo-rail-item:hover { background: var(--bg-secondary, rgba(127,127,127,.1)); }
.repo-rail-item.active { background: var(--accent-cyan-softer); color: var(--accent-cyan); }
.repo-rail-item-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  padding: 0;
  cursor: pointer;
  text-align: left;
}
.repo-rail-item-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.repo-rail-item-count { font-style: normal; font-size: 10.5px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.repo-rail-item.active .repo-rail-item-count { color: var(--accent-cyan); }
.repo-rail-item-actions {
  display: none;
  align-items: center;
  gap: 2px;
}
.repo-rail-item:hover .repo-rail-item-actions { display: inline-flex; }
.repo-rail-item-actions button {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 11px;
  padding: 0 3px;
  border-radius: 4px;
}
.repo-rail-item-actions button:hover { color: var(--text-primary); background: var(--bg-card); }
.repo-space-rename {
  width: 100%;
  font-size: 12px;
  padding: 3px 6px;
  border: 1px solid var(--accent-cyan);
  border-radius: 5px;
  background: var(--bg-card);
  color: var(--text-primary);
}
.repo-rail-tags { display: flex; flex-wrap: wrap; gap: 4px; padding: 2px 6px; }
.repo-tag-chip {
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-muted);
  font-size: 10.5px;
  padding: 2px 8px;
  border-radius: 999px;
  cursor: pointer;
  transition: all .12s;
}
.repo-tag-chip:hover { color: var(--text-primary); border-color: var(--text-muted); }
.repo-tag-chip.active {
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  color: var(--accent-cyan);
}
.repo-rail-bottom {
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid var(--border-subtle, rgba(128,128,128,.15));
}

/* ---- 主区 ---- */
.repo-main { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.repo-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.repo-toolbar .material-search { flex: 1; min-width: 200px; }
.repo-toolbar-spacer { flex: 0 0 8px; }
.repo-view-toggle {
  display: inline-flex;
  border: var(--panel-border);
  border-radius: 8px;
  overflow: hidden;
}
.repo-view-toggle button {
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 13px;
  padding: 6px 10px;
  cursor: pointer;
  transition: all .12s;
}
.repo-view-toggle button.active { background: var(--accent-cyan-softer); color: var(--accent-cyan); }

.repo-stats {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  padding: 8px 12px;
  border: var(--panel-border);
  border-radius: 10px;
  background: var(--surface-workbench-control, var(--surface-card));
  font-size: 12px;
  color: var(--text-muted);
}
.repo-stat b { color: var(--text-primary); font-variant-numeric: tabular-nums; margin-right: 2px; }
.repo-stat-types { display: inline-flex; gap: 8px; flex-wrap: wrap; }
.repo-stat-type { white-space: nowrap; }
.repo-stat-type::before { content: '·'; margin-right: 6px; color: var(--border-color); }
.repo-stat-size { margin-left: auto; font-variant-numeric: tabular-nums; opacity: .8; }

/* 列表视图 */
.repo-list {
  display: flex;
  flex-direction: column;
  border: var(--panel-border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--surface-card, var(--bg-card));
}
.repo-list-row {
  display: grid;
  grid-template-columns: auto 52px minmax(0, 1fr) 110px minmax(0, 160px) 76px auto;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle, rgba(128,128,128,.12));
  cursor: pointer;
  transition: background .12s;
  font-size: 12.5px;
}
.repo-list-row:last-child { border-bottom: none; }
.repo-list-row:hover { background: var(--bg-secondary, rgba(127,127,127,.07)); }
.repo-list-row.selected { background: var(--accent-cyan-softer); }
.repo-list-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-primary); }
.repo-list-source, .repo-list-tags, .repo-list-date {
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  color: var(--text-muted); font-size: 11px;
}
.repo-list-actions { display: inline-flex; gap: 4px; }
.repo-list-actions button {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 5px;
}
.repo-list-actions button:hover { background: var(--bg-card); color: var(--text-primary); }

/* 回收站 */
.repo-trash-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.repo-trash-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border: var(--panel-border);
  border-radius: 9px;
  background: var(--surface-card, var(--bg-card));
  font-size: 12.5px;
}
.repo-trash-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-primary); }
.repo-trash-date { color: var(--text-muted); font-size: 11px; white-space: nowrap; }
.repo-trash-actions { display: inline-flex; gap: 6px; }

/* 详情抽屉 */
.repo-drawer-backdrop { position: fixed; inset: 0; z-index: 90; background: rgba(0,0,0,.35); }
.repo-drawer {
  position: fixed;
  top: 12px;
  right: 12px;
  bottom: 12px;
  width: min(480px, 92vw);
  z-index: 91;
  display: flex;
  flex-direction: column;
  background: var(--bg-card, #1a1a1a);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: var(--panel-border);
  border-radius: 14px;
  box-shadow: 0 16px 48px rgba(0,0,0,.4);
  animation: repo-drawer-in .18s ease-out;
}
@keyframes repo-drawer-in {
  from { opacity: 0; transform: translateX(24px); }
  to { opacity: 1; transform: translateX(0); }
}
.repo-drawer-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border-subtle, rgba(128,128,128,.15));
}
.repo-drawer-title {
  flex: 1;
  min-width: 0;
  margin: 0;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.repo-drawer-close {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
}
.repo-drawer-close:hover { color: var(--text-primary); background: var(--bg-secondary); }
.repo-drawer-body { flex: 1; min-height: 0; overflow-y: auto; padding: 14px; display: flex; flex-direction: column; gap: 12px; }
.repo-drawer-content {
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 13px;
  line-height: 1.7;
  color: var(--text-primary);
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--bg-secondary, rgba(127,127,127,.08));
}
.repo-drawer-section { display: flex; flex-direction: column; gap: 4px; }
.repo-drawer-section label { font-size: 10.5px; font-weight: 700; color: var(--text-muted); letter-spacing: .05em; }
.repo-drawer-section textarea,
.repo-drawer-section input,
.repo-drawer-section select {
  border: 1px solid var(--border-color);
  border-radius: 7px;
  background: var(--bg-secondary, rgba(127,127,127,.06));
  color: var(--text-primary);
  font-size: 12px;
  padding: 6px 8px;
  resize: vertical;
}
.repo-drawer-section textarea:focus,
.repo-drawer-section input:focus,
.repo-drawer-section select:focus { outline: none; border-color: var(--accent-cyan); }
.repo-drawer-meta { display: flex; flex-direction: column; gap: 4px; font-size: 11px; color: var(--text-muted); }
.repo-drawer-meta a { color: var(--accent-cyan); text-decoration: none; }
.repo-drawer-foot {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px solid var(--border-subtle, rgba(128,128,128,.15));
}

/* 窄屏适配：左栏折叠为顶部横条 */
@media (max-width: 900px) {
  .repo-page { grid-template-columns: 1fr; }
  .repo-rail { position: static; max-height: none; flex-direction: row; flex-wrap: wrap; }
  .repo-rail-group { flex: 1 1 160px; }
  .repo-list-row { grid-template-columns: auto 52px minmax(0, 1fr) auto; }
  .repo-list-source, .repo-list-tags, .repo-list-date { display: none; }
}

/* ============================================================
   社区生态（微博式）：tabs / 分享 / markdown 阅读视图
   ============================================================ */
.community-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--border-subtle, rgba(128,128,128,.15));
}
.community-tab {
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 13px;
  padding: 8px 16px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: all .12s;
}
.community-tab:hover { color: var(--text-primary); }
.community-tab.active { color: var(--accent-cyan); border-bottom-color: var(--accent-cyan); font-weight: 600; }
.community-post-draft {
  padding: 0 6px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--accent-amber, #f59e0b) 18%, transparent);
  color: var(--accent-amber, #f59e0b);
  font-size: 10px;
  font-weight: 600;
}
.community-post-excerpt {
  max-height: 180px;
  overflow: hidden;
  position: relative;
  margin: 6px 0 0;
}
.community-post-excerpt::after {
  content: '';
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 48px;
  background: linear-gradient(transparent, var(--bg-card, var(--bg-primary)));
  pointer-events: none;
}
.community-post-body.md-body h1, .community-post-body.md-body h2, .community-post-body.md-body h3 {
  margin: .8em 0 .4em;
  line-height: 1.4;
}
.community-post-body.md-body p { margin: .5em 0; line-height: 1.75; }
.community-post-body.md-body pre {
  background: var(--bg-secondary, rgba(127,127,127,.1));
  padding: 10px 12px;
  border-radius: 8px;
  overflow-x: auto;
  font-size: 12px;
}
.community-post-body.md-body blockquote {
  margin: .6em 0;
  padding: 4px 12px;
  border-left: 3px solid var(--accent-cyan);
  color: var(--text-muted);
}
.community-post-body.md-body img { max-width: 100%; border-radius: 8px; }
.community-load-more { display: flex; justify-content: center; padding: 14px 0; }
.community-load-more button {
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-muted);
  padding: 8px 24px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 12.5px;
}
.community-load-more button:hover { color: var(--accent-cyan); border-color: var(--accent-cyan); }
.btn-publish-square {
  color: var(--accent-cyan) !important;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 40%, transparent) !important;
}
.btn-publish-square:disabled { opacity: .5; cursor: wait; }

/* Infinite workflow canvas */
.wf-canvas { position: relative; min-height: 520px; overflow: hidden; border: 1px solid var(--border-color, rgba(148,163,184,.22)); border-radius: 18px; background: #0b1220; user-select: none; cursor: grab; }

/* ===== v14 纯画布页：画布独占整屏，只有画布内浮动元素 ===== */
.feed.feed-canvas { padding: 0; overflow: hidden; display: flex; flex-direction: column; }
.canvas-page { position: relative; flex: 1; min-height: 0; display: flex; }
.canvas-page .wf-canvas { flex: 1; min-height: 0; height: auto; border: none; border-radius: 0; }
.canvas-float { position: absolute; z-index: 20; }
.canvas-float-name { top: 14px; left: 14px; }
.canvas-name-chip {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 7px 14px; border: 1px solid var(--border-color); border-radius: 999px;
  background: color-mix(in srgb, var(--bg-primary) 88%, transparent);
  color: var(--text-primary); font-size: 13px; font-weight: 700; cursor: pointer;
  backdrop-filter: blur(8px);
}
.canvas-name-chip:hover { border-color: var(--accent-cyan); }
.canvas-name-chip small { font-size: 10px; color: var(--text-muted); font-weight: 500; }
.canvas-name-input {
  width: 220px; padding: 7px 14px;
  border: 1px solid var(--accent-cyan); border-radius: 999px;
  background: var(--bg-primary); color: var(--text-primary);
  font-size: 13px; font-weight: 700; outline: none;
}
.canvas-float-actions { top: 14px; right: 14px; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; justify-content: flex-end; max-width: calc(100% - 200px); }
.canvas-page.ai-open .canvas-float-actions { right: 362px; max-width: calc(100% - 560px); }
.canvas-float-actions > button, .canvas-templates-wrap > button {
  padding: 6px 12px; border: 1px solid var(--border-color); border-radius: 999px;
  background: color-mix(in srgb, var(--bg-primary) 88%, transparent);
  color: var(--text-primary); font-size: 11.5px; cursor: pointer;
  backdrop-filter: blur(8px);
}
.canvas-float-actions > button:hover:not(:disabled), .canvas-templates-wrap > button:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-float-actions > button:disabled { opacity: 0.45; cursor: not-allowed; }
.canvas-templates-wrap { position: relative; display: inline-flex; }
.canvas-templates-pop {
  position: absolute; top: calc(100% + 6px); right: 0; z-index: 30;
  min-width: 200px; max-height: 260px; overflow-y: auto;
  padding: 6px;
  background: var(--bg-primary); border: 1px solid var(--border-color); border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  display: flex; flex-direction: column; gap: 2px;
}
.canvas-templates-pop button {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 7px 10px; border: 0; border-radius: 7px;
  background: transparent; color: var(--text-primary); font-size: 12px; cursor: pointer; text-align: left;
}
.canvas-templates-pop button:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.canvas-templates-pop small { color: var(--text-muted); font-size: 10px; }
/* 节点配置卡：画布右下浮动 */
.canvas-node-editor {
  right: 14px; bottom: 14px;
  width: 320px; max-height: min(52vh, 460px); overflow-y: auto;
  padding: 12px;
  background: var(--bg-primary); border: 1px solid var(--border-color); border-radius: 14px;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.3);
  display: flex; flex-direction: column; gap: 9px;
}
.canvas-node-editor .workflow-node-tools { display: flex; align-items: center; gap: 6px; }
.canvas-node-editor .workflow-node-tools b { font-size: 12px; color: var(--accent-cyan); }
.canvas-node-editor-space { flex: 1; }
.canvas-node-editor .workflow-node-tools button {
  padding: 3px 8px; border: 1px solid var(--border-color); border-radius: 6px;
  background: transparent; color: var(--text-primary); font-size: 11px; cursor: pointer;
}
.canvas-node-editor .workflow-node-tools button:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-node-editor .workflow-node-tools button.is-danger:hover { border-color: var(--status-critical, #f85149); color: var(--status-critical, #f85149); }
.canvas-node-editor label { display: flex; flex-direction: column; gap: 4px; }
.canvas-node-editor label > span { font-size: 10.5px; font-weight: 700; color: var(--text-muted); }
.canvas-node-editor input, .canvas-node-editor select, .canvas-node-editor textarea {
  width: 100%; padding: 6px 9px;
  border: 1px solid var(--border-color); border-radius: 8px;
  background: var(--bg-secondary); color: var(--text-primary);
  font-size: 12px; font-family: inherit; line-height: 1.5;
  outline: none; resize: vertical;
}
.canvas-node-editor input:focus, .canvas-node-editor select:focus, .canvas-node-editor textarea:focus { border-color: var(--accent-cyan); }
.canvas-node-editor .workflow-toggle { display: inline-flex; flex-direction: row; align-items: center; gap: 5px; white-space: nowrap; }
.canvas-node-editor .workflow-node-editor-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
/* 窄屏：节点配置卡收窄 */
@media (max-width: 1100px) {
  .canvas-node-editor { width: min(320px, calc(100vw - 28px)); }
  .canvas-float-actions { right: 14px; }
}
.wf-canvas:active { cursor: grabbing; }
.wf-world { position: absolute; left: 0; top: 0; width: 4000px; height: 3000px; transform-origin: 0 0; background-image: linear-gradient(rgba(148,163,184,.10) 1px, transparent 1px), linear-gradient(90deg, rgba(148,163,184,.10) 1px, transparent 1px); }
.wf-edges { position: absolute; inset: 0; overflow: visible; pointer-events: none; }
.wf-edge { fill: none; stroke: rgba(103,232,249,.65); stroke-width: 3; stroke-dasharray: 8 7; }
.wf-node { position: absolute; min-height: 118px; box-sizing: border-box; padding: 12px 14px; border: 1px solid rgba(148,163,184,.32); border-radius: 14px; background: rgba(15,23,42,.96); color: #e2e8f0; box-shadow: 0 12px 28px rgba(0,0,0,.24); cursor: move; }
.wf-node.selected { border-color: #67e8f9; box-shadow: 0 0 0 2px rgba(103,232,249,.2), 0 12px 28px rgba(0,0,0,.3); }
.wf-node.disabled { opacity: .55; }
.wf-node-head, .wf-node-io { display: flex; align-items: center; gap: 8px; font-size: 10px; color: #94a3b8; }
.wf-node-head { margin-bottom: 12px; } .wf-node-index { color: #67e8f9; font-weight: 800; } .wf-node-type { text-transform: uppercase; letter-spacing: .08em; }
.wf-node-off { margin-left: auto; color: #fca5a5; } .wf-node-title { display: block; font-size: 14px; } .wf-node-role { margin: 5px 0 12px; color: #94a3b8; font-size: 11px; line-height: 1.4; }
.wf-node-io { justify-content: space-between; border-top: 1px solid rgba(148,163,184,.16); padding-top: 8px; font-size: 9px; } .wf-node-io-arrow { color: var(--accent-cyan); }
.wf-node-off { color: var(--status-critical, #f85149); }
.wf-port { border-color: var(--bg-primary); background: var(--accent-cyan); }
.wf-edge { stroke: color-mix(in srgb, var(--accent-cyan) 52%, transparent); } .wf-port-in { left: -7px; } .wf-port-out { right: -7px; }
.wf-palette { position: absolute; z-index: 3; top: 14px; left: 14px; width: 150px; padding: 10px; border: 1px solid rgba(148,163,184,.22); border-radius: 12px; background: rgba(15,23,42,.92); }
.wf-palette-label { margin-bottom: 8px; color: #94a3b8; font-size: 11px; } .wf-palette-item { display: flex; align-items: center; gap: 8px; padding: 8px 6px; color: #e2e8f0; font-size: 12px; border-radius: 8px; cursor: grab; } .wf-palette-item:hover { background: rgba(103,232,249,.1); } .wf-palette-dot { width: 8px; height: 8px; border-radius: 50%; }
.wf-zoombar { position: absolute; z-index: 3; right: 14px; bottom: 14px; display: flex; align-items: center; gap: 7px; padding: 7px; border: 1px solid rgba(148,163,184,.22); border-radius: 10px; background: rgba(15,23,42,.92); } .wf-zoombar button { width: 28px; height: 28px; border: 0; border-radius: 7px; background: rgba(148,163,184,.12); color: #e2e8f0; cursor: pointer; } .wf-zoom-value { min-width: 42px; text-align: center; color: #cbd5e1; font-size: 11px; }
.wf-empty-hint { position: absolute; inset: 50% auto auto 50%; transform: translate(-50%,-50%); color: #94a3b8; font-size: 13px; }

/* Phase 3 collaboration */
.chat-page { width: 100%; max-width: 1480px; margin: 0 auto; padding: 28px; color: var(--text-primary); }
.chat-header { display:flex; justify-content:space-between; gap:24px; align-items:flex-end; margin-bottom:18px; }
.chat-header h1 { margin:4px 0 8px; font-size:28px; } .chat-header p { margin:0; color:var(--text-muted); }
.chat-header-actions { display:flex; gap:8px; } .chat-header-actions input,.chat-panel-title input,.chat-group-create input { min-width:130px; border:1px solid var(--border-color); border-radius:7px; padding:9px 10px; background:var(--bg-card); color:var(--text-primary); }
.chat-header-actions button,.chat-panel-title button,.chat-contact button,.chat-group-create button { border:1px solid var(--border-color); border-radius:7px; padding:8px 11px; background:var(--bg-card); color:var(--text-secondary); cursor:pointer; }
.chat-layout { display:grid; grid-template-columns:260px minmax(0,1fr) 280px; min-height:650px; overflow:hidden; border:1px solid var(--border-color); border-radius:12px; background:var(--bg-card); }
.chat-sidebar,.chat-contacts { padding:14px; background:color-mix(in srgb,var(--bg-secondary) 75%,transparent); } .chat-sidebar { border-right:1px solid var(--border-color); } .chat-contacts { border-left:1px solid var(--border-color); }
.chat-panel-title,.chat-main-head,.chat-contact,.chat-conversation { display:flex; align-items:center; gap:9px; } .chat-panel-title { justify-content:space-between; margin-bottom:12px; }
.chat-conversation { width:100%; padding:10px 8px; border:0; border-radius:8px; background:transparent; color:var(--text-primary); text-align:left; cursor:pointer; } .chat-conversation.active,.chat-conversation:hover { background:var(--bg-hover); }
.chat-conversation > span:last-child,.chat-contact > span:nth-child(2) { min-width:0; display:flex; flex-direction:column; gap:3px; } .chat-conversation small,.chat-contact small,.chat-main-head span { overflow:hidden; color:var(--text-muted); font-size:10px; text-overflow:ellipsis; white-space:nowrap; }
.chat-avatar { display:grid; flex:0 0 32px; width:32px; height:32px; place-items:center; border-radius:50%; background:var(--accent-cyan-soft); color:var(--accent-cyan); font-weight:800; }
.chat-main { display:flex; min-width:0; flex-direction:column; } .chat-main-head { justify-content:space-between; padding:14px 18px; border-bottom:1px solid var(--border-color); } .chat-main-head div { display:flex; flex-direction:column; gap:4px; } .chat-main-head code { color:var(--accent-amber); font-size:10px; }
.chat-messages { display:flex; flex:1; min-height:440px; flex-direction:column; gap:10px; overflow:auto; padding:18px; background:var(--bg-primary); } .chat-message { max-width:76%; align-self:flex-start; } .chat-message.mine { align-self:flex-end; text-align:right; } .chat-message-meta { margin-bottom:3px; color:var(--text-muted); font:10px var(--font-mono); } .chat-message p { margin:0; padding:9px 11px; border-radius:9px; background:var(--bg-card); color:var(--text-secondary); line-height:1.5; white-space:pre-wrap; } .chat-message.mine p { background:var(--accent-cyan-soft); }
.chat-composer { padding:12px; border-top:1px solid var(--border-color); } .chat-composer textarea { width:100%; min-height:70px; resize:vertical; border:1px solid var(--border-color); border-radius:8px; padding:10px; background:var(--bg-primary); color:var(--text-primary); } .chat-composer button { margin-top:8px; } .chat-share-pending { margin-bottom:7px; color:var(--accent-amber); font-size:11px; } .chat-share-pending button { margin:0 0 0 8px; padding:2px 6px; }
.chat-contact { padding:8px 0; } .chat-contact > span:nth-child(2) { flex:1; } .chat-group-create { display:flex; flex-direction:column; gap:8px; margin-top:18px; padding-top:16px; border-top:1px solid var(--border-color); } .chat-group-create label { color:var(--text-muted); font-size:11px; } .chat-group-create input[type=checkbox] { min-width:auto; margin-right:6px; } .chat-muted { padding:18px 8px; color:var(--text-muted); font-size:12px; } .chat-error { margin-bottom:10px; padding:10px; border:1px solid color-mix(in srgb,var(--signal-critical) 45%,transparent); border-radius:8px; color:var(--signal-critical); } .chat-share-card { margin-bottom:5px; padding:9px; border:1px solid var(--accent-amber); border-radius:8px; background:color-mix(in srgb,var(--accent-amber) 10%,var(--bg-card)); text-align:left; } .chat-share-card span,.chat-share-card small { display:block; color:var(--text-muted); font-size:10px; } .chat-share-card strong { display:block; margin:3px 0; } .chat-empty { min-height:420px; }
.wf-floating-inspector { position:absolute; z-index:5; top:14px; right:14px; width:220px; padding:12px; border:1px solid var(--accent-cyan); border-radius:10px; background:color-mix(in srgb,var(--bg-card) 94%,transparent); box-shadow:0 14px 32px rgba(0,0,0,.2); } .wf-floating-inspector-head { display:flex; justify-content:space-between; color:var(--accent-cyan); font:10px var(--font-mono); } .wf-floating-inspector-head button { border:0; background:transparent; color:var(--text-muted); cursor:pointer; } .wf-floating-inspector strong { display:block; margin-top:9px; } .wf-floating-inspector small { color:var(--accent-amber); } .wf-floating-inspector p { margin:7px 0 0; color:var(--text-muted); font-size:11px; line-height:1.5; }
@media (max-width:900px) { .chat-layout { grid-template-columns:220px minmax(0,1fr); } .chat-contacts { display:none; } .chat-header { align-items:flex-start; flex-direction:column; } }


/* === Profile dashboard v2: data visibility + user control === */
.profile-dashboard-v2.profile-overview { gap: 12px; padding: 0 24px 28px; }
.profile-dashboard-kpis { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.profile-metric { min-width: 0; display: grid; gap: 4px; padding: 10px 12px; border: 1px solid var(--border-color); border-top: 2px solid var(--accent-cyan); border-radius: 7px; background: var(--bg-card); }
.profile-metric.green { border-top-color: var(--accent-green, #35d07f); }
.profile-metric.amber { border-top-color: var(--accent-amber, #f3b562); }
.profile-metric.violet { border-top-color: var(--accent-violet, #a78bfa); }
.profile-metric span, .profile-metric small { color: var(--text-muted); font-size: 10px; }
.profile-metric strong { color: var(--text-primary); font: 700 20px/1 var(--font-mono); }
.profile-dashboard-v2 .profile-dashboard-grid { display: grid; gap: 12px; }
.profile-dashboard-grid-main { grid-template-columns: minmax(0, 1.55fr) minmax(280px, .9fr); }
.profile-dashboard-grid-secondary { grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); }
.profile-data-panel { min-width: 0; padding: 14px 16px; border: 1px solid var(--border-color); border-radius: 8px; background: linear-gradient(145deg, var(--bg-card), var(--bg-primary)); }
.profile-panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.profile-panel-kicker { color: var(--text-muted); font-size: 9px; letter-spacing: .16em; }
.profile-panel-head h2 { margin: 3px 0 0; color: var(--text-primary); font-size: 15px; }
.profile-panel-status { padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--accent-green, #35d07f) 35%, transparent); border-radius: 4px; color: var(--accent-green, #35d07f); font: 700 9px/1 var(--font-mono); }
.profile-panel-meta { color: var(--text-muted); font-size: 10px; white-space: nowrap; }
.profile-panel-summary { margin: 12px 0 8px; color: var(--text-secondary); font-size: 12px; line-height: 1.6; }
.profile-chart-caption, .profile-mini-legend { display: flex; align-items: center; justify-content: space-between; gap: 10px; color: var(--text-muted); font-size: 10px; }
.profile-chart-caption b { color: var(--accent-cyan); font-weight: 600; }
.profile-mini-legend { justify-content: flex-start; gap: 14px; margin-top: 4px; }
.profile-mini-legend .dot { display: inline-block; width: 6px; height: 6px; margin-right: 5px; border-radius: 50%; background: var(--accent-cyan); }
.profile-mini-legend .dot.green { background: var(--accent-green, #35d07f); }
.profile-heatmap-wrap { display: flex; gap: 10px; margin-top: 20px; }
.profile-heatmap-weekdays { width: 14px; display: grid; grid-template-rows: repeat(3, 1fr); color: var(--text-muted); font-size: 9px; }
.profile-heatmap-grid { display: grid; grid-template-columns: repeat(10, minmax(12px, 1fr)); grid-auto-rows: 14px; gap: 5px; flex: 1; }
.profile-heat-cell { border-radius: 3px; background: var(--bg-tertiary); }
.profile-heat-cell[data-level="1"], .profile-heatmap-foot i[data-level="1"] { background: color-mix(in srgb, var(--accent-cyan) 20%, var(--bg-tertiary)); }
.profile-heat-cell[data-level="2"], .profile-heatmap-foot i[data-level="2"] { background: color-mix(in srgb, var(--accent-cyan) 40%, var(--bg-tertiary)); }
.profile-heat-cell[data-level="3"], .profile-heatmap-foot i[data-level="3"] { background: color-mix(in srgb, var(--accent-cyan) 65%, var(--bg-tertiary)); }
.profile-heat-cell[data-level="4"], .profile-heatmap-foot i[data-level="4"] { background: var(--accent-cyan); }
.profile-heat-cell:hover { outline: 1px solid var(--accent-cyan); outline-offset: 2px; }
.profile-heatmap-foot { display: flex; align-items: center; justify-content: flex-end; gap: 4px; margin-top: 10px; color: var(--text-muted); font-size: 9px; }
.profile-heatmap-foot i { width: 10px; height: 10px; border-radius: 2px; background: var(--bg-tertiary); }
.profile-topic-divider { height: 1px; margin: 14px 0; background: var(--border-color); }
.profile-topic-head h3 { margin: 0; color: var(--text-primary); font-size: 11px; }
.profile-topic-head span { color: var(--text-muted); font-size: 10px; }
.profile-preference-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; margin-top: 12px; }
.profile-preference-grid > div { position: relative; display: grid; gap: 5px; padding: 10px; border: 1px solid var(--border-color); background: var(--bg-primary); }
.profile-preference-grid span { color: var(--text-muted); font-size: 10px; }
.profile-preference-grid strong { color: var(--text-primary); font-size: 13px; }
.profile-preference-grid i { height: 2px; background: var(--accent-cyan); opacity: .6; }
.profile-section-rail { display: flex; gap: 6px; padding: 0 24px 14px; overflow-x: auto; }
.profile-section-rail-item { display: inline-flex; align-items: center; gap: 6px; padding: 7px 10px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--bg-card); color: var(--text-muted); cursor: pointer; font-size: 11px; white-space: nowrap; }
.profile-section-rail-item:hover, .profile-section-rail-item.active { border-color: var(--accent-cyan-border); background: var(--accent-cyan-soft); color: var(--accent-cyan); }
.profile-section-rail-item svg { width: 13px; height: 13px; }
@media (max-width: 900px) { .profile-dashboard-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } .profile-dashboard-grid-main, .profile-dashboard-grid-secondary { grid-template-columns: 1fr; } .profile-preference-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) { .profile-dashboard-v2.profile-overview { padding-left: 12px; padding-right: 12px; } .profile-section-rail { padding-left: 12px; padding-right: 12px; } .profile-preference-grid { grid-template-columns: 1fr; } .profile-heatmap-grid { gap: 3px; } }


/* profile overview cleanup: remove visual noise */
.profile-dashboard-v2 .profile-panel-head h2 { display: block; font-weight: 650; letter-spacing: .01em; }
.profile-dashboard-v2 .profile-panel-head h2::before { content: ''; display: inline-block; width: 5px; height: 5px; margin: 0 7px 3px 0; border-radius: 50%; background: var(--accent-cyan); box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 55%, transparent); }
.profile-dashboard-v2 .profile-panel-summary { max-width: 62ch; }
.profile-dashboard-v2 .profile-data-panel { overflow: hidden; }
.profile-dashboard-v2 .profile-chart-caption { padding-top: 2px; }

/* ============================================================
   AI 工作站：多空间侧边栏 + 智能体 Tab + 团队中心（对标 WorkBuddy）
   ============================================================ */

/* ---------- Tab 行：三等分 + 运行中圆点 ---------- */
.session-tabs .session-tab { position: relative; display: inline-flex; align-items: center; gap: 4px; }
.session-tab-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--status-ok, #3fb950);
  box-shadow: 0 0 6px var(--status-ok, #3fb950);
  animation: tabDotPulse 1.6s ease-in-out infinite;
}
@keyframes tabDotPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

/* ---------- 置顶标记与会话动作 ---------- */
.session-pin-mark { flex: none; font-size: 10px; line-height: 1; }
.session-item .session-item-btn.session-item-pin { font-size: 12px; line-height: 1; }
.session-item { position: relative; }

/* ---------- 空间分区（WorkBuddy 式折叠列表） ---------- */
.space-section { margin: 2px 0; }
.space-row { display: flex; align-items: center; gap: 2px; }
.space-row-main {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 6px;
  padding: 6px 8px; border: 0; border-radius: 7px; background: transparent;
  color: var(--text-muted); font-size: 12px; cursor: pointer; text-align: left;
}
.space-row-main:hover { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); color: var(--text-primary); }
.space-section.is-active > .space-row .space-name { color: var(--accent-cyan); }
.space-arrow { display: inline-block; font-size: 10px; transition: transform 0.18s ease; color: var(--text-muted); flex: none; }
.space-arrow.open { transform: rotate(90deg); }
.space-icon { display: inline-flex; flex: none; opacity: 0.75; }
.space-name { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.space-count { font-size: 11px; opacity: 0.7; flex: none; }
.space-rename-input {
  flex: 1; min-width: 0; padding: 2px 6px; font-size: 12px;
  border: 1px solid var(--accent-cyan); border-radius: 4px;
  background: var(--bg-primary); color: var(--text-primary); outline: none;
}
.space-row-actions { display: none; align-items: center; gap: 2px; flex: none; }
.space-row:hover .space-row-actions { display: inline-flex; }
.space-act {
  border: 0; background: transparent; color: var(--text-muted);
  font-size: 11px; padding: 3px 5px; border-radius: 4px; cursor: pointer;
}
.space-act:hover { background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); color: var(--text-primary); }
.space-act.is-danger:hover { color: var(--status-critical, #f85149); }
.space-act.is-danger.confirm {
  background: var(--status-critical, #f85149); color: #fff; font-weight: 600;
}
.space-sessions { padding-left: 14px; }
.space-empty { padding: 6px 10px; font-size: 11px; color: var(--text-muted); opacity: 0.8; }

.space-create { padding: 4px 8px 8px; }
.space-create-btn {
  width: 100%; padding: 6px; border: 1px dashed var(--border-color); border-radius: 7px;
  background: transparent; color: var(--text-muted); font-size: 12px; cursor: pointer;
}
.space-create-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.space-create-input {
  width: 100%; padding: 6px 8px; font-size: 12px;
  border: 1px solid var(--accent-cyan); border-radius: 7px;
  background: var(--bg-primary); color: var(--text-primary); outline: none;
}
.space-create-hint {
  font-size: 11px; color: var(--status-warn, #d29922);
  padding: 2px 4px 4px; line-height: 1.5;
}

/* ---------- 智能体 Tab ---------- */
/* v8：占满剩余高度，把「今日速报」固定压在侧栏底部（此前内容撑开把底栏顶出视口） */
.agents-tab { padding: 10px; display: flex; flex-direction: column; gap: 8px; overflow-y: auto; flex: 1 1 0; min-height: 0; }
/* 群聊列表（v6：侧栏自由切换） */
.agents-chats { display: flex; flex-direction: column; gap: 4px; }
/* 群聊行（v12）：条目 + 悬停操作（重命名/解散）——群管理统一在侧栏 */
.agents-chat-row {
  position: relative; display: flex; align-items: center;
}
.agents-chat-row .agents-chat-item { border-radius: 9px; }
.agents-chat-row:hover .agents-chat-item { border-color: var(--accent-cyan); }
.agents-chat-row.active .agents-chat-item {
  border-color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 9%, transparent);
}
.agents-chat-acts {
  position: absolute; right: 6px; z-index: 5;
  display: none; align-items: center; gap: 2px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color); border-radius: 7px;
  padding: 1px 3px;
}
.agents-chat-row:hover .agents-chat-acts { display: inline-flex; }
.agents-chat-acts button {
  border: 0; background: transparent; color: var(--text-muted);
  font-size: 11px; line-height: 1; padding: 3px 5px; border-radius: 5px; cursor: pointer;
}
.agents-chat-acts button:hover { color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.agents-chat-acts button.is-danger:hover { color: var(--status-critical, #f85149); background: color-mix(in srgb, var(--status-critical, #f85149) 10%, transparent); }
.agents-chat-rename {
  width: 100%; padding: 6px 10px;
  border: 1px solid var(--accent-cyan); border-radius: 9px;
  background: var(--bg-primary); color: var(--text-primary);
  font-size: 12.5px; font-weight: 600; outline: none;
}
.agents-chat-item {
  display: flex; align-items: center; gap: 7px; width: 100%;
  padding: 7px 10px; border: 1px solid var(--border-color); border-radius: 9px;
  background: transparent; color: var(--text-primary); cursor: pointer; text-align: left;
  transition: all var(--ease-fast);
}
.agents-chat-item:hover { border-color: var(--accent-cyan); }
.agents-chat-item.active {
  border-color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 9%, transparent);
}
.agents-chat-dot {
  width: 7px; height: 7px; border-radius: 50%; flex: none;
  background: var(--border-color);
}
.agents-chat-item.active .agents-chat-dot {
  background: var(--accent-cyan);
  box-shadow: 0 0 5px color-mix(in srgb, var(--accent-cyan) 50%, transparent);
}
.agents-chat-name {
  flex: 1; min-width: 0; font-size: 12.5px; font-weight: 600;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.agents-chat-item.active .agents-chat-name { color: var(--accent-cyan); }
.agents-chat-item em { flex: none; font-style: normal; font-size: 10px; color: var(--text-muted); }
.agents-chat-new {
  padding: 6px; font-size: 11.5px; font-weight: 600;
  border: 1px dashed var(--border-color); border-radius: 9px;
  background: transparent; color: var(--text-muted); cursor: pointer;
  transition: all var(--ease-fast);
}
.agents-chat-new:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); border-style: solid; }
.agents-team-entry {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 10px 12px; border: 1px solid var(--border-color); border-radius: 10px;
  background: color-mix(in srgb, var(--accent-cyan) 6%, transparent);
  color: var(--text-primary); cursor: pointer; text-align: left;
}
.agents-team-entry:hover { border-color: var(--accent-cyan); }
.agents-team-entry-icon {
  display: inline-flex; width: 30px; height: 30px; border-radius: 8px; flex: none;
  align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); color: var(--accent-cyan);
}
.agents-team-entry-text { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.agents-team-entry-text strong { font-size: 13px; }
.agents-team-entry-text small { font-size: 11px; color: var(--text-muted); }
.agents-team-badge {
  margin-left: auto; flex: none; min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: 9px; background: var(--status-ok, #3fb950); color: #fff;
  font-size: 11px; font-weight: 700; display: inline-flex; align-items: center; justify-content: center;
}
.agents-running { display: flex; flex-direction: column; gap: 3px; }
.agents-running-label { font-size: 10px; color: var(--text-muted); letter-spacing: 0.08em; padding: 2px 4px; }
.agents-running-item {
  display: flex; align-items: center; gap: 6px; width: 100%;
  padding: 5px 8px; border: 0; border-radius: 6px; background: transparent;
  color: var(--text-primary); font-size: 12px; cursor: pointer; text-align: left;
}
.agents-running-item:hover { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.agents-running-dot {
  width: 6px; height: 6px; border-radius: 50%; flex: none;
  background: var(--status-ok, #3fb950); box-shadow: 0 0 6px var(--status-ok, #3fb950);
  animation: tabDotPulse 1.6s ease-in-out infinite;
}
.agents-running-goal { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.agents-running-item em { font-style: normal; margin-left: auto; font-size: 10px; color: var(--text-muted); flex: none; }
.agents-cap-label { font-size: 10px; color: var(--text-muted); letter-spacing: 0.1em; padding: 4px 4px 0; }
.agents-cap-list { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.agents-cap-item {
  padding: 8px; border: 1px solid var(--border-color); border-radius: 8px;
  background: var(--bg-secondary);
}
.agents-cap-name { font-size: 12px; font-weight: 600; color: var(--text-primary); display: block; }
.agents-cap-id { font-size: 10px; color: var(--accent-cyan); font-family: ui-monospace, monospace; }
.agents-cap-item p { margin: 4px 0 0; font-size: 10px; color: var(--text-muted); line-height: 1.5; }
/* 编排能力速览：纯文本行，不放卡片（v11） */
.agents-mode-hints { display: flex; flex-direction: column; gap: 4px; padding: 0 4px; }
.agents-mode-hints p { margin: 0; font-size: 10.5px; color: var(--text-muted); line-height: 1.5; }
.agents-mode-hints code {
  font-family: ui-monospace, monospace; font-size: 10px;
  color: var(--accent-cyan); margin-right: 5px;
}
.agents-open-center {
  margin-top: 2px; padding: 8px; border: 1px solid var(--accent-cyan); border-radius: 8px;
  background: transparent; color: var(--accent-cyan); font-size: 12px; font-weight: 600; cursor: pointer;
}
.agents-open-center:hover { background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); }

/* ---------- 团队中心页 ---------- */
.team-center-col { display: flex; flex-direction: column; min-width: 0; }
.team-center-topbar {
  display: flex; align-items: center; gap: 12px; padding: 5px 12px; /* v8 压缩：为对话区让空间 */
  border-bottom: 1px solid var(--border-color);
}
.team-center-back {
  border: 1px solid var(--border-color); border-radius: 7px; background: transparent;
  color: var(--text-primary); font-size: 12px; padding: 5px 10px; cursor: pointer;
}
.team-center-back:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.team-center-crumb { font-size: 11px; color: var(--text-muted); }
.team-center-scroll { flex: 1; overflow-y: auto; }
.team-center { padding: 18px 22px 40px; max-width: 1080px; margin: 0 auto; display: flex; flex-direction: column; gap: 14px; }
/* v10 精简顶栏：标题一行 + 右侧发起按钮；模式说明收进 tooltip */
.team-center-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.team-center-title { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.team-center-title h2 { margin: 0; font-size: 20px; color: var(--text-primary); }
.team-center-running { font-size: 11.5px; color: var(--status-ok, #3fb950); font-weight: 600; white-space: nowrap; }
.team-center-actions { display: flex; gap: 8px; flex: none; }
.team-launch-btn {
  border: 1px solid var(--border-color); border-radius: 7px; background: transparent;
  color: var(--text-primary); font-size: 12px; padding: 6px 12px; cursor: pointer;
}
.team-launch-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.team-launch-btn.is-primary {
  background: var(--accent-cyan); border-color: var(--accent-cyan); color: var(--bg-primary); font-weight: 700;
}
.team-launch-btn.is-primary:hover { filter: brightness(1.1); color: var(--bg-primary); }

/* 快速派活：一行 chips（职责/预算在 tooltip） */
.team-quick-row {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 8px 12px; border: 1px solid var(--border-color); border-radius: 10px;
  background: color-mix(in srgb, var(--bg-secondary) 60%, transparent);
}
.team-quick-label { font-size: 10.5px; font-weight: 700; color: var(--text-muted); letter-spacing: 0.06em; }
.team-quick-chip {
  padding: 4px 12px; border: 1px solid var(--border-color); border-radius: 999px;
  background: transparent; color: var(--text-primary); font-size: 12px; cursor: pointer;
  transition: all var(--ease-fast);
}
.team-quick-chip:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }

.team-list-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 10px; }
.team-list-head h3 { margin: 0; font-size: 15px; color: var(--text-primary); }
.team-list-head span { font-size: 11px; color: var(--text-muted); }
.team-empty {
  padding: 30px 22px; border: 1px dashed var(--border-color); border-radius: 12px;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
}
.team-empty p { margin: 0; font-size: 12.5px; color: var(--text-muted); }
.team-empty small { font-size: 11px; color: var(--text-muted); opacity: 0.8; }

.team-card { border: 1px solid var(--border-color); border-radius: 12px; background: var(--bg-secondary); margin-bottom: 10px; overflow: hidden; }
.team-card-head {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 11px 14px; border: 0; background: transparent; cursor: pointer; text-align: left;
}
.team-card-head:hover { background: color-mix(in srgb, var(--accent-cyan) 5%, transparent); }
.team-card-arrow { color: var(--text-muted); font-size: 11px; transition: transform 0.18s ease; flex: none; }
.team-card-arrow.open { transform: rotate(90deg); }
.team-status-badge {
  flex: none; font-size: 10px; font-weight: 700; padding: 2px 8px; border-radius: 9px;
}
.team-status-badge.is-running { background: color-mix(in srgb, var(--status-ok, #3fb950) 16%, transparent); color: var(--status-ok, #3fb950); }
.team-status-badge.is-done { background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); color: var(--accent-cyan); }
.team-status-badge.is-failed { background: color-mix(in srgb, var(--status-critical, #f85149) 14%, transparent); color: var(--status-critical, #f85149); }
.team-card-goal { flex: 1; min-width: 0; font-size: 13px; font-weight: 600; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.team-card-meta { flex: none; font-size: 11px; color: var(--text-muted); }
.team-card-body { padding: 4px 14px 14px; display: flex; flex-direction: column; gap: 12px; }
.team-members { display: flex; flex-wrap: wrap; gap: 6px; }
.team-member-chip {
  display: inline-flex; align-items: baseline; gap: 5px;
  padding: 3px 9px; border: 1px solid var(--border-color); border-radius: 9px; font-size: 11px;
  background: var(--bg-primary);
}
.team-member-chip b { color: var(--text-primary); font-weight: 600; }
.team-member-chip i { font-style: normal; color: var(--accent-cyan); font-size: 10px; font-family: ui-monospace, monospace; }

.team-kanban { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.team-kanban-col {
  padding: 8px; border-radius: 9px; background: var(--bg-primary);
  border: 1px solid var(--border-color); display: flex; flex-direction: column; gap: 6px; min-height: 60px;
}
.team-kanban-col-head {
  display: flex; align-items: center; justify-content: space-between;
  font-size: 10px; letter-spacing: 0.08em; color: var(--text-muted);
}
.team-kanban-col-head b { font-size: 11px; }
.team-kanban-col.is-in_progress .team-kanban-col-head { color: var(--accent-cyan); }
.team-kanban-col.is-done .team-kanban-col-head { color: var(--status-ok, #3fb950); }
.team-kanban-col.is-failed .team-kanban-col-head { color: var(--status-critical, #f85149); }
.team-kanban-empty { text-align: center; font-size: 10px; color: var(--text-muted); opacity: 0.5; padding: 6px 0; }
.team-task-card {
  padding: 6px 8px; border: 1px solid var(--border-color); border-radius: 7px;
  background: var(--bg-secondary); display: flex; flex-direction: column; gap: 3px;
}
.team-task-title { font-size: 11px; color: var(--text-primary); line-height: 1.45; }
.team-task-owner { font-size: 10px; color: var(--text-muted); }
.team-task-result { margin: 0; font-size: 10px; color: var(--text-muted); border-top: 1px dashed var(--border-color); padding-top: 3px; line-height: 1.5; }

.team-mailbox-toggle {
  display: inline-flex; align-items: center; gap: 6px; align-self: flex-start;
  border: 0; background: transparent; color: var(--accent-cyan); font-size: 12px; cursor: pointer; padding: 0;
}
.team-mailbox-list {
  list-style: none; margin: 0; padding: 8px; max-height: 260px; overflow-y: auto;
  border: 1px solid var(--border-color); border-radius: 9px; background: var(--bg-primary);
  display: flex; flex-direction: column; gap: 8px;
}
.team-mailbox-msg { display: flex; flex-direction: column; gap: 2px; }
.team-mailbox-route { font-size: 10px; color: var(--accent-cyan); font-family: ui-monospace, monospace; }
.team-mailbox-msg p { margin: 0; font-size: 11px; color: var(--text-primary); line-height: 1.55; }
.team-mailbox-msg time { font-size: 10px; color: var(--text-muted); }

@media (max-width: 1100px) {
  .team-kanban { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .team-center-head { flex-direction: column; align-items: flex-start; }
}

/* ============================================================
   AI 工作站 v3：空间×本地文件 + Agent Team 群聊
   ============================================================ */

/* ---------- 文件面板：空间标签 ---------- */
.workspace-space-tag {
  flex: none; max-width: 90px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  padding: 1px 7px; border-radius: 6px; font-size: 11px; font-weight: 700;
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); color: var(--accent-cyan);
}

/* ---------- 侧边栏：Agent Team 入口 ---------- */
.agents-team-entry.is-chat {
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 40%, var(--border-color));
}
.agents-roster-preview { display: flex; flex-wrap: wrap; gap: 5px; padding: 0 4px; }
.agents-roster-chip {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 2px 8px 2px 3px; border-radius: 999px; font-size: 11px;
  border: 1px solid var(--border-color); color: var(--text-primary);
  background: var(--bg-secondary);
}
/* 群成员 chip 的迷你头像（与群聊内同成员同色相） */
.agents-roster-avatar {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  width: 16px; height: 16px; border-radius: 50%; border: 1px solid;
  font-style: normal; font-weight: 700; font-size: 9px; line-height: 1;
}

/* ---------- Agent Team 群聊页 ---------- */
.gtc { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.gtc-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 10px 16px 4px; }
.gtc-head h2 { margin: 1px 0 2px; font-size: 16px; color: var(--text-primary); }
.gtc-head p { margin: 0; font-size: 10.5px; color: var(--text-muted); }
.gtc-head-actions { display: flex; gap: 8px; flex: none; }
.gtc-records-btn, .gtc-clear-btn {
  border: 1px solid var(--border-color); border-radius: 7px; background: transparent;
  color: var(--text-primary); font-size: 12px; padding: 5px 11px; cursor: pointer;
}
.gtc-records-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-clear-btn:hover { border-color: var(--status-critical, #f85149); color: var(--status-critical, #f85149); }

/* ---------- 群聊切换条（多群聊管理，v4） ---------- */
.gtc-chats-bar {
  display: flex; align-items: center; gap: 8px;
  padding: 0 16px 6px;
}
.gtc-chats-scroll {
  display: flex; align-items: center; gap: 6px;
  overflow-x: auto; min-width: 0; flex: 1 1 auto;
  scrollbar-width: thin;
}
.gtc-chat-chip {
  display: inline-flex; align-items: center; gap: 5px; flex: none;
  padding: 3px 10px; border: 1px solid var(--border-color); border-radius: 999px;
  background: transparent; color: var(--text-secondary);
  font-size: 11.5px; font-weight: 600; cursor: pointer;
  transition: all var(--ease-fast);
}
.gtc-chat-chip:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-chat-chip.active {
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}
.gtc-chat-chip small { font-size: 9.5px; color: var(--text-muted); font-weight: 500; }
.gtc-chat-chip.is-editing { cursor: default; }
.gtc-chat-chip input {
  width: 110px; font-size: 11.5px;
  border: 1px solid var(--accent-cyan); border-radius: 6px;
  background: var(--bg-primary); color: var(--text-primary); outline: none;
  padding: 1px 5px;
}
.gtc-chat-chip-act {
  border: none; background: transparent; color: var(--text-muted);
  font-size: 10px; cursor: pointer; padding: 0 1px; line-height: 1;
}
.gtc-chat-chip-act:hover { color: var(--accent-cyan); }
.gtc-chat-chip-act.is-danger:hover, .gtc-chat-chip-act.is-danger.confirm { color: var(--status-critical, #f85149); }
.gtc-chat-new {
  flex: none;
  padding: 3px 10px; font-size: 11.5px; font-weight: 600;
  border: 1px dashed var(--border-color); border-radius: 999px;
  background: transparent; color: var(--text-muted); cursor: pointer;
  transition: all var(--ease-fast);
}
.gtc-chat-new:hover:not(:disabled) { border-color: var(--accent-cyan); color: var(--accent-cyan); border-style: solid; }
.gtc-chat-new:disabled { opacity: .45; cursor: not-allowed; }
/* 系统失败气泡（接力异常中断提示） */
.gtc-msg .gtc-bubble .gtc-bubble-text { word-break: break-word; }

.gtc-roster {
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;
  padding: 4px 16px 8px; border-bottom: 1px solid var(--border-color);
}
.gtc-member {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 9px 3px 4px; border: 1px solid var(--border-color); border-radius: 999px;
  background: var(--bg-secondary);
}
.gtc-avatar {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  border-radius: 50%; border: 1.5px solid; font-weight: 700; line-height: 1;
}
.gtc-member-name { font-size: 12px; font-weight: 600; color: var(--text-primary); }
.gtc-member small { font-size: 10px; color: var(--text-muted); font-family: ui-monospace, monospace; }
.gtc-member-remove {
  border: 0; background: transparent; color: var(--text-muted); font-size: 13px;
  cursor: pointer; padding: 0 2px; line-height: 1;
}
.gtc-member-remove:hover { color: var(--status-critical, #f85149); }
.gtc-invite-wrap { position: relative; }
.gtc-invite-btn {
  border: 1px dashed var(--border-color); border-radius: 999px; background: transparent;
  color: var(--text-muted); font-size: 12px; padding: 4px 12px; cursor: pointer;
}
.gtc-invite-btn:hover:not(:disabled) { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-invite-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.gtc-invite-menu {
  position: absolute; top: calc(100% + 6px); left: 0; z-index: 40;
  min-width: 210px; padding: 6px;
  background: var(--bg-primary); border: 1px solid var(--border-color); border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  display: flex; flex-direction: column; gap: 2px;
}
.gtc-invite-menu button {
  display: flex; flex-direction: column; gap: 1px; text-align: left;
  padding: 7px 9px; border: 0; border-radius: 7px; background: transparent; cursor: pointer;
}
.gtc-invite-menu button:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.gtc-invite-menu b { font-size: 12px; color: var(--text-primary); }
.gtc-invite-menu small { font-size: 10px; color: var(--text-muted); }
.gtc-invite-empty { padding: 8px; font-size: 11px; color: var(--text-muted); text-align: center; }

.gtc-stream { flex: 1; min-height: 0; overflow-y: auto; padding: 12px 16px; display: flex; flex-direction: column; gap: 10px; overflow-anchor: none; }
/* 群聊流防抖动：flex 子项禁止收缩（流式增高时整列重排会挤压气泡产生抖动）；禁用原生滚动锚定（与手动贴底锚定冲突） */
.gtc-stream > * { flex-shrink: 0; }
.gtc-empty {
  margin: auto; max-width: 420px; text-align: center;
  border: 1px dashed var(--border-color); border-radius: 14px; padding: 26px 22px;
}
.gtc-empty-title { margin: 0 0 10px; font-size: 15px; font-weight: 700; color: var(--text-primary); }
.gtc-empty-desc { margin: 0 0 10px; font-size: 12px; color: var(--text-muted); line-height: 2; text-align: left; }
.gtc-empty-example {
  margin: 0; font-size: 11px; color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 8%, transparent);
  border-radius: 8px; padding: 8px 10px; text-align: left; line-height: 1.6;
}
.gtc-msg { display: flex; gap: 8px; max-width: 88%; }
.gtc-msg.is-user { align-self: flex-end; flex-direction: row-reverse; }
.gtc-msg.is-agent { align-self: flex-start; }
.gtc-bubble {
  padding: 9px 12px; border-radius: 12px; font-size: 13px; line-height: 1.65;
  border: 1px solid var(--border-color); background: var(--bg-secondary);
  color: var(--text-primary); min-width: 0;
}
.gtc-msg.is-user .gtc-bubble {
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 35%, var(--border-color));
  border-bottom-right-radius: 4px;
}
.gtc-msg.is-agent .gtc-bubble { border-bottom-left-radius: 4px; }
.gtc-msg.is-error .gtc-bubble { border-color: color-mix(in srgb, var(--status-critical, #f85149) 50%, var(--border-color)); }
.gtc-bubble-head { display: flex; align-items: baseline; gap: 8px; margin-bottom: 4px; }
.gtc-bubble-head b { font-size: 12px; color: var(--accent-cyan); }
.gtc-bubble-head small { font-size: 10px; color: var(--text-muted); }
.gtc-running-tag {
  font-size: 10px; color: var(--status-ok, #3fb950);
  animation: tabDotPulse 1.4s ease-in-out infinite;
}
/* 认领阶段标签：区分 Phase 1 认领声明与 Phase 2 完整产出 */
.gtc-phase-tag {
  font-size: 10px;
  padding: 0 5px;
  border-radius: 4px;
  color: var(--accent-cyan);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  flex: none;
}

/* ===== v8 紧凑顶栏：群名下拉 | 成员 chips + 邀请 | 导出/清空/记录 ===== */
.gtc-topbar {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 10px;
  padding: 6px 12px;
  border-bottom: 1px solid var(--border-color);
  flex: none;
  min-width: 0;
}
/* 居中群名（v12）：只显示名称，醒目；群管理在左侧栏 */
.gtc-topbar-title { min-width: 0; text-align: center; }
.gtc-topbar-title h3 {
  margin: 0; font-size: 15px; font-weight: 700; color: var(--text-primary);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.gtc-topbar .gtc-avatar-stack { justify-self: start; }
.gtc-topbar .gtc-topbar-actions { justify-self: end; }

.gtc-topbar-members {
  display: flex; align-items: center; gap: 6px;
  flex: 1 1 auto; min-width: 0; overflow-x: auto; overflow-y: visible;
  scrollbar-width: thin;
}
.gtc-member { flex: none; }
.gtc-member-chip {
  display: inline-flex; align-items: center; gap: 6px;
  border: 0; background: transparent; padding: 0;
  color: inherit; cursor: pointer; font: inherit;
}
.gtc-member-chip:hover .gtc-member-name { color: var(--accent-cyan); }
.gtc-topbar-actions { display: flex; gap: 6px; flex: none; }
.gtc-topbar-btn {
  padding: 4px 10px; border: 1px solid var(--border-color); border-radius: 7px;
  background: transparent; color: var(--text-primary); font-size: 11.5px; cursor: pointer;
  white-space: nowrap; transition: all var(--ease-fast);
}
.gtc-topbar-btn:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-invite-divider { height: 1px; background: var(--border-color); margin: 4px 0; }
.gtc-invite-create {
  padding: 6px 8px; border: 0; border-radius: 7px;
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  color: var(--accent-cyan); font-size: 12px; font-weight: 600; cursor: pointer;
  text-align: left;
}
.gtc-invite-create:hover { background: color-mix(in srgb, var(--accent-cyan) 20%, transparent); }

/* ===== 气泡常用操作（复制 / 存素材）：hover 浮现 ===== */
.gtc-bubble-foot {
  display: flex; align-items: center; gap: 8px;
  margin-top: 2px;
}
/* 微信同款节奏：气泡自身时间 / 执行元数据 hover 才浮现，密集消息流不噪音 */
.gtc-bubble-foot time, .gtc-bubble-meta {
  font-size: 10px; color: var(--text-muted);
  opacity: 0; transition: opacity .12s ease;
}
.gtc-msg:hover .gtc-bubble-foot time, .gtc-msg:hover .gtc-bubble-meta { opacity: 0.75; }
.gtc-msg.is-error .gtc-msg-actions { opacity: 1; }
.gtc-retry-btn { color: var(--status-critical, #f85149) !important; font-weight: 600; }
.gtc-msg-actions {
  display: inline-flex; gap: 4px;
  opacity: 0; transition: opacity .12s ease;
}
.gtc-msg:hover .gtc-msg-actions { opacity: 1; }
.gtc-msg-actions button {
  border: 0; background: transparent; color: var(--text-muted);
  font-size: 10.5px; padding: 1px 5px; border-radius: 5px; cursor: pointer;
}
.gtc-msg-actions button:hover {
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}

/* ===== 成员角色卡（portal 弹层） ===== */
.gtc-card-backdrop {
  position: fixed; inset: 0; z-index: 1000;
  background: rgba(0, 0, 0, 0.35);
}
.gtc-role-card {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
  z-index: 1001;
  width: min(430px, 92vw); max-height: 86vh;
  display: flex; flex-direction: column;
  background: var(--bg-card, var(--bg-primary));
  border: 1px solid var(--border-color); border-radius: 14px;
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}
.gtc-role-card-head {
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px; border-bottom: 1px solid var(--border-color);
}
.gtc-role-card-avatar {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  width: 36px; height: 36px; border-radius: 10px;
  background: color-mix(in srgb, var(--accent-cyan) 16%, transparent);
  color: var(--accent-cyan); border: 1px solid color-mix(in srgb, var(--accent-cyan) 40%, transparent);
  font-size: 16px; font-weight: 700;
}
.gtc-role-card-avatar.is-custom {
  background: color-mix(in srgb, #c9a961 16%, transparent);
  color: #c9a961; border-color: color-mix(in srgb, #c9a961 40%, transparent);
}
.gtc-role-card-title { flex: 1; min-width: 0; }
.gtc-role-card-title h3 { margin: 0; font-size: 14px; color: var(--text-primary); }
.gtc-role-card-title small { font-size: 10.5px; color: var(--text-muted); }
.gtc-role-card-close {
  border: 0; background: transparent; color: var(--text-muted);
  font-size: 14px; cursor: pointer; padding: 4px;
}
.gtc-role-card-close:hover { color: var(--text-primary); }
.gtc-role-card-body {
  flex: 1 1 auto; min-height: 0; overflow-y: auto;
  padding: 12px 14px; display: flex; flex-direction: column; gap: 12px;
}
.gtc-role-field { display: flex; flex-direction: column; gap: 5px; }
.gtc-role-field > span { font-size: 11px; font-weight: 700; color: var(--text-muted); }
.gtc-role-field input,
.gtc-role-field textarea {
  width: 100%; padding: 7px 10px;
  border: 1px solid var(--border-color); border-radius: 8px;
  background: var(--bg-secondary); color: var(--text-primary);
  font-size: 12.5px; font-family: inherit; line-height: 1.5;
  resize: vertical; outline: none;
  transition: border-color .15s ease;
}
.gtc-role-field input:focus,
.gtc-role-field textarea:focus { border-color: var(--accent-cyan); }
.gtc-role-meta {
  display: flex; flex-direction: column; gap: 4px;
  font-size: 10.5px; color: var(--text-muted);
}
.gtc-role-meta code {
  font-family: ui-monospace, monospace; font-size: 10.5px;
  color: var(--text-muted);
}
.gtc-role-card-foot {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 14px; border-top: 1px solid var(--border-color);
}
.gtc-role-card-foot-space { flex: 1; }
.gtc-role-card-btn {
  padding: 6px 14px; border: 1px solid var(--border-color); border-radius: 8px;
  background: transparent; color: var(--text-primary); font-size: 12.5px; cursor: pointer;
  transition: all var(--ease-fast);
}
.gtc-role-card-btn:hover:not(:disabled) { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-role-card-btn.primary {
  background: color-mix(in srgb, var(--accent-cyan) 16%, transparent);
  border-color: color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  color: var(--accent-cyan); font-weight: 600;
}
.gtc-role-card-btn.primary:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-cyan) 26%, transparent);
}
.gtc-role-card-btn.primary:disabled { opacity: 0.45; cursor: not-allowed; }
.gtc-role-card-btn.danger { color: var(--status-critical, #f85149); border-color: color-mix(in srgb, var(--status-critical, #f85149) 35%, var(--border-color)); }
.gtc-role-card-btn.danger:hover { border-color: var(--status-critical, #f85149); }
.gtc-role-card-btn.danger.confirm {
  background: color-mix(in srgb, var(--status-critical, #f85149) 16%, transparent);
}
.gtc-bubble-text { white-space: pre-wrap; word-break: break-word; }
/* 成员报告的 Markdown 渲染排版（气泡内收敛尺寸） */
.gtc-markdown { white-space: normal; }
.gtc-markdown > :first-child { margin-top: 0; }
.gtc-markdown > :last-child { margin-bottom: 0; }
.gtc-markdown h1, .gtc-markdown h2, .gtc-markdown h3, .gtc-markdown h4 {
  margin: 10px 0 4px; font-size: 13px; font-weight: 700; color: var(--text-primary); line-height: 1.4;
}
.gtc-markdown h1 { font-size: 14px; }
.gtc-markdown p { margin: 4px 0; }
.gtc-markdown ul, .gtc-markdown ol { margin: 4px 0; padding-left: 18px; }
.gtc-markdown li { margin: 2px 0; }
.gtc-markdown code {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 11.5px;
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 4px; padding: 1px 4px;
}
.gtc-markdown pre {
  margin: 6px 0; padding: 8px 10px;
  background: var(--bg-primary); border: 1px solid var(--border-color);
  border-radius: 8px; overflow-x: auto;
}
.gtc-markdown pre code { background: transparent; padding: 0; }
.gtc-markdown blockquote {
  margin: 6px 0; padding: 2px 10px;
  border-left: 3px solid color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  color: var(--text-muted);
}
.gtc-markdown table { border-collapse: collapse; margin: 6px 0; font-size: 12px; width: 100%; }
.gtc-markdown th, .gtc-markdown td { border: 1px solid var(--border-color); padding: 4px 8px; text-align: left; }
.gtc-markdown th { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.gtc-markdown a { color: var(--accent-cyan); }
.gtc-bubble time { display: block; margin-top: 4px; font-size: 10px; color: var(--text-muted); text-align: right; }
.gtc-typing { display: flex; gap: 4px; padding: 4px 0; }
.gtc-typing span {
  width: 6px; height: 6px; border-radius: 50%; background: var(--text-muted);
  animation: gtcBlink 1.2s ease-in-out infinite;
}
.gtc-typing span:nth-child(2) { animation-delay: 0.15s; }
.gtc-typing span:nth-child(3) { animation-delay: 0.3s; }
@keyframes gtcBlink { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }
.gtc-pipeline-hint {
  align-self: center; font-size: 11px; color: var(--text-muted);
  padding: 4px 12px; border-radius: 999px;
  background: color-mix(in srgb, var(--status-ok, #3fb950) 8%, transparent);
  color: var(--status-ok, #3fb950);
}

/* ===== v9 消息语义：时间分隔线 / 居中系统行 / 引用块 / @ 高亮 / 流式光标 ===== */
.gtc-body { display: flex; flex: 1 1 auto; min-height: 0; }
.gtc-main { position: relative; flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; }
.gtc-stream { flex: 1; min-height: 0; }

/* 居中时间分隔线（相邻消息 >5 分钟时插入，微信同款） */
.gtc-time-divider {
  display: flex; align-items: center; gap: 10px;
  margin: 6px 0 2px; align-self: center; max-width: 78%;
}
.gtc-time-divider::before, .gtc-time-divider::after {
  content: ''; flex: 1; height: 1px;
  background: color-mix(in srgb, var(--border-color) 70%, transparent);
}
.gtc-time-divider span {
  flex: none; font-size: 10px; color: var(--text-muted);
  padding: 1px 8px; border-radius: 999px;
  background: color-mix(in srgb, var(--border-color) 28%, transparent);
}

/* 居中系统行：群生命周期 + 流水线事件（微信"XX加入了群聊"同款） */
.gtc-system-line {
  align-self: center; max-width: 82%;
  font-size: 11px; color: var(--text-muted); text-align: center;
  padding: 2px 10px; line-height: 1.6;
  word-break: break-word;
}

/* 创始人头像（金色，右侧消息位） */
.gtc-avatar-founder,
.gtc-msg.is-user .gtc-avatar-founder {
  background: color-mix(in srgb, #c9a961 20%, transparent);
  color: #c9a961;
  border-color: color-mix(in srgb, #c9a961 55%, transparent);
}

/* 用户消息里的 @成员：指派语义高亮（微信蓝色 @ 同款思路） */
.gtc-mention {
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-radius: 4px; padding: 0 3px; font-weight: 600;
}

/* 接力引用块（微信引用样式）：置灰小块，点击定位原消息 */
.gtc-quote {
  display: flex; align-items: baseline; gap: 6px;
  width: 100%; margin-bottom: 5px; padding: 4px 8px;
  border: 0; border-left: 2px solid color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  border-radius: 6px; text-align: left; cursor: pointer;
  background: color-mix(in srgb, var(--border-color) 22%, transparent);
}
.gtc-quote:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.gtc-quote-from { flex: none; font-size: 10.5px; font-weight: 700; color: var(--accent-cyan); }
.gtc-quote-text {
  font-size: 10.5px; color: var(--text-muted); line-height: 1.4;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* 流式渐进渲染：打字机光标 */
.gtc-streaming { white-space: pre-wrap; word-break: break-word; }
.gtc-streaming::after {
  content: '▍'; margin-left: 1px; color: var(--accent-cyan);
  animation: gtcCaretBlink 0.9s steps(1) infinite;
}
@keyframes gtcCaretBlink { 50% { opacity: 0; } }

/* 引用跳转命中闪烁 */
.gtc-flash { animation: gtcFlash 1.4s ease; border-radius: 10px; }
@keyframes gtcFlash {
  0%, 55% { background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent-cyan) 40%, transparent); }
  100% { background: transparent; }
}

/* 认领语义标签配色：认领=青、关注=金、旁观=灰、产出=绿 */
.gtc-phase-tag.is-watch { color: #c9a961; border-color: color-mix(in srgb, #c9a961 40%, transparent); background: color-mix(in srgb, #c9a961 10%, transparent); }
.gtc-phase-tag.is-bystander { color: var(--text-muted); border-color: var(--border-color); background: color-mix(in srgb, var(--border-color) 18%, transparent); }
.gtc-phase-tag.is-work {
  color: var(--status-ok, #3fb950);
  border-color: color-mix(in srgb, var(--status-ok, #3fb950) 40%, transparent);
  background: color-mix(in srgb, var(--status-ok, #3fb950) 10%, transparent);
}

/* ===== v9 顶栏成员头像叠放 + 群信息面板开关 ===== */
.gtc-avatar-stack {
  display: inline-flex; align-items: center; gap: 0;
  margin-left: 2px; padding: 3px 8px 3px 4px;
  border: 1px solid transparent; border-radius: 999px;
  background: transparent; cursor: pointer;
  transition: all var(--ease-fast);
}
.gtc-avatar-stack .gtc-avatar { margin-left: -6px; box-shadow: 0 0 0 2px var(--bg-secondary); }
.gtc-avatar-stack .gtc-avatar:first-child { margin-left: 0; }
.gtc-avatar-stack-count { margin-left: 5px; font-size: 10.5px; color: var(--text-muted); font-weight: 600; }
.gtc-avatar-stack:hover, .gtc-avatar-stack.open { border-color: var(--border-color); background: color-mix(in srgb, var(--border-color) 14%, transparent); }
.gtc-panel-toggle.active { border-color: var(--accent-cyan); color: var(--accent-cyan); }

/* ===== v9 右侧群信息面板（公告 / 成员网格 / 记录筛选 / 快捷入口） ===== */
.gtc-panel {
  flex: none; width: 258px;
  border-left: 1px solid var(--border-color);
  padding: 12px 12px 16px;
  display: flex; flex-direction: column; gap: 16px;
  overflow-y: auto;
  background: color-mix(in srgb, var(--bg-secondary) 55%, transparent);
}
.gtc-panel-sec { display: flex; flex-direction: column; gap: 8px; }
.gtc-panel-cap {
  display: flex; align-items: center; justify-content: space-between;
  font-size: 10.5px; font-weight: 700; color: var(--text-muted); letter-spacing: 0.06em;
}
.gtc-panel-cap-act {
  border: 0; background: transparent; padding: 1px 6px; border-radius: 5px;
  color: var(--accent-cyan); font-size: 10.5px; cursor: pointer; letter-spacing: normal;
}
.gtc-panel-cap-act:hover { background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); }
.gtc-ann-body {
  margin: 0; padding: 8px 10px; border-radius: 9px;
  border: 1px dashed var(--border-color);
  font-size: 12px; line-height: 1.7; color: var(--text-primary);
  white-space: pre-wrap; word-break: break-word;
}
.gtc-ann-body.is-empty { color: var(--text-muted); font-size: 11.5px; }
.gtc-ann-editor { display: flex; flex-direction: column; gap: 6px; }
.gtc-ann-editor textarea {
  width: 100%; padding: 8px 10px; border-radius: 9px;
  border: 1px solid var(--accent-cyan); background: var(--bg-primary);
  color: var(--text-primary); font-size: 12px; font-family: inherit; line-height: 1.6;
  resize: vertical; outline: none;
}
.gtc-ann-actions { display: flex; justify-content: flex-end; }
/* ===== v26 #12 Goal 目标机制：面板状态条 ===== */
.gtc-goal-bar {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  margin-top: 8px; padding: 6px 2px 0;
}
.gtc-goal-status {
  flex: none; padding: 2px 9px; border-radius: 999px;
  font-size: 10.5px; font-weight: 700; letter-spacing: 0.02em;
  border: 1px solid var(--border-color); color: var(--text-muted);
}
.gtc-goal-status.is-running {
  border-color: color-mix(in srgb, var(--status-info) 55%, transparent);
  color: var(--status-info);
  background: color-mix(in srgb, var(--status-info) 10%, transparent);
  animation: gtcGoalPulse 1.6s ease-in-out infinite;
}
.gtc-goal-status.is-done {
  border-color: color-mix(in srgb, var(--status-ok) 55%, transparent);
  color: var(--status-ok);
  background: color-mix(in srgb, var(--status-ok) 10%, transparent);
}
.gtc-goal-status.is-failed {
  border-color: color-mix(in srgb, var(--status-critical) 55%, transparent);
  color: var(--status-critical);
  background: color-mix(in srgb, var(--status-critical) 10%, transparent);
}
.gtc-goal-status.is-stopped { border-color: color-mix(in srgb, var(--status-warn) 50%, transparent); color: var(--status-warn); }
@keyframes gtcGoalPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
.gtc-goal-round { font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.gtc-goal-hint {
  margin-top: 6px; font-size: 10.5px; line-height: 1.6; color: var(--text-muted);
  padding: 6px 8px; border-radius: 8px;
  background: color-mix(in srgb, var(--status-info) 7%, transparent);
}
.gtc-goal-bar .gtc-panel-entry { margin-left: auto; padding: 4px 12px; font-size: 11px; }
.gtc-panel-members { display: flex; flex-direction: column; gap: 4px; }
.gtc-panel-member {
  display: flex; align-items: center; gap: 4px;
  border-radius: 9px; padding: 2px 4px;
}
.gtc-panel-member:hover { background: color-mix(in srgb, var(--accent-cyan) 7%, transparent); }
.gtc-panel-member-main {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 9px;
  border: 0; background: transparent; padding: 5px 4px; cursor: pointer; text-align: left;
}
.gtc-panel-member-info { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.gtc-panel-member-info b { font-size: 12px; color: var(--text-primary); }
.gtc-panel-member-info small {
  font-size: 10px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.gtc-panel-member .gtc-member-remove { flex: none; }
.gtc-panel-member-add {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  width: 100%; padding: 8px; margin-top: 2px;
  border: 1px dashed var(--border-color); border-radius: 9px;
  background: transparent; color: var(--text-muted);
  font-size: 12px; cursor: pointer; transition: all var(--ease-fast);
}
.gtc-panel-member-add:hover:not(:disabled) { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-panel-member-add:disabled { opacity: 0.45; cursor: not-allowed; }
.gtc-panel-invite { position: relative; }
.gtc-panel-invite .gtc-invite-menu { left: 0; right: 0; bottom: calc(100% + 6px); top: auto; }
.gtc-filter-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.gtc-filter-chips button {
  padding: 3px 12px; border: 1px solid var(--border-color); border-radius: 999px;
  background: transparent; color: var(--text-muted);
  font-size: 11px; cursor: pointer; transition: all var(--ease-fast);
}
.gtc-filter-chips button:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-filter-chips button.active {
  border-color: color-mix(in srgb, var(--accent-cyan) 55%, transparent);
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}
.gtc-panel-entry {
  display: block; width: 100%; padding: 8px 10px;
  border: 1px solid var(--border-color); border-radius: 9px;
  background: transparent; color: var(--text-primary);
  font-size: 12px; cursor: pointer; text-align: left; transition: all var(--ease-fast);
}
.gtc-panel-entry:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.gtc-panel-entry.is-primary {
  border-color: color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 14%, transparent);
  color: var(--accent-cyan); font-weight: 600;
}

/* ===== v9 「有新消息」跳转浮标（未读计数） ===== */
.gtc-jump-latest {
  position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%);
  z-index: 30; padding: 6px 16px;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 45%, transparent);
  border-radius: 999px;
  background: var(--bg-primary); color: var(--accent-cyan);
  font-size: 11.5px; font-weight: 600; cursor: pointer;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.3);
  animation: gtcJumpIn 0.18s ease;
}
/* v26 Bug#10：motion.css 的 :where(button):hover 会用 translateY(-1px) 整体替换
   transform，丢掉 translateX(-50%) 居中 → 浮标 hover 时向右跳半宽点不到。
   此处用更高特异性 (0,2,0) 覆盖，保留居中的同时提供同款上浮/按压反馈。 */
.gtc-jump-latest:hover { background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); transform: translate(-50%, -1px); }
.gtc-jump-latest:active { transform: translate(-50%, 0) scale(0.98); }
@keyframes gtcJumpIn { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }

/* ===== v9 侧栏群聊：微信式四宫格合成头像 ===== */
.agents-chat-gavatar {
  flex: none; display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr;
  gap: 1px; border-radius: 6px; overflow: hidden;
  background: var(--border-color);
}
.agents-chat-gavatar i {
  display: inline-flex; align-items: center; justify-content: center;
  font-style: normal; font-weight: 700; line-height: 1;
}

.gtc-input-wrap { position: relative; display: flex; gap: 8px; padding: 8px 16px 12px; border-top: 1px solid var(--border-color); }
.gtc-input {
  flex: 1; resize: none; padding: 9px 12px; font-size: 13px; line-height: 1.55;
  border: 1px solid var(--border-color); border-radius: 10px;
  background: var(--bg-secondary); color: var(--text-primary); outline: none;
  font-family: inherit;
}
.gtc-input:focus { border-color: var(--accent-cyan); }
.gtc-send {
  flex: none; align-self: flex-end; padding: 9px 18px; border-radius: 10px; border: 0;
  background: var(--accent-cyan); color: var(--bg-primary); font-size: 13px; font-weight: 700; cursor: pointer;
}
.gtc-send:disabled { opacity: 0.4; cursor: not-allowed; }
.gtc-send.is-stop { background: transparent; border: 1px solid var(--status-critical, #f85149); color: var(--status-critical, #f85149); font-weight: 600; }
.gtc-mention-pop {
  position: absolute; bottom: calc(100% - 4px); left: 18px; z-index: 40;
  min-width: 240px; padding: 6px;
  background: var(--bg-primary); border: 1px solid var(--border-color); border-radius: 10px;
  box-shadow: 0 -8px 30px rgba(0, 0, 0, 0.18);
  display: flex; flex-direction: column; gap: 2px;
}
.gtc-mention-pop button {
  display: flex; align-items: baseline; gap: 8px; text-align: left;
  padding: 7px 9px; border: 0; border-radius: 7px; background: transparent; cursor: pointer;
}
.gtc-mention-pop button:hover { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.gtc-mention-pop b { font-size: 12px; color: var(--accent-cyan); }
.gtc-mention-pop small { font-size: 10px; color: var(--text-muted); }
.gtc-mention-empty { padding: 8px; font-size: 11px; color: var(--text-muted); text-align: center; }

/* ===== v16 素材管理：侧栏占满 + 素材卡片重设计 ===== */
.repo-page { align-items: stretch; }
.repo-rail {
  max-height: none;
  gap: 18px;
  padding: 14px 12px;
}
.repo-rail-label { font-size: 10.5px; letter-spacing: .08em; color: var(--text-muted); font-weight: 700; }
.repo-rail-item { padding: 7px 10px; border-radius: 8px; font-size: 12.5px; }
.repo-rail-item.active {
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  font-weight: 600;
}
.repo-rail-group + .repo-rail-group { border-top: 1px dashed var(--border-color); padding-top: 12px; }

/* ---- 素材卡片：封面化头部 + 悬停浮起 + 三行钳制 + 分隔 meta ---- */
.materials-grid { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; }
.material-card {
  max-height: none;
  padding: 12px 14px;
  border-radius: 14px;
  gap: 8px;
  transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease;
}
.material-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent-cyan) 45%, var(--border-color));
  box-shadow: 0 12px 28px rgba(0, 0, 0, .16);
}
.material-card.starred {
  border-color: color-mix(in srgb, #c9a961 55%, var(--border-color));
  background: color-mix(in srgb, #c9a961 4%, var(--bg-card));
}
.material-card .material-content {
  max-height: none;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  padding-right: 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.6;
}
.material-card .material-title { font-size: 13.5px; font-weight: 700; line-height: 1.45; }
.material-card .material-image { border-radius: 10px; }
.material-card .material-meta {
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px dashed var(--border-color);
  gap: 8px;
}
.material-card .material-tags {
  color: var(--accent-cyan);
  font-size: 11px;
}
.material-card .material-note {
  margin: 0;
  font-size: 11.5px;
}
/* 卡片内操作按钮：hover 才浮现，减少常驻噪音 */
.material-card .material-header-actions { opacity: 0; transition: opacity .14s ease; }
.material-card:hover .material-header-actions { opacity: 1; }
.material-research { border: 1px solid var(--accent-cyan-border); background: transparent; }

/* ===== v17 素材管理：左栏固定 + 选中态重设计 + 详情抽屉科技化 ===== */
/* 布局：整页占满，左右两列各自独立滚动 —— 左栏筛选不再跟随内容滚动 */
.repo-page { height: 100%; }
.repo-rail {
  position: static;
  height: 100%;
  max-height: none;
  overflow-y: auto;
}
.repo-main {
  height: 100%;
  overflow-y: auto;
  padding-right: 2px;
}
.repo-main::-webkit-scrollbar { width: 4px; }
.repo-main::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 2px; }

/* 选择框：单只、定制样式（原生 input 隐藏） */
.material-checkbox-label { position: relative; width: 16px; height: 16px; flex: none; }
.material-checkbox-label input {
  position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer;
}
.material-checkbox-label .checkbox-custom {
  display: block; width: 16px; height: 16px; border-radius: 5px;
  border: 1.5px solid var(--border-color);
  background: var(--bg-primary);
  transition: all .15s ease;
}
.material-checkbox-label input:checked + .checkbox-custom {
  background: var(--accent-cyan);
  border-color: var(--accent-cyan);
  box-shadow: 0 0 8px color-mix(in srgb, var(--accent-cyan) 45%, transparent);
}
.material-checkbox-label input:checked + .checkbox-custom::after {
  content: '✓'; position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  color: var(--bg-primary); font-size: 11px; font-weight: 800;
}
.material-checkbox-label input:focus-visible + .checkbox-custom {
  outline: 2px solid color-mix(in srgb, var(--accent-cyan) 45%, transparent); outline-offset: 1px;
}

/* 选中卡片：科技感青色辉光 + 右上角对勾角标 */
.material-card { position: relative; }
.material-card.selected {
  border-color: var(--accent-cyan);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 8%, transparent), transparent 55%),
    var(--bg-card);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--accent-cyan) 65%, transparent),
    0 10px 32px color-mix(in srgb, var(--accent-cyan) 20%, transparent);
}
.material-card.selected .material-type-badge {
  box-shadow: 0 0 10px color-mix(in srgb, var(--accent-cyan) 35%, transparent);
}

/* 类型徽标：发光胶囊 */
.material-type-badge {
  display: inline-flex; align-items: center;
  padding: 2px 9px; border-radius: 999px;
  font-size: 10.5px; font-weight: 700; letter-spacing: .04em;
}

/* ---- 详情抽屉：科技感/艺术感重设计 ---- */
.repo-drawer {
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 30%, var(--border-color));
  border-left: 1px solid color-mix(in srgb, var(--accent-cyan) 30%, var(--border-color));
  box-shadow: -24px 0 64px rgba(0, 0, 0, .3), inset 1px 0 0 color-mix(in srgb, var(--accent-cyan) 22%, transparent);
  animation: repoDrawerIn .22s cubic-bezier(.2, .8, .2, 1);
}
@keyframes repoDrawerIn { from { transform: translateX(36px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
.repo-drawer::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
  z-index: 1;
}
.repo-drawer-head {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--accent-cyan) 7%, transparent), transparent 60%);
}
.repo-drawer-title { letter-spacing: .01em; }
.repo-drawer-body {
  padding: 16px 18px 22px;
  background:
    radial-gradient(90% 50% at 100% 0%, color-mix(in srgb, var(--accent-cyan) 4%, transparent), transparent 60%);
}
.repo-drawer-content {
  font-size: 13px; line-height: 1.85;
  padding: 12px 14px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg-primary) 55%, transparent);
}
.repo-drawer-content.markdown-body h1,
.repo-drawer-content.markdown-body h2,
.repo-drawer-content.markdown-body h3 {
  border-left: 2px solid var(--accent-cyan);
  padding-left: 8px;
}
.repo-drawer-content.markdown-body img { max-width: 100%; border-radius: 8px; }
.repo-drawer-content.markdown-body code {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
}
.repo-drawer-section label {
  display: flex; align-items: center; gap: 6px;
  font-size: 10.5px; font-weight: 700; letter-spacing: .06em;
  color: var(--text-muted);
}
.repo-drawer-section label::before {
  content: '◈'; color: var(--accent-cyan); font-size: 9px;
}
.repo-drawer { display: flex; flex-direction: column; }
.repo-drawer-body { flex: 1; }

/* ===== v18 素材管理：左栏贴边全高（去留白） ===== */
/* 素材视图接管 feed 布局：不再用悬浮卡片，而是与工作站侧栏同款的贴边全高面板 */
.feed:has(.repo-page) {
  padding: 0;
  overflow: hidden;
  display: flex;
}
.repo-page {
  flex: 1;
  height: 100%;
  min-height: 0;
  grid-template-columns: 244px minmax(0, 1fr);
  gap: 0;
  padding: 0;
}
.repo-rail {
  height: 100%;
  max-height: none;
  border: none;
  border-right: 1px solid var(--border-color);
  border-radius: 0;
  padding: 14px 12px 20px;
  gap: 18px;
  background: var(--surface-card, var(--bg-card));
}
.repo-main {
  height: 100%;
  padding: 14px 20px 24px;
  overflow-y: auto;
}
/* 顶栏工具行贴齐：搜索/筛选行随 main 滚动保持现状 */

/* ===== v18 无限画布：主题跟随 + 顺滑视口 + 模拟运行动效 + 多工作流/AI 面板 ===== */
/* 背景/网格/节点全面 token 化（深浅主题自动跟随，且随调色板变色） */
.wf-canvas {
  background:
    radial-gradient(90% 70% at 15% 0%, color-mix(in srgb, var(--accent-cyan) 5%, transparent), transparent 58%),
    var(--bg-primary);
  cursor: default;
  touch-action: none;
}
.wf-canvas:active { cursor: default; }
.wf-world {
  position: absolute; left: 0; top: 0; width: 6000px; height: 4000px;
  transform-origin: 0 0;
  will-change: transform;
  background-image:
    linear-gradient(color-mix(in srgb, var(--accent-cyan) 7%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--accent-cyan) 7%, transparent) 1px, transparent 1px),
    linear-gradient(color-mix(in srgb, var(--accent-cyan) 13%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--accent-cyan) 13%, transparent) 1px, transparent 1px);
}
/* 平滑缩放动画：只在按钮/适应视图期间挂上，拖拽时不能有 transition */
.wf-world.is-animating { transition: transform .26s cubic-bezier(.22,.61,.36,1); }
.wf-world.grid-dot {
  background-image:
    radial-gradient(color-mix(in srgb, var(--accent-cyan) 22%, transparent) 1.2px, transparent 1.2px);
  background-size: 28px 28px !important;
}
.wf-world.grid-off { background-image: none; }
.wf-world.grab, .wf-world.grab .wf-node { cursor: grab; }

/* 连线：静态虚线 → 完成实线 → 流动动画 */
.wf-edge { fill: none; stroke: color-mix(in srgb, var(--accent-cyan) 52%, transparent); stroke-width: 2.5; stroke-dasharray: 7 6; stroke-linecap: round; transition: stroke .25s ease; }
.wf-edge.done { stroke: var(--status-ok, #3fb950); stroke-dasharray: none; }
.wf-edge.flow { stroke: var(--accent-cyan); stroke-width: 3.2; stroke-dasharray: 9 7; animation: wfEdgeFlow .55s linear infinite; }
@keyframes wfEdgeFlow { to { stroke-dashoffset: -16; } }
.wf-arrow-path { fill: color-mix(in srgb, var(--accent-cyan) 55%, transparent); }
.wf-arrow-path.done { fill: var(--status-ok, #3fb950); }
.wf-arrow-path.flow { fill: var(--accent-cyan); }
.wf-edge-dot { fill: var(--accent-cyan); filter: drop-shadow(0 0 6px color-mix(in srgb, var(--accent-cyan) 70%, transparent)); }
.wf-edge-label {
  fill: var(--text-primary); font-size: 11px; font-weight: 600;
  paint-order: stroke; stroke: var(--bg-primary); stroke-width: 4px; stroke-linejoin: round;
}

/* 节点：主题跟随 */
.wf-node { background: var(--bg-card); color: var(--text-primary); border-color: var(--border-color); box-shadow: 0 8px 22px rgba(0,0,0,.18); transition: box-shadow .18s ease, border-color .18s ease, opacity .18s ease; }
.wf-node:hover { border-color: color-mix(in srgb, var(--accent-cyan) 55%, transparent); }
.wf-node.selected { border-color: var(--accent-cyan); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-cyan) 28%, transparent), 0 12px 28px rgba(0,0,0,.2); }
.wf-node.disabled { opacity: .5; }
.wf-node-title { color: var(--text-primary); }
.wf-node-role { color: var(--text-secondary); }
.wf-node-head span, .wf-node-io span { color: var(--text-muted); }
.wf-node-io { border-top-color: var(--border-color); }

/* 节点模拟状态 */
.wf-node.sim-running { border-color: var(--accent-cyan); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-cyan) 32%, transparent), 0 0 26px color-mix(in srgb, var(--accent-cyan) 28%, transparent); }
.wf-node.sim-running .wf-node-index { color: var(--accent-cyan); animation: tabDotPulse 1s ease-in-out infinite; }
.wf-node.sim-done { border-color: color-mix(in srgb, var(--status-ok, #3fb950) 55%, transparent); }
.wf-node.sim-done .wf-node-index { color: var(--status-ok, #3fb950); }
.wf-node.sim-skipped { opacity: .5; border-style: dashed; }
.wf-node.sim-skipped .wf-node-index { color: var(--text-muted); }
.wf-node.sim-invalid { border-color: color-mix(in srgb, #f59e0b 62%, transparent); }
.wf-node.sim-invalid .wf-node-index { color: #f59e0b; }
.wf-node-off.sim-tag { background: color-mix(in srgb, var(--accent-cyan) 16%, transparent); color: var(--accent-cyan); border-radius: 4px; padding: 0 5px; }
.wf-node-off.sim-tag.done { background: color-mix(in srgb, var(--status-ok, #3fb950) 16%, transparent); color: var(--status-ok, #3fb950); }
.wf-node-off.sim-tag.skipped { background: color-mix(in srgb, var(--text-muted) 14%, transparent); color: var(--text-muted); }
.wf-node-off.sim-tag.invalid { background: color-mix(in srgb, #f59e0b 16%, transparent); color: #f59e0b; }
/* 运行中进度条 + 产物摘要 */
.wf-node-progress {
  position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 0 0 14px 14px; overflow: hidden;
  background: color-mix(in srgb, var(--accent-cyan) 15%, transparent);
}
.wf-node-progress::after {
  content: ''; position: absolute; inset: 0; width: 40%; border-radius: 2px;
  background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent);
  animation: wfNodeProgress 1s ease-in-out infinite;
}
@keyframes wfNodeProgress { 0% { transform: translateX(-100%); } 100% { transform: translateX(280%); } }
.wf-node-sim {
  margin-top: 7px; padding: 4px 7px; border-radius: 7px; font-size: 10px; line-height: 1.45;
  color: var(--status-ok, #3fb950); background: color-mix(in srgb, var(--status-ok, #3fb950) 10%, transparent);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* 节点面板：左下角，可滚动 */
.wf-palette {
  position: absolute; z-index: 6; left: 14px; top: 66px; width: 156px; max-height: calc(100% - 150px);
  display: flex; flex-direction: column; gap: 6px; padding: 10px;
  border: 1px solid var(--border-color); border-radius: 12px;
  background: color-mix(in srgb, var(--bg-card) 92%, transparent);
  backdrop-filter: blur(8px); box-shadow: 0 10px 26px rgba(0,0,0,.14);
}
.wf-palette-label { color: var(--text-muted); font-size: 10.5px; font-weight: 700; letter-spacing: .04em; display: flex; align-items: center; justify-content: space-between; gap: 6px; }
/* v20：面板收起按钮 + 收起态竖排窄条 */
.wf-palette-collapse { width: 18px; height: 18px; padding: 0; border: 1px solid var(--border-color); border-radius: 5px; background: transparent; color: var(--text-muted); font-size: 11px; line-height: 1; cursor: pointer; }
.wf-palette-collapse:hover { color: var(--accent-cyan); border-color: var(--accent-cyan); }
.wf-palette-rail {
  position: absolute; z-index: 6; left: 14px; top: 66px;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  padding: 10px 6px; border: 1px solid var(--border-color); border-radius: 10px;
  background: color-mix(in srgb, var(--bg-card) 92%, transparent); backdrop-filter: blur(8px);
  color: var(--text-muted); font-size: 10px; cursor: pointer;
}
.wf-palette-rail:hover { color: var(--accent-cyan); border-color: var(--accent-cyan); }
.wf-palette-rail-icon { font-size: 13px; line-height: 1; }
.wf-palette-rail-text { writing-mode: vertical-rl; letter-spacing: .18em; }
.wf-palette-list { display: flex; flex-direction: column; gap: 2px; overflow-y: auto; }
.wf-palette-item {
  display: flex; align-items: center; gap: 8px; width: 100%; padding: 7px 8px; border: 0; border-radius: 8px;
  background: transparent; color: var(--text-primary); font-size: 12px; text-align: left; cursor: grab;
  transition: background .15s ease, transform .15s ease;
}
.wf-palette-item:hover { background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); transform: translateX(2px); }
.wf-palette-item:active { cursor: grabbing; }
.wf-palette-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.wf-palette-plus { margin-left: auto; color: var(--text-muted); font-size: 13px; }

/* 视图控制条：底部居中 */
.wf-zoombar {
  position: absolute; z-index: 6; left: 50%; right: auto; transform: translateX(-50%); bottom: 14px;
  display: flex; align-items: center; gap: 6px; padding: 6px;
  border: 1px solid var(--border-color); border-radius: 11px;
  background: color-mix(in srgb, var(--bg-card) 92%, transparent);
  backdrop-filter: blur(8px); box-shadow: 0 8px 22px rgba(0,0,0,.14);
}
.wf-zoombar button {
  width: 28px; height: 28px; border: 0; border-radius: 8px; cursor: pointer;
  background: color-mix(in srgb, var(--text-muted) 12%, transparent); color: var(--text-primary); font-size: 13px;
}
.wf-zoombar button:hover { background: color-mix(in srgb, var(--accent-cyan) 18%, transparent); color: var(--accent-cyan); }
.wf-zoom-value { min-width: 44px; text-align: center; color: var(--text-secondary); font-size: 11px; font-variant-numeric: tabular-nums; }

/* 空画布提示 */
.wf-empty-hint {
  position: absolute; z-index: 5; left: 50%; top: 50%; transform: translate(-50%, -50%);
  display: flex; flex-direction: column; gap: 8px; align-items: center; max-width: 420px; text-align: center;
  padding: 22px 26px; border: 1px dashed var(--border-color); border-radius: 16px;
  background: color-mix(in srgb, var(--bg-card) 80%, transparent);
  color: var(--text-muted); font-size: 12px; line-height: 1.7; pointer-events: none;
}
.wf-empty-hint b { color: var(--text-primary); font-size: 14px; }

/* 画布顶部动作 chips：校验/模拟/整理/保存/AI */
.canvas-validate-chip,
.canvas-sim-btn,
.canvas-ai-btn,
.canvas-act-btn {
  padding: 5px 10px; border-radius: 9px; cursor: pointer; font-size: 11.5px; font-weight: 600;
  border: 1px solid var(--border-color); background: color-mix(in srgb, var(--bg-card) 90%, transparent);
  color: var(--text-secondary); white-space: nowrap; transition: border-color .15s ease, color .15s ease, background .15s ease;
}
.canvas-validate-chip.ok { border-color: color-mix(in srgb, var(--status-ok, #3fb950) 55%, transparent); color: var(--status-ok, #3fb950); }
.canvas-validate-chip.warn { border-color: color-mix(in srgb, #f59e0b 55%, transparent); color: #f59e0b; }
.canvas-validate-chip:hover, .canvas-sim-btn:hover:not(:disabled), .canvas-ai-btn:hover, .canvas-act-btn:hover:not(:disabled) { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-sim-btn:disabled, .canvas-act-btn:disabled { opacity: .4; cursor: not-allowed; }
.canvas-ai-btn.open { border-color: var(--accent-cyan); color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); }

/* 校验面板 */
.canvas-validate-pop {
  position: absolute; top: 38px; right: 0; width: 320px; max-height: 380px; overflow-y: auto;
  display: flex; flex-direction: column; gap: 2px; padding: 8px;
  border: 1px solid var(--border-color); border-radius: 12px;
  background: var(--bg-card); box-shadow: 0 16px 40px rgba(0,0,0,.2);
}
.canvas-validate-pop-label {
  display: flex; align-items: center; gap: 6px; padding: 4px 6px 8px;
  font-size: 11px; font-weight: 700; color: var(--text-muted);
}
.canvas-validate-pop-label b { margin-left: auto; color: var(--text-primary); }
.canvas-validate-item {
  display: grid; grid-template-columns: 14px 1fr; gap: 2px 8px; padding: 7px 8px; border: 0; border-radius: 8px;
  background: transparent; text-align: left; cursor: pointer;
}
.canvas-validate-item:hover { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.canvas-validate-item i { font-style: normal; font-size: 11px; grid-row: span 2; padding-top: 2px; }
.canvas-validate-item.ok i { color: var(--status-ok, #3fb950); }
.canvas-validate-item.blocking i { color: var(--status-critical, #f85149); }
.canvas-validate-item.warn i { color: #f59e0b; }
.canvas-validate-item span { font-size: 11.5px; color: var(--text-primary); }
.canvas-validate-item small { grid-column: 2; font-size: 10px; color: var(--text-muted); }

/* 多工作流切换器 */
.canvas-flow-switch { display: flex; align-items: center; gap: 4px; }
.canvas-flow-caret {
  width: 24px; height: 30px; border: 1px solid var(--border-color); border-radius: 8px; cursor: pointer;
  background: color-mix(in srgb, var(--bg-card) 90%, transparent); color: var(--text-secondary); font-size: 12px;
}
.canvas-flow-caret:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-flows-pop {
  position: absolute; top: 38px; left: 0; width: 268px; max-height: 340px; overflow-y: auto;
  display: flex; flex-direction: column; gap: 2px; padding: 8px;
  border: 1px solid var(--border-color); border-radius: 12px;
  background: var(--bg-card); box-shadow: 0 16px 40px rgba(0,0,0,.2);
}
.canvas-flows-head {
  display: flex; align-items: center; padding: 2px 6px 8px;
  font-size: 11px; font-weight: 700; color: var(--text-muted);
}
.canvas-flows-head button {
  margin-left: auto; padding: 3px 8px; border-radius: 7px; cursor: pointer; font-size: 11px;
  border: 1px solid var(--border-color); background: transparent; color: var(--accent-cyan);
}
.canvas-flows-item { display: flex; align-items: center; gap: 2px; border-radius: 8px; }
.canvas-flows-item.active { background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.canvas-flows-item-main {
  flex: 1; display: flex; align-items: center; gap: 8px; padding: 7px 8px; border: 0; border-radius: 8px;
  background: transparent; color: var(--text-primary); font-size: 12px; text-align: left; cursor: pointer;
}
.canvas-flows-item-main small { color: var(--text-muted); font-size: 10px; }
.canvas-flows-item-main:hover { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.canvas-flows-act {
  width: 24px; height: 26px; border: 0; border-radius: 6px; cursor: pointer;
  background: transparent; color: var(--text-muted); font-size: 12px;
}
.canvas-flows-act:hover { background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); color: var(--accent-cyan); }
.canvas-flows-act.danger:hover { background: color-mix(in srgb, var(--status-critical, #f85149) 12%, transparent); color: var(--status-critical, #f85149); }

/* 模拟运行报告 */
.canvas-sim-report {
  top: 60px; left: 50%; transform: translateX(-50%); width: min(520px, calc(100% - 60px));
  display: flex; flex-direction: column; border: 1px solid var(--border-color); border-radius: 12px;
  background: var(--bg-card); box-shadow: 0 18px 44px rgba(0,0,0,.22); overflow: hidden;
}
.canvas-sim-report-head {
  display: flex; align-items: center; gap: 8px; padding: 9px 12px; border-bottom: 1px solid var(--border-color);
  font-size: 11.5px; font-weight: 700; color: var(--text-muted);
}
.canvas-sim-report-head b { color: var(--status-ok, #3fb950); font-size: 11.5px; }
.canvas-sim-report-head b.warn { color: #f59e0b; }
.canvas-sim-report-head button {
  margin-left: auto; border: 0; background: transparent; color: var(--text-muted); cursor: pointer; font-size: 14px;
}
.canvas-sim-report-body { max-height: 240px; overflow-y: auto; padding: 8px 12px; display: flex; flex-direction: column; gap: 2px; }
.canvas-sim-step {
  display: grid; grid-template-columns: 14px 1fr auto; gap: 2px 8px; padding: 6px 4px;
  border-bottom: 1px dashed color-mix(in srgb, var(--border-color) 60%, transparent);
}
.canvas-sim-step:last-child { border-bottom: 0; }
.canvas-sim-step i { color: var(--status-ok, #3fb950); font-style: normal; font-size: 11px; grid-row: span 2; }
.canvas-sim-step.skipped i { color: var(--text-muted); }
.canvas-sim-step-title { font-size: 12px; color: var(--text-primary); }
.canvas-sim-step-out { font-size: 11px; color: var(--accent-cyan); }
.canvas-sim-step small { grid-column: 2 / span 2; font-size: 10px; color: var(--text-muted); }
.canvas-sim-report-foot { padding: 8px 12px; border-top: 1px solid var(--border-color); font-size: 10.5px; color: var(--text-muted); }

/* 节点配置卡 */
.canvas-node-editor {
  right: 14px; top: 58px; bottom: auto; width: 328px; max-height: calc(100% - 130px); overflow-y: auto;
  display: flex; flex-direction: column; gap: 9px; padding: 12px;
  border: 1px solid var(--border-color); border-radius: 13px;
  background: color-mix(in srgb, var(--bg-card) 96%, transparent);
  backdrop-filter: blur(10px); box-shadow: 0 16px 40px rgba(0,0,0,.2);
}
.canvas-node-issues { display: flex; flex-direction: column; gap: 4px; }
.canvas-node-issues span {
  padding: 5px 8px; border-radius: 7px; font-size: 10.5px; line-height: 1.5;
  background: color-mix(in srgb, #f59e0b 10%, transparent); color: #f59e0b;
}
.canvas-node-issues span.blocking { background: color-mix(in srgb, var(--status-critical, #f85149) 10%, transparent); color: var(--status-critical, #f85149); }
.canvas-node-hint { font-size: 10px; color: var(--text-muted); font-weight: 400; }

/* AI 搭建抽屉 */
/* AI 抽屉打开时，右侧浮层让位 */
.canvas-page.ai-open .canvas-node-editor { right: 362px; }
.canvas-page.ai-open .canvas-sim-report { transform: translateX(calc(-50% - 174px)); }
.canvas-ai-panel {
  position: absolute; z-index: 30; right: 0; top: 0; bottom: 0; width: 348px;
  display: flex; flex-direction: column;
  border-left: 1px solid var(--border-color); background: var(--bg-card);
  box-shadow: -18px 0 48px rgba(0,0,0,.16);
  animation: canvasAiIn .24s cubic-bezier(.22,.61,.36,1);
}
@keyframes canvasAiIn { from { transform: translateX(24px); opacity: 0; } to { transform: none; opacity: 1; } }
.canvas-ai-head { display: flex; align-items: center; gap: 8px; padding: 12px 14px; border-bottom: 1px solid var(--border-color); }
.canvas-ai-title { font-size: 13px; font-weight: 700; color: var(--accent-cyan); }
.canvas-ai-sub {
  font-size: 10px; color: var(--text-muted); padding: 2px 6px; border-radius: 6px;
  background: color-mix(in srgb, var(--text-muted) 10%, transparent); max-width: 150px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.canvas-ai-close { margin-left: auto; border: 0; background: transparent; color: var(--text-muted); font-size: 15px; cursor: pointer; padding: 2px 6px; border-radius: 6px; }
.canvas-ai-close:hover { color: var(--text-primary); background: color-mix(in srgb, var(--text-muted) 12%, transparent); }
.canvas-ai-messages { flex: 1; overflow-y: auto; padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.canvas-ai-hint p { margin: 0 0 10px; font-size: 12px; color: var(--text-muted); line-height: 1.7; }
.canvas-ai-hint button {
  display: block; width: 100%; margin-bottom: 6px; padding: 8px 10px; border-radius: 9px; cursor: pointer;
  border: 1px dashed var(--border-color); background: transparent; color: var(--text-secondary);
  font-size: 11.5px; text-align: left;
}
.canvas-ai-hint button:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-ai-msg { display: flex; flex-direction: column; gap: 6px; }
.canvas-ai-msg.user { align-items: flex-end; }
.canvas-ai-msg .canvas-ai-msg-text {
  max-width: 92%; padding: 8px 11px; border-radius: 11px; font-size: 12px; line-height: 1.65;
}
.canvas-ai-msg.user .canvas-ai-msg-text { background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); color: var(--text-primary); }
.canvas-ai-msg.assistant .canvas-ai-msg-text { background: var(--bg-secondary); border: 1px solid var(--border-color); color: var(--text-primary); }
.canvas-ai-msg .canvas-ai-msg-detail { max-width: 92%; font-size: 10.5px; line-height: 1.7; color: var(--text-muted); }
.canvas-ai-msg .canvas-ai-msg-note { max-width: 92%; font-size: 10.5px; line-height: 1.6; color: #f59e0b; }
.canvas-ai-msg-text.typing { position: relative; }
.canvas-ai-msg-text.typing::after { content: '…'; animation: tabDotPulse 1s ease-in-out infinite; }
.canvas-ai-apply { display: flex; gap: 6px; flex-wrap: wrap; }
.canvas-ai-apply button {
  padding: 6px 10px; border-radius: 8px; cursor: pointer; font-size: 11.5px;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-secondary);
}
.canvas-ai-apply button:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-ai-apply button.is-primary { border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); color: var(--accent-cyan); }
.canvas-ai-undo {
  margin: 0 14px 8px; padding: 7px; border-radius: 8px; cursor: pointer; font-size: 11px;
  border: 1px dashed var(--border-color); background: transparent; color: var(--text-muted);
}
.canvas-ai-undo:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.canvas-ai-input { display: flex; gap: 8px; padding: 12px; border-top: 1px solid var(--border-color); }
.canvas-ai-input textarea {
  flex: 1; padding: 9px 10px; border-radius: 9px; resize: none; font-size: 12px; line-height: 1.6;
  border: 1px solid var(--border-color); background: var(--bg-secondary); color: var(--text-primary);
}
.canvas-ai-input textarea:focus { border-color: var(--accent-cyan); outline: none; }
.canvas-ai-send {
  padding: 0 14px; border-radius: 9px; border: 0; cursor: pointer;
  background: var(--accent-cyan); color: var(--bg-primary); font-weight: 700; font-size: 12px;
}
.canvas-ai-send:disabled { opacity: .4; cursor: not-allowed; }

@media (max-width: 1180px) {
  .canvas-ai-panel { width: 300px; }
  .canvas-node-editor { width: 290px; }
}
@media (max-width: 860px) {
  .wf-palette { display: none; }
  .canvas-ai-panel { width: 100%; }
}

/* ===== v19 批次：资讯预览抽屉 / 侧栏分组 / 精灵记录 / 豆包搜索状态 / 画像优先级 / 画布增强 ===== */

/* ---- 1. 资讯侧边预览抽屉 ---- */
.item-title.clickable { cursor: pointer; transition: color .15s ease; }
.item-title.clickable:hover { color: var(--accent-cyan); }
.news-preview-mask {
  position: fixed; inset: 0; z-index: 900; background: rgba(0,0,0,.32);
  animation: fadeIn .18s ease;
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.news-preview-panel {
  position: fixed; z-index: 901; top: 0; right: 0; bottom: 0; width: min(560px, 92vw);
  display: flex; flex-direction: column;
  background: var(--bg-primary); border-left: 1px solid var(--border-color);
  box-shadow: -24px 0 60px rgba(0,0,0,.24);
  animation: newsPreviewIn .24s cubic-bezier(.22,.61,.36,1);
}
@keyframes newsPreviewIn { from { transform: translateX(40px); opacity: 0; } to { transform: none; opacity: 1; } }
.news-preview-head { position: relative; padding: 20px 22px 14px; border-bottom: 1px solid var(--border-color); }
.news-preview-close {
  position: absolute; top: 14px; right: 14px; width: 30px; height: 30px; border-radius: 8px;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted);
  font-size: 15px; cursor: pointer;
}
.news-preview-close:hover { color: var(--text-primary); border-color: var(--accent-cyan); }
.news-preview-meta { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.news-preview-source {
  padding: 2px 8px; border-radius: 6px; font-size: 10.5px; font-weight: 700;
  color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
}
.news-preview-time { font-size: 11px; color: var(--text-muted); }
.news-preview-title { margin: 0 0 10px; font-size: 17px; line-height: 1.5; color: var(--text-primary); }
.news-preview-actions { display: flex; }
.news-preview-link {
  display: inline-flex; align-items: center; gap: 5px; font-size: 12px;
  color: var(--accent-cyan); text-decoration: none;
}
.news-preview-link:hover { text-decoration: underline; }
.news-preview-body { flex: 1; overflow-y: auto; padding: 20px 22px 32px; }
/* v21：阅读排版——呼吸感与层级，不再挤成一团 */
.news-preview-para { margin: 0 0 18px; font-size: 14px; line-height: 1.95; color: var(--text-primary); letter-spacing: .01em; text-align: justify; }
.news-preview-para.lede { font-size: 15px; line-height: 1.85; color: var(--text-primary); padding: 12px 14px; border-left: 3px solid var(--accent-cyan); border-radius: 0 10px 10px 0; background: color-mix(in srgb, var(--accent-cyan) 6%, transparent); margin-bottom: 22px; }
.news-preview-para.lede::first-letter { font-size: 1.1em; font-weight: 700; color: var(--accent-cyan); }
/* v20：正文配图（懒加载 + 失败自动隐藏 + 点击看原图）；v21 加大与正文间距 */
.news-preview-figure { margin: 8px 0 22px; border-radius: 10px; overflow: hidden; border: 1px solid var(--panel-border); background: var(--bg-elevated); }
.news-preview-figure img { display: block; width: 100%; height: auto; max-height: 380px; object-fit: cover; cursor: zoom-in; min-height: 60px; }
.news-preview-figure.hero img { max-height: 300px; }
.news-preview-figure.hero { margin-bottom: 24px; }
/* v20：markdown 正文排版（素材快照/工作空间 md 全文） */
.news-preview-md p { margin: 0 0 14px; font-size: 14px; line-height: 1.9; color: var(--text-primary); }
.news-preview-md h1, .news-preview-md h2, .news-preview-md h3 { margin: 22px 0 10px; line-height: 1.4; color: var(--text-primary); }
.news-preview-md h1 { font-size: 19px; padding-left: 10px; border-left: 3px solid var(--accent-cyan); }
.news-preview-md h2 { font-size: 17px; padding-left: 10px; border-left: 3px solid color-mix(in srgb, var(--accent-cyan) 60%, transparent); }
.news-preview-md h3 { font-size: 15px; }
.news-preview-md ul, .news-preview-md ol { margin: 0 0 14px; padding-left: 22px; display: flex; flex-direction: column; gap: 6px; }
.news-preview-md li { font-size: 13px; line-height: 1.8; color: var(--text-primary); }
.news-preview-md blockquote { margin: 0 0 14px; padding: 10px 14px; border-left: 3px solid var(--accent-cyan); background: var(--bg-elevated); border-radius: 0 8px 8px 0; color: var(--text-muted); font-size: 13px; line-height: 1.8; }
.news-preview-md code { padding: 1px 6px; border-radius: 4px; background: var(--bg-elevated); border: 1px solid var(--panel-border); font-size: 12px; }
.news-preview-md pre.code-block { margin: 0 0 14px; padding: 12px 14px; border-radius: 8px; border: 1px solid var(--panel-border); background: var(--bg-elevated); overflow-x: auto; }
.news-preview-md img { max-width: 100%; height: auto; border-radius: 8px; margin: 6px 0; }
.news-preview-md a { color: var(--accent-cyan); }
.news-preview-md strong { color: var(--text-primary); }
.news-preview-md hr { border: none; border-top: 1px solid var(--panel-border); margin: 18px 0; }
.news-preview-state {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  padding: 36px 10px; color: var(--text-muted); font-size: 13px;
}
.news-preview-fallback {
  margin: 4px 0 0; padding: 14px 16px; border-left: 2px solid var(--border-color);
  font-size: 13px; line-height: 1.8; color: var(--text-secondary); text-align: left;
}
.news-preview-spinner {
  width: 22px; height: 22px; border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--accent-cyan) 25%, transparent);
  border-top-color: var(--accent-cyan);
  animation: spin .8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ---- 2. 侧边栏分组 ---- */
.nav-primary-group.nav-grouped + .nav-primary-group.nav-grouped { margin-top: 14px; padding-top: 10px; border-top: 1px solid color-mix(in srgb, var(--border-color) 60%, transparent); }
.nav-group-title-static { margin: 0 0 6px; padding: 0 10px; font-size: 10px; font-weight: 800; letter-spacing: .12em; color: var(--text-muted); opacity: .75; }

/* ---- 3. AI 精灵聊天记录 ---- */
.ai-elf-history { display: flex; flex-direction: column; max-height: 220px; border-bottom: 1px solid var(--border-color); background: var(--bg-secondary, var(--bg-primary)); }
.ai-elf-history-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 14px; font-size: 11px; font-weight: 700; color: var(--text-muted);
}
.ai-elf-history-head button {
  padding: 4px 10px; border-radius: 7px; cursor: pointer; font-size: 11px;
  border: 1px solid var(--border-color); background: transparent; color: var(--accent-cyan);
}
.ai-elf-history-head button:hover { border-color: var(--accent-cyan); }
.ai-elf-history-list { overflow-y: auto; padding: 0 10px 10px; display: flex; flex-direction: column; gap: 3px; }
.ai-elf-history-empty { margin: 4px 6px 8px; font-size: 11.5px; line-height: 1.7; color: var(--text-muted); }
.ai-elf-history-item { display: flex; align-items: center; gap: 4px; border-radius: 8px; }
.ai-elf-history-item:hover { background: color-mix(in srgb, var(--accent-cyan) 7%, transparent); }
.ai-elf-history-main {
  flex: 1; display: flex; flex-direction: column; gap: 2px; padding: 7px 9px;
  border: 0; border-radius: 8px; background: transparent; text-align: left; cursor: pointer;
}
.ai-elf-history-main b { font-size: 12px; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ai-elf-history-main small { font-size: 10px; color: var(--text-muted); }
.ai-elf-history-del {
  width: 22px; height: 24px; border: 0; border-radius: 6px; background: transparent;
  color: var(--text-muted); cursor: pointer; font-size: 13px;
}
.ai-elf-history-del:hover { color: var(--status-critical, #f85149); background: color-mix(in srgb, var(--status-critical, #f85149) 10%, transparent); }
.ai-elf-btn.active { color: var(--accent-cyan); border-color: var(--accent-cyan); }

/* ---- 4. 联网搜索状态条（豆包） ---- */
.llm-websearch-status {
  display: flex; align-items: center; gap: 10px; padding: 10px 12px; margin-bottom: 12px;
  border: 1px solid var(--border-color); border-radius: 11px;
  background: color-mix(in srgb, var(--bg-secondary, var(--bg-primary)) 80%, transparent);
}
.llm-websearch-status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted); flex: none; }
.llm-websearch-status.provider-doubao .llm-websearch-status-dot { background: var(--status-ok, #3fb950); box-shadow: 0 0 8px color-mix(in srgb, var(--status-ok, #3fb950) 60%, transparent); }
.llm-websearch-status.provider-tavily .llm-websearch-status-dot,
.llm-websearch-status.provider-duckduckgo .llm-websearch-status-dot { background: #f59e0b; }
.llm-websearch-status.provider-off .llm-websearch-status-dot { background: var(--status-critical, #f85149); }
.llm-websearch-status-main { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.llm-websearch-status-main b { font-size: 12.5px; color: var(--text-primary); }
.llm-websearch-status-main small { font-size: 10.5px; color: var(--text-muted); }
.llm-websearch-status-btn {
  margin-left: auto; padding: 6px 12px; border-radius: 8px; cursor: pointer; font-size: 11.5px; font-weight: 600;
  border: 1px solid var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); color: var(--accent-cyan);
  white-space: nowrap;
}
.llm-websearch-status-btn:hover { background: color-mix(in srgb, var(--accent-cyan) 22%, transparent); }
.llm-doubao-row { display: flex; gap: 8px; }
.llm-doubao-row .llm-input { flex: 1; }
.llm-key-toggle {
  padding: 0 12px; border-radius: 8px; cursor: pointer; font-size: 11.5px;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted); white-space: nowrap;
}
.llm-key-toggle:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.llm-doubao-hint { margin: 6px 0 0; font-size: 11.5px; line-height: 1.75; color: var(--text-muted); }
.llm-doubao-hint b { color: var(--accent-cyan); }
.llm-doubao-hint a { color: var(--accent-cyan); text-decoration: none; margin-left: 6px; }
.llm-doubao-hint a:hover { text-decoration: underline; }

/* ---- 5. 画像优先级模块 ---- */
.priority-summary { display: flex; align-items: center; gap: 14px; margin-top: 10px; }
.priority-summary span { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; color: var(--text-muted); }
.tier-dot { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.tier-dot.tier-focus { background: var(--status-ok, #3fb950); }
.tier-dot.tier-normal { background: var(--accent-cyan); }
.tier-dot.tier-explore { background: var(--text-muted); }
.priority-add-row { display: flex; gap: 8px; margin-bottom: 12px; }
/* v20：添加领域/信息源的预选 chips（点一下即加，已存在的自动隐藏） */
.priority-preset-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: -6px 0 12px; }
.priority-preset-label { font-size: 10px; color: var(--text-muted); letter-spacing: .04em; margin-right: 2px; }
.priority-preset-chip { padding: 3px 10px; border: 1px solid var(--border-color); border-radius: 999px; background: transparent; color: var(--text-muted); font-size: 11px; cursor: pointer; transition: color .15s ease, border-color .15s ease, background .15s ease; }
.priority-preset-chip:hover { color: var(--accent-cyan); border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.priority-add-row input {
  flex: 1; padding: 9px 12px; border-radius: 9px; font-size: 12.5px;
  border: 1px dashed var(--border-color); background: var(--bg-secondary, transparent); color: var(--text-primary);
}
.priority-add-row input:focus { border-color: var(--accent-cyan); border-style: solid; outline: none; }
.priority-add-row button {
  padding: 0 16px; border-radius: 9px; cursor: pointer; font-size: 12px; font-weight: 600; white-space: nowrap;
  border: 1px solid var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); color: var(--accent-cyan);
}
.priority-add-row button:hover { background: color-mix(in srgb, var(--accent-cyan) 22%, transparent); }
.priority-row-label { display: inline-flex; align-items: center; gap: 6px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.priority-custom-tag {
  flex: none; font-style: normal; font-size: 9px; font-weight: 700; letter-spacing: .05em;
  padding: 1px 5px; border-radius: 5px; color: var(--accent-cyan);
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 45%, transparent);
}
.priority-count { margin-left: 6px; font-size: 10px; color: var(--text-muted); }
.priority-remove-btn {
  flex: none; padding: 3px 9px; border-radius: 7px; cursor: pointer; font-size: 10.5px;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted);
}
.priority-remove-btn:hover { color: var(--status-critical, #f85149); border-color: var(--status-critical, #f85149); }

/* ---- 6. 画布增强 ---- */
/* 无限网格层：铺满视口，随 pan/zoom 移动，视觉上无限延伸 */
.wf-grid-layer {
  position: absolute; inset: 0; z-index: 1; pointer-events: none;
  background-image:
    linear-gradient(color-mix(in srgb, var(--accent-cyan) 7%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--accent-cyan) 7%, transparent) 1px, transparent 1px),
    linear-gradient(color-mix(in srgb, var(--accent-cyan) 13%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--accent-cyan) 13%, transparent) 1px, transparent 1px);
}
.wf-grid-layer.grid-dot {
  background-image: radial-gradient(color-mix(in srgb, var(--accent-cyan) 22%, transparent) 1.2px, transparent 1.2px);
  background-size: 28px 28px !important;
}
.wf-grid-layer.grid-off { background-image: none; }
.wf-world { background-image: none; }
.wf-canvas { z-index: 0; }
.wf-world { z-index: 2; }

/* 节点快捷工具条 */
.wf-node-toolbar {
  position: absolute; left: 50%; top: -34px; transform: translateX(-50%);
  display: inline-flex; gap: 4px; padding: 4px; border-radius: 9px; white-space: nowrap;
  background: var(--bg-card); border: 1px solid var(--border-color);
  box-shadow: 0 8px 22px rgba(0,0,0,.2); z-index: 5;
}
.wf-node-toolbar button {
  padding: 4px 9px; border: 0; border-radius: 6px; cursor: pointer; font-size: 11px; font-weight: 600;
  background: transparent; color: var(--text-secondary);
}
.wf-node-toolbar button:hover { background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); color: var(--accent-cyan); }
.wf-node-toolbar button.danger:hover { background: color-mix(in srgb, var(--status-critical, #f85149) 12%, transparent); color: var(--status-critical, #f85149); }

/* 成果预览 */
.canvas-sim-report-foot { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-top: 1px solid var(--border-color); font-size: 10.5px; color: var(--text-muted); }
.canvas-sim-deliverable-btn {
  padding: 5px 11px; border-radius: 8px; cursor: pointer; font-size: 11px; font-weight: 700; white-space: nowrap;
  border: 1px solid var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 12%, transparent); color: var(--accent-cyan);
}
.canvas-sim-deliverable-btn:hover:not(:disabled), .canvas-sim-deliverable-btn.open { background: color-mix(in srgb, var(--accent-cyan) 24%, transparent); }
.canvas-sim-deliverable-btn:disabled { opacity: .4; cursor: not-allowed; }
.canvas-sim-deliverable { border-top: 1px solid var(--border-color); padding: 10px 12px; display: flex; flex-direction: column; gap: 8px; }
.canvas-sim-deliverable pre {
  margin: 0; max-height: 200px; overflow: auto; padding: 10px 12px; border-radius: 9px;
  background: var(--bg-secondary, transparent); border: 1px solid var(--border-color);
  font-size: 11.5px; line-height: 1.75; color: var(--text-primary); white-space: pre-wrap; word-break: break-word;
}
.canvas-sim-deliverable-actions { display: flex; gap: 8px; }
.canvas-sim-deliverable-actions button {
  padding: 5px 12px; border-radius: 8px; cursor: pointer; font-size: 11px;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-secondary);
}
.canvas-sim-deliverable-actions button:hover { border-color: var(--accent-cyan); color: var(--accent-cyan); }

/* ============================================================
 * v21：今日行业情报雷达（IntelligenceFeedPanel 重设计）
 * 榜首主卡（评分环）+ TOP 榜单（条形指标），点击 → 预览抽屉带情报解读
 * ============================================================ */
.intel-radar-lead {
  display: flex; gap: 16px; align-items: flex-start;
  padding: 18px 20px; margin-top: 12px;
  border: 1px solid var(--border-color); border-radius: 12px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent-cyan) 7%, var(--bg-card)) 0%, var(--bg-card) 55%);
  cursor: pointer; position: relative; overflow: hidden;
  transition: border-color .18s ease, box-shadow .18s ease, transform .18s ease;
}
.intel-radar-lead::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, var(--accent-cyan), transparent 65%);
}
.intel-radar-lead:hover { border-color: var(--accent-cyan); box-shadow: 0 8px 28px color-mix(in srgb, var(--accent-cyan) 14%, transparent); transform: translateY(-1px); }
.intel-radar-lead:focus-visible { outline: 2px solid var(--accent-cyan); outline-offset: 2px; }
.intel-radar-lead-score {
  flex-shrink: 0; width: 64px; height: 64px; border-radius: 50%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  background:
    radial-gradient(closest-side, var(--bg-card) 74%, transparent 75% 100%),
    conic-gradient(var(--accent-cyan) calc(var(--score, 0) * 1%), color-mix(in srgb, var(--border-color) 60%, transparent) 0);
  color: var(--text-primary);
}
.intel-radar-lead-score span { font-size: 19px; font-weight: 800; line-height: 1; font-family: var(--font-mono, monospace); }
.intel-radar-lead-score small { font-size: 9px; color: var(--text-muted); margin-top: 2px; letter-spacing: .1em; }
.intel-radar-lead-main { min-width: 0; display: flex; flex-direction: column; gap: 8px; }
.intel-radar-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.intel-radar-chip { padding: 2px 9px; border-radius: 999px; border: 1px solid var(--border-color); color: var(--text-muted); font-size: 10px; }
.intel-radar-chip.rank { color: var(--accent-cyan); border-color: color-mix(in srgb, var(--accent-cyan) 45%, transparent); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.intel-radar-lead-title { margin: 0; font-size: 16px; line-height: 1.5; color: var(--text-primary); }
.intel-radar-lead-summary { margin: 0; font-size: 12.5px; line-height: 1.75; color: var(--text-muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.intel-radar-lead-foot { display: flex; align-items: center; justify-content: space-between; font-size: 10.5px; color: var(--text-muted); }
.intel-radar-lead-foot em { font-style: normal; color: var(--accent-cyan); font-weight: 600; }
.intel-radar-list { margin-top: 10px; display: flex; flex-direction: column; gap: 6px; }
.intel-radar-list-title { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; color: var(--text-muted); padding: 2px 2px 4px; }
.intel-radar-row {
  display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 10px 12px; border: 1px solid var(--border-color); border-radius: 10px;
  background: var(--bg-elevated); text-align: left; cursor: pointer;
  transition: border-color .15s ease, background .15s ease, transform .15s ease;
}
.intel-radar-row:hover { border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 6%, var(--bg-elevated)); transform: translateX(3px); }
.intel-radar-row-rank { flex-shrink: 0; font-family: var(--font-mono, monospace); font-size: 12px; font-weight: 700; color: var(--accent-cyan); opacity: .85; }
.intel-radar-row-main { min-width: 0; flex: 1; display: flex; flex-direction: column; gap: 3px; }
.intel-radar-row-title { font-size: 13px; font-weight: 600; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.intel-radar-row-meta { display: flex; flex-wrap: wrap; gap: 6px; font-size: 10px; color: var(--text-muted); }
.intel-radar-row-meta i { font-style: normal; padding: 1px 7px; border: 1px solid var(--border-color); border-radius: 999px; max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.intel-radar-row-bars { flex-shrink: 0; display: flex; flex-direction: column; gap: 4px; width: 64px; }
.intel-radar-bar { height: 4px; border-radius: 2px; background: color-mix(in srgb, var(--border-color) 70%, transparent); overflow: hidden; }
.intel-radar-bar i { display: block; height: 100%; border-radius: 2px; }
.intel-radar-bar i[data-kind="impact"] { background: var(--accent-cyan); }
.intel-radar-bar i[data-kind="heat"] { background: var(--accent-amber, #d97706); }
.intel-radar-row-score { flex-shrink: 0; font-family: var(--font-mono, monospace); font-size: 15px; font-weight: 800; color: var(--text-primary); }

/* v21：预览抽屉「情报解读」块 */
.news-preview-insight { margin: 0 0 20px; padding: 14px 16px; border: 1px solid color-mix(in srgb, var(--accent-cyan) 35%, transparent); border-radius: 12px; background: color-mix(in srgb, var(--accent-cyan) 6%, var(--bg-elevated)); }
.news-preview-insight-head { font-size: 10.5px; font-weight: 800; letter-spacing: .12em; color: var(--accent-cyan); margin-bottom: 8px; }
.news-preview-insight-score { display: block; font-size: 12.5px; color: var(--text-primary); margin-bottom: 8px; font-family: var(--font-mono, monospace); }
.news-preview-insight p { margin: 0 0 7px; font-size: 12px; line-height: 1.8; color: var(--text-muted); }
.news-preview-insight-entities { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.news-preview-insight-entities span { padding: 2px 9px; border-radius: 999px; border: 1px solid var(--border-color); font-size: 10px; color: var(--text-primary); background: var(--bg-card); }

/* v21 #22：专业图表区（ProCharts） */
.pro-charts { margin: 0 0 14px; padding: 14px 16px 16px; border: 1px solid var(--border-color); border-radius: 14px; background: var(--bg-card); display: flex; flex-direction: column; gap: 12px; }
.pro-charts-title { font-size: 10.5px; font-weight: 800; letter-spacing: .14em; color: var(--accent-cyan); }
.pro-charts-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; }
.pro-charts-grid .pro-chart-block { margin: 0; }
.pro-chart-block { padding: 12px 14px; border: 1px solid var(--border-color); border-radius: 10px; background: var(--bg-elevated); display: flex; flex-direction: column; gap: 9px; }
.pro-chart-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.pro-chart-head strong { font-size: 12px; color: var(--text-primary); }
.pro-chart-head span { font-size: 10px; color: var(--text-muted); }
.pro-chart-head span b { color: var(--text-primary); font-family: var(--font-mono, monospace); }
.pro-chart-svg { width: 100%; height: auto; display: block; }
.pro-chart-grid { stroke: var(--border-color); stroke-width: 1; stroke-dasharray: 2 4; }
.pro-chart-level { stroke: var(--accent-amber, #d97706); stroke-width: 1.2; opacity: .75; }
.pro-chart-label { fill: var(--text-muted); font-size: 9px; font-family: var(--font-mono, monospace); }
.pro-chart-legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 10px; color: var(--text-muted); }
.pro-chart-legend span { display: inline-flex; align-items: center; gap: 5px; }
.pro-chart-legend i { width: 10px; height: 10px; border-radius: 3px; display: inline-block; }
.pro-chart-empty { margin: 0; font-size: 11px; color: var(--text-muted); }
.pro-chart-note { font-size: 9.5px; color: var(--text-muted); line-height: 1.5; }

/* 多空证据强度条 */
.pro-evidence-track { display: flex; height: 10px; border-radius: 5px; overflow: hidden; border: 1px solid var(--border-color); }
.pro-evidence-seg { height: 100%; }
.pro-evidence-seg.bull { background: var(--signal-critical); }
.pro-evidence-seg.bear { background: var(--signal-positive); }
.pro-evidence-legend { display: flex; gap: 14px; font-size: 10px; color: var(--text-muted); }
.pro-evidence-legend span { display: inline-flex; align-items: center; gap: 5px; }
.pro-evidence-legend i { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.pro-evidence-legend i.bull { background: var(--signal-critical); }
.pro-evidence-legend i.bear { background: var(--signal-positive); }

/* 基准对比条 */
.pro-bench-rows { display: flex; flex-direction: column; gap: 8px; }
.pro-bench-row { display: grid; grid-template-columns: 44px 1fr 56px; align-items: center; gap: 9px; font-size: 11px; color: var(--text-muted); }
.pro-bench-track { height: 8px; border-radius: 4px; background: color-mix(in srgb, var(--border-color) 60%, transparent); overflow: hidden; }
.pro-bench-track i { display: block; height: 100%; border-radius: 4px; }
.pro-bench-track i.up { background: var(--signal-critical); }
.pro-bench-track i.down { background: var(--signal-positive); }
.pro-bench-row b { text-align: right; font-family: var(--font-mono, monospace); font-size: 11px; }
.pro-bench-row b.up { color: var(--signal-critical); }
.pro-bench-row b.down { color: var(--signal-positive); }

/* v21 #22：研究工具「AI 生成」按钮与初稿说明 */
.stock-tool-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 9px; }
.stock-ai-fill-btn { padding: 5px 12px; border: 1px solid color-mix(in srgb, var(--accent-cyan) 45%, transparent); border-radius: 8px; background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); color: var(--accent-cyan); font-size: 10.5px; font-weight: 700; letter-spacing: .04em; cursor: pointer; transition: background .15s ease, transform .15s ease; }
.stock-ai-fill-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-cyan) 20%, transparent); transform: translateY(-1px); }
.stock-ai-fill-btn:disabled { opacity: .45; cursor: not-allowed; }
.stock-scenario-rationale { margin-top: 9px; padding: 8px 10px; border-left: 2px solid var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 6%, var(--bg-elevated)); font-size: 10.5px; line-height: 1.65; color: var(--text-secondary); border-radius: 0 8px 8px 0; }
.stock-checklist-notice.error { border-left-color: var(--signal-critical); background: color-mix(in srgb, var(--signal-critical) 8%, var(--bg-elevated)); color: var(--signal-critical); }

/* v22 #1：画像阅读深度统计 chips */
.profile-reading-depth-stats { display: flex; gap: 8px; margin-top: 7px; }
.profile-reading-depth-stats span { padding: 2px 10px; border-radius: 999px; border: 1px solid var(--border-color); font-size: 10px; color: var(--text-secondary); background: var(--bg-elevated); font-family: var(--font-mono, monospace); }

/* v22 #3：登录弹窗「体验模式」按钮 */
.auth-guest-btn {
  width: 100%; margin-top: 10px; padding: 9px 14px; border-radius: 10px; cursor: pointer;
  border: 1px dashed color-mix(in srgb, var(--accent-cyan) 55%, transparent);
  background: color-mix(in srgb, var(--accent-cyan) 7%, transparent);
  color: var(--accent-cyan); font-size: 12px; font-weight: 600; letter-spacing: .02em;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  transition: background .15s ease, border-color .15s ease;
}
.auth-guest-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-cyan) 14%, transparent); border-color: var(--accent-cyan); }
.auth-guest-btn:disabled { opacity: .5; cursor: not-allowed; }
/* v26.9b 修复：appConstants 图标 SVG 均无 width/height（靠上下文约束），
   此按钮之前未约束 → sparkle 图标被 flex 拉伸成整块巨型星形溢出 */
.auth-guest-btn svg { width: 16px; height: 16px; flex: none; }

/* v23 #4：侧边栏收起态仅显示图标（居中、隐藏文字占位） */
.sidebar.collapsed .nav-label-wrap, .sidebar.collapsed .nav-label, .sidebar.collapsed .nav-count, .sidebar.collapsed .sidebar-action span, .sidebar.collapsed .nav-short-label { display: none; }
.sidebar.collapsed .nav-item { justify-content: center; padding-left: 0; padding-right: 0; gap: 0; }
.sidebar.collapsed .nav-icon { width: 20px; height: 20px; }
.sidebar.collapsed .sidebar-action { justify-content: center; padding-left: 0; padding-right: 0; gap: 0; }

/* v23 #5：卡片预览段落缩进与布局 */
.news-preview-para { text-indent: 2em; }
.news-preview-para.lede { text-indent: 0; }
.news-preview-md p { text-indent: 2em; }
.news-preview-md h1 + p, .news-preview-md h2 + p, .news-preview-md h3 + p, .news-preview-md h4 + p, .news-preview-md li p { text-indent: 0; }
.news-preview-body { padding-right: 22px; }

/* v23 #2：新增素材类型徽章（浅色深字 / 深色亮字，跨主题可读） */
.type-tutorial { background: rgba(132, 204, 22, .16); color: #4d7c0f; }
.type-paper { background: rgba(99, 102, 241, .16); color: #4f46e5; }
.type-news { background: rgba(234, 88, 12, .15); color: #c2410c; }
:root[data-mode="dark"] .type-tutorial { color: #a3e635; }
:root[data-mode="dark"] .type-paper { color: #818cf8; }
:root[data-mode="dark"] .type-news { color: #fb923c; }

/* v23 #1：划词翻译气泡 */
.sel-translate-bubble {
  position: fixed; z-index: 9997;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  box-shadow: 0 10px 32px rgba(0, 0, 0, .18);
  display: flex; flex-direction: column;
  max-height: 300px;
  overflow: hidden;
  animation: selTranslateIn .16s ease;
}
@keyframes selTranslateIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.sel-translate-head {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 12px; border-bottom: 1px solid var(--border-color);
}
.sel-translate-title { font-size: 12px; font-weight: 700; color: var(--accent-cyan); flex-shrink: 0; }
.sel-translate-text {
  font-size: 12px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1;
}
.sel-translate-close {
  flex-shrink: 0; border: none; background: transparent; cursor: pointer;
  color: var(--text-muted); font-size: 14px; line-height: 1; padding: 2px 4px; border-radius: 6px;
}
.sel-translate-close:hover { color: var(--text-primary); background: color-mix(in srgb, var(--text-primary) 8%, transparent); }
.sel-translate-body { padding: 10px 12px; overflow-y: auto; flex: 1; min-height: 40px; }
.sel-translate-result { font-size: 13px; line-height: 1.65; color: var(--text-primary); white-space: pre-wrap; word-break: break-word; }
.sel-translate-loading { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-muted); }
.sel-translate-spinner {
  width: 12px; height: 12px; border-radius: 50%; flex-shrink: 0;
  border: 2px solid color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  border-top-color: var(--accent-cyan);
  animation: selTranslateSpin .8s linear infinite;
}
@keyframes selTranslateSpin { to { transform: rotate(360deg); } }
.sel-translate-error { font-size: 12px; color: var(--status-critical, #e5484d); line-height: 1.6; }
.sel-translate-actions {
  display: flex; gap: 8px; padding: 8px 12px; border-top: 1px solid var(--border-color);
}
.sel-translate-actions button {
  flex: 1; padding: 6px 0; font-size: 12px; font-weight: 600; cursor: pointer;
  border-radius: 8px; border: 1px solid var(--border-color);
  background: transparent; color: var(--text-primary);
  transition: background .15s ease, border-color .15s ease;
}
.sel-translate-actions button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border-color: var(--accent-cyan);
}
.sel-translate-actions button:disabled { opacity: .45; cursor: not-allowed; }
/* v26：手动触发主按钮 + 待机提示 */
.sel-translate-actions .sel-translate-go {
  background: color-mix(in srgb, var(--accent-cyan) 16%, transparent);
  border-color: var(--accent-cyan); color: var(--accent-cyan);
}
.sel-translate-actions .sel-translate-go:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-cyan) 26%, transparent);
}
.sel-translate-idle { font-size: 12px; color: var(--text-muted); line-height: 1.6; }

/* v23 #1：精灵协作能力设置 */
.elf-collab-list { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
.elf-collab-item {
  display: flex; align-items: flex-start; gap: 10px;
  padding: 10px 12px; border-radius: 10px; cursor: pointer;
  border: 1px solid var(--border-color);
  transition: border-color .15s ease, background .15s ease;
}
.elf-collab-item:hover { border-color: color-mix(in srgb, var(--accent-cyan) 45%, var(--border-color)); }
.elf-collab-item input[type="checkbox"] { margin-top: 3px; accent-color: var(--accent-cyan); }
.elf-collab-info { display: flex; flex-direction: column; gap: 2px; }
.elf-collab-info b { font-size: 13px; color: var(--text-primary); font-weight: 600; }
.elf-collab-info small { font-size: 12px; color: var(--text-muted); line-height: 1.5; }

/* v23 #3：显式连线（用户拖拽建立）与交互控件 */
.wf-edge-hit {
  fill: none; stroke: transparent; stroke-width: 16;
  pointer-events: stroke; cursor: pointer;
}
.wf-edge-explicit {
  stroke: #c9a961; stroke-width: 2.8; stroke-dasharray: none;
  pointer-events: none;
}
.wf-edge-explicit-group.selected .wf-edge-explicit { stroke: var(--accent-cyan); stroke-width: 3.2; }
.wf-edge-temp { stroke: var(--accent-cyan); stroke-width: 2.5; stroke-dasharray: 5 5; pointer-events: none; opacity: .85; }
.wf-edge-bend-handle {
  fill: var(--bg-secondary); stroke: var(--accent-cyan); stroke-width: 2;
  cursor: grab; pointer-events: all;
}
.wf-edge-bend-handle:hover { fill: color-mix(in srgb, var(--accent-cyan) 25%, var(--bg-secondary)); }
.wf-edge-del { cursor: pointer; }
.wf-edge-del circle { fill: var(--status-critical, #f85149); opacity: .92; }
.wf-edge-del text { fill: #fff; font-size: 12px; font-weight: 700; user-select: none; }
.wf-edge-del:hover circle { opacity: 1; }
/* 连线拖拽中：光标提示 */
.wf-canvas.is-connecting, .wf-canvas.is-connecting .wf-node { cursor: crosshair; }

/* v23 #3：节点端口真实命中区（原先 0 尺寸纯装饰，无法作为连线拖拽起点） */
.wf-port {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 14px; height: 14px; border-radius: 50%;
  border: 2px solid var(--bg-primary);
  box-sizing: border-box; z-index: 2;
}
.wf-port-in { pointer-events: none; }
.wf-port-out { cursor: crosshair; transition: transform .12s ease, box-shadow .12s ease; }
.wf-port-out:hover {
  transform: translateY(-50%) scale(1.35);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-cyan) 25%, transparent);
}
.wf-edge-overlay { position: absolute; inset: 0; overflow: visible; pointer-events: none; }
.wf-edge-overlay circle, .wf-edge-overlay g { pointer-events: all; }

/* v24 #1：股市 AI 大师叙述排版（Markdown 结构化输出） */
.stock-ai-master { line-height: 1.75; font-size: 13.5px; }
.stock-ai-master h2 {
  font-size: 14px; font-weight: 700; margin: 16px 0 8px;
  padding-left: 10px; border-left: 3px solid var(--accent-cyan);
  color: var(--text-primary);
}
.stock-ai-master h3 { font-size: 13px; font-weight: 700; margin: 12px 0 6px; color: var(--text-primary); }
.stock-ai-master p { margin: 6px 0; color: var(--text-primary); }
.stock-ai-master ul, .stock-ai-master ol { margin: 6px 0 6px 18px; }
.stock-ai-master li { margin: 4px 0; }
.stock-ai-master strong { color: var(--accent-cyan); font-weight: 700; }
.stock-ai-master table { width: 100%; border-collapse: collapse; margin: 10px 0; font-size: 12.5px; }
.stock-ai-master th, .stock-ai-master td {
  border: 1px solid var(--border-color); padding: 6px 9px; text-align: left;
}
.stock-ai-master th { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); font-weight: 700; }
.stock-ai-master blockquote {
  margin: 8px 0; padding: 6px 12px; border-left: 3px solid var(--border-color);
  color: var(--text-muted);
}

/* ===== v24 #2：用户广场重设计 ===== */
.community-header-compact { padding: 6px 0 2px; }
.community-header-compact h1 { margin: 0; }
.community-header-compact p { display: none; }

/* 内容卡：摘要裁剪 + 类型徽章排版 */
.community-post { display: flex; flex-direction: column; gap: 6px; }
.community-post-type {
  display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600;
  background: color-mix(in srgb, var(--accent-cyan) 12%, transparent);
  color: var(--accent-cyan);
}
.community-post-meta { display: flex; align-items: center; gap: 8px; color: var(--text-muted); font-size: 12px; }
.community-post h2 { margin: 0; font-size: 16px; line-height: 1.4; }
.community-post-excerpt {
  margin: 2px 0 4px; color: var(--text-secondary); font-size: 13px; line-height: 1.65;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}

/* 发布器：来源导入行 + 选择列表 */
.community-compose-import { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; font-size: 12px; color: var(--text-muted); }
.community-compose-import button {
  padding: 4px 12px; border-radius: 8px; border: 1px solid var(--border-color);
  background: transparent; color: var(--text-primary); font-size: 12px; cursor: pointer;
  transition: border-color .15s ease, background .15s ease;
}
.community-compose-import button:hover:not(:disabled) { border-color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); }
.community-compose-import button.active { border-color: var(--accent-cyan); color: var(--accent-cyan); }
.community-compose-import button:disabled { opacity: .45; cursor: not-allowed; }
.community-compose-picker {
  display: flex; flex-direction: column; gap: 6px; max-height: 220px; overflow-y: auto;
  border: 1px solid var(--border-color); border-radius: 10px; padding: 8px; margin-bottom: 10px;
}
.community-picker-item {
  display: flex; flex-direction: column; gap: 2px; text-align: left; padding: 8px 10px;
  border-radius: 8px; border: 1px solid transparent; background: transparent; cursor: pointer;
}
.community-picker-item:hover { background: color-mix(in srgb, var(--accent-cyan) 8%, transparent); border-color: color-mix(in srgb, var(--accent-cyan) 40%, transparent); }
.community-picker-item b { font-size: 13px; color: var(--text-primary); }
.community-picker-item small { font-size: 12px; color: var(--text-muted); }

/* 详情抽屉：固定右侧滑入窗口，信息流不再被挤压 */
.community-layout.has-detail { grid-template-columns: minmax(0, 1fr); }
.community-drawer-root { position: fixed; inset: 0; z-index: 1200; }
.community-drawer-mask { position: absolute; inset: 0; background: rgba(0, 0, 0, .38); animation: communityMaskIn .18s ease; }
@keyframes communityMaskIn { from { opacity: 0; } to { opacity: 1; } }
.community-drawer-root .community-detail,
.community-detail[data-testid="community-detail"] {
  position: fixed; top: 0; right: 0; bottom: 0; left: auto;
  width: min(560px, 92vw); max-height: none;
  border-left: 1px solid var(--border-color); border-radius: 0;
  box-shadow: -18px 0 48px rgba(0, 0, 0, .22);
  animation: communityDrawerIn .22s cubic-bezier(.22, .8, .3, 1);
}
@keyframes communityDrawerIn { from { transform: translateX(40px); opacity: 0; } to { transform: none; opacity: 1; } }

/* ── v24 #5 联系人页（ChatPage）：满屏 + 紧凑头部 + 好友发现/删除 + 火花 ── */
.chat-page-full { display:flex; flex-direction:column; max-width:none; min-height:calc(100dvh - 150px); padding:18px 22px 22px; }
.chat-page-full .chat-layout { flex:1; min-height:0; }
.chat-page-full .chat-messages { min-height:0; }
.chat-header-compact { align-items:center; margin-bottom:12px; } .chat-header-compact h1 { margin:0; font-size:20px; }
.chat-header-compact .chat-header-actions input { min-width:150px; padding:7px 9px; }
.chat-streak { margin-left:6px; font-style:normal; font-size:10px; color:var(--accent-amber); }
.chat-contact-search { width:100%; margin-bottom:8px; border:1px solid var(--border-color); border-radius:7px; padding:8px 10px; background:var(--bg-card); color:var(--text-primary); }
.chat-discover { display:flex; flex-direction:column; gap:6px; margin-bottom:12px; padding:10px; border:1px dashed var(--border-color); border-radius:8px; }
.chat-discover-title { margin:4px 0 2px; color:var(--text-muted); font-size:10px; }
.chat-discover-item,.chat-discover-manual { display:flex; align-items:center; gap:8px; }
.chat-discover-item > span:nth-child(2) { flex:1; min-width:0; display:flex; flex-direction:column; gap:2px; overflow:hidden; }
.chat-discover-item strong,.chat-discover-item small { overflow:hidden; font-size:11px; text-overflow:ellipsis; white-space:nowrap; }
.chat-discover-item small { color:var(--text-muted); }
.chat-discover-item button,.chat-discover-manual button { border:1px solid var(--border-color); border-radius:7px; padding:6px 10px; background:var(--bg-card); color:var(--text-secondary); cursor:pointer; }
.chat-discover-manual input { flex:1; min-width:0; border:1px solid var(--border-color); border-radius:7px; padding:7px 9px; background:var(--bg-card); color:var(--text-primary); }
.chat-icon-btn { padding:6px 8px !important; }
.chat-danger-btn { border-color:color-mix(in srgb,var(--signal-critical) 55%,transparent) !important; color:var(--signal-critical) !important; }

/* ── v24 #4 画布节点配置卡：类型导语 / 路由规则行 / skill 卡片 ── */
.canvas-node-guide { display:block; margin:-4px 0 10px; color:var(--text-muted); font-size:10px; line-height:1.5; }
.canvas-node-section-title { display:block; margin:10px 0 6px; color:var(--accent-cyan); font:10px var(--font-mono); letter-spacing:.04em; }
.canvas-node-hint-wide { grid-column:1 / -1; }
.canvas-router-rules { display:flex; flex-direction:column; gap:6px; }
.canvas-router-rule { display:grid; grid-template-columns:1fr 88px 1fr 26px; gap:6px; align-items:center; }
.canvas-router-rule input,.canvas-router-rule select { min-width:0; border:1px solid var(--border-color); border-radius:6px; padding:6px 8px; background:var(--bg-card); color:var(--text-primary); font-size:11px; }
.canvas-router-remove,.canvas-router-add { border:1px solid var(--border-color); border-radius:6px; padding:6px 8px; background:var(--bg-card); color:var(--text-secondary); cursor:pointer; }
.canvas-router-remove { color:var(--signal-critical); }
.canvas-router-add { align-self:flex-start; font-size:11px; }
.canvas-router-add:hover { color:var(--accent-cyan); }
.canvas-skill-picker { display:flex; flex-direction:column; gap:8px; }
.canvas-skill-list { display:grid; grid-template-columns:1fr 1fr; gap:6px; }
.canvas-skill-card { display:flex; flex-direction:column; gap:3px; padding:8px 9px; border:1px solid var(--border-color); border-radius:8px; background:var(--bg-card); color:var(--text-primary); text-align:left; cursor:pointer; }
.canvas-skill-card:hover { border-color:var(--accent-cyan); }
.canvas-skill-card.active { border-color:var(--accent-cyan); background:color-mix(in srgb,var(--accent-cyan) 10%,var(--bg-card)); }
.canvas-skill-card strong { font-size:11px; }
.canvas-skill-card small { color:var(--text-muted); font-size:10px; line-height:1.4; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }

/* ===== v26 #13 进化档案（PersonaDrawer 内）===== */
.evo-section { border-top: 1px dashed var(--border-color); margin-top: 8px; padding-top: 12px; }
.evo-level-row { display: flex; align-items: center; gap: 10px; }
.evo-level-badge {
  padding: 3px 12px; border-radius: 999px; font-size: 12px; font-weight: 700;
  border: 1px solid color-mix(in srgb, var(--accent-cyan) 55%, transparent);
  color: var(--accent-cyan);
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
}
.evo-level-badge.is-lv0, .evo-level-badge.is-lv1 { border-color: var(--border-color); color: var(--text-muted); background: transparent; }
.evo-level-badge.is-lv4, .evo-level-badge.is-lv5 {
  border-color: color-mix(in srgb, var(--accent-amber, #c9a961) 60%, transparent);
  color: var(--accent-amber, #c9a961);
  background: color-mix(in srgb, var(--accent-amber, #c9a961) 10%, transparent);
}
.evo-level-score { font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.evo-progress {
  height: 5px; border-radius: 999px; overflow: hidden; margin-top: 8px;
  background: color-mix(in srgb, var(--text-muted) 14%, transparent);
}
.evo-progress-bar {
  height: 100%; border-radius: 999px; min-width: 4px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent-cyan) 55%, transparent), var(--accent-cyan));
  transition: width 0.5s var(--ease-standard, ease);
}
.evo-level-hint { margin-top: 6px; font-size: 10.5px; line-height: 1.6; color: var(--text-muted); }
.evo-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 12px; }
.evo-stat {
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 8px 4px; border-radius: 9px; border: 1px solid var(--border-color);
}
.evo-stat b { font-size: 15px; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.evo-stat span { font-size: 10px; color: var(--text-muted); }
.evo-tree { margin-top: 14px; }
.evo-tree-title { font-size: 11.5px; font-weight: 600; color: var(--text-primary); margin-bottom: 8px; }
.evo-tree-list { list-style: none; margin: 0; padding: 0 0 0 6px; border-left: 1.5px solid var(--border-color); }
.evo-tree-node { position: relative; display: flex; align-items: center; gap: 8px; padding: 4px 0 4px 12px; font-size: 11.5px; color: var(--text-primary); }
.evo-tree-dot {
  position: absolute; left: -4.5px; width: 8px; height: 8px; border-radius: 50%;
  background: var(--accent-cyan); border: 1.5px solid var(--bg-card);
}
.evo-tree-node time { margin-left: auto; font-size: 10px; color: var(--text-muted); }
.evo-exp { margin-top: 14px; }
.evo-exp-empty { font-size: 11px; color: var(--text-muted); padding: 8px; border: 1px dashed var(--border-color); border-radius: 9px; }
.evo-exp-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.evo-exp-item { padding: 8px 10px; border-radius: 9px; border: 1px solid var(--border-color); }
.evo-exp-head { display: flex; align-items: center; gap: 8px; }
.evo-exp-head b { font-size: 11.5px; color: var(--text-primary); }
.evo-exp-meta { font-size: 10px; color: var(--text-muted); }
.evo-exp-del {
  margin-left: auto; flex: none; width: 18px; height: 18px; border-radius: 50%;
  border: none; background: transparent; color: var(--text-muted); cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; font-size: 12px;
}
.evo-exp-del:hover { background: color-mix(in srgb, var(--status-critical) 14%, transparent); color: var(--status-critical); }
.evo-exp-text { margin: 4px 0 0; font-size: 11px; line-height: 1.7; color: var(--text-muted); }
.evo-ladder { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 14px; }
.evo-ladder-step {
  padding: 2px 8px; border-radius: 999px; font-size: 10px;
  border: 1px solid var(--border-color); color: var(--text-muted);
}
.evo-ladder-step.reached { border-color: color-mix(in srgb, var(--accent-cyan) 50%, transparent); color: var(--accent-cyan); }

/* ===== v26 #13 排队消息拖拽排序 ===== */
.chat-queue-item { cursor: grab; }
.chat-queue-item:active { cursor: grabbing; }
.chat-queue-item.is-dragging { opacity: 0.45; }

/* ===== v26 #15/#16 像素办公室 v2：实时协作监测面板（左侧栏底部） ===== */
.team-office {
  flex-shrink: 0;
  margin: 0 6px 6px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  background: var(--bg-primary);
  overflow: hidden;
  font-size: 10px;
}
.team-office-head {
  display: flex; align-items: center; gap: 6px;
  padding: 5px 8px;
  border-bottom: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--accent-cyan) 5%, transparent);
}
.team-office-title { font-weight: 700; font-size: 10.5px; color: var(--text-primary); letter-spacing: 0.04em; }
.team-office-live {
  display: inline-flex; align-items: center; gap: 4px;
  margin-left: auto; color: var(--text-muted); font-size: 9.5px;
}
.team-office-live i { width: 6px; height: 6px; border-radius: 50%; background: var(--border-color); }
.team-office-live.is-on { color: var(--status-info); }
.team-office-live.is-on i { background: var(--status-info); animation: ofcBlink 1s steps(2) infinite; }
@keyframes ofcBlink { 50% { opacity: 0.25; } }
.team-office-fold {
  flex: none; width: 18px; height: 18px; border-radius: 5px;
  border: 1px solid var(--border-color); background: transparent;
  color: var(--text-muted); cursor: pointer; font-size: 9px; line-height: 1;
  display: inline-flex; align-items: center; justify-content: center;
}
.team-office-fold:hover { color: var(--accent-cyan); border-color: var(--accent-cyan); }
.team-office.is-collapsed .team-office-head { border-bottom: none; }

/* —— 场景容器 —— */
.team-office-scene { position: relative; user-select: none; }

/* —— 墙面：踢脚线 + 竖纹墙纸 —— */
.ofc-wall {
  position: relative; height: 46px;
  background:
    repeating-linear-gradient(90deg,
      color-mix(in srgb, var(--border-color) 18%, transparent) 0 1px,
      transparent 1px 18px),
    color-mix(in srgb, var(--accent-cyan) 7%, var(--bg-secondary));
  border-bottom: 3px solid color-mix(in srgb, var(--border-color) 70%, var(--bg-primary));
}
/* 窗户：天空渐变 + 飘云 + 窗棂 */
.ofc-window {
  position: absolute; left: 8px; top: 6px; width: 44px; height: 28px;
  border: 3px solid color-mix(in srgb, var(--border-color) 80%, var(--text-primary));
  border-radius: 2px; overflow: hidden;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--accent-cyan) 45%, var(--bg-primary)) 0%,
      color-mix(in srgb, var(--accent-cyan) 12%, var(--bg-primary)) 70%,
      color-mix(in srgb, var(--accent-emerald, #37f5b6) 16%, var(--bg-primary)) 100%);
}
.ofc-cloud {
  position: absolute; top: 4px; left: -12px; width: 12px; height: 4px;
  background: color-mix(in srgb, var(--bg-primary) 88%, transparent);
  box-shadow: 3px -3px 0 color-mix(in srgb, var(--bg-primary) 88%, transparent), 8px 0 0 color-mix(in srgb, var(--bg-primary) 88%, transparent);
  animation: ofcCloud 16s steps(24) infinite linear;
}
.ofc-cloud2 { top: 14px; animation-duration: 24s; animation-delay: -8s; transform: scale(0.7); }
@keyframes ofcCloud { from { left: -14px; } to { left: 48px; } }
/* 挂钟：秒针 steps 旋转 */
.ofc-clock {
  position: absolute; left: 60px; top: 8px; width: 16px; height: 16px;
  border: 2px solid var(--border-color); border-radius: 2px;
  background: var(--bg-primary);
}
.ofc-clock i {
  position: absolute; left: 50%; top: 50%; width: 1px; height: 5px;
  background: var(--text-primary); transform-origin: 50% 0;
  animation: ofcTick 60s steps(60) infinite;
}
@keyframes ofcTick { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
/* 门（新成员进门位） */
.ofc-door {
  position: absolute; right: 10px; top: 2px; width: 20px; height: 34px;
  border: 2px solid var(--border-color); border-bottom: none;
  background: linear-gradient(180deg, #7a5230 0 60%, #6b4a2b 60% 100%);
}
.ofc-door::after {
  content: ''; position: absolute; left: 2px; top: 14px; width: 3px; height: 3px;
  background: color-mix(in srgb, var(--accent-amber, #c9a961) 80%, white);
}
/* 白板：写团队目标，Goal 推进时亮灯 */
.ofc-board {
  position: absolute; left: 86px; top: 8px; width: 46px; height: 26px;
  border: 3px solid color-mix(in srgb, var(--border-color) 80%, var(--text-primary));
  border-radius: 2px;
  background: color-mix(in srgb, var(--bg-primary) 84%, var(--border-color));
  display: flex; align-items: center; justify-content: center;
}
.ofc-board b { font-size: 7px; letter-spacing: 0.16em; color: var(--text-muted); font-weight: 700; }
.ofc-board-goal {
  position: absolute; right: -4px; top: -4px; width: 6px; height: 6px; border-radius: 50%;
  background: var(--status-info);
  animation: ofcBlink 1.2s steps(2) infinite;
}
/* 海报（装饰） */
.ofc-poster {
  position: absolute; right: 40px; top: 10px; width: 14px; height: 20px;
  border: 2px solid var(--border-color); border-radius: 1px;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--accent-amber, #c9a961) 55%, transparent) 0 30%,
      color-mix(in srgb, var(--accent-cyan) 35%, transparent) 30% 60%,
      color-mix(in srgb, var(--accent-rose, #ff6b8a) 35%, transparent) 60% 100%);
}

/* —— 地板：棋盘格 + 地毯 + 水吧 + 绿植 —— */
.ofc-floor {
  position: relative; height: 196px;
  background:
    repeating-conic-gradient(
      color-mix(in srgb, var(--border-color) 14%, var(--bg-primary)) 0% 25%,
      var(--bg-primary) 0% 50%
    ) 0 0 / 16px 16px;
}
.ofc-empty {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  color: var(--text-muted); font-size: 10px;
}
/* 水吧区地毯（像素圆角矩形） */
.ofc-rug {
  position: absolute; left: 2%; top: 44%; width: 34%; height: 46%;
  background: color-mix(in srgb, var(--accent-cyan) 10%, transparent);
  border: 2px dashed color-mix(in srgb, var(--accent-cyan) 30%, transparent);
  border-radius: 6px;
}
/* 饮水机 */
.ofc-cooler {
  position: absolute; left: 3%; top: 26%; width: 16px; height: 30px;
  background: #c7cdd8; border: 2px solid var(--border-color); border-radius: 2px;
}
.ofc-cooler-jug {
  position: absolute; left: 1px; top: -8px; width: 10px; height: 8px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 60%, transparent), color-mix(in srgb, var(--accent-cyan) 25%, transparent));
  border: 1px solid var(--border-color); border-radius: 2px 2px 0 0;
}
.ofc-cooler-tap {
  position: absolute; left: 4px; top: 12px; width: 4px; height: 4px;
  background: var(--border-color);
}
/* 绿植：三叶像素植物 + 陶盆（左右各一株） */
.ofc-plant { position: absolute; width: 18px; height: 26px; }
.ofc-plant-l { left: 33%; top: 44%; }
.ofc-plant-r { right: 2%; top: 10%; }
.ofc-plant i {
  position: absolute; width: 5px; height: 12px; border-radius: 2px 2px 0 0;
  background: #4f7a43;
}
.ofc-plant i:nth-child(1) { left: 0; bottom: 8px; transform: rotate(-14deg); }
.ofc-plant i:nth-child(2) { left: 6px; bottom: 8px; height: 15px; }
.ofc-plant i:nth-child(3) { left: 12px; bottom: 8px; transform: rotate(14deg); }
.ofc-plant::after {
  content: ''; position: absolute; left: 2px; bottom: 0; width: 13px; height: 8px;
  background: linear-gradient(180deg, #9a6a3c 0 40%, #7a5230 40% 100%);
  border: 1px solid var(--border-color); border-radius: 1px 1px 3px 3px;
}

/* —— 成员单元：小人 + 工位 + 徽章，绝对定位 + 平滑走位 —— */
.ofc-unit {
  position: absolute; width: 60px; margin: -20px 0 0 -30px;
  display: flex; flex-direction: column; align-items: center;
  transition: left 1.5s cubic-bezier(0.45, 0, 0.55, 1), top 1.5s cubic-bezier(0.45, 0, 0.55, 1);
}
.ofc-person { position: relative; z-index: 2; }
.ofc-person-svg { transition: transform 0.3s ease; }
.ofc-unit.is-face-left .ofc-person-svg { transform: scaleX(-1); }
.ofc-unit.is-working .ofc-person { animation: ofcType 0.55s steps(2) infinite; }
.ofc-unit.is-claiming .ofc-person { animation: ofcThink 1.6s steps(2) infinite; }
.ofc-unit.is-done .ofc-person { animation: ofcJump 0.6s steps(4) 2; }
.ofc-unit.is-idle .ofc-person { animation: ofcSway 2.8s steps(2) infinite; }
@keyframes ofcType { 50% { transform: translateY(1px); } }
@keyframes ofcThink { 50% { transform: translateY(-1px); } }
@keyframes ofcJump { 25% { transform: translateY(-4px); } 50% { transform: translateY(0); } 75% { transform: translateY(-2px); } }
@keyframes ofcSway { 50% { transform: translateX(1px); } }

/* 走路两帧：腿/臂交替（steps(1) 硬切保持像素感） */
.ofc-legs-b, .ofc-arm-b { opacity: 0; }
.ofc-unit.is-walking .ofc-legs-a { animation: ofcFrameA 0.36s steps(1) infinite; }
.ofc-unit.is-walking .ofc-legs-b { animation: ofcFrameB 0.36s steps(1) infinite; }
.ofc-unit.is-walking .ofc-arm-a { animation: ofcFrameA 0.36s steps(1) infinite; }
.ofc-unit.is-walking .ofc-arm-b { animation: ofcFrameB 0.36s steps(1) infinite; }
.ofc-unit.is-walking .ofc-person { animation: ofcBob 0.36s steps(2) infinite; }
@keyframes ofcFrameA { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes ofcFrameB { 0%, 49% { opacity: 0; } 50%, 100% { opacity: 1; } }
@keyframes ofcBob { 50% { transform: translateY(-2px); } }

/* 工位在身后（idle 去水吧时隐藏桌子） */
.ofc-desk {
  position: absolute; z-index: 1; left: 50%; top: -6px;
  transform: translateX(-50%);
  transition: opacity 0.6s steps(4);
}
.ofc-unit.is-idle .ofc-desk { opacity: 0; }
.ofc-screen-flicker { animation: ofcBlink 0.9s steps(2) infinite; }
.ofc-screen-flicker2 { animation: ofcBlink 1.3s steps(2) infinite; }

/* 状态徽章 + 名牌（语义色跨调色板固定） */
.ofc-chip {
  margin-top: 2px; padding: 1px 6px; border-radius: 3px;
  font-size: 8.5px; font-weight: 700; line-height: 1.5;
  border: 1px solid var(--border-color); color: var(--text-muted);
  background: var(--bg-primary);
}
.ofc-unit.is-working .ofc-chip,
.ofc-unit.is-claiming .ofc-chip { border-color: var(--status-info); color: var(--status-info); }
.ofc-unit.is-claimed .ofc-chip { border-color: var(--status-warn); color: var(--status-warn); }
.ofc-unit.is-done .ofc-chip { border-color: var(--status-ok); color: var(--status-ok); }
.ofc-name {
  font-size: 8.5px; color: var(--text-muted); max-width: 60px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* 像素对话气泡 */
.ofc-bubble {
  position: absolute; bottom: calc(100% + 2px); left: 50%; transform: translateX(-50%);
  z-index: 30; padding: 3px 7px;
  border: 2px solid var(--text-primary); border-radius: 3px;
  background: var(--bg-primary); color: var(--text-primary);
  font-size: 9px; font-weight: 600; line-height: 1.4; white-space: nowrap;
  box-shadow: 2px 2px 0 color-mix(in srgb, var(--text-primary) 25%, transparent);
  animation: ofcPop 0.25s steps(3);
  pointer-events: none;
}
.ofc-bubble::after {
  content: ''; position: absolute; left: 50%; bottom: -6px; margin-left: -3px;
  width: 6px; height: 6px; background: var(--bg-primary);
  border-right: 2px solid var(--text-primary); border-bottom: 2px solid var(--text-primary);
  transform: rotate(45deg);
}
@keyframes ofcPop { 0% { transform: translateX(-50%) scale(0.6); } 100% { transform: translateX(-50%) scale(1); } }

/* 窄侧栏自适应：单元微缩，保持间距 */
@media (max-width: 250px) {
  .ofc-unit { width: 52px; margin-left: -26px; }
  .ofc-name, .ofc-chip { font-size: 8px; }
  .ofc-floor { height: 180px; }
}

/* ===== v26 #17 像素养成模拟游戏（OfficeGame 大屏覆盖层） ===== */
.team-office-game {
  flex: none; padding: 2px 8px; border-radius: 5px; margin-left: 4px;
  border: 1px solid color-mix(in srgb, var(--accent-amber, #c9a961) 55%, transparent);
  background: color-mix(in srgb, var(--accent-amber, #c9a961) 10%, transparent);
  color: var(--accent-amber, #c9a961); font-size: 9px; font-weight: 700; cursor: pointer;
}
.team-office-game:hover { background: color-mix(in srgb, var(--accent-amber, #c9a961) 20%, transparent); }

.ogame-overlay {
  position: fixed; inset: 0; z-index: 9500;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--bg-primary) 62%, transparent);
  animation: ofcFadeIn 0.2s ease;
}
@keyframes ofcFadeIn { from { opacity: 0; } to { opacity: 1; } }
.ogame {
  width: min(860px, 94vw); height: min(600px, 88vh);
  display: flex; flex-direction: column;
  border: 2px solid var(--border-color); border-radius: 14px;
  background: var(--bg-primary);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.4);
  overflow: hidden;
  /* 容器查询锚点：内部 UI 随对话框尺寸动态适配（缩放不挤压不重叠） */
  container: ogame / size;
}
.ogame-topbar {
  display: flex; align-items: center; gap: 8px;
  padding: 7px 10px; border-bottom: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--accent-cyan) 6%, transparent);
}
.ogame-title { font-size: 12.5px; font-weight: 800; letter-spacing: 0.04em; color: var(--text-primary); white-space: nowrap; }
.ogame-coins {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 9px; border-radius: 999px; font-size: 11px; font-weight: 800;
  border: 1px solid color-mix(in srgb, var(--accent-amber, #c9a961) 55%, transparent);
  color: var(--accent-amber, #c9a961);
  background: color-mix(in srgb, var(--accent-amber, #c9a961) 10%, transparent);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.ogame-coins i {
  width: 9px; height: 9px; border-radius: 2px;
  background: linear-gradient(135deg, #ffd76b, #c9a961);
  border: 1px solid #8a7136;
}
.ogame-scene-tabs { display: flex; gap: 4px; margin-left: auto; }
.ogame-scene-tabs button {
  padding: 3px 10px; border-radius: 7px; cursor: pointer; font-size: 10.5px; font-weight: 700;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted);
  white-space: nowrap;
}
.ogame-scene-tabs button.active { border-color: var(--accent-cyan); color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.ogame-scene-tabs button:disabled { opacity: 0.45; cursor: not-allowed; }
.ogame-close {
  flex: none; width: 24px; height: 24px; border-radius: 7px; cursor: pointer;
  border: 1px solid var(--border-color); background: transparent; color: var(--text-muted); font-size: 11px;
}
.ogame-close:hover { color: var(--status-critical); border-color: var(--status-critical); }

.ogame-toolbar {
  display: flex; align-items: center; flex-wrap: wrap; gap: 5px;
  padding: 6px 10px; border-bottom: 1px solid var(--border-color);
  background: var(--bg-secondary);
}
.ogame-mode {
  padding: 3px 9px; border-radius: 7px; cursor: pointer; font-size: 10.5px; font-weight: 700;
  border: 1px solid var(--border-color); background: var(--bg-primary); color: var(--text-muted);
  white-space: nowrap;
}
.ogame-mode.active { border-color: var(--accent-cyan); color: var(--accent-cyan); background: color-mix(in srgb, var(--accent-cyan) 10%, transparent); }
.ogame-mode.is-salary.active { border-color: var(--accent-amber, #c9a961); color: var(--accent-amber, #c9a961); background: color-mix(in srgb, var(--accent-amber, #c9a961) 10%, transparent); }
.ogame-foods { display: inline-flex; gap: 4px; }
.ogame-food {
  padding: 3px 8px; border-radius: 7px; cursor: pointer; font-size: 10.5px;
  border: 1px dashed var(--border-color); background: var(--bg-primary); color: var(--text-muted);
  white-space: nowrap;
}
.ogame-food.active { border-style: solid; border-color: var(--status-ok); color: var(--status-ok); }
.ogame-food em { font-style: normal; font-size: 9px; color: var(--accent-amber, #c9a961); font-weight: 700; margin-left: 2px; }

/* 场景大屏（复用 ofc-wall/ofc-floor，放大） */
.ogame-scene { position: relative; flex: 1; min-height: 0; display: flex; flex-direction: column; }
.ofc-wall-big { height: 84px; }
.ofc-floor-big { flex: 1; height: auto; }
.ogame-lounge-sign {
  position: absolute; left: 50%; top: 10px; transform: translateX(-50%);
  padding: 3px 16px; border: 2px solid var(--border-color); border-radius: 2px;
  font-size: 9px; font-weight: 800; letter-spacing: 0.3em; color: var(--text-muted);
  background: color-mix(in srgb, var(--bg-primary) 84%, var(--border-color));
}
.ogame-desk-only { position: absolute; margin: -12px 0 0 -20px; opacity: 0.75; }

/* 休息区物件：沙发 / 电视 / 饮水机 */
.ogame-sofa { position: absolute; width: 74px; height: 34px; }
.ogame-sofa-a { left: 8%; top: 46%; }
.ogame-sofa-b { right: 10%; top: 60%; }
.ogame-sofa i {
  position: absolute; left: 0; bottom: 0; width: 74px; height: 22px;
  background: linear-gradient(180deg, #5a7db0 0 60%, #48648c 60% 100%);
  border: 2px solid var(--border-color); border-radius: 4px;
}
.ogame-sofa b {
  position: absolute; left: -4px; bottom: 14px; width: 10px; height: 24px;
  background: #48648c; border: 2px solid var(--border-color); border-radius: 3px;
}
.ogame-tv {
  position: absolute; left: 44%; top: 8%; width: 64px; height: 40px;
  border: 3px solid #1c2230; border-radius: 3px; background: #0e1520;
}
.ogame-tv i {
  display: block; width: 100%; height: 100%;
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 35%, #0e1520), #0e1520);
}
.ogame-cooler-l { left: auto; right: 4%; top: 40%; }

/* 床铺（v26.9）：休息区 3 张像素床，坐标与 officeGame.BED_SPOTS 一一对应。
   transform translate(-50%,-50%) 让床中心对齐 BED_SPOTS 坐标（= 躺卧小人的中心点） */
.ogame-bed {
  position: absolute; width: 52px; height: 34px;
  transform: translate(-50%, -50%);
  pointer-events: none;
}
.ogame-bed::before {
  /* 床架（木色底框） */
  content: ""; position: absolute; left: 0; bottom: 0; width: 52px; height: 26px;
  background: linear-gradient(180deg, #8a6a48 0 46%, #6e5438 46% 100%);
  border: 2px solid var(--border-color); border-radius: 3px;
}
.ogame-bed::after {
  /* 床头板 */
  content: ""; position: absolute; left: -2px; bottom: 18px; width: 9px; height: 20px;
  background: #6e5438; border: 2px solid var(--border-color); border-radius: 3px 3px 0 0;
}
.ogame-bed-pillow {
  position: absolute; left: 5px; bottom: 16px; width: 13px; height: 9px;
  background: #e8e2d4; border: 2px solid var(--border-color); border-radius: 3px;
}
.ogame-bed-quilt {
  position: absolute; left: 18px; bottom: 5px; width: 30px; height: 17px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent-cyan) 32%, #ffffff) 0 34%, color-mix(in srgb, var(--accent-cyan) 58%, #3a6a86) 34% 100%);
  border: 2px solid var(--border-color); border-radius: 2px 4px 4px 2px;
}
.ogame-bed-quilt::after {
  /* 被角折线装饰 */
  content: ""; position: absolute; left: 0; top: 0; width: 8px; height: 100%;
  background: rgba(255, 255, 255, 0.16);
}

/* 躺卧姿态（v26.9）：睡床休息时人物旋转 90° 横躺（头朝床头侧），叠呼吸动画 */
.ogame-unit.is-lying .ofc-person-svg {
  transform: rotate(90deg) translateY(8px);
  transform-origin: 50% 58%;
  transition: transform 0.45s ease;
}
.ogame-unit.is-lying .ogame-name,
.ogame-unit.is-lying .ogame-stats { opacity: 0.55; }
.ogame-unit.is-lying .ogame-zzz { top: -6px; left: 60%; }

/* 成员单元（游戏版：更大 + 可拖拽） */
.ogame-unit {
  position: absolute; width: 96px; margin: -30px 0 0 -48px;
  display: flex; flex-direction: column; align-items: center;
  cursor: grab; touch-action: none;
  transition: left 1.2s cubic-bezier(0.45, 0, 0.55, 1), top 1.2s cubic-bezier(0.45, 0, 0.55, 1);
}
.ogame-unit.is-dragging { cursor: grabbing; transition: none; z-index: 99 !important; filter: drop-shadow(0 8px 10px rgba(0, 0, 0, 0.3)); }
.ogame-unit:active { cursor: grabbing; }
.ogame-unit .ofc-person { animation: none; }
.ogame-unit.is-working .ofc-person { animation: ofcType 0.55s steps(2) infinite; }
.ogame-unit.is-claiming .ofc-person { animation: ofcThink 1.6s steps(2) infinite; }
.ogame-unit.is-done .ofc-person { animation: ofcJump 0.6s steps(4) 2; }
.ogame-unit.is-idle .ofc-person { animation: ofcSway 2.8s steps(2) infinite; }
.ogame-unit.is-lunch .ofc-person { animation: ofcBob 0.8s steps(2) infinite; }
.ogame-name {
  margin-top: 2px; font-size: 10.5px; font-weight: 700; color: var(--text-primary);
  max-width: 96px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* 三维属性条：饱食/精力/心情（v26.6 迷你版，减少画面占用） */
.ogame-stats { display: flex; flex-direction: column; gap: 1px; margin-top: 2px; width: 44px; }
.ogame-bar {
  position: relative; display: block; height: 4px; border-radius: 2px;
  background: color-mix(in srgb, var(--text-muted) 18%, transparent);
  border: 1px solid color-mix(in srgb, var(--border-color) 80%, transparent);
  overflow: hidden;
}
.ogame-bar i {
  position: absolute; left: 0; top: 0; bottom: 0; min-width: 2px;
  transition: width 0.6s ease;
}
.ogame-bar.is-hunger i { background: linear-gradient(90deg, #d98a3d, #f2b25c); }
.ogame-bar.is-energy i { background: linear-gradient(90deg, #3d8ad9, #5cc8f2); }
.ogame-bar.is-mood i { background: linear-gradient(90deg, #d95c9a, #f28ab8); }
.ogame-bar.is-low i { background: var(--status-critical); animation: ofcBlink 1.2s steps(2) infinite; }
.ogame-chip {
  margin-top: 3px; padding: 1px 8px; border-radius: 3px;
  font-size: 9px; font-weight: 700;
  border: 1px solid var(--border-color); color: var(--text-muted); background: var(--bg-primary);
}
.ogame-chip.is-busy { border-color: var(--status-info); color: var(--status-info); }

/* 粒子：爱心/金币/食物/烟花 */
.ogame-pt {
  position: absolute; z-index: 50; width: 8px; height: 8px;
  pointer-events: none;
  animation: ofcParticle 1.3s ease-out forwards;
}
.ogame-pt.is-heart { background: #f26d9d; box-shadow: -4px 0 0 #f26d9d, 4px 0 0 #f26d9d, 0 -4px 0 #f26d9d, -2px -6px 0 #f26d9d, 2px -6px 0 #f26d9d, -6px -2px 0 #f26d9d, 6px -2px 0 #f26d9d; }
.ogame-pt.is-coin { background: #ffd76b; border: 1px solid #8a7136; border-radius: 2px; }
.ogame-pt.is-food { background: #7ec97e; border-radius: 2px; }
.ogame-pt.is-firework {
  width: 6px; height: 6px;
  background: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
}
.ogame-pt.is-firework:nth-child(3n) { background: var(--accent-amber, #c9a961); box-shadow: 0 0 6px var(--accent-amber, #c9a961); }
.ogame-pt.is-firework:nth-child(3n+1) { background: var(--accent-rose, #ff6b8a); box-shadow: 0 0 6px var(--accent-rose, #ff6b8a); }
@keyframes ofcParticle {
  0% { transform: translate(0, 0) scale(1); opacity: 1; }
  100% { transform: translate(var(--pt-dx, 0px), var(--pt-dy, -40px)) scale(0.4); opacity: 0; }
}

.ogame-foot {
  padding: 5px 10px; border-top: 1px solid var(--border-color);
  font-size: 10px; color: var(--text-muted); background: var(--bg-secondary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

/* —— v26.7：容器查询动态适配（对话框缩小 → UI 同步缩放，不挤压不重叠） —— */
@container ogame (max-width: 560px) {
  .ogame-unit { width: 66px; margin: -17px 0 0 -33px; }
  .ogame-unit .ofc-person svg { width: 27px; }
  .ogame-name { font-size: 9px; max-width: 66px; }
  .ogame-stats { width: 33px; }
  .ogame-chip { font-size: 8px; padding: 1px 5px; }
  .ofc-bubble { font-size: 9px; max-width: 110px; }
}
@container ogame (max-height: 460px) {
  .ofc-wall-big { height: 60px; }
}

/* —— v26.7：休息睡觉态（慢呼吸 + Zzz 漂浮） —— */
.ogame-unit.is-resting .ofc-person { animation: ofcBreath 2.6s ease-in-out infinite; }
@keyframes ofcBreath {
  0%, 100% { transform: translateY(0) scaleY(1); }
  50% { transform: translateY(1px) scaleY(0.96); }
}
.ogame-zzz { position: absolute; top: -15px; left: 55%; width: 20px; height: 16px; z-index: 3; pointer-events: none; }
.ogame-zzz i {
  position: absolute; left: 0; bottom: 0;
  font-size: 9px; font-weight: 800; font-style: normal; line-height: 1;
  color: var(--status-info); opacity: 0;
  animation: ogameZzz 2.7s steps(4) infinite;
}
.ogame-zzz i:nth-child(2) { animation-delay: 0.9s; }
.ogame-zzz i:nth-child(3) { animation-delay: 1.8s; }
@keyframes ogameZzz {
  0% { opacity: 0; transform: translate(0, 0) scale(0.7); }
  30% { opacity: 1; }
  100% { opacity: 0; transform: translate(9px, -13px) scale(1.15); }
}

/* —— v26.7 关键修复：themes.css 的 `html * { transition: … !important }`（主题切换过渡）
   会吞掉所有位移过渡，导致小人移动瞬移。这里用更高特异性夺回 left/top 过渡。 —— */
html .ogame-overlay .ogame-unit,
html .team-office-scene .ofc-unit {
  transition-property: left, top !important;
  transition-duration: 1.2s !important;
  transition-timing-function: cubic-bezier(0.45, 0, 0.55, 1) !important;
}
html .team-office-scene .ofc-unit { transition-duration: 1.5s !important; }
/* 步行时长随距离伸缩（组件内联 --ogame-walk-ms） */
html .ogame-overlay .ogame-unit.is-walking { transition-duration: var(--ogame-walk-ms, 1.2s) !important; }
/* 家具挪位短过渡 */
html .ogame-overlay .ogame-furn {
  transition-property: left, top !important;
  transition-duration: 0.3s !important;
  transition-timing-function: ease !important;
}
/* 拖拽中必须零过渡（跟手） */
html .ogame-overlay .is-dragging { transition: none !important; }
/* 朝向翻转 */
html .ogame-overlay .ofc-person-svg,
html .team-office-scene .ofc-person-svg { transition: transform 0.3s ease !important; }

/* ---------- v26.6：自主行动 / 布置模式 / 思考气泡 ---------- */

/* 自主漫步走路动画（复用 ofc 两帧腿臂） */
.ogame-unit.is-walking .ofc-legs-a { animation: ofcFrameA 0.36s steps(1) infinite; }
.ogame-unit.is-walking .ofc-legs-b { animation: ofcFrameB 0.36s steps(1) infinite; }
.ogame-unit.is-walking .ofc-arm-a { animation: ofcFrameA 0.36s steps(1) infinite; }
.ogame-unit.is-walking .ofc-arm-b { animation: ofcFrameB 0.36s steps(1) infinite; }
.ogame-unit.is-walking .ofc-person { animation: ofcBob 0.36s steps(2) infinite; }

/* 思考/执行气泡：头顶像素小云 + 跳动三点（省空间的状态表达） */
.ogame-think {
  position: absolute; top: -16px; left: 50%; margin-left: -12px;
  width: 24px; height: 14px; z-index: 3;
  display: flex; align-items: center; justify-content: center; gap: 2px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color); border-radius: 3px;
  pointer-events: none;
  animation: ogameThinkFloat 1.6s steps(2) infinite;
}
.ogame-think::after {
  content: ''; position: absolute; bottom: -5px; left: 50%; margin-left: -1px;
  width: 2px; height: 2px; background: var(--border-color);
  box-shadow: -3px -3px 0 var(--border-color);
}
.ogame-think i { width: 3px; height: 3px; background: var(--status-info); opacity: 0.35; }
.ogame-think i:nth-child(2) { opacity: 0.7; animation: ofcBlink 0.9s steps(2) infinite; }
.ogame-think i:nth-child(3) { opacity: 1; animation: ofcBlink 0.9s steps(2) infinite; animation-delay: 0.3s; }
@keyframes ogameThinkFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-2px); }
}

/* 玩家摆放家具（布置模式可拖拽/收回；平时纯装饰不可点） */
.ogame-furn {
  position: absolute; margin: -43px 0 0 -18px;
  pointer-events: none;
  transition: left 0.3s ease, top 0.3s ease;
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.22));
}
.ogame-scene.is-decorating .ogame-furn {
  pointer-events: auto; cursor: grab;
  outline: 1px dashed color-mix(in srgb, var(--accent-cyan) 55%, transparent);
  outline-offset: 2px;
}
.ogame-furn.is-dragging {
  transition: none; cursor: grabbing; z-index: 99 !important;
  filter: drop-shadow(0 6px 8px rgba(0, 0, 0, 0.3));
}
.ogame-scene.is-decorating .ofc-floor-big { cursor: crosshair; }
/* 布置模式下装饰工位不拦截指针（否则会盖住低处家具并把点击漏给地板误摆放） */
.ogame-scene.is-decorating .ogame-desk-only { pointer-events: none; }
